    const boostMult = onBoost ? 1.4 : 1;
    engineOsc.saw.frequency.setTargetAtTime(baseFreq * boostMult, ctx.currentTime, 0.05);
    engineOsc.square.frequency.setTargetAtTime(baseFreq * 2 * boostMult, ctx.currentTime, 0.05);
