/**
 * audio.js — fully procedural audio via the Web Audio API.
 *
 * Every sound effect and music track is synthesised at runtime from
 * oscillators and noise — there are zero audio asset files. This keeps the
 * project self-contained and, more usefully for study, makes the relationship
 * between code and sound completely explicit: an envelope here is an envelope
 * you can hear.
 *
 * Music uses the standard Web Audio "lookahead scheduler" pattern: a coarse
 * timer wakes periodically and schedules any notes that fall inside the next
 * small window using the audio clock for sample-accurate timing.
 *
 * @module engine/audio
 */

import { CONFIG } from "../config.js";

/** MIDI note number -> frequency in Hz (A4 = 69 = 440Hz). */
const mtof = (m) => 440 * 2 ** ((m - 69) / 12);

/**
 * Music tracks as 16-step patterns. Numbers are MIDI notes, null = rest.
 * Each track loops. Designed to be "memorable in under 20 seconds" per the GDD.
 */
const TRACKS = {
  title: {
    bpm: 96,
    bass: [40, null, 40, null, 45, null, 43, null, 38, null, 38, null, 43, null, 45, null],
    lead: [64, 67, 71, 67, 69, 72, 76, 72, 62, 65, 69, 65, 67, 71, 74, 71],
