  hitSpark(x, y, color = "#fff", count = 10) {
    for (let i = 0; i < count; i++) {
      const a = rand(0, Math.PI * 2);
      const s = rand(120, 420);
      this.spawn({
        x, y,
        vx: Math.cos(a) * s, vy: Math.sin(a) * s,
        life: rand(0.18, 0.4), size: rand(2, 5),
        color, gravity: 900, drag: 4, shape: "square",
      });
