    }

    this.hp -= amount;
    this.flash = 0.12;
    this.vx = knockX;
    if (_launch) this.vy = _launch;
    this.iframes = 0.08;
    if (this.hp <= 0) {
      this.die();
    } else {
      this.fsm.change("hurt");
    }
    return true;
  }

