/**
 * boot.js — the stylized boot/splash card.
 *
 * Data is already loaded by main.js, so this is pure presentation: an animated
 * logo and a "restoring archive" progress sweep that sets the tone before the
 * title. It is skippable with confirm (a modern concession from the GDD's UX
