        p(hx+hw-1,hy,3,15,B); p(hx+hw,hy+1,2,14,M);
        for(let i=0;i<7;i++) p(hx+hw,hy+1+i*2,1,1,D);
        p(hx-2,hy+15,3,2,B); p(hx+hw-1,hy+15,3,2,B);
