  constructor() {
    /** @type {Particle[]} */
    this.pool = Array.from({ length: MAX_PARTICLES }, () => ({
      x: 0, y: 0, vx: 0, vy: 0, life: 0, maxLife: 1,
      size: 2, color: "#fff", gravity: 0, drag: 0, shape: "square", active: false,
    }));
    this.cursor = 0;
  }

