  _spawnContent(def) {
    const prog = this.app.progression;
    this.enemies = (def.enemies ?? []).map((e) =>
      new Enemy(this.app, this.app.data.enemies[e.type], e.x, e.y)
    );
    this.pickups = (def.pickups ?? [])
      .filter((spec) => {
