    // 4: Shaggy / messy
    else if(hs===4){
      if(dir==='down'||dir==='up'){
        p(hx,hy-3,hw,5,B); p(hx+1,hy-3,hw-2,4,M);
        p(hx-1,hy,2,8,B); p(hx,hy+1,1,7,M);
