        p(hx,hy-3,hw+1,5,B); p(hx+1,hy-3,hw,4,M);
        p(hx,hy-5,3,3,B); p(hx+1,hy-5,2,2,L);
        if(dir==='right'){ p(hx,hy,1,8,B); p(hx+1,hy+1,1,7,M); }
