```javascript
function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

class Inventory {
  constructor(){this.slots=new Map();}
  add(item,q=1){const e=this.slots.get(item.id);if(e)e.qty+=q;else this.slots.set(item.id,{item,qty:q});return true;}
  remove(id,q=1){const e=this.slots.get(id);if(!e||e.qty<q)return null;e.qty-=q;if(e.qty===0)this.slots.delete(id);return e.item;}
  has(id){return this.slots.has(id);}
}
class Equipment {
  constructor(inv){this.inv=inv;this.worn=new Map();}
  equip(id){const item=this.inv.remove(id,1);if(!item)return false;const prev=this.worn.get(item.slot);if(prev)this.inv.add(prev,1);this.worn.set(item.slot,item);return true;}
  unequip(slot){const item=this.worn.get(slot);if(!item)return false;this.worn.delete(slot);this.inv.add(item,1);return true;}
  bonus(stat){let t=0;for(const it of this.worn.values())t+=(it.mods&&it.mods[stat])||0;return t;}
}
class Character { constructor(base,eq){this.base=base;this.equipment=eq;} stat(name){return (this.base[name]||0)+this.equipment.bonus(name);} }
const inv=new Inventory(), eq=new Equipment(inv), hero=new Character({attack:5,defense:2},eq);
const weapon={id:'sword',slot:'hand',mods:{attack:4}};
inv.add(weapon,1);
const base=hero.stat('attack');
eq.equip('sword');
assert(hero.stat('attack')===base+4, 'equipping raises the stat');
assert(!inv.has('sword'), 'the equipped item left the bag');
eq.unequip('hand');
assert(hero.stat('attack')===base, 'unequipping returns the stat to base');
assert(inv.has('sword'), 'the item returned to the bag');
console.log('gen invequip fantasy/basic OK');
```

