  const hasCycles = (node, parent = node, seen = []) => {
    for (const next of graph.get(node)) {
      if (next === parent) return true;
      if (seen[next]) continue;
      seen[next] = true;
      if (hasCycles(next, parent, seen)) return true;
    }
    return false;
  };

  for (let i = 0; i < n; i++) {
