  const entries = []; // array of [word, count] pairs

  for (let i = 0; i < words.length; i++) {
    if (!words[i]) continue;
    let count = 1;
    for (let j = i + 1; j < words.length; j++) {
      if (words[i] === words[j]) {
        count++;
        words[j] = null; // removed letter once it's counted.
      }
    }
    entries.push([words[i], count]);
  }

  return entries
    .sort((a, b) => b[1] - a[1])
    .slice(0, n)
    .map((w) => w[0]);
}


