class Crop {
  constructor(name, yieldPerHarvest) {
    this.name = name;
    this.yieldPerHarvest = yieldPerHarvest;
  }

  harvest() {
    return this.yieldPerHarvest;
  }
}

class Market {
  constructor() {
    this.prices = {};
  }

  setPrice(crop, price) {
    this.prices[crop.name] = price;
  }

  getPrice(crop) {
    return this.prices[crop.name] || 0;
  }
}

class Farm {
  constructor(market) {
    this.market = market;
    this.crops = [];
    this.balance = 0;
  }

  plantCrop(crop) {
    this.crops.push(crop);
  }

  harvestCrops() {
    let totalHarvest = 0;
    this.crops.forEach(crop => {
      totalHarvest += crop.harvest();
    });
    return totalHarvest;
  }

  sellCrops() {
    let totalEarnings = 0;
    this.crops.forEach(crop => {
      const price = this.market.getPrice(crop);
      totalEarnings += price * crop.yieldPerHarvest;
    });
    this.balance += totalEarnings;
    this.crops = [];
    return totalEarnings;
  }

  getBalance() {
    return this.balance;
  }
}

// Demo
const market = new Market();
const wheat = new Crop("Wheat", 10);
const corn = new Crop("Corn", 15);

market.setPrice(wheat, 2);
market.setPrice(corn, 3);

const farm = new Farm(market);
farm.plantCrop(wheat);
farm.plantCrop(corn);

console.log("Harvested:", farm.harvestCrops()); // Harvested: 25
console.log("Earnings from sell:", farm.sellCrops()); // Earnings from sell: 75
console.log("Farm balance:", farm.getBalance()); // Farm balance: 75
