let lastPipeSpawn = Date.now();

function update() {
  const now = Date.now();
  const deltaTime = Math.min(now - lastUpdate, 16); // Cap deltaTime to prevent frame drops

  // Bird physics
  bird.velocity += bird.gravity;
  bird.y += bird.velocity;

  // Check for ground collision
  if (bird.y + bird.height >= canvas.height) {
    bird.y = canvas.height - bird.height;
    bird.velocity = 0;
  }

  // Pipe spawning
  if (now - lastPipeSpawn >= pipeSpawnInterval) {
    const pipeHeight = Math.random() * (canvas.height - pipeGap);
    pipes.push({
      x: canvas.width,
      y: 0,
      height: pipeHeight
    });
    pipes.push({
      x: canvas.width,
      y: pipeHeight + pipeGap,
      height: canvas.height - (pipeHeight + pipeGap)
    });
    lastPipeSpawn = now;
    // Increase difficulty
    pipeSpawnInterval = Math.max(pipeSpawnInterval - 50, 500);
  }

  // Pipe movement
  pipes.forEach(pipe => {
    pipe.x -= pipeSpeed;
  });

  // Remove pipes offscreen
  pipes = pipes.filter(pipe => pipe.x + pipeWidth > 0);

  // Collision detection
  pipes.forEach(pipe => {
    if (bird.x < pipe.x + pipeWidth &&
        bird.x + bird.width > pipe.x &&
        (bird.y < pipe.height || bird.y + bird.height > pipe.height + pipeGap)) {
      resetGame();
    }
  });

  lastUpdate = now;
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw bird
  ctx.fillStyle = 'blue';
  ctx.fillRect(bird.x, bird.y, bird.width, bird.height);

  // Draw pipes
  ctx.fillStyle = 'green';
  pipes.forEach(pipe => {
    ctx.fillRect(pipe.x, pipe.y, pipeWidth, pipe.height);
  });

  requestAnimationFrame(render);
}

function resetGame() {
  pipes.length = 0;
  bird.y = canvas.height / 2;
  bird.velocity = 0;
  pipeSpawnInterval = 1500;
  lastPipeSpawn = Date.now();
}

function jump() {
  bird.velocity = bird.jumpPower;
}

document.addEventListener('keydown', (e) => {
  if (e.code === 'Space') {
    jump();
  }
});

let lastUpdate = Date.now();
setInterval(update, 16); // Fixed timestep update loop
requestAnimationFrame(render);
