class Pricing {
  constructor(basePrice) {
    this.basePrice = basePrice;
  }

  calculatePrice(demand) {
    // Simple pricing model: price increases with demand
    return this.basePrice + (demand * 0.1 * this.basePrice);
  }
}

class Demand {
  constructor(initialDemand) {
    this.demand = initialDemand;
  }

  increaseDemand(amount) {
    this.demand += amount;
  }

  getDemand() {
    return this.demand;
  }
}

class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
  }

  sellProduct() {
    const price = this.pricing.calculatePrice(this.demand.getDemand());
    this.demand.increaseDemand(1); // Each sale increases demand slightly
    return price;
  }
}

// Top-level coordinator
class GameCoordinator {
  constructor() {
    const pricing = new Pricing(100);
    const demand = new Demand(50);
    this.store = new Store(pricing, demand);
