    constructor() {
        this.items = {};
    }

    addItem(item, quantity) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    removeItem(item, quantity) {
        if (this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            return true;
        }
        return false;
    }

    hasItem(item, quantity) {
        return this.items[item] && this.items[item] >= quantity;
    }

    getItems() {
        return this.items;
    }
}

class Crafting {
    constructor(inventory, recipes) {
        this.inventory = inventory;
        this.recipes = recipes;
    }

    canCraft(recipeName) {
        const recipe = this.recipes.find(r => r.getName() === recipeName);
        if (!recipe) return false;

        const ingredients = recipe.getIngredients();
        for (const [item, quantity] of Object.entries(ingredients)) {
            if (!this.inventory.hasItem(item, quantity)) {
                return false;
            }
        }
        return true;
    }

    craft(recipeName) {
        if (!this.canCraft(recipeName)) {
            return false;
        }

        const recipe = this.recipes.find(r => r.getName() === recipeName);
        const ingredients = recipe.getIngredients();
        for (const [item, quantity] of Object.entries(ingredients)) {
            this.inventory.removeItem(item, quantity);
        }

        console.log(`Crafted: ${recipeName}`);
        return true;
    }
}

