const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
const cardSize = 50;
const margin = 10;
const cols = 4;
const rows = 4;
const totalCards = cols * rows;
const cards = [];
let firstCard = null;
let secondCard = null;
let isFlipping = false;
let score = 0;
let highScore = localStorage.getItem('highScore') ? parseInt(localStorage.getItem('highScore')) : 0;
let lastTimestamp = performance.now();
const fixedTimestep = 1000 / 60;

canvas.width = cols * (cardSize + margin) - margin;
canvas.height = rows * (cardSize + margin) - margin;

function shuffle(array) {
    for (let i = array.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [array[i], array[j]] = [array[j], array[i]];
    }
}

function createCards() {
    const values = [];
    for (let i = 0; i < totalCards / 2; i++) {
        values.push(i + 1);
        values.push(i + 1);
    }
    shuffle(values);
    for (let i = 0; i < totalCards; i++) {
        const col = i % cols;
        const row = Math.floor(i / cols);
        cards.push({
            value: values[i],
            revealed: false,
            x: col * (cardSize + margin),
            y: row * (cardSize + margin)
        });
    }
}

function drawCard(card) {
    ctx.fillStyle = card.revealed ? 'lightgreen' : 'lightblue';
    ctx.fillRect(card.x, card.y, cardSize, cardSize);
    if (card.revealed) {
        ctx.fillStyle = 'black';
        ctx.font = '20px Arial';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(card.value, card.x + cardSize / 2, card.y + cardSize / 2);
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    cards.forEach(drawCard);
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
    ctx.fillText(`High Score: ${highScore}`, 10, 60);
}

function update(timestamp) {
    const deltaTime = timestamp - lastTimestamp;
    if (deltaTime >= fixedTimestep) {
        lastTimestamp = timestamp;
        // Update game logic here
        if (firstCard && secondCard) {
            if (firstCard.value !== secondCard.value) {
                firstCard.revealed = false;
                secondCard.revealed = false;
            } else {
                score++;
                if (score > highScore) {
                    highScore = score;
                    localStorage.setItem('highScore', highScore);
                }
            }
            firstCard = secondCard = null;
            isFlipping = false;
        }
    }
    draw();
    requestAnimationFrame(update);
}

canvas.addEventListener('click', (event) => {
    if (isFlipping) return;
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    const clickedCard = cards.find(card => x > card.x && x < card.x + cardSize && y > card.y && y < card.y + cardSize);
    if (clickedCard && !clickedCard.revealed) {
        clickedCard.revealed = true;
        if (!firstCard) {
            firstCard = clickedCard;
        } else {
            secondCard = clickedCard;
            isFlipping = true;
        }
    }
});

createCards();
requestAnimationFrame(update);
