const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 400;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const gravity = 0.5;
const jumpStrength = -10;
const playerSize = 20;
const gapSize = 100;
const gapMin = 50;
const gapMax = 200;
const obstacleSpeed = 3;
const maxHealth = 5;
const healthBarHeight = 10;

let playerX = 50;
let playerY = canvas.height / 2;
let playerVelocity = 0;
let playerHealth = maxHealth;
let obstacles = [];
let gameRunning = true;
let lastTimestamp = 0;
let fixedTimestep = 1000 / 60; // 60 FPS

function drawPlayer() {
  ctx.fillStyle = 'blue';
  ctx.fillRect(playerX, playerY, playerSize, playerSize);
}

function drawHealthBar() {
  ctx.fillStyle = 'red';
  ctx.fillRect(0, 0, canvas.width, healthBarHeight);
  ctx.fillStyle = 'green';
  ctx.fillRect(0, 0, (canvas.width / maxHealth) * playerHealth, healthBarHeight);
}

function drawObstacles() {
  ctx.fillStyle = 'black';
  obstacles.forEach(obstacle => {
    ctx.fillRect(obstacle.x, 0, playerSize, obstacle.gapTop);
    ctx.fillRect(obstacle.x, obstacle.gapTop + gapSize, playerSize, canvas.height);
  });
}

function drawGameOver() {
  ctx.fillStyle = 'black';
  ctx.font = '30px Arial';
  ctx.fillText('Game Over', canvas.width / 2 - 60, canvas.height / 2);
}

function updatePlayer(timestamp) {
  const delta = timestamp - lastTimestamp;
  playerVelocity += gravity;
  playerY += playerVelocity * (delta / fixedTimestep);

  if (playerY + playerSize > canvas.height || playerY < 0) {
    playerHealth--;
    if (playerHealth <= 0) {
      gameRunning = false;
    } else {
      respawnPlayer();
    }
  }
}

function respawnPlayer() {
  playerY = canvas.height / 2;
  playerVelocity = 0;
}

function updateObstacles(timestamp) {
  obstacles.forEach(obstacle => {
    obstacle.x -= obstacleSpeed * (timestamp - lastTimestamp) / fixedTimestep;
  });

  if (obstacles.length === 0 || obstacles[obstacles.length - 1].x < canvas.width - 200) {
    const gapTop = gapMin + Math.random() * (gapMax - gapMin);
    obstacles.push({ x: canvas.width, gapTop });
  }

  obstacles = obstacles.filter(obstacle => obstacle.x + playerSize > 0);

  if (obstacles.some(obstacle => 
      playerX < obstacle.x + playerSize &&
      playerX + playerSize > obstacle.x &&
      (playerY < obstacle.gapTop || playerY + playerSize > obstacle.gapTop + gapSize)
    )) {
    playerHealth--;
    if (playerHealth <= 0) {
      gameRunning = false;
    } else {
      respawnPlayer();
    }
  }
}

function update(timestamp) {
  if (!gameRunning) return;

  ctx.clearRect(0, 0, canvas.width, canvas.height);

  updatePlayer(timestamp);
  updateObstacles(timestamp);

  drawHealthBar();
  drawPlayer();
  drawObstacles();

  lastTimestamp = timestamp;
  requestAnimationFrame(update);
}

function handleKeyDown(event) {
  if (event.code === 'Space') {
    playerVelocity = jumpStrength;
  }
}

document.addEventListener('keydown', handleKeyDown);

update(performance.now());
