const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = 800;
canvas.height = 600;

class Player {
    constructor() {
        this.x = canvas.width / 2;
        this.y = canvas.height / 2;
        this.width = 20;
        this.height = 20;
        this.speed = 5;
        this.bullets = [];
    }

    draw() {
        ctx.fillStyle = 'blue';
        ctx.fillRect(this.x, this.y, this.width, this.height);
        this.bullets.forEach(bullet => bullet.draw());
    }

    update(keys) {
        if (keys['ArrowLeft']) this.x -= this.speed;
        if (keys['ArrowRight']) this.x += this.speed;
        if (keys['ArrowUp']) this.y -= this.speed;
        if (keys['ArrowDown']) this.y += this.speed;
        this.bullets = this.bullets.filter(bullet => bullet.update());
    }

    shoot() {
        this.bullets.push(new Bullet(this.x + this.width / 2, this.y));
    }
}

class Bullet {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.width = 3;
        this.height = 3;
        this.speed = 10;
    }

    draw() {
        ctx.fillStyle = 'white';
        ctx.fillRect(this.x, this.y, this.width, this.height);
    }

    update() {
        this.y -= this.speed;
        return this.y > 0;
    }
}

class Enemy {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.width = 40;
        this.height = 40;
        this.speed = 2;
    }

    draw() {
        ctx.fillStyle = 'red';
        ctx.fillRect(this.x, this.y, this.width, this.height);
    }

    update() {
        this.y += this.speed;
        return this.y < canvas.height;
    }
}

const player = new Player();
const enemies = [];
let spawnInterval = 1000;
let lastSpawn = Date.now();
let keys = {};

document.addEventListener('keydown', e => keys[e.key] = true);
document.addEventListener('keyup', e => keys[e.key] = false);

function spawnEnemy() {
    const x = Math.random() * (canvas.width - 40);
    enemies.push(new Enemy(x, 0));
}

function checkCollisions() {
    player.bullets.forEach((bullet, bulletIndex) => {
        enemies.forEach((enemy, enemyIndex) => {
            if (bullet.x < enemy.x + enemy.width &&
                bullet.x + bullet.width > enemy.x &&
                bullet.y < enemy.y + enemy.height &&
                bullet.y + bullet.height > enemy.y) {
                enemies.splice(enemyIndex, 1);
                player.bullets.splice(bulletIndex, 1);
            }
        });
    });
}

function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (Date.now() - lastSpawn > spawnInterval) {
        spawnEnemy();
        lastSpawn = Date.now();
        spawnInterval = Math.max(500, spawnInterval - 50); // Increase difficulty
    }

    player.update(keys);
    if (keys[' ']) player.shoot();

    enemies.forEach((enemy, index) => {
        enemy.draw();
        if (!enemy.update()) enemies.splice(index, 1);
    });

    player.draw();
    checkCollisions();

    requestAnimationFrame(gameLoop);
}

gameLoop();
