const ctx = canvas.getContext('2d');

let state = 'menu';
let ball = { x: 100, y: 50, radius: 10, dy: 2 };
let score = 0;
let highScore = 0;

function resizeCanvas() {
  canvas.width = window.innerWidth * devicePixelRatio;
  canvas.height = window.innerHeight * devicePixelRatio;
  ctx.scale(devicePixelRatio, devicePixelRatio);
}

window.addEventListener('resize', resizeCanvas);
resizeCanvas();

function updateMenu() {
  if (keyboard.space) {
    state = 'playing';
    ball = { x: 100, y: 50, radius: 10, dy: 2 };
    score = 0;
  }
}

function updatePlaying() {
  ball.y += ball.dy;
  if (ball.y + ball.radius > canvas.height) {
    ball.y = canvas.height - ball.radius;
    ball.dy = -ball.dy;
    score++;
    highScore = Math.max(score, highScore);
  }
  if (keyboard.space) {
    state = 'paused';
  }
}

function updatePaused() {
  if (keyboard.space) {
    state = 'playing';
  }
}

function updateGameOver() {
  if (keyboard.space) {
    state = 'menu';
  }
}

function drawMenu() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.font = '30px Arial';
  ctx.fillStyle = 'black';
  ctx.fillText('Press SPACE to Start', 50, canvas.height / 2);
}

function drawPlaying() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.beginPath();
  ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
  ctx.fillStyle = 'red';
  ctx.fill();
  ctx.font = '20px Arial';
  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`High Score: ${highScore}`, 10, 50);
}

function drawPaused() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.font = '30px Arial';
  ctx.fillStyle = 'black';
  ctx.fillText('Game Paused', 50, canvas.height / 2);
  ctx.fillText('Press SPACE to Resume', 50, canvas.height / 2 + 30);
}

function drawGameOver() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.font = '30px Arial';
  ctx.fillStyle = 'black';
  ctx.fillText('Game Over', 50, canvas.height / 2);
  ctx.fillText(`Your Score: ${score}`, 50, canvas.height / 2 + 30);
  ctx.fillText('Press SPACE to Restart', 50, canvas.height / 2 + 60);
}

const keyboard = { space: false };
window.addEventListener('keydown', (e) => {
  if (e.code === 'Space') {
    keyboard.space = true;
  }
});
window.addEventListener('keyup', (e) => {
  if (e.code === 'Space') {
    keyboard.space = false;
  }
});

function gameLoop() {
  switch (state) {
    case 'menu':
      updateMenu();
      drawMenu();
      break;
    case 'playing':
      updatePlaying();
      drawPlaying();
      break;
    case 'paused':
      updatePaused();
      drawPaused();
      break;
    case 'gameover':
      updateGameOver();
      drawGameOver();
      break;
  }
  requestAnimationFrame(gameLoop);
}

