// Constants
const CANVAS_WIDTH = 400;
const CANVAS_HEIGHT = 600;
const FLAP_SPEED = -5;
const GRAVITY = 0.5;
const GAP_HEIGHT = 100;
const PIPE_WIDTH = 50;
const PIPE_GAP = 150;
const PIPE_SPEED = -2;

// Variables
let score = 0;
let highScore = localStorage.getItem('highScore') ? parseInt(localStorage.getItem('highScore')) : 0;
let isGameOver = false;

// Elements
const canvas = document.createElement('canvas');
const ctx = canvas.getContext('2d');
canvas.width = CANVAS_WIDTH;
canvas.height = CANVAS_HEIGHT;
document.body.appendChild(canvas);

// Bird
const bird = {
  x: 50,
  y: CANVAS_HEIGHT / 2,
  width: 20,
  height: 20,
  velocity: 0
};

// Pipes
const pipes = [];

// Functions
function drawBackground() {
  ctx.fillStyle = '#87CEEB';
  ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
}

function drawBird() {
  ctx.fillStyle = '#FFD700';
  ctx.fillRect(bird.x, bird.y, bird.width, bird.height);
}

function drawPipes() {
  pipes.forEach(pipe => {
    ctx.fillStyle = '#32CD32';
    ctx.fillRect(pipe.x, 0, pipe.width, pipe.height);
    ctx.fillRect(pipe.x, pipe.height + GAP_HEIGHT, pipe.width, CANVAS_HEIGHT - pipe.height - GAP_HEIGHT);
  });
}

function drawScore() {
  ctx.fillStyle = '#000';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`High Score: ${highScore}`, 10, 60);
}

function updateBird() {
  bird.velocity += GRAVITY;
  bird.y += bird.velocity;
  if (bird.y + bird.height > CANVAS_HEIGHT || bird.y < 0) {
    gameOver();
  }
}

function updatePipes() {
  pipes.forEach(pipe => {
    pipe.x += PIPE_SPEED;
  });
  pipes = pipes.filter(pipe => pipe.x + pipe.width > 0);

  if (pipes.length === 0 || pipes[pipes.length - 1].x < CANVAS_WIDTH - PIPE_GAP * 2) {
    const pipeHeight = Math.random() * (CANVAS_HEIGHT - GAP_HEIGHT) + GAP_HEIGHT / 2;
    pipes.push({
      x: CANVAS_WIDTH,
      y: 0,
      width: PIPE_WIDTH,
      height: pipeHeight
    });
  }
}

function checkCollision() {
  pipes.forEach(pipe => {
    if (bird.x < pipe.x + pipe.width && bird.x + bird.width > pipe.x &&
        (bird.y < pipe.height || bird.y + bird.height > pipe.height + GAP_HEIGHT)) {
      gameOver();
    }
  });
}

function gameOver() {
  isGameOver = true;
  if (score > highScore) {
    highScore = score;
    localStorage.setItem('highScore', highScore.toString());
  }
  alert(`Game Over! Your Score: ${score}. High Score: ${highScore}`);
}

function resetGame() {
  score = 0;
  isGameOver = false;
  bird.y = CANVAS_HEIGHT / 2;
  bird.velocity = 0;
  pipes.length = 0;
}

function draw() {
  drawBackground();
  drawBird();
  drawPipes();
  drawScore();
}

function update() {
  if (!isGameOver) {
    updateBird();
    updatePipes();
    checkCollision();
    score++;
  }
}

function gameLoop() {
  if (!isGameOver) {
    update();
  }
  draw();
  requestAnimationFrame(gameLoop);
}

function flap() {
  if (!isGameOver) {
    bird.velocity = FLAP_SPEED;
  }
}

// Event Listeners
document.addEventListener('keydown', e => {
  if (e.code === 'Space') {
    flap();
  }
});

// Start Game
resetGame();
gameLoop();
