class Crop {
  constructor(name, growthRate) {
    this.name = name;
    this.growthRate = growthRate;
    this.stage = 0; // 0: planted, 1: growing, 2: ready for harvest
  }

  grow() {
    if (this.stage < 2) {
      this.stage += this.growthRate;
      if (this.stage > 2) this.stage = 2;
    }
  }

  isReadyForHarvest() {
    return this.stage === 2;
  }

  harvest() {
    if (this.isReadyForHarvest()) {
      this.stage = 0;
      return true;
    }
    return false;
  }

  getName() {
    return this.name;
  }
}

class Farm {
  constructor(market) {
    this.market = market;
    this.crops = [];
  }

  plantCrop(name, growthRate) {
    const crop = new Crop(name, growthRate);
    this.crops.push(crop);
  }

  growAllCrops() {
    this.crops.forEach(crop => crop.grow());
  }

  harvestReadyCrops() {
    const harvestedCrops = this.crops.filter(crop => {
      if (crop.isReadyForHarvest()) {
        this.market.sellCrop(crop.getName());
        return true;
      }
      return false;
    });
    return harvestedCrops.map(crop => crop.getName());
  }
}

class Market {
  constructor() {
    this.inventory = {};
  }

  sellCrop(name) {
    if (this.inventory[name]) {
      this.inventory[name]++;
    } else {
      this.inventory[name] = 1;
    }
  }

  getInventory() {
    return this.inventory;
  }
}

// Demo
const market = new Market();
const farm = new Farm(market);

farm.plantCrop('Tomato', 1);
farm.plantCrop('Carrot', 2);

console.log("Day 1: Growing crops");
