class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Skill {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('levelUp', this.onLevelUp.bind(this));
  }

  learn(skillName) {
    console.log(`Learning ${skillName}`);
    this.eventBus.emit('skillLearned', skillName);
  }

  onLevelUp(level) {
    console.log(`Leveling up to ${level}, learning new skills...`);
    this.learn(`Advanced Skill ${level}`);
  }
}

class Experience {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('skillLearned', this.onSkillLearned.bind(this));
    this.experiencePoints = 0;
  }

  gainExperience(points) {
    this.experiencePoints += points;
    console.log(`Gained ${points} experience points, total: ${this.experiencePoints}`);
    this.checkLevelUp();
  }

  onSkillLearned(skillName) {
    console.log(`Skill learned: ${skillName}, gaining experience...`);
    this.gainExperience(100);
  }

  checkLevelUp() {
    const level = Math.floor(this.experiencePoints / 1000) + 1;
    this.eventBus.emit('levelUp', level);
  }
}

class LevelUp {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('levelUp', this.onLevelUp.bind(this));
    this.currentLevel = 1;
  }

  onLevelUp(level) {
    if (level > this.currentLevel) {
      this.currentLevel = level;
      console.log(`Level up! New level: ${level}`);
    }
  }
}

