// Define the game settings
const canvas = document.createElement('canvas');
const ctx = canvas.getContext('2d');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;

const cardWidth = 100;
const cardHeight = 150;
const margin = 10;
const columns = 4;
const rows = 3;
const totalCards = columns * rows;
const cardPairs = totalCards / 2;
const cardColors = ['red', 'green', 'blue', 'yellow', 'purple', 'orange', 'cyan', 'magenta'];
const cardBack = 'grey';

let cards = [];
let flippedCards = [];
let score = 0;
let gameOver = false;

// Initialize the game
function init() {
    score = 0;
    gameOver = false;
    cards = [];
    flippedCards = [];
    const shuffledColors = shuffle([...cardColors, ...cardColors]);
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < columns; j++) {
            cards.push({
                x: j * (cardWidth + margin),
                y: i * (cardHeight + margin),
                color: shuffledColors[i * columns + j],
                flipped: false
            });
        }
    }
}

// Shuffle an array
function shuffle(array) {
    for (let i = array.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [array[i], array[j]] = [array[j], array[i]];
    }
    return array;
}

// Render the game
function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    cards.forEach(card => {
        if (card.flipped || gameOver) {
            ctx.fillStyle = card.color;
        } else {
            ctx.fillStyle = cardBack;
        }
        ctx.fillRect(card.x, card.y, cardWidth, cardHeight);
    });
    ctx.fillStyle = 'black';
    ctx.font = '24px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
}

// Check for a match
function checkMatch() {
    if (flippedCards.length === 2) {
        if (flippedCards[0].color === flippedCards[1].color) {
            score += 10;
            if (score === cardPairs * 10) {
                gameOver = true;
            }
        } else {
            flippedCards.forEach(card => {
                setTimeout(() => {
                    card.flipped = false;
                }, 1000);
            });
        }
        flippedCards = [];
    }
}

// Flip a card
function flipCard(x, y) {
    const card = cards.find(card => x > card.x && x < card.x + cardWidth && y > card.y && y < card.y + cardHeight);
    if (card && !card.flipped && !gameOver) {
        card.flipped = true;
        flippedCards.push(card);
        checkMatch();
    }
}

// Game loop
function gameLoop() {
    render();
    if (!gameOver) {
        requestAnimationFrame(gameLoop);
    }
}

// Event listeners
canvas.addEventListener('click', (event) => {
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    flipCard(x, y);
});

// Start the game
init();
gameLoop();
