const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const cardWidth = 100;
const cardHeight = 150;
const margin = 10;
const grid = 4; // 4x4 grid
let cards = [];
let flippedCards = [];
let matchedPairs = 0;
let timeLeft = 60; // 60 seconds
let timerInterval;
let isFlipping = false;

function shuffle(array) {
    for (let i = array.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [array[i], array[j]] = [array[j], array[i]];
    }
}

function createCards() {
    const icons = ['🔥', '🌊', '🌳', '🚀', '🌌', '🌈', '🌍', '🌙'];
    let iconsDoubled = [...icons, ...icons];
    shuffle(iconsDoubled);

    for (let i = 0; i < grid * grid; i++) {
        cards.push({
            x: (i % grid) * (cardWidth + margin) + margin,
            y: Math.floor(i / grid) * (cardHeight + margin) + margin,
            icon: iconsDoubled[i],
            flipped: false,
            matched: false
        });
    }
}

function drawCard(card) {
    ctx.fillStyle = card.flipped || card.matched ? 'lightblue' : 'lightgray';
    ctx.fillRect(card.x, card.y, cardWidth, cardHeight);
    if (card.flipped) {
        ctx.font = '36px Arial';
        ctx.fillStyle = 'black';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(card.icon, card.x + cardWidth / 2, card.y + cardHeight / 2);
    }
}

function drawTimer() {
    ctx.fillStyle = 'black';
    ctx.font = '24px Arial';
    ctx.fillText(`Time: ${timeLeft}s`, margin, canvas.height - margin);
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    cards.forEach(drawCard);
    drawTimer();
    requestAnimationFrame(draw);
}

function checkForMatch() {
    if (flippedCards.length === 2) {
        isFlipping = true;
        setTimeout(() => {
            if (flippedCards[0].icon === flippedCards[1].icon) {
                flippedCards[0].matched = true;
                flippedCards[1].matched = true;
                matchedPairs++;
            } else {
                flippedCards[0].flipped = false;
                flippedCards[1].flipped = false;
            }
            flippedCards = [];
            isFlipping = false;
        }, 500);
    }
}

function onCanvasClick(event) {
    if (isFlipping) return;
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;

    const clickedCard = cards.find(card => x > card.x && x < card.x + cardWidth && y > card.y && y < card.y + cardHeight);
    if (clickedCard && !clickedCard.flipped && !clickedCard.matched) {
        clickedCard.flipped = true;
        flippedCards.push(clickedCard);
        checkForMatch();
    }
}

function startTimer() {
    timerInterval = setInterval(() => {
        timeLeft--;
        if (timeLeft <= 0) {
            clearInterval(timerInterval);
            alert('Time\'s up! Game Over.');
        }
    }, 1000);
}

function resizeCanvas() {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
}

window.addEventListener('resize', resizeCanvas);
canvas.addEventListener('click', onCanvasClick);

createCards();
resizeCanvas();
draw();
startTimer();
