const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const TILE_SIZE = 32;
const ROOM_WIDTH = 20;
const ROOM_HEIGHT = 15;
const PLAYER = 'P';
const ENEMY = 'E';
const WALL = '#';
const FLOOR = '.';

class Room {
    constructor(width, height) {
        this.width = width;
        this.height = height;
        this.grid = Array.from({ length: height }, () => Array(width).fill(WALL));
        this.generateRoom();
    }

    generateRoom() {
        for (let y = 1; y < this.height - 1; y++) {
            for (let x = 1; x < this.width - 1; x++) {
                this.grid[y][x] = Math.random() > 0.7 ? WALL : FLOOR;
            }
        }
        this.grid[1][1] = PLAYER;
        this.grid[this.height - 2][this.width - 2] = ENEMY;
    }

    draw() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        for (let y = 0; y < this.height; y++) {
            for (let x = 0; x < this.width; x++) {
                ctx.fillStyle = this.grid[y][x] === WALL ? 'gray' : 'white';
                ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
                ctx.strokeStyle = 'black';
                ctx.strokeRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
            }
        }
    }

    movePlayer(dx, dy) {
        const [px, py] = this.find(PLAYER);
        const nx = px + dx;
        const ny = py + dy;
        if (nx >= 0 && nx < this.width && ny >= 0 && ny < this.height && this.grid[ny][nx] === FLOOR) {
            this.grid[ny][nx] = PLAYER;
            this.grid[py][px] = FLOOR;
        }
    }

    find(target) {
        for (let y = 0; y < this.height; y++) {
            for (let x = 0; x < this.width; x++) {
                if (this.grid[y][x] === target) {
                    return [x, y];
                }
            }
        }
        return [-1, -1];
    }

    moveEnemy() {
        const [ex, ey] = this.find(ENEMY);
        const [px, py] = this.find(PLAYER);
        const dx = px - ex;
        const dy = py - ey;
        const moveX = dx !== 0 ? (dx > 0 ? 1 : -1) : 0;
        const moveY = dy !== 0 ? (dy > 0 ? 1 : -1) : 0;
        if (this.grid[ey + moveY] && this.grid[ey + moveY][ex + moveX] === FLOOR) {
            this.grid[ey + moveY][ex + moveX] = ENEMY;
            this.grid[ey][ex] = FLOOR;
        }
