// Constants for the game
const CANVAS_ID = 'gameCanvas';
const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 600;
const PLAYER_SIZE = 50;
const ENEMY_SIZE = 50;
const PLAYER_COLOR = 'blue';
const ENEMY_COLOR = 'red';
const BACKGROUND_COLOR = 'gray';
const FPS = 60;

// Game state
let playerPosition = { x: CANVAS_WIDTH / 2 - PLAYER_SIZE / 2, y: CANVAS_HEIGHT - PLAYER_SIZE - 10 };
let enemyPosition = { x: CANVAS_WIDTH / 2 - ENEMY_SIZE / 2, y: 10 };
let playerScore = 0;
let enemyScore = 0;
let isGameOver = false;

// Canvas setup
const canvas = document.createElement('canvas');
canvas.id = CANVAS_ID;
canvas.width = CANVAS_WIDTH * devicePixelRatio;
canvas.height = CANVAS_HEIGHT * devicePixelRatio;
canvas.style.width = `${CANVAS_WIDTH}px`;
canvas.style.height = `${CANVAS_HEIGHT}px`;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
ctx.scale(devicePixelRatio, devicePixelRatio);

// Game loop
function gameLoop() {
    if (isGameOver) return;

    update();
    render();

    requestAnimationFrame(gameLoop);
}

// Update game state
function update() {
    // Example: Move player left/right
    if (keys['ArrowLeft'] && playerPosition.x > 0) {
        playerPosition.x -= 5;
    }
    if (keys['ArrowRight'] && playerPosition.x < CANVAS_WIDTH - PLAYER_SIZE) {
        playerPosition.x += 5;
    }

    // Example: Move enemy towards player
    if (enemyPosition.x < playerPosition.x) {
        enemyPosition.x += 2;
    } else if (enemyPosition.x > playerPosition.x) {
        enemyPosition.x -= 2;
    }

    // Check for collision
    if (checkCollision(playerPosition, enemyPosition)) {
        playerScore++;
        enemyScore++;
        resetPositions();
    }
}

// Render game
function render() {
    ctx.fillStyle = BACKGROUND_COLOR;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    ctx.fillStyle = PLAYER_COLOR;
    ctx.fillRect(playerPosition.x, playerPosition.y, PLAYER_SIZE, PLAYER_SIZE);

    ctx.fillStyle = ENEMY_COLOR;
    ctx.fillRect(enemyPosition.x, enemyPosition.y, ENEMY_SIZE, ENEMY_SIZE);

    ctx.fillStyle = 'black';
    ctx.font = '24px Arial';
    ctx.fillText(`Player: ${playerScore}`, 10, 30);
    ctx.fillText(`Enemy: ${enemyScore}`, 10, 60);

    if (playerScore >= 5 || enemyScore >= 5) {
        isGameOver = true;
        ctx.fillStyle = 'black';
        ctx.font = '48px Arial';
        ctx.textAlign = 'center';
        ctx.fillText('Game Over', CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
    }
}

// Collision detection
function checkCollision(rect1, rect2) {
    return !(rect1.x > rect2.x + rect2.width ||
             rect1.x + rect1.width < rect2.x ||
             rect1.y > rect2.y + rect2.height ||
             rect1.y + rect1.height < rect2.y);
}

// Reset positions after collision
function resetPositions() {
    playerPosition = { x: CANVAS_WIDTH / 2 - PLAYER_SIZE / 2, y: CANVAS_HEIGHT - PLAYER_SIZE - 10 };
    enemyPosition = { x: CANVAS_WIDTH / 2 - ENEMY_SIZE / 2, y: 10 };
}

// Handle keyboard input
const keys = {};
window.addEventListener('keydown', function(e) {
    keys[e.key] = true;
});
window.addEventListener('keyup', function(e) {
    keys[e.key] = false;
});

// Start the game
requestAnimationFrame(gameLoop);
