class LevelUp {
    constructor(skill, experience, levelThresholds) {
        this.skill = skill;
        this.experience = experience;
        this.levelThresholds = levelThresholds;
    }

    gainExperience(points) {
        this.experience.addPoints(points);
        this.checkLevelUp();
    }

    checkLevelUp() {
        const currentPoints = this.experience.getPoints();
        for (let level = this.skill.getLevel() + 1; level <= this.levelThresholds.length; level++) {
            if (currentPoints >= this.levelThresholds[level - 1]) {
                this.skill.setLevel(level);
                console.log(`Level up! ${this.skill.getName()} is now level ${level}.`);
            } else {
                break;
            }
        }
    }
}

