    x: roomWidth / 2,
    y: roomHeight / 2,
    speed: 2,
    move: function(dx, dy) {
        this.x = Math.max(0, Math.min(roomWidth - 1, this.x + dx));
        this.y = Math.max(0, Math.min(roomHeight - 1, this.y + dy));
    }
};

const tiles = Array.from({ length: roomHeight }, () => Array(roomWidth).fill(0));

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let y = 0; y < roomHeight; y++) {
        for (let x = 0; x < roomWidth; x++) {
            ctx.fillStyle = tiles[y][x] ? '#000' : '#fff';
            ctx.fillRect(x * tileSize, y * tileSize, tileSize, tileSize);
        }
    }
    ctx.fillStyle = '#f00';
    ctx.fillRect(player.x * tileSize, player.y * tileSize, tileSize, tileSize);
}

canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = Math.floor((e.clientX - rect.left) / tileSize);
    const y = Math.floor((e.clientY - rect.top) / tileSize);
    player.move(x - player.x, y - player.y);
});

canvas.addEventListener('click', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = Math.floor((e.clientX - rect.left) / tileSize);
    const y = Math.floor((e.clientY - rect.top) / tileSize);
    tiles[y][x] = 1 - tiles[y][x];
});

document.addEventListener('keydown', (e) => {
    switch (e.key) {
        case 'ArrowUp': player.move(0, -1); break;
        case 'ArrowDown': player.move(0, 1); break;
        case 'ArrowLeft': player.move(-1, 0); break;
        case 'ArrowRight': player.move(1, 0); break;
    }
});

const fixedTimestep = 1000 / 60; // 60 FPS
let lastTime = performance.now();

function gameLoop() {
    const now = performance.now();
    const deltaTime = now - lastTime;
    lastTime = now;

    if (deltaTime >= fixedTimestep) {
        draw();
    }

    requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
