class RarityTable {
  constructor() {
    this.table = [
      { rarity: "Common", chance: 0.6 },
      { rarity: "Uncommon", chance: 0.3 },
      { rarity: "Rare", chance: 0.08 },
      { rarity: "Epic", chance: 0.01 },
      { rarity: "Legendary", chance: 0.01 }
    ];
  }

  rollRarity() {
    const roll = Math.random();
    let cumulativeChance = 0;

    for (const entry of this.table) {
      cumulativeChance += entry.chance;
      if (roll < cumulativeChance) {
        return entry.rarity;
      }
    }

    return "Common"; // Fallback to common if something goes wrong
  }
}

class Inventory {
  constructor() {
    this.items = [];
  }

  addItem(item) {
    this.items.push(item);
  }

  getInventory() {
    return this.items;
  }

  getTotalValue() {
    return this.items.reduce((total, item) => total + item.getValue(), 0);
  }
}

class GameCoordinator {
  constructor() {
    this.rarityTable = new RarityTable();
    this.inventory = new Inventory();
  }

  generateLoot() {
    const rarity = this.rarityTable.rollRarity();
    let value = 0;

    switch (rarity) {
      case "Common":
        value = Math.floor(Math.random() * 10) + 1;
        break;
      case "Uncommon":
        value = Math.floor(Math.random() * 20) + 11;
        break;
      case "Rare":
        value = Math.floor(Math.random() * 50) + 21;
        break;
      case "Epic":
        value = Math.floor(Math.random() * 100) + 51;
        break;
      case "Legendary":
        value = Math.floor(Math.random() * 500) + 101;
        break;
    }

    const loot = new Loot(`${rarity} Loot`, value);
    this.inventory.addItem(loot);
    return loot;
  }

