  });
}

function movePlayer() {
  const speed = player.speed;
  player.x += speed * Math.cos(player.angle);
  player.y += speed * Math.sin(player.angle);
}

function moveAI() {
  const speed = ai.speed;
  ai.x += speed * Math.cos(ai.angle);
  ai.y += speed * Math.sin(ai.angle);

  // Simple AI: Shoot towards player
  const angleToPlayer = Math.atan2(player.y - ai.y, player.x - ai.x);
  ai.angle = angleToPlayer;
  aiBullets.push({
    x: ai.x,
    y: ai.y,
    size: 3,
    speed: 10,
    angle: angleToPlayer
  });
