class Building {
  constructor() {
    this.buildings = {};
  }

  addBuilding(type, count) {
    if (this.buildings[type]) {
      this.buildings[type] += count;
    } else {
      this.buildings[type] = count;
    }
  }

  getBuildingCount(type) {
    return this.buildings[type] || 0;
  }
}

class Resource {
  constructor() {
    this.resources = {};
  }

  addResource(type, amount) {
    if (this.resources[type]) {
      this.resources[type] += amount;
    } else {
      this.resources[type] = amount;
    }
  }

  getResourceAmount(type) {
    return this.resources[type] || 0;
  }

  consumeResource(type, amount) {
    if (this.resources[type] >= amount) {
      this.resources[type] -= amount;
      return true;
    }
    return false;
  }
}

class Economy {
  constructor(buildingSystem, resourceSystem) {
    this.buildingSystem = buildingSystem;
    this.resourceSystem = resourceSystem;
  }

  produceResources() {
    const woodMills = this.buildingSystem.getBuildingCount('woodMill');
    const foodFarms = this.buildingSystem.getBuildingCount('foodFarm');

    this.resourceSystem.addResource('wood', woodMills * 10);
    this.resourceSystem.addResource('food', foodFarms * 5);
  }

  consumeResources() {
    const consumedWood = this.resourceSystem.consumeResource('wood', 5);
    const consumedFood = this.resourceSystem.consumeResource('food', 3);

    return { consumedWood, consumedFood };
  }
}

