// Match-3 Board Game with High Score

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.style.width = '100vw';
canvas.style.height = '100vh';
canvas.width = canvas.clientWidth * devicePixelRatio;
canvas.height = canvas.clientHeight * devicePixelRatio;
const ctx = canvas.getContext('2d');

const BOARD_SIZE = 8;
const TILE_SIZE = canvas.width / BOARD_SIZE;
const COLORS = ['#FF5733', '#33FF57', '#3357FF', '#F333FF', '#33FFF7'];
let board = [];
let score = 0;
let highScore = localStorage.getItem('highScore') || 0;

function initBoard() {
    for (let i = 0; i < BOARD_SIZE; i++) {
        board[i] = [];
        for (let j = 0; j < BOARD_SIZE; j++) {
            board[i][j] = Math.floor(Math.random() * COLORS.length);
        }
    }
}

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let i = 0; i < BOARD_SIZE; i++) {
        for (let j = 0; j < BOARD_SIZE; j++) {
            ctx.fillStyle = COLORS[board[i][j]];
            ctx.fillRect(i * TILE_SIZE, j * TILE_SIZE, TILE_SIZE, TILE_SIZE);
            ctx.strokeStyle = '#000';
            ctx.strokeRect(i * TILE_SIZE, j * TILE_SIZE, TILE_SIZE, TILE_SIZE);
        }
    }
    ctx.fillStyle = '#000';
    ctx.fillText(`Score: ${score}`, 10, 20);
    ctx.fillText(`High Score: ${highScore}`, 10, 40);
}

function checkMatches() {
    let matches = [];
    for (let i = 0; i < BOARD_SIZE; i++) {
        for (let j = 0; j < BOARD_SIZE - 2; j++) {
            if (board[i][j] === board[i][j + 1] && board[i][j] === board[i][j + 2]) {
                matches.push([i, j], [i, j + 1], [i, j + 2]);
            }
        }
    }
    for (let j = 0; j < BOARD_SIZE; j++) {
        for (let i = 0; i < BOARD_SIZE - 2; i++) {
            if (board[i][j] === board[i + 1][j] && board[i][j] === board[i + 2][j]) {
                matches.push([i, j], [i + 1, j], [i + 2, j]);
            }
        }
    }
    return matches;
}

function removeMatches(matches) {
    for (const [i, j] of matches) {
        board[i][j] = -1;
        score += 10;
    }
    for (let j = 0; j < BOARD_SIZE; j++) {
        let emptyCount = 0;
        for (let i = BOARD_SIZE - 1; i >= 0; i--) {
            if (board[i][j] === -1) {
                emptyCount++;
            } else if (emptyCount > 0) {
                board[i + emptyCount][j] = board[i][j];
                board[i][j] = -1;
            }
        }
    }
    if (score > highScore) {
        highScore = score;
        localStorage.setItem('highScore', highScore);
    }
}

function gameLoop() {
    const matches = checkMatches();
    if (matches.length > 0) {
        removeMatches(matches);
        initBoard();
    }
    drawBoard();
    requestAnimationFrame(gameLoop);
}

initBoard();
gameLoop();

canvas.addEventListener('click', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = Math.floor((e.clientX - rect.left) / TILE_SIZE);
    const y = Math.floor((e.clientY - rect.top) / TILE_SIZE);
    if (x >= 0 && x < BOARD_SIZE && y >= 0 && y < BOARD_SIZE) {
        board[x][y] = Math.floor(Math.random() * COLORS.length);
        gameLoop();
    }
});
