ctx.scale(dpr, dpr);

const gridWidth = 10;
const gridHeight = 20;
const blockWidth = canvas.width / gridWidth;
const blockHeight = canvas.height / gridHeight;
const colors = ['#FF6347', '#4682B4', '#32CD32', '#FFD700', '#FF69B4'];

let grid = Array.from({ length: gridHeight }, () => Array(gridWidth).fill(0));
let currentBlock = createBlock();
let aiBlock = createBlock();
let aiNextBlock = createBlock();
let score = 0;

function createBlock() {
    const shapes = [
        [[1, 1, 1, 1]], // I
        [[1, 1], [1, 1]], // O
        [[1, 1, 0], [0, 1, 1]], // S
        [[0, 1, 1], [1, 1, 0]], // Z
        [[1, 1, 1], [0, 1, 0]], // T
        [[1, 1, 1], [1, 0, 0]], // L
        [[1, 1, 1], [0, 0, 1]]  // J
    ];
    const shape = shapes[Math.floor(Math.random() * shapes.length)];
    const color = colors[Math.floor(Math.random() * colors.length)];
    return { shape, color, x: Math.floor(gridWidth / 2) - Math.floor(shape[0].length / 2), y: 0 };
}

function drawBlock(block) {
    block.shape.forEach((row, y) => {
        row.forEach((cell, x) => {
            if (cell) {
                ctx.fillStyle = block.color;
                ctx.fillRect((block.x + x) * blockWidth, (block.y + y) * blockHeight, blockWidth, blockHeight);
                ctx.strokeStyle = '#000';
                ctx.strokeRect((block.x + x) * blockWidth, (block.y + y) * blockHeight, blockWidth, blockHeight);
            }
        });
    });
}

function drawGrid() {
    ctx.strokeStyle = '#ccc';
    for (let x = 0; x <= gridWidth; x++) {
        ctx.beginPath();
        ctx.moveTo(x * blockWidth, 0);
        ctx.lineTo(x * blockWidth, canvas.height);
        ctx.stroke();
    }
    for (let y = 0; y <= gridHeight; y++) {
        ctx.beginPath();
        ctx.moveTo(0, y * blockHeight);
        ctx.lineTo(canvas.width, y * blockHeight);
        ctx.stroke();
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawGrid();
    drawBlock(currentBlock);
    drawBlock(aiBlock);
}

function moveBlock(block, dx, dy) {
    if (canMove(block, dx, dy)) {
        block.x += dx;
        block.y += dy;
    }
}

function canMove(block, dx, dy) {
    return block.shape.every((row, y) => {
        return row.every((cell, x) => {
            const nx = block.x + x + dx;
            const ny = block.y + y + dy;
            return cell === 0 || (nx >= 0 && nx < gridWidth && ny < gridHeight && grid[ny][nx] === 0);
        });
    });
}

function placeBlock(block) {
    block.shape.forEach((row, y) => {
        row.forEach((cell, x) => {
            if (cell) {
                grid[block.y + y][block.x + x] = block.color;
            }
        });
    });
    currentBlock = aiNextBlock;
    aiNextBlock = createBlock();
    aiBlock = createBlock();
    clearLines();
}

function clearLines() {
    for (let y = gridHeight - 1; y >= 0; y--) {
        if (grid[y].every(cell => cell !== 0)) {
            grid.splice(y, 1);
            grid.unshift(Array(gridWidth).fill(0));
            score++;
        }
    }
}

function aiMove() {
    let bestScore = -Infinity;
    let bestBlock = null;

    const shapes = [
        [[1, 1, 1, 1]], // I
        [[1, 1], [1, 1]], // O
        [[1, 1, 0], [0, 1, 1]], // S
        [[0, 1, 1], [1, 1, 0]], // Z
        [[1, 1, 1], [0, 1, 0]], // T
        [[1, 1, 1], [1, 0, 0]], // L
        [[1, 1, 1], [0, 0, 1]]  // J
    ];

    for (let shape of shapes) {
        for (let rotation = 0; rotation < 4; rotation++) {
            let block = { shape: rotateShape(shape, rotation), color: colors[Math.floor(Math.random() * colors.length)], x: Math.floor(gridWidth / 2) - Math.floor(shape[0].length / 2), y: 0 };
            let moves = 0;
            while (canMove(block, 1, 0)) {
                block.x++;
                moves++;
            }
            let score = getScore(block);
            if (score > bestScore) {
                bestScore = score;
                bestBlock = { shape: rotateShape(shape, rotation), color: colors[Math.floor(Math.random() * colors.length)], x: Math.floor(gridWidth / 2) - Math.floor(shape[0].length / 2) - moves, y: 0 };
            }
        }
    }

    aiBlock = bestBlock;
}

function rotateShape(shape, rotation) {
    for (let i = 0; i < rotation; i++) {
        shape = shape[0].map((_, index) => shape.map(row => row[index]).reverse());
    }
    return shape;
}

function getScore(block) {
    let score = 0;
    for (let y = 0; y < gridHeight; y++) {
        let lineComplete = true;
        for (let x = 0; x < gridWidth; x++) {
            if (y < block.y || y >= block.y + block.shape.length || x < block.x || x >= block.x + block.shape[0].length || block.shape[y - block.y][x - block.x] === 0) {
                if (grid[y][x] === 0) {
                    lineComplete = false;
                    break;
                }
            }
        }
        if (lineComplete) {
            score++;
        }
    }
    return score;
}

function gameLoop() {
    moveBlock(currentBlock, 0, 1);
    if (currentBlock.y + currentBlock.shape.length >= gridHeight || grid.some((row, y) => currentBlock.shape[y - currentBlock.y].some((cell, x) => cell && row[currentBlock.x + x] !== 0))) {
        placeBlock(currentBlock);
        aiMove();
    }
    draw();
    requestAnimationFrame(gameLoop);
}

aiMove();
gameLoop();

window.addEventListener('keydown', (e) => {
    switch (e.key) {
        case 'ArrowLeft':
            moveBlock(currentBlock, -1, 0);
            break;
        case 'ArrowRight':
            moveBlock(currentBlock, 1, 0);
            break;
        case 'ArrowDown':
            moveBlock(currentBlock, 0, 1);
            break;
        case 'ArrowUp':
            currentBlock.shape = rotateShape(currentBlock.shape, 1);
            break;
    }
});

window.addEventListener('resize', () => {
    dpr = window.devicePixelRatio || 1;
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    canvas.style.width = `${window.innerWidth}px`;
    canvas.style.height = `${window.innerHeight}px`;
    ctx.scale(dpr, dpr);
    blockWidth = canvas.width / gridWidth;
    blockHeight = canvas.height / gridHeight;
});
