const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
let ctx = canvas.getContext('2d');
let dpr = window.devicePixelRatio || 1;

function resizeCanvas() {
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    ctx.scale(dpr, dpr);
}

resizeCanvas();
window.addEventListener('resize', resizeCanvas);

const cardWidth = 100;
const cardHeight = 150;
const padding = 10;
const colors = ['red', 'blue', 'green', 'yellow', 'purple', 'orange', 'cyan', 'magenta'];
let cards = [];
let flippedCards = [];
let comboMultiplier = 1;

function createCards() {
    let cardPairs = colors.concat(colors);
    cardPairs.sort(() => Math.random() - 0.5);
    for (let i = 0; i < cardPairs.length; i++) {
        cards.push({
            x: (i % 8) * (cardWidth + padding),
            y: Math.floor(i / 8) * (cardHeight + padding),
            color: cardPairs[i],
            flipped: false,
            matched: false
        });
    }
}

createCards();

function drawCard(card) {
    ctx.fillStyle = card.flipped || card.matched ? card.color : 'gray';
    ctx.fillRect(card.x, card.y, cardWidth, cardHeight);
    ctx.strokeStyle = 'black';
    ctx.strokeRect(card.x, card.y, cardWidth, cardHeight);
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    cards.forEach(drawCard);
    requestAnimationFrame(draw);
}

draw();

canvas.addEventListener('click', (event) => {
    let rect = canvas.getBoundingClientRect();
    let x = (event.clientX - rect.left) / dpr;
    let y = (event.clientY - rect.top) / dpr;
    let clickedCard = cards.find(card => x > card.x && x < card.x + cardWidth && y > card.y && y < card.y + cardHeight);

    if (clickedCard && !clickedCard.flipped && !clickedCard.matched) {
        clickedCard.flipped = true;
        flippedCards.push(clickedCard);

        if (flippedCards.length === 2) {
            setTimeout(() => {
                if (flippedCards[0].color === flippedCards[1].color) {
                    flippedCards[0].matched = true;
                    flippedCards[1].matched = true;
                    comboMultiplier++;
                } else {
                    flippedCards[0].flipped = false;
                    flippedCards[1].flipped = false;
                    comboMultiplier = 1;
                }
                flippedCards.length = 0;
            }, 500);
        }
    }
});
