const canvas = document.createElement('canvas');
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

class Entity {
    constructor(x, y, radius, color, velocity) {
        this.x = x;
        this.y = y;
        this.radius = radius;
        this.color = color;
        this.velocity = velocity;
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2, false);
        ctx.fillStyle = this.color;
        ctx.fill();
        ctx.closePath();
    }

    update() {
        this.draw();
        this.x += this.velocity.x;
        this.y += this.velocity.y;

        if (this.x + this.radius < 0 || this.x - this.radius > canvas.width || 
            this.y + this.radius < 0 || this.y - this.radius > canvas.height) {
            this.x = Math.random() * canvas.width;
            this.y = Math.random() * canvas.height;
        }
    }
}

class Ship extends Entity {
    constructor(x, y, radius, color, velocity) {
        super(x, y, radius, color, velocity);
        this.angle = 0;
    }

    draw() {
        ctx.save();
        ctx.translate(this.x, this.y);
        ctx.rotate(this.angle);
        ctx.beginPath();
        ctx.moveTo(0, -this.radius * 2);
        ctx.lineTo(-this.radius, this.radius * 2);
        ctx.lineTo(this.radius, this.radius * 2);
        ctx.closePath();
        ctx.fillStyle = this.color;
        ctx.fill();
        ctx.restore();
    }

    move(up, right) {
        const rad = Math.PI / 180 * this.angle;
        this.velocity.x = up * Math.cos(rad) + right * Math.sin(rad);
        this.velocity.y = up * Math.sin(rad) - right * Math.cos(rad);
    }

    turn(direction) {
        this.angle += direction;
    }
}

class Asteroid extends Entity {
    constructor(x, y, radius, color, velocity) {
        super(x, y, radius, color, velocity);
    }
}

class Bullet extends Entity {
    constructor(x, y, radius, color, velocity) {
        super(x, y, radius, color, velocity);
        this.lifeSpan = 100;
    }

    update() {
        super.update();
        this.lifeSpan--;
        if (this.lifeSpan <= 0) {
            this.markedForDeletion = true;
        }
    }
}

const player = new Ship(canvas.width / 2, canvas.height / 2, 10, 'white', { x: 0, y: 0 });
const asteroids = [];
const bullets = [];

for (let i = 0; i < 5; i++) {
    asteroids.push(new Asteroid(
        Math.random() * canvas.width,
        Math.random() * canvas.height,
        Math.random() * 20 + 10,
        'gray',
        {
            x: (Math.random() - 0.5) * 2,
            y: (Math.random() - 0.5) * 2
        }
    ));
}

let score = 0;
let gameOver = false;

function handleCollisions() {
    asteroids.forEach(asteroid => {
        if (distance(player.x, player.y, asteroid.x, asteroid.y) < player.radius + asteroid.radius) {
            gameOver = true;
        }
        bullets.forEach(bullet => {
            if (!bullet.markedForDeletion && distance(bullet.x, bullet.y, asteroid.x, asteroid.y) < bullet.radius + asteroid.radius) {
                score += 10;
                bullet.markedForDeletion = true;
                asteroid.markedForDeletion = true;
            }
        });
    });
}

function distance(x1, y1, x2, y2) {
    return Math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2);
}

function animate() {
    if (gameOver) {
        ctx.fillStyle = 'black';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.font = '30px Arial';
        ctx.fillStyle = 'white';
        ctx.textAlign = 'center';
        ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
        ctx.fillText(`Score: ${score}`, canvas.width / 2, canvas.height / 2 + 40);
        return;
    }

    ctx.fillStyle = 'black';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    player.update();
    asteroids.forEach(asteroid => asteroid.update());
    bullets.forEach(bullet => bullet.update());

    handleCollisions();

    asteroids = asteroids.filter(asteroid => !asteroid.markedForDeletion);
    bullets = bullets.filter(bullet => !bullet.markedForDeletion);

    ctx.font = '20px Arial';
    ctx.fillStyle = 'white';
    ctx.fillText(`Score: ${score}`, 10, 30);

    requestAnimationFrame(animate);
}

function shoot() {
    bullets.push(new Bullet(
        player.x,
        player.y,
        5,
        'yellow',
        {
            x: player.velocity.x * 3 + Math.cos(player.angle * Math.PI / 180) * 5,
            y: player.velocity.y * 3 + Math.sin(player.angle * Math.PI / 180) * 5
        }
    ));
}

canvas.addEventListener('keydown', (event) => {
    switch (event.key) {
        case 'ArrowUp':
            player.move(1, 0);
            break;
        case 'ArrowDown':
            player.move(-1, 0);
            break;
        case 'ArrowLeft':
            player.turn(-5);
            break;
        case 'ArrowRight':
            player.turn(5);
            break;
        case ' ':
            shoot();
            break;
    }
});

animate();
