class Quest {
  constructor() {
    this.activeQuests = [];
  }

  startQuest(questName) {
    this.activeQuests.push(questName);
    console.log(`Started quest: ${questName}`);
  }

  completeQuest(questName) {
    const index = this.activeQuests.indexOf(questName);
    if (index !== -1) {
      this.activeQuests.splice(index, 1);
      console.log(`Completed quest: ${questName}`);
      return true;
    }
    console.log(`Quest not found: ${questName}`);
    return false;
  }

  getActiveQuests() {
    return [...this.activeQuests];
  }
}

class Reward {
  constructor() {
    this.rewards = {};
  }

  addReward(questName, reward) {
    this.rewards[questName] = reward;
    console.log(`Added reward for quest ${questName}: ${reward}`);
  }

  getReward(questName) {
    if (this.rewards[questName]) {
      console.log(`Reward for quest ${questName}: ${this.rewards[questName]}`);
      return this.rewards[questName];
    }
    console.log(`No reward for quest ${questName}`);
    return null;
  }
}

class Inventory {
  constructor() {
    this.items = [];
  }

  addItem(item) {
    this.items.push(item);
    console.log(`Added item to inventory: ${item}`);
  }

  getInventory() {
    return [...this.items];
  }
}

class GameCoordinator {
  constructor() {
    this.questSystem = new Quest();
    this.rewardSystem = new Reward();
    this.inventorySystem = new Inventory();
  }

  startQuestAndReward(questName, reward) {
    this.questSystem.startQuest(questName);
    this.rewardSystem.addReward(questName, reward);
  }

  completeQuestAndCollectReward(questName) {
    if (this.questSystem.completeQuest(questName)) {
      const reward = this.rewardSystem.getReward(questName);
      if (reward) {
        this.inventorySystem.addItem(reward);
      }
    }
  }

  displayActiveQuests() {
    console.log('Active quests:', this.questSystem.getActiveQuests());
  }

  displayInventory() {
    console.log('Inventory:', this.inventorySystem.getInventory());
  }
}

// Runnable demo
