gameCoordinator.startQuestAndReward('Find the Lost Amulet', 'Golden Amulet');
gameCoordinator.startQuestAndReward('Defeat the Dark Lord', 'Heroic Sword');

gameCoordinator.displayActiveQuests();
gameCoordinator.displayInventory();

gameCoordinator.completeQuestAndCollectReward('Find the Lost Amulet');
gameCoordinator.completeQuestAndCollectReward('Defeat the Dark Lord');

gameCoordinator.displayActiveQuests();
gameCoordinator.displayInventory();
