    const price = this.updatePrice();
    const demand = this.updateDemand(price);
    if (demand > 0) {
      console.log(`Product sold at $${price.toFixed(2)}. Remaining demand: ${demand}.`);
      this.stockLevel--;
    } else {
      console.log('No demand for the product at this price.');
    }
  }
}

