// Constants for the room dimensions
const ROOM_WIDTH = 40;
const ROOM_HEIGHT = 30;
const TILE_SIZE = 20;

// Constants for particle system
const PARTICLE_COUNT = 50;
const MAX_PARTICLE_LIFE = 100;
const PARTICLE_SIZE = 2;

// Canvas setup
const canvas = document.createElement('canvas');
canvas.width = ROOM_WIDTH * TILE_SIZE;
canvas.height = ROOM_HEIGHT * TILE_SIZE;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Room grid
const room = Array.from({ length: ROOM_HEIGHT }, () => Array(ROOM_WIDTH).fill('#000'));

// Particle system
const particles = [];
for (let i = 0; i < PARTICLE_COUNT; i++) {
    particles.push({
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        vx: (Math.random() - 0.5) * 2,
        vy: (Math.random() - 0.5) * 2,
        life: Math.random() * MAX_PARTICLE_LIFE
    });
}

// Event listener for key presses
document.addEventListener('keydown', (e) => {
    if (e.key === ' ') { // Spacebar for particle burst
        for (let i = 0; i < particles.length; i++) {
            particles[i].life = MAX_PARTICLE_LIFE;
            particles[i].x = Math.random() * canvas.width;
            particles[i].y = Math.random() * canvas.height;
        }
    }
});

// Render function
function render() {
    // Clear the canvas
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Render the room
    for (let y = 0; y < ROOM_HEIGHT; y++) {
        for (let x = 0; x < ROOM_WIDTH; x++) {
            ctx.fillStyle = room[y][x];
            ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
        }
    }

    // Update and render particles
    ctx.fillStyle = 'white';
    for (let i = 0; i < particles.length; i++) {
        const p = particles[i];
        if (p.life > 0) {
            ctx.fillRect(p.x, p.y, PARTICLE_SIZE, PARTICLE_SIZE);
            p.x += p.vx;
            p.y += p.vy;
            p.life--;
        }
    }

    // Request next frame
    requestAnimationFrame(render);
}

// Start the animation loop
render();
