// Trade System
class Trade {
  constructor() {
    this.trades = [];
  }

  recordTrade(participants, item, quantity, price) {
    this.trades.push({ participants, item, quantity, price });
    console.log(`Trade recorded: ${participants.join(', ')} traded ${quantity} ${item} for ${price}`);
  }

  getTradeHistory() {
    return this.trades;
  }
}

// Reputation System
class Reputation {
  constructor() {
    this.reputations = {};
  }

  updateReputation(entity, change) {
    if (!this.reputations[entity]) {
      this.reputations[entity] = 0;
    }
    this.reputations[entity] += change;
    console.log(`Reputation updated for ${entity}: ${this.reputations[entity]}`);
  }

  getReputation(entity) {
    return this.reputations[entity] || 0;
  }
}

// Faction System
class Faction {
  constructor() {
    this.factions = {};
  }

  joinFaction(entity, faction) {
    if (!this.factions[faction]) {
      this.factions[faction] = [];
    }
    this.factions[faction].push(entity);
    console.log(`${entity} joined faction ${faction}`);
  }

  getFactionMembers(faction) {
    return this.factions[faction] || [];
  }
}

// Coordinator
class Coordinator {
  constructor() {
    this.tradeSystem = new Trade();
    this.reputationSystem = new Reputation();
    this.factionSystem = new Faction();
  }

  performTrade(participants, item, quantity, price) {
    this.tradeSystem.recordTrade(participants, item, quantity, price);
    const tradeReputationChange = price * 0.1; // 10% of the trade price affects reputation
    participants.forEach(participant => {
      this.reputationSystem.updateReputation(participant, tradeReputationChange);
    });
  }

  joinFaction(entity, faction) {
    this.factionSystem.joinFaction(entity, faction);
  }

  getTradeHistory() {
    return this.tradeSystem.getTradeHistory();
  }

  getReputation(entity) {
    return this.reputationSystem.getReputation(entity);
  }

  getFactionMembers(faction) {
    return this.factionSystem.getFactionMembers(faction);
  }
}

// Demo
