const ctx = canvas.getContext('2d');

let width = window.innerWidth;
let height = window.innerHeight;
canvas.width = width * devicePixelRatio;
canvas.height = height * devicePixelRatio;
ctx.scale(devicePixelRatio, devicePixelRatio);

canvas.style.width = width + 'px';
canvas.style.height = height + 'px';

const player = {
  x: width / 2,
  y: height / 2,
  radius: 10,
  speed: 5,
  angle: 0,
  shooting: false,
  bullets: []
};

const enemies = [];
const enemySpawner = {
  interval: 2000,
  spawn() {
    const enemy = {
      x: Math.random() * width,
      y: Math.random() * height,
      radius: 5,
      speed: Math.random() * 2 + 1,
      angle: Math.random() * Math.PI * 2
    };
    enemies.push(enemy);
  }
};

function updatePlayer() {
  if (keys['ArrowRight']) player.angle += 0.1;
  if (keys['ArrowLeft']) player.angle -= 0.1;
  if (keys['ArrowUp']) {
    player.x += player.speed * Math.cos(player.angle);
    player.y += player.speed * Math.sin(player.angle);
  }
  if (keys['ArrowDown']) {
    player.x -= player.speed * Math.cos(player.angle);
    player.y -= player.speed * Math.sin(player.angle);
  }
  if (player.shooting) {
    const bullet = {
      x: player.x + Math.cos(player.angle) * (player.radius + 5),
      y: player.y + Math.sin(player.angle) * (player.radius + 5),
      radius: 2,
      speed: 10,
      angle: player.angle
    };
    player.bullets.push(bullet);
    player.shooting = false;
  }
}

function updateEnemies() {
  enemies.forEach((enemy, index) => {
    enemy.x += enemy.speed * Math.cos(enemy.angle);
    enemy.y += enemy.speed * Math.sin(enemy.angle);
    if (enemy.x < 0 || enemy.x > width || enemy.y < 0 || enemy.y > height) {
      enemies.splice(index, 1);
    }
  });
}

function updateBullets() {
  player.bullets.forEach((bullet, index) => {
    bullet.x += bullet.speed * Math.cos(bullet.angle);
    bullet.y += bullet.speed * Math.sin(bullet.angle);
    if (bullet.x < 0 || bullet.x > width || bullet.y < 0 || bullet.y > height) {
      player.bullets.splice(index, 1);
    }
  });
}

function checkCollisions() {
  player.bullets.forEach((bullet, bulletIndex) => {
    enemies.forEach((enemy, enemyIndex) => {
      const dx = bullet.x - enemy.x;
      const dy = bullet.y - enemy.y;
      const distance = Math.sqrt(dx * dx + dy * dy);
      if (distance < bullet.radius + enemy.radius) {
        player.bullets.splice(bulletIndex, 1);
        enemies.splice(enemyIndex, 1);
      }
    });
  });
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = 'blue';
  ctx.beginPath();
  ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = 'red';
  enemies.forEach(enemy => {
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, enemy.radius, 0, Math.PI * 2);
    ctx.fill();
  });

  ctx.fillStyle = 'yellow';
  player.bullets.forEach(bullet => {
    ctx.beginPath();
    ctx.arc(bullet.x, bullet.y, bullet.radius, 0, Math.PI * 2);
    ctx.fill();
  });

  requestAnimationFrame(render);
}

function spawnEnemies() {
  enemySpawner.spawn();
  enemySpawner.interval *= 0.99; // Increase difficulty by reducing spawn interval
  setTimeout(spawnEnemies, enemySpawner.interval);
}

const keys = {};
window.addEventListener('keydown', e => {
  keys[e.key] = true;
  if (e.key === ' ') player.shooting = true;
});
window.addEventListener('keyup', e => {
  keys[e.key] = false;
});
window.addEventListener('resize', () => {
  width = window.innerWidth;
  height = window.innerHeight;
  canvas.width = width * devicePixelRatio;
  canvas.height = height * devicePixelRatio;
  ctx.scale(devicePixelRatio, devicePixelRatio);
  canvas.style.width = width + 'px';
  canvas.style.height = height + 'px';
});

spawnEnemies();
render();
