        if (amount > 0) {
            this.balance += amount;
        }
    }

    withdraw(amount) {
        if (amount > 0 && this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }
}

class Store {
    constructor() {
        this.items = {
            apple: { price: 1 },
            bread: { price: 2 },
            cheese: { price: 3 }
        };
    }

