    this.balance = 1000;
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }

  debit(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Inventory {
  constructor() {
    this.items = { wheat: 0, carrot: 0, apple: 0 };
  }

  addItem(item, quantity) {
    this.items[item] = (this.items[item] || 0) + quantity;
  }

  getInventory() {
    return this.items;
  }
}

class Market {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
  }

  purchase(item, quantity) {
    const price = this.economy.getPrice(item);
    const totalCost = price * quantity;

    if (this.economy.debit(totalCost)) {
      this.inventory.addItem(item, quantity);
      console.log(`Purchased ${quantity} ${item}(s) for ${totalCost}.`);
      return true;
    } else {
      console.log(`Insufficient funds to purchase ${quantity} ${item}(s).`);
      return false;
    }
  }
}

