class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
    this.inventory = {};
    this.balance = 1000; // Initial balance for the store
  }

  purchaseItem(item, quantity) {
    const price = this.pricing.getPrice(item);
    const demand = this.demand.getDemand(item);

    if (quantity > demand) {
      console.log(`Not enough demand for ${quantity} of ${item}.`);
      return;
    }

    const totalCost = price * quantity;
    if (totalCost > this.balance) {
      console.log(`Insufficient funds to purchase ${quantity} of ${item}.`);
      return;
    }

    this.balance -= totalCost;
    this.inventory[item] = (this.inventory[item] || 0) + quantity;
    console.log(`Purchased ${quantity} of ${item} for ${totalCost}. Remaining balance: ${this.balance}.`);
  }

  getInventory() {
    return this.inventory;
  }
}

