class Farm {
    constructor() {
        this.crops = {};
    }

    plantCrop(cropName, crop) {
        if (!this.crops[cropName]) {
            this.crops[cropName] = [];
        }
        this.crops[cropName].push(crop);
    }

    harvestCrop(cropName) {
        if (this.crops[cropName] && this.crops[cropName].length > 0) {
            return this.crops[cropName].pop();
        }
        return null;
    }
}

