        return this.prices[cropName] || 0;
    }
}

class Coordinator {
    constructor(farm, market) {
        this.farm = farm;
        this.market = market;
    }

    plantCrop(cropName, crop) {
        this.farm.plantCrop(cropName, crop);
    }

