const mazeHeight = 15;
const cellSize = 30;

function generateMaze() {
    for (let y = 0; y < mazeHeight; y++) {
        for (let x = 0; x < mazeWidth; x++) {
            maze[y * mazeWidth + x] = Math.random() > 0.7 ? 1 : 0;
        }
    }
}

function drawMaze() {
    ctx.fillStyle = 'gray';
    for (let y = 0; y < mazeHeight; y++) {
        for (let x = 0; x < mazeWidth; x++) {
            if (maze[y * mazeWidth + x]) {
                ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
            }
        }
    }
}

function drawPlayer() {
    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x - player.size / 2, player.y - player.size / 2, player.size, player.size);
}

function drawHealthBar() {
    ctx.fillStyle = 'red';
    ctx.fillRect(10, 10, player.health * 0.8, 20);
    ctx.strokeStyle = 'black';
    ctx.strokeRect(10, 10, 100, 20);
}

function checkCollision(x, y) {
    const cellX = Math.floor(x / cellSize);
    const cellY = Math.floor(y / cellSize);
    return cellX >= 0 && cellX < mazeWidth && cellY >= 0 && cellY < mazeHeight && maze[cellY * mazeWidth + cellX];
}

function updatePlayer() {
    let newX = player.x;
    let newY = player.y;

    if (keys['ArrowUp'] && !checkCollision(player.x, player.y - player.speed)) {
        newY -= player.speed;
    }
    if (keys['ArrowDown'] && !checkCollision(player.x, player.y + player.speed)) {
        newY += player.speed;
    }
    if (keys['ArrowLeft'] && !checkCollision(player.x - player.speed, player.y)) {
        newX -= player.speed;
    }
    if (keys['ArrowRight'] && !checkCollision(player.x + player.speed, player.y)) {
        newX += player.speed;
    }

    player.x = newX;
    player.y = newY;

    if (Math.random() < 0.01) {
        player.health -= 1;
        if (player.health <= 0) {
            player.x = canvas.width / 2;
            player.y = canvas.height / 2;
            player.health = 100;
        }
    }
}

