const PLAYER_SIZE = 50;
const ENEMY_SIZE = 50;
const PLAYER_SPEED = 5;
const ENEMY_SPEED = 3;
const FRAME_RATE = 60;

// Game state
let canvas;
let ctx;
let player = { x: CANVAS_WIDTH / 2, y: CANVAS_HEIGHT - PLAYER_SIZE, width: PLAYER_SIZE, height: PLAYER_SIZE };
let enemy = { x: CANVAS_WIDTH / 2, y: 0, width: ENEMY_SIZE, height: ENEMY_SIZE };
let playerVelocity = { x: 0, y: 0 };
let enemyVelocity = { x: 0, y: 0 };
let keys = {};

// Initialize canvas
function initCanvas() {
    canvas = document.createElement('canvas');
    canvas.width = CANVAS_WIDTH;
    canvas.height = CANVAS_HEIGHT;
    document.body.appendChild(canvas);
    ctx = canvas.getContext('2d');
}

// Update game state
function update() {
    // Player movement
    if (keys['ArrowLeft']) playerVelocity.x = -PLAYER_SPEED;
    else if (keys['ArrowRight']) playerVelocity.x = PLAYER_SPEED;
    else playerVelocity.x = 0;

    player.x += playerVelocity.x;

    // Enemy AI
    if (enemy.x < player.x) enemyVelocity.x = ENEMY_SPEED;
    else if (enemy.x > player.x) enemyVelocity.x = -ENEMY_SPEED;
    else enemyVelocity.x = 0;

    enemy.x += enemyVelocity.x;

    // Collision detection
    if (player.x < 0) player.x = 0;
    if (player.x + player.width > CANVAS_WIDTH) player.x = CANVAS_WIDTH - player.width;
    if (enemy.x < 0) enemy.x = 0;
    if (enemy.x + enemy.width > CANVAS_WIDTH) enemy.x = CANVAS_WIDTH - enemy.width;
}

// Render game
function render() {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x, player.y, player.width, player.height);
    ctx.fillStyle = 'red';
    ctx.fillRect(enemy.x, enemy.y, enemy.width, enemy.height);
}

// Game loop
function gameLoop() {
    update();
    render();
    requestAnimationFrame(gameLoop);
}

// Event listeners
function keyDownHandler(e) {
    keys[e.key] = true;
}

function keyUpHandler(e) {
    keys[e.key] = false;
}

document.addEventListener('keydown', keyDownHandler);
document.addEventListener('keyup', keyUpHandler);

// Start the game
initCanvas();
gameLoop();
