  constructor() {
    this.table = {
      common: ['Potion', 'Coin'],
      uncommon: ['Ring', 'Scroll'],
      rare: ['Sword', 'Armor'],
      epic: ['Amulet', 'Staff']
    };
  }

  getRandomLoot(rarity) {
    if (!this.table[rarity]) return null;
    const lootName = this.table[rarity][Math.floor(Math.random() * this.table[rarity].length)];
    const value = this.calculateValue(rarity);
    return new Loot(lootName, value);
  }

  calculateValue(rarity) {
    switch (rarity) {
      case 'common': return 5;
      case 'uncommon': return 10;
      case 'rare': return 20;
      case 'epic': return 50;
      default: return 0;
    }
  }
}

