    this.x = x;
    this.y = y;
    this.width = width;
    this.height = height;
    this.velocityY = 0;
    this.onGround = false;
  }

  update() {
    if (!this.onGround) {
      this.velocityY += gravity;
    }
    this.y += this.velocityY;
    if (this.y + this.height > canvas.height) {
      this.y = canvas.height - this.height;
      this.velocityY = 0;
      this.onGround = true;
    }
  }

  draw() {
    ctx.fillRect(this.x, this.y, this.width, this.height);
  }
}

class Player extends Entity {
  constructor(x, y) {
    super(x, y, 50, 50);
  }

  jump() {
    if (this.onGround) {
      this.velocityY = jumpSpeed;
      this.onGround = false;
    }
  }

  moveLeft() {
    this.x -= playerSpeed;
  }

  moveRight() {
    this.x += playerSpeed;
  }
}

class AI extends Entity {
