    super(x, y, 50, 50);
  }

  update() {
    if (Math.abs(this.x - player.x) < canvas.width / 2) {
      if (this.x < player.x) {
        this.x += aiSpeed;
      } else if (this.x > player.x) {
        this.x -= aiSpeed;
      }
    }
    super.update();
  }
}

