        console.log(`Planted ${type} on the farm.`);
        this.eventBus.emit('cropPlanted', { type });
    }

    sellCrop(data) {
        const { type, quantity } = data;
        const index = this.crops.indexOf(type);
        if (index !== -1) {
            this.crops.splice(index, quantity);
            console.log(`Sold ${quantity} of ${type}.`);
