class Recipe {
    constructor(name, ingredients, result) {
        this.name = name;
        this.ingredients = ingredients;
        this.result = result;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    removeItem(item, quantity) {
        if (this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            return true;
        }
        return false;
    }

    hasItems(ingredients) {
        for (let [item, quantity] of Object.entries(ingredients)) {
            if (!this.items[item] || this.items[item] < quantity) {
                return false;
            }
        }
        return true;
    }

    getItems() {
        return { ...this.items };
    }
}

class Crafting {
    constructor(inventory) {
        this.inventory = inventory;
        this.recipes = [];
    }

    addRecipe(recipe) {
        this.recipes.push(recipe);
    }

    canCraft(recipeName) {
        const recipe = this.recipes.find(r => r.name === recipeName);
        if (recipe) {
            return this.inventory.hasItems(recipe.ingredients);
        }
        return false;
    }

    craft(recipeName) {
        const recipe = this.recipes.find(r => r.name === recipeName);
        if (recipe && this.canCraft(recipeName)) {
            for (let [item, quantity] of Object.entries(recipe.ingredients)) {
                this.inventory.removeItem(item, quantity);
            }
            this.inventory.addItem(recipe.result, 1);
            return true;
        }
        return false;
    }
}

