let player = { x: 50, y: canvas.height / 2, width: 20, height: 50, speed: 0, gravity: 0.5, jumpPower: -10 };
let groundY = canvas.height - player.height;
let isGrounded = true;
let obstacles = [];
let obstacleSpeed = 2;
let obstacleWidth = 30;
let obstacleHeight = 50;
let score = 0;
let highScore = 0;

function createObstacle() {
    obstacles.push({ x: canvas.width, y: groundY - obstacleHeight, width: obstacleWidth, height: obstacleHeight });
}

function update() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Player movement
    player.speed += player.gravity;
    player.y += player.speed;
    if (player.y + player.height > groundY) {
        player.y = groundY - player.height;
        player.speed = 0;
        isGrounded = true;
    }

    // Obstacle movement and collision detection
    obstacles.forEach((obstacle, index) => {
        obstacle.x -= obstacleSpeed;
        ctx.fillStyle = 'red';
        ctx.fillRect(obstacle.x, obstacle.y, obstacle.width, obstacle.height);

        if (player.x < obstacle.x + obstacle.width &&
            player.x + player.width > obstacle.x &&
            player.y < obstacle.y + obstacle.height &&
            player.y + player.height > obstacle.y) {
            // Collision detected
            alert(`Game Over! Your score: ${score}. High Score: ${highScore}`);
            document.location.reload();
        }

        if (obstacle.x + obstacle.width < 0) {
            obstacles.splice(index, 1);
            score++;
            highScore = Math.max(score, highScore);
        }
    });

    // Player jump
    if (isGrounded && (keyboard.isPressed('Space') || mouse.isClicked)) {
        player.speed = player.jumpPower;
        isGrounded = false;
    }

    // Score display
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score} | High Score: ${highScore}`, 10, 30);

    // Create new obstacle
    if (Math.random() < 0.02) {
        createObstacle();
    }

    requestAnimationFrame(update);
}

