class Crop {
    constructor(name, growthTime) {
        this.name = name;
        this.growthTime = growthTime;
        this.plantedAt = null;
    }

    plant() {
        this.plantedAt = Date.now();
        console.log(`Crop ${this.name} planted at ${this.plantedAt}`);
    }

    isReady() {
        if (!this.plantedAt) return false;
        const currentTime = Date.now();
        const growthDuration = currentTime - this.plantedAt;
        return growthDuration >= this.growthTime;
    }
}

class Market {
