        crops.forEach(crop => {
            if (this.prices[crop.name]) {
                totalRevenue += this.prices[crop.name];
                console.log(`Sold ${crop.name} for ${this.prices[crop.name]}`);
            }
        });
        console.log(`Total revenue: ${totalRevenue}`);
        return totalRevenue;
    }
}

