// Tower Defense Game
const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const HIGH_SCORE_KEY = 'towerDefenseHighScore';
let highScore = localStorage.getItem(HIGH_SCORE_KEY) ? parseInt(localStorage.getItem(HIGH_SCORE_KEY)) : 0;
let score = 0;
let gameRunning = false;
let enemies = [];
let towers = [];
let path = [{x: 50, y: 50}, {x: 750, y: 50}, {x: 750, y: 550}, {x: 50, y: 550}];

function drawPath() {
    ctx.strokeStyle = 'gray';
    ctx.lineWidth = 10;
    for (let i = 0; i < path.length - 1; i++) {
        ctx.beginPath();
        ctx.moveTo(path[i].x, path[i].y);
        ctx.lineTo(path[i + 1].x, path[i + 1].y);
        ctx.stroke();
    }
}

class Enemy {
    constructor() {
        this.x = path[0].x;
        this.y = path[0].y;
        this.width = 20;
        this.height = 20;
        this.speed = 2;
        this.health = 100;
        this.pathIndex = 1;
    }

    update() {
        const target = path[this.pathIndex];
        const dx = target.x - this.x;
        const dy = target.y - this.y;
        const distance = Math.sqrt(dx * dx + dy * dy);

        if (distance < this.speed) {
            this.x = target.x;
            this.y = target.y;
            if (this.pathIndex < path.length - 1) {
                this.pathIndex++;
            } else {
                this.health = 0;
            }
        } else {
            this.x += (dx / distance) * this.speed;
            this.y += (dy / distance) * this.speed;
        }
    }

    draw() {
        ctx.fillStyle = 'red';
        ctx.fillRect(this.x, this.y, this.width, this.height);
    }
}

class Tower {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.range = 100;
        this.damage = 10;
        this.cooldown = 1000;
        this.lastAttack = Date.now();
    }

    update() {
        const enemy = enemies.find(e => {
            const dx = e.x - this.x;
            const dy = e.y - this.y;
            return Math.sqrt(dx * dx + dy * dy) < this.range;
        });

        if (enemy) {
            const now = Date.now();
            if (now - this.lastAttack > this.cooldown) {
                this.lastAttack = now;
                enemy.health -= this.damage;
                if (enemy.health <= 0) {
                    score++;
                    enemies = enemies.filter(e => e !== enemy);
                }
            }
        }
    }

    draw() {
        ctx.fillStyle = 'blue';
        ctx.fillRect(this.x, this.y, 20, 20);
    }
}

function spawnEnemies() {
    setInterval(() => {
        if (gameRunning) {
            enemies.push(new Enemy());
        }
    }, 2000);
}

function drawScore() {
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
    ctx.fillText(`High Score: ${highScore}`, 10, 60);
}

function update() {
    if (gameRunning) {
        enemies.forEach(enemy => enemy.update());
        towers.forEach(tower => tower.update());
        if (enemies.length === 0) {
            gameRunning = false;
            if (score > highScore) {
                highScore = score;
                localStorage.setItem(HIGH_SCORE_KEY, highScore);
            }
            alert(`Game Over! Your score: ${score}`);
            score = 0;
        }
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawPath();
    enemies.forEach(enemy => enemy.draw());
    towers.forEach(tower => tower.draw());
    drawScore();
    requestAnimationFrame(draw);
}

canvas.addEventListener('click', (event) => {
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    towers.push(new Tower(x, y));
});

function startGame() {
    gameRunning = true;
    enemies = [];
    towers = [];
    score = 0;
    spawnEnemies();
    draw();
}

document.getElementById('startButton').addEventListener('click', startGame);

const startButton = document.createElement('button');
startButton.id = 'startButton';
startButton.textContent = 'Start Game';
document.body.appendChild(startButton);
