const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const ball = { x: canvas.width / 2, y: canvas.height - 30, dx: 2, dy: -2, radius: 10 };
const paddle = { x: (canvas.width - 75) / 2, y: canvas.height - 10, width: 75, height: 10, dx: 7 };
const bricks = [];
const powerUps = [];
const brickRowCount = 5;
const brickColumnCount = 3;
const brickWidth = 75;
const brickHeight = 20;
const brickPadding = 10;
const brickOffsetTop = 30;
const brickOffsetLeft = 30;
const rightPressed = false;
const leftPressed = false;
const powerUpTypes = ['expand', 'shrink', 'fast', 'slow'];
const powerUpSpeed = 2;
const powerUpRadius = 8;
const powerUpDuration = 5000; // 5 seconds

let score = 0;
let lives = 3;
let gameRunning = true;
let lastTime = performance.now();
let powerUpEffect = null;
let powerUpTimer = null;

for (let c = 0; c < brickColumnCount; c++) {
  bricks[c] = [];
  for (let r = 0; r < brickRowCount; r++) {
    bricks[c][r] = { x: 0, y: 0, status: 1 };
  }
}

document.addEventListener('keydown', keyDownHandler, false);
document.addEventListener('keyup', keyUpHandler, false);

function keyDownHandler(e) {
  if (e.key === 'Right' || e.key === 'ArrowRight') {
    rightPressed = true;
  } else if (e.key === 'Left' || e.key === 'ArrowLeft') {
    leftPressed = true;
  }
}

function keyUpHandler(e) {
  if (e.key === 'Right' || e.key === 'ArrowRight') {
    rightPressed = false;
  } else if (e.key === 'Left' || e.key === 'ArrowLeft') {
    leftPressed = false;
  }
}

function collisionDetection() {
  for (let c = 0; c < brickColumnCount; c++) {
    for (let r = 0; r < brickRowCount; r++) {
      const b = bricks[c][r];
      if (b.status === 1) {
        if (ball.x > b.x && ball.x < b.x + brickWidth && ball.y > b.y && ball.y < b.y + brickHeight) {
          ball.dy = -ball.dy;
          b.status = 0;
          score++;
          if (score === brickRowCount * brickColumnCount) {
            alert('YOU WIN, CONGRATULATIONS!');
            document.location.reload();
          }
        }
      }
    }
  }
}

function drawBall() {
  ctx.beginPath();
  ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
  ctx.fillStyle = '#0095DD';
  ctx.fill();
  ctx.closePath();
}

function drawPaddle() {
  ctx.beginPath();
  ctx.rect(paddle.x, paddle.y, paddle.width, paddle.height);
  ctx.fillStyle = '#0095DD';
  ctx.fill();
  ctx.closePath();
}

function drawBricks() {
  for (let c = 0; c < brickColumnCount; c++) {
    for (let r = 0; r < brickRowCount; r++) {
      if (bricks[c][r].status === 1) {
        const brickX = (c * (brickWidth + brickPadding)) + brickOffsetLeft;
        const brickY = (r * (brickHeight + brickPadding)) + brickOffsetTop;
        bricks[c][r].x = brickX;
        bricks[c][r].y = brickY;
        ctx.beginPath();
        ctx.rect(brickX, brickY, brickWidth, brickHeight);
        ctx.fillStyle = '#0095DD';
        ctx.fill();
        ctx.closePath();
      }
    }
  }
}

function drawScore() {
  ctx.font = '16px Arial';
  ctx.fillStyle = '#0095DD';
  ctx.fillText('Score: ' + score, 8, 20);
}

function drawLives() {
  ctx.font = '16px Arial';
  ctx.fillStyle = '#0095DD';
  ctx.fillText('Lives: ' + lives, canvas.width - 65, 20);
}

function drawPowerUps() {
  for (let i = 0; i < powerUps.length; i++) {
    const powerUp = powerUps[i];
    ctx.beginPath();
    ctx.arc(powerUp.x, powerUp.y, powerUp.radius, 0, Math.PI * 2);
    ctx.fillStyle = powerUp.type === 'expand' ? 'green' : powerUp.type === 'shrink' ? 'red' : powerUp.type === 'fast' ? 'blue' : 'orange';
    ctx.fill();
    ctx.closePath();
  }
}

function updatePowerUps() {
  for (let i = 0; i < powerUps.length; i++) {
    const powerUp = powerUps[i];
    powerUp.y += powerUpSpeed;
    if (powerUp.y > canvas.height) {
      powerUps.splice(i, 1);
      i--;
    }
  }
}

function collisionWithPowerUps() {
  for (let i = 0; i < powerUps.length; i++) {
    const powerUp = powerUps[i];
    if (powerUp.x > paddle.x && powerUp.x < paddle.x + paddle.width && powerUp.y > paddle.y && powerUp.y < paddle.y + paddle.height) {
      applyPowerUp(powerUp.type);
      powerUps.splice(i, 1);
      i--;
    }
  }
}

function applyPowerUp(type) {
  if (powerUpEffect) {
    clearTimeout(powerUpTimer);
  }
  powerUpEffect = type;
  if (type === 'expand') {
    paddle.width *= 1.5;
  } else if (type === 'shrink') {
    paddle.width /= 1.5;
  } else if (type === 'fast') {
    paddle.dx *= 1.5;
  } else if (type === 'slow') {
    paddle.dx /= 1.5;
  }
  powerUpTimer = setTimeout(() => {
    if (powerUpEffect === 'expand') {
      paddle.width /= 1.5;
    } else if (powerUpEffect === 'shrink') {
      paddle.width *= 1.5;
    } else if (powerUpEffect === 'fast') {
      paddle.dx /= 1.5;
    } else if (powerUpEffect === 'slow') {
      paddle.dx *= 1.5;
    }
    powerUpEffect = null;
  }, powerUpDuration);
}

function createPowerUp() {
  if (Math.random() < 0.05) {
    const type = powerUpTypes[Math.floor(Math.random() * powerUpTypes.length)];
    const x = Math.random() * (canvas.width - powerUpRadius * 2) + powerUpRadius;
    const y = brickOffsetTop + (brickRowCount + 1) * (brickHeight + brickPadding) + powerUpRadius;
    powerUps.push({ x, y, type, radius: powerUpRadius });
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawBricks();
  drawBall();
  drawPaddle();
  drawScore();
  drawLives();
  drawPowerUps();

  if (rightPressed && paddle.x < canvas.width - paddle.width) {
    paddle.x += paddle.dx;
  } else if (leftPressed && paddle.x > 0) {
    paddle.x -= paddle.dx;
  }

  if (ball.x + ball.dx > canvas.width - ball.radius || ball.x + ball.dx < ball.radius) {
    ball.dx = -ball.dx;
  }
  if (ball.y + ball.dy < ball.radius) {
    ball.dy = -ball.dy;
  } else if (ball.y + ball.dy > canvas.height - ball.radius) {
    if (ball.x > paddle.x && ball.x < paddle.x + paddle.width) {
      ball.dy = -ball.dy;
    } else {
      lives--;
      if (!lives) {
        alert('GAME OVER');
        document.location.reload();
      } else {
        ball.x = canvas.width / 2;
        ball.y = canvas.height - 30;
        ball.dx = 2;
        ball.dy = -2;
        paddle.x = (canvas.width - paddle.width) / 2;
      }
    }
  }

  collisionDetection();
  updatePowerUps();
  collisionWithPowerUps();
  createPowerUp();

  requestAnimationFrame(draw);
}

draw();
