    this.rewardSystem = new Reward();
    this.inventorySystem = new Inventory();
  }

  startNewQuest(description) {
    this.questSystem.addQuest(description);
  }

  completeQuest(description) {
    if (this.questSystem.completeQuest(description)) {
      this.grantRewardsForQuest(description);
    }
