// Bank System
class Bank {
  constructor() {
    this.balance = 0;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

// Market System
class Market {
  constructor(prices) {
    this.prices = prices; // prices is an object mapping item names to their prices
  }

  buy(item, bank) {
    const price = this.prices[item];
    if (price && bank.withdraw(price)) {
      return true;
    }
    return false;
  }

  sell(item, bank) {
    const price = this.prices[item];
    if (price) {
      bank.deposit(price);
      return true;
    }
    return false;
  }

  getPrice(item) {
    return this.prices[item] || null;
  }
}

// Inventory System
class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
      return true;
    }
    return false;
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getInventory() {
    return { ...this.items };
  }
}

