// Economy.js
class Economy {
  constructor(initialBalance = 1000) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  debit(amount) {
    if (amount > this.balance) {
      throw new Error("Insufficient funds");
    }
    this.balance -= amount;
    return this.balance;
  }

  credit(amount) {
    this.balance += amount;
    return this.balance;
  }
}

// Loot.js
class Loot {
  constructor(name, value) {
    this.name = name;
    this.value = value;
  }
}

// RarityTable.js
class RarityTable {
  constructor() {
    this.rarityMap = {
      "Common": 0.6,
      "Uncommon": 0.3,
      "Rare": 0.09,
      "Epic": 0.01
    };
  }

  rollRarity() {
    const roll = Math.random();
    let cumulativeProbability = 0;

    for (const [rarity, probability] of Object.entries(this.rarityMap)) {
      cumulativeProbability += probability;
      if (roll <= cumulativeProbability) {
        return rarity;
      }
    }

    return "Common"; // Fallback to Common
  }

  generateLoot() {
    const rarity = this.rollRarity();
    let value;

    switch (rarity) {
      case "Common":
        value = Math.floor(Math.random() * 50) + 1;
        break;
      case "Uncommon":
        value = Math.floor(Math.random() * 100) + 50;
        break;
      case "Rare":
        value = Math.floor(Math.random() * 200) + 150;
        break;
      case "Epic":
        value = Math.floor(Math.random() * 500) + 400;
        break;
      default:
        value = 1; // Fallback to a value
    }

    return new Loot(`Item-${rarity}`, value);
  }
}

// Inventory.js
class Inventory {
  constructor() {
    this.items = [];
  }

  addItem(item) {
    this.items.push(item);
  }

  getItems() {
    return this.items;
  }

  getTotalValue() {
    return this.items.reduce((total, item) => total + item.value, 0);
  }
}

