        const demand = this.demand.getDemand(item);

        if (demand >= quantity) {
            this.demand.updateDemand(item, -quantity);
            return { success: true, total: price * quantity };
        } else {
            return { success: false, message: "Not enough demand" };
        }
    }

    restockItem(item, quantity) {
        this.demand.updateDemand(item, quantity);
    }
