const GAME_OVER_SCORE = 1000;

let asteroids = [];
let bullets = [];
let ship = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  dx: 0,
  dy: 0,
  angle: 0,
  thrusting: false,
  turningLeft: false,
  turningRight: false
};
let score = 0;
let gameRunning = true;
let lastTime = 0;

function createAsteroid(size) {
  return {
    x: Math.random() * canvas.width,
    y: Math.random() * canvas.height,
    dx: (Math.random() - 0.5) * ASTEROID_SPEED,
    dy: (Math.random() - 0.5) * ASTEROID_SPEED,
    size: size,
    radius: 20 - size * 3
  };
}

function createBullet(x, y, angle) {
  return {
    x: x,
    y: y,
    dx: Math.cos(angle) * BULLET_SPEED,
    dy: Math.sin(angle) * BULLET_SPEED,
    life: BULLET_LIFE
  };
}

function resetGame() {
  asteroids = [];
  bullets = [];
  ship.x = canvas.width / 2;
  ship.y = canvas.height / 2;
  ship.dx = 0;
  ship.dy = 0;
  ship.angle = 0;
  ship.thrusting = false;
  ship.turningLeft = false;
  ship.turningRight = false;
  score = 0;
  gameRunning = true;
  for (let i = 0; i < 5; i++) {
    asteroids.push(createAsteroid(4));
  }
}

function update(deltaTime) {
  if (!gameRunning) return;

  if (ship.thrusting) {
    ship.dx += Math.cos(ship.angle) * SHIP_THRUST;
    ship.dy += Math.sin(ship.angle) * SHIP_THRUST;
  } else {
    ship.dx *= SHIP_FRICTION;
    ship.dy *= SHIP_FRICTION;
  }

  if (ship.turningLeft) {
    ship.angle -= SHIP_TURN_SPEED;
  }
  if (ship.turningRight) {
    ship.angle += SHIP_TURN_SPEED;
  }

  ship.x += ship.dx * deltaTime;
  ship.y += ship.dy * deltaTime;

  if (ship.x < 0) ship.x += canvas.width;
  if (ship.x > canvas.width) ship.x -= canvas.width;
  if (ship.y < 0) ship.y += canvas.height;
  if (ship.y > canvas.height) ship.y -= canvas.height;

  for (let i = bullets.length - 1; i >= 0; i--) {
    bullets[i].x += bullets[i].dx * deltaTime;
    bullets[i].y += bullets[i].dy * deltaTime;
    bullets[i].life -= deltaTime;
    if (bullets[i].life <= 0) {
      bullets.splice(i, 1);
    }
  }

  for (let i = asteroids.length - 1; i >= 0; i--) {
    let asteroid = asteroids[i];
    asteroid.x += asteroid.dx * deltaTime;
    asteroid.y += asteroid.dy * deltaTime;

    if (asteroid.x < 0) asteroid.x += canvas.width;
    if (asteroid.x > canvas.width) asteroid.x -= canvas.width;
    if (asteroid.y < 0) asteroid.y += canvas.height;
    if (asteroid.y > canvas.height) asteroid.y -= canvas.height;

    if (distance(ship.x, ship.y, asteroid.x, asteroid.y) < ship.radius + asteroid.radius) {
      resetGame();
      break;
    }

    for (let j = bullets.length - 1; j >= 0; j--) {
      if (distance(bullets[j].x, bullets[j].y, asteroid.x, asteroid.y) < bullets[j].life + asteroid.radius) {
        score += 10 * asteroid.size;
        if (score >= GAME_OVER_SCORE) {
          alert('Game Over! Your score: ' + score);
          resetGame();
        }
        bullets.splice(j, 1);
        if (asteroid.size > 1) {
          splitAsteroid(asteroid);
        }
        asteroids.splice(i, 1);
        break;
      }
    }
  }
}

function splitAsteroid(asteroid) {
  for (let i = 0; i < 2; i++) {
    asteroids.push({
      x: asteroid.x,
      y: asteroid.y,
      dx: (Math.random() - 0.5) * ASTEROID_SPEED,
      dy: (Math.random() - 0.5) * ASTEROID_SPEED,
      size: asteroid.size - 1,
      radius: 20 - (asteroid.size - 1) * 3
    });
  }
}

function distance(x1, y1, x2, y2) {
  return Math.sqrt(Math.pow(x2 - x1, 2) + Math.pow(y2 - y1, 2));
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.strokeStyle = 'white';
  ctx.beginPath();
  ctx.moveTo(
    ship.x + ship.radius * Math.cos(ship.angle),
    ship.y + ship.radius * Math.sin(ship.angle)
  );
  ctx.lineTo(
    ship.x + ship.radius * Math.cos(ship.angle - 0.5),
    ship.y + ship.radius * Math.sin(ship.angle - 0.5)
  );
  ctx.lineTo(
    ship.x + ship.radius * Math.cos(ship.angle + 0.5),
    ship.y + ship.radius * Math.sin(ship.angle + 0.5)
  );
  ctx.closePath();
  ctx.stroke();

  ctx.fillStyle = 'white';
  for (let bullet of bullets) {
    ctx.fillRect(bullet.x - 1, bullet.y - 1, 2, 2);
  }

  ctx.fillStyle = 'gray';
  for (let asteroid of asteroids) {
    ctx.beginPath();
    ctx.arc(asteroid.x, asteroid.y, asteroid.radius, 0, Math.PI * 2);
    ctx.closePath();
    ctx.fill();
  }

  ctx.fillStyle = 'white';
  ctx.fillText('Score: ' + score, 10, 20);
}

function gameLoop(time) {
  let deltaTime = (time - lastTime) / 1000;
  update(deltaTime);
  draw();
  lastTime = time;
  if (gameRunning) requestAnimationFrame(gameLoop);
}

canvas.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowLeft' || e.key === 'a') {
    ship.turningLeft = true;
  }
  if (e.key === 'ArrowRight' || e.key === 'd') {
    ship.turningRight = true;
  }
  if (e.key === 'ArrowUp' || e.key === 'w') {
    ship.thrusting = true;
  }
  if (e.key === ' ') {
    if (bullets.length < MAX_BULLETS) {
      bullets.push(createBullet(ship.x, ship.y, ship.angle));
    }
  }
});

canvas.addEventListener('keyup', (e) => {
  if (e.key === 'ArrowLeft' || e.key === 'a') {
    ship.turningLeft = false;
  }
  if (e.key === 'ArrowRight' || e.key === 'd') {
    ship.turningRight = false;
  }
  if (e.key === 'ArrowUp' || e.key === 'w') {
    ship.thrusting = false;
  }
});

resetGame();
requestAnimationFrame(gameLoop);
