let gameState = 'menu';
let player = { x: 0, y: 0, angle: 0 };
let enemies = [];
let bullets = [];
let score = 0;
let lastTime = 0;
let highScore = 0;

function setCanvasSize() {
  const dpr = window.devicePixelRatio || 1;
  const rect = canvas.getBoundingClientRect();
  canvas.width = rect.width * dpr;
  canvas.height = rect.height * dpr;
  ctx.scale(dpr, dpr);
}

window.addEventListener('resize', setCanvasSize);
setCanvasSize();

function setState(newState) {
  gameState = newState;
  if (newState === 'playing') {
    player = { x: canvas.width / 2, y: canvas.height / 2, angle: 0 };
    enemies = [];
    bullets = [];
    score = 0;
  }
}

function spawnEnemy() {
  const x = Math.random() * canvas.width;
  const y = Math.random() * canvas.height;
  enemies.push({ x, y, angle: Math.random() * Math.PI * 2 });
}

function update(dt) {
  if (gameState === 'playing') {
    // Player movement
    if (keys['ArrowUp']) player.y -= 5 * dt;
    if (keys['ArrowDown']) player.y += 5 * dt;
    if (keys['ArrowLeft']) player.x -= 5 * dt;
    if (keys['ArrowRight']) player.x += 5 * dt;

    // Bullet movement
    bullets.forEach(bullet => {
      bullet.x += Math.cos(bullet.angle) * 10 * dt;
      bullet.y += Math.sin(bullet.angle) * 10 * dt;
    });

    // Enemy movement
    enemies.forEach(enemy => {
      const dx = player.x - enemy.x;
      const dy = player.y - enemy.y;
      const distance = Math.sqrt(dx * dx + dy * dy);
      if (distance < 20) setState('gameover');
      enemy.angle = Math.atan2(dy, dx);
      enemy.x += Math.cos(enemy.angle) * 2 * dt;
      enemy.y += Math.sin(enemy.angle) * 2 * dt;
    });

    // Collision detection
    bullets = bullets.filter(bullet => {
      let hit = false;
      enemies = enemies.filter(enemy => {
        const dx = bullet.x - enemy.x;
        const dy = bullet.y - enemy.y;
        if (dx * dx + dy * dy < 100) {
          hit = true;
          score++;
          return false;
        }
        return true;
      });
      return !hit;
    });

    // Spawn new enemies
    if (Math.random() < dt * 0.01) spawnEnemy();

    // Check for game over
    if (score > highScore) highScore = score;
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  if (gameState === 'menu') {
    ctx.fillStyle = 'white';
    ctx.textAlign = 'center';
    ctx.font = '48px Arial';
    ctx.fillText('Menu', canvas.width / 2, canvas.height / 2);
    ctx.font = '24px Arial';
    ctx.fillText('Press Enter to Start', canvas.width / 2, canvas.height / 2 + 50);
  } else if (gameState === 'playing') {
    // Draw player
    ctx.save();
    ctx.translate(player.x, player.y);
    ctx.rotate(player.angle);
    ctx.fillStyle = 'blue';
    ctx.fillRect(-5, -5, 10, 10);
    ctx.restore();

    // Draw bullets
    ctx.fillStyle = 'green';
    bullets.forEach(bullet => ctx.fillRect(bullet.x - 2, bullet.y - 2, 4, 4));

    // Draw enemies
    ctx.fillStyle = 'red';
    enemies.forEach(enemy => ctx.fillRect(enemy.x - 5, enemy.y - 5, 10, 10));

    // Draw score
    ctx.fillStyle = 'white';
    ctx.font = '18px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
    ctx.fillText(`High Score: ${highScore}`, 10, 50);
  } else if (gameState === 'paused') {
    ctx.fillStyle = 'white';
    ctx.textAlign = 'center';
    ctx.font = '48px Arial';
    ctx.fillText('Paused', canvas.width / 2, canvas.height / 2);
    ctx.font = '24px Arial';
    ctx.fillText('Press Space to Resume', canvas.width / 2, canvas.height / 2 + 50);
  } else if (gameState === 'gameover') {
    ctx.fillStyle = 'white';
    ctx.textAlign = 'center';
    ctx.font = '48px Arial';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    ctx.font = '24px Arial';
    ctx.fillText(`Score: ${score}`, canvas.width / 2, canvas.height / 2 + 50);
    ctx.fillText('Press Enter to Restart', canvas.width / 2, canvas.height / 2 + 80);
  }
}

const keys = {};
window.addEventListener('keydown', e => keys[e.key] = true);
window.addEventListener('keyup', e => keys[e.key] = false);

function gameLoop(timestamp) {
  const dt = (timestamp - lastTime) / 1000;
  lastTime = timestamp;

  if (keys['Enter']) {
    if (gameState === 'menu') setState('playing');
    if (gameState === 'gameover') setState('playing');
  }
  if (keys['Space']) {
    if (gameState === 'playing') setState('paused');
    if (gameState === 'paused') setState('playing');
  }
  if (keys['ArrowUp'] || keys['ArrowDown'] || keys['ArrowLeft'] || keys['ArrowRight']) {
    if (keys[' ']) {
      bullets.push({ x: player.x, y: player.y, angle: player.angle });
    }
  }

  update(dt);
  render();

  requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
