class EventBus {
    constructor() {
        this.listeners = {};
    }

    subscribe(event, listener) {
        if (!this.listeners[event]) {
            this.listeners[event] = [];
        }
        this.listeners[event].push(listener);
    }

    emit(event, data) {
        if (this.listeners[event]) {
            this.listeners[event].forEach(listener => listener(data));
        }
    }
}

class Farm {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.crops = [];

        this.eventBus.subscribe('market:buyCrop', this.onMarketBuyCrop.bind(this));
    }

    plantCrop(crop) {
        this.crops.push(crop);
        console.log(`Farm: Planted ${crop.name}`);
        this.eventBus.emit('farm:cropPlanted', crop);
    }

    onMarketBuyCrop(data) {
        const { cropName } = data;
        const cropIndex = this.crops.findIndex(crop => crop.name === cropName);
        if (cropIndex !== -1) {
            const crop = this.crops.splice(cropIndex, 1)[0];
            console.log(`Farm: Sold ${crop.name}`);
            this.eventBus.emit('farm:cropSold', crop);
        } else {
            console.log(`Farm: Crop ${cropName} not found`);
        }
    }
}

class Crop {
    constructor(name) {
        this.name = name;
    }
}

class Market {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.inventory = [];

        this.eventBus.subscribe('farm:cropPlanted', this.onFarmCropPlanted.bind(this));
        this.eventBus.subscribe('farm:cropSold', this.onFarmCropSold.bind(this));
    }

    buyCrop(cropName) {
        const crop = this.inventory.find(crop => crop.name === cropName);
        if (crop) {
            this.inventory = this.inventory.filter(crop => crop.name !== cropName);
            console.log(`Market: Bought ${cropName}`);
            this.eventBus.emit('market:cropBought', crop);
        } else {
            console.log(`Market: Crop ${cropName} not available`);
        }
    }

    onFarmCropPlanted(crop) {
        this.inventory.push(crop);
        console.log(`Market: Received ${crop.name}`);
        this.eventBus.emit('market:cropReceived', crop);
    }

    onFarmCropSold(crop) {
        this.inventory = this.inventory.filter(cropItem => cropItem !== crop);
        console.log(`Market: Removed ${crop.name} from inventory`);
        this.eventBus.emit('market:cropRemoved', crop);
    }
}

// Runnable demo
const eventBus = new EventBus();
const farm = new Farm(eventBus);
const market = new Market(eventBus);

const corn = new Crop('Corn');
const wheat = new Crop('Wheat');

farm.plantCrop(corn);
farm.plantCrop(wheat);

market.buyCrop('Corn');
market.buyCrop('Wheat');
market.buyCrop('Corn'); // Attempt to buy a non-existent crop
