class Building {
    constructor(name, resourceRequirements) {
        this.name = name;
        this.resourceRequirements = resourceRequirements;
        this.isBuilt = false;
    }

    build() {
        if (this.isBuilt) {
            console.log(`${this.name} is already built.`);
            return;
        }

        this.isBuilt = true;
        console.log(`${this.name} has been built.`);
    }

    getRequirements() {
        return this.resourceRequirements;
    }

    isConstructed() {
        return this.isBuilt;
    }
}

class Resource {
    constructor(name, amount) {
        this.name = name;
        this.amount = amount;
    }

    consume(amount) {
        if (this.amount < amount) {
            console.log(`Not enough ${this.name} to consume ${amount}.`);
            return false;
        }

        this.amount -= amount;
        console.log(`Consumed ${amount} ${this.name}. Remaining: ${this.amount}`);
        return true;
    }

    add(amount) {
        this.amount += amount;
        console.log(`Added ${amount} ${this.name}. Total: ${this.amount}`);
    }

    getAmount() {
        return this.amount;
    }
}

class Economy {
    constructor(buildings, resources) {
        this.buildings = buildings;
        this.resources = resources;
    }

    buildBuilding(buildingName) {
        const building = this.buildings.find(b => b.name === buildingName);
        if (!building) {
            console.log(`${buildingName} not found.`);
            return;
        }

        if (building.isConstructed()) {
            console.log(`${buildingName} is already built.`);
            return;
        }

        const requirements = building.getRequirements();
        let canBuild = true;

        for (const resource of requirements) {
            const resourceObj = this.resources.find(r => r.name === resource.name);
            if (!resourceObj || !resourceObj.consume(resource.amount)) {
                canBuild = false;
                break;
            }
        }

        if (canBuild) {
            building.build();
        } else {
            console.log(`Not enough resources to build ${buildingName}.`);
        }
    }

    addResource(resourceName, amount) {
        const resource = this.resources.find(r => r.name === resourceName);
        if (!resource) {
            console.log(`${resourceName} not found.`);
            return;
        }

        resource.add(amount);
    }

    getResourceAmount(resourceName) {
        const resource = this.resources.find(r => r.name === resourceName);
        return resource ? resource.getAmount() : 0;
    }
}

// Demo
