const stone = new Resource('Stone', 50);
const resources = [wood, stone];

const house = new Building('House', [{ name: 'Wood', amount: 30 }, { name: 'Stone', amount: 20 }]);
const buildings = [house];

const economy = new Economy(buildings, resources);

console.log('Initial Resources:');
console.log(`Wood: ${economy.getResourceAmount('Wood')}`);
console.log(`Stone: ${economy.getResourceAmount('Stone')}`);

economy.buildBuilding('House');

console.log('After Building House:');
console.log(`Wood: ${economy.getResourceAmount('Wood')}`);
console.log(`Stone: ${economy.getResourceAmount('Stone')}`);

economy.addResource('Wood', 50);
economy.buildBuilding('House');
