const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
let pixelRatio = window.devicePixelRatio || 1;

function resizeCanvas() {
  const width = window.innerWidth;
  const height = window.innerHeight;
  canvas.width = width * pixelRatio;
  canvas.height = height * pixelRatio;
  canvas.style.width = `${width}px`;
  canvas.style.height = `${height}px`;
  ctx.scale(pixelRatio, pixelRatio);
}

resizeCanvas();
window.addEventListener('resize', resizeCanvas);

const cardWidth = 100;
const cardHeight = 150;
const margin = 10;
const cards = [];
const powerUps = [];
const gridSize = 4;
let flippedCards = [];
let score = 0;
let powerUpTimer = null;

class Card {
  constructor(x, y, value) {
    this.x = x;
    this.y = y;
    this.value = value;
    this.flipped = false;
    this.matched = false;
  }

  draw() {
    ctx.fillStyle = this.matched ? '#0f0' : this.flipped ? '#fff' : '#ccc';
    ctx.fillRect(this.x, this.y, cardWidth, cardHeight);
    if (this.flipped && !this.matched) {
      ctx.fillStyle = '#000';
      ctx.font = '20px Arial';
      ctx.fillText(this.value, this.x + 30, this.y + 70);
    }
  }

  flip() {
    this.flipped = !this.flipped;
  }

  checkMatch(otherCard) {
    if (this.value === otherCard.value) {
      this.matched = true;
      otherCard.matched = true;
      score++;
    } else {
      flippedCards = [];
    }
  }
}

class PowerUp {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.collected = false;
  }

  draw() {
    if (!this.collected) {
      ctx.fillStyle = '#ff0';
      ctx.beginPath();
      ctx.arc(this.x + cardWidth / 2, this.y + cardHeight / 2, 20, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  collect() {
    this.collected = true;
    clearTimeout(powerUpTimer);
    powerUpTimer = null;
    // Apply power-up effect, e.g., double score for 5 seconds
    setTimeout(() => {
      score /= 2;
    }, 5000);
  }
}

function createGrid() {
  const values = [];
  for (let i = 1; i <= (gridSize * gridSize) / 2; i++) {
    values.push(i, i);
  }
  values.sort(() => Math.random() - 0.5);
  for (let i = 0; i < gridSize; i++) {
    for (let j = 0; j < gridSize; j++) {
      const x = j * (cardWidth + margin);
      const y = i * (cardHeight + margin);
      cards.push(new Card(x, y, values[i * gridSize + j]));
    }
  }
}

function createPowerUps() {
  for (let i = 0; i < gridSize; i++) {
    for (let j = 0; j < gridSize; j++) {
      const x = j * (cardWidth + margin) + cardWidth / 2;
      const y = i * (cardHeight + margin) + cardHeight / 2;
      powerUps.push(new PowerUp(x, y));
    }
  }
}

function checkPowerUpCollision(x, y) {
  for (const powerUp of powerUps) {
    const dx = x - powerUp.x;
    const dy = y - powerUp.y;
    if (dx * dx + dy * dy < 400) {
      powerUp.collect();
      break;
    }
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (const card of cards) {
    card.draw();
  }
  for (const powerUp of powerUps) {
    powerUp.draw();
  }
  ctx.fillStyle = '#000';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
}

function update() {
  if (flippedCards.length === 2) {
    setTimeout(() => {
      flippedCards[0].flip();
      flippedCards[1].flip();
      flippedCards[0].checkMatch(flippedCards[1]);
      flippedCards = [];
    }, 500);
  }
}

canvas.addEventListener('click', (e) => {
  const rect = canvas.getBoundingClientRect();
  const x = (e.clientX - rect.left) * pixelRatio;
  const y = (e.clientY - rect.top) * pixelRatio;
  checkPowerUpCollision(x, y);
  for (const card of cards) {
    if (x > card.x && x < card.x + cardWidth && y > card.y && y < card.y + cardHeight) {
      if (!card.flipped && !card.matched) {
        card.flip();
        flippedCards.push(card);
        if (flippedCards.length === 2) {
          break;
        }
      }
    }
  }
});

createGrid();
createPowerUps();
setInterval(update, 100);
setInterval(draw, 100);
