class Kitchen {
  constructor(orderSystem) {
    this.orderSystem = orderSystem;
  }

  startCooking(orderId) {
    const order = this.orderSystem.orders.find(o => o.orderId === orderId);
    if (order && order.status === 'received') {
      order.status = 'cooking';
      console.log(`Order ${orderId} is now cooking.`);
      setTimeout(() => this.finishCooking(orderId), 2000); // Simulate cooking time
    } else {
      console.log(`Order ${orderId} cannot be started cooking.`);
    }
  }

  finishCooking(orderId) {
    const order = this.orderSystem.orders.find(o => o.orderId === orderId);
    if (order && order.status === 'cooking') {
      order.status = 'ready';
      console.log(`Order ${orderId} is ready.`);
    }
  }
}

class Customer {
  constructor(orderSystem) {
    this.orderSystem = orderSystem;
  }

  placeOrder(items) {
    return this.orderSystem.takeOrder('Customer', items);
  }

  checkOrderStatus(orderId) {
    this.orderSystem.getOrderStatus(orderId);
  }
}

