const canvas = document.createElement('canvas');
canvas.width = 400;
canvas.height = 400;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
const tileSize = 100;
const grid = Array.from({ length: 4 }, () => Array(4).fill(0));
let score = 0;
let level = 1;
let gameOver = false;

function drawGrid() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.strokeStyle = '#ccc';
  for (let i = 1; i < 4; i++) {
    ctx.beginPath();
    ctx.moveTo(i * tileSize, 0);
    ctx.lineTo(i * tileSize, canvas.height);
    ctx.stroke();
    ctx.moveTo(0, i * tileSize);
    ctx.lineTo(canvas.width, i * tileSize);
    ctx.stroke();
  }
}

function drawTiles() {
  for (let y = 0; y < 4; y++) {
    for (let x = 0; x < 4; x++) {
      const value = grid[y][x];
      ctx.fillStyle = value ? (value > 4 ? '#776e65' : '#cdc1b4') : '#cdc1b4';
      ctx.fillRect(x * tileSize, y * tileSize, tileSize, tileSize);
      if (value) {
        ctx.font = '50px Arial';
        ctx.fillStyle = value > 4 ? '#f9f6f2' : '#776e65';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(value, x * tileSize + tileSize / 2, y * tileSize + tileSize / 2);
      }
    }
  }
}

function spawnTile() {
  const emptyTiles = [];
  for (let y = 0; y < 4; y++) {
    for (let x = 0; x < 4; x++) {
      if (grid[y][x] === 0) {
        emptyTiles.push({ x, y });
      }
    }
  }
  if (emptyTiles.length > 0) {
    const randomTile = emptyTiles[Math.floor(Math.random() * emptyTiles.length)];
    grid[randomTile.y][randomTile.x] = Math.random() < 0.9 ? 2 : 4;
  }
}

function moveTiles(direction) {
  let moved = false;
  const tempGrid = JSON.parse(JSON.stringify(grid));
  for (let y = 0; y < 4; y++) {
    for (let x = 0; x < 4; x++) {
      if (direction === 'up' && grid[y][x] !== 0) {
        let moveY = y;
        while (moveY > 0 && grid[moveY - 1][x] === 0) {
          grid[moveY - 1][x] = grid[moveY][x];
          grid[moveY][x] = 0;
          moveY--;
          moved = true;
        }
        if (moveY > 0 && grid[moveY - 1][x] === grid[moveY][x]) {
          grid[moveY - 1][x] *= 2;
          score += grid[moveY - 1][x];
          grid[moveY][x] = 0;
          moved = true;
        }
      }
      if (direction === 'down' && grid[y][x] !== 0) {
        let moveY = y;
        while (moveY < 3 && grid[moveY + 1][x] === 0) {
          grid[moveY + 1][x] = grid[moveY][x];
          grid[moveY][x] = 0;
          moveY++;
          moved = true;
        }
        if (moveY < 3 && grid[moveY + 1][x] === grid[moveY][x]) {
          grid[moveY + 1][x] *= 2;
          score += grid[moveY + 1][x];
          grid[moveY][x] = 0;
          moved = true;
        }
      }
      if (direction === 'left' && grid[y][x] !== 0) {
        let moveX = x;
        while (moveX > 0 && grid[y][moveX - 1] === 0) {
          grid[y][moveX - 1] = grid[y][moveX];
          grid[y][moveX] = 0;
          moveX--;
          moved = true;
        }
        if (moveX > 0 && grid[y][moveX - 1] === grid[y][moveX]) {
          grid[y][moveX - 1] *= 2;
          score += grid[y][moveX - 1];
          grid[y][moveX] = 0;
          moved = true;
        }
      }
      if (direction === 'right' && grid[y][x] !== 0) {
        let moveX = x;
        while (moveX < 3 && grid[y][moveX + 1] === 0) {
          grid[y][moveX + 1] = grid[y][moveX];
          grid[y][moveX] = 0;
          moveX++;
          moved = true;
        }
        if (moveX < 3 && grid[y][moveX + 1] === grid[y][moveX]) {
          grid[y][moveX + 1] *= 2;
          score += grid[y][moveX + 1];
          grid[y][moveX] = 0;
          moved = true;
        }
      }
    }
  }
  if (moved) {
    spawnTile();
  }
}

function checkGameOver() {
  for (let y = 0; y < 4; y++) {
    for (let x = 0; x < 4; x++) {
      if (grid[y][x] === 0) {
        return false;
      }
      if (y > 0 && grid[y][x] === grid[y - 1][x]) {
        return false;
      }
      if (y < 3 && grid[y][x] === grid[y + 1][x]) {
        return false;
      }
      if (x > 0 && grid[y][x] === grid[y][x - 1]) {
        return false;
      }
      if (x < 3 && grid[y][x] === grid[y][x + 1]) {
        return false;
      }
    }
  }
  return true;
}

function update() {
  if (gameOver) {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.font = '50px Arial';
    ctx.fillStyle = '#f9f6f2';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    return;
  }
  drawGrid();
  drawTiles();
}

function gameLoop() {
  update();
  requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
  if (gameOver) return;
  switch (e.key) {
    case 'ArrowUp':
      moveTiles('up');
      break;
    case 'ArrowDown':
      moveTiles('down');
      break;
    case 'ArrowLeft':
      moveTiles('left');
      break;
    case 'ArrowRight':
      moveTiles('right');
      break;
  }
  gameOver = checkGameOver();
  level = Math.floor(score / 100) + 1;
});

