class Loot {
  constructor(name, value) {
    this.name = name;
    this.value = value;
  }
}

class RarityTable {
  constructor() {
    this.table = {
      COMMON: 0.6,
      UNCOMMON: 0.3,
      RARE: 0.08,
      EPIC: 0.02
    };
  }

  rollRarity() {
    const roll = Math.random();
    let cumulativeProbability = 0;

    for (const [rarity, probability] of Object.entries(this.table)) {
      cumulativeProbability += probability;
      if (roll <= cumulativeProbability) {
        return rarity;
      }
    }

    return 'COMMON'; // Fallback to COMMON if roll is outside expected range
  }
}

class Inventory {
  constructor() {
    this.items = [];
  }

  addItem(item) {
    this.items.push(item);
  }

  listItems() {
    return this.items.map(item => `${item.name} (${item.value})`).join(', ');
  }
}

class GameCoordinator {
  constructor() {
    this.rarityTable = new RarityTable();
    this.inventory = new Inventory();
  }

  generateLoot() {
    const rarity = this.rarityTable.rollRarity();
    let value = 0;

    switch (rarity) {
      case 'COMMON':
        value = 10;
        break;
      case 'UNCOMMON':
        value = 50;
        break;
      case 'RARE':
        value = 100;
        break;
      case 'EPIC':
        value = 500;
        break;
    }

    const lootName = `${rarity} Loot`;
    const loot = new Loot(lootName, value);
    this.inventory.addItem(loot);
    console.log(`Generated ${lootName} worth ${value} and added to inventory.`);
  }

  displayInventory() {
