class CombatSystem {
  constructor() {
    this.attacks = {};
  }

  registerAttack(name, damage) {
    this.attacks[name] = damage;
  }

  performAttack(attacker, defender, attackName) {
    if (this.attacks[attackName]) {
      return this.attacks[attackName];
    }
    return 0;
  }
}

class HealthSystem {
  constructor() {
    this.healths = {};
  }

  setHealth(entity, health) {
    this.healths[entity] = health;
  }

  getHealth(entity) {
    return this.healths[entity] || 0;
  }

  takeDamage(entity, damage) {
    if (this.healths[entity]) {
      this.healths[entity] -= damage;
      if (this.healths[entity] < 0) {
        this.healths[entity] = 0;
      }
    }
  }
}

class LootSystem {
  constructor() {
    this.loot = {};
  }

  addItem(item) {
    if (!this.loot[item]) {
      this.loot[item] = 0;
    }
    this.loot[item]++;
  }

  getItemCount(item) {
    return this.loot[item] || 0;
  }
}

class GameCoordinator {
  constructor() {
    this.combat = new CombatSystem();
    this.health = new HealthSystem();
    this.loot = new LootSystem();
  }

  registerAttack(name, damage) {
    this.combat.registerAttack(name, damage);
  }

  setHealth(entity, health) {
    this.health.setHealth(entity, health);
  }

  performAttack(attacker, defender, attackName) {
    const damage = this.combat.performAttack(attacker, defender, attackName);
    if (damage > 0) {
      this.health.takeDamage(defender, damage);
    }
    console.log(`${attacker} attacks ${defender} for ${damage} damage. ${defender} has ${this.health.getHealth(defender)} health remaining.`);
  }

  addItem(item) {
    this.loot.addItem(item);
  }

  getItemCount(item) {
    return this.loot.getItemCount(item);
  }
}

// Runnable demo
const game = new GameCoordinator();

game.registerAttack('Punch', 10);
game.setHealth('Player', 100);
game.setHealth('Enemy', 50);

game.performAttack('Player', 'Enemy', 'Punch'); // Player attacks Enemy for 10 damage. Enemy has 40 health remaining.
game.performAttack('Enemy', 'Player', 'Punch'); // Enemy attacks Player for 10 damage. Player has 90 health remaining.

game.addItem('Sword');
game.addItem('Potion');
console.log(`Number of Swords: ${game.getItemCount('Sword')}`); // Number of Swords: 1
console.log(`Number of Potions: ${game.getItemCount('Potion')}`); // Number of Potions: 1
