const canvas = document.createElement('canvas');
const ctx = canvas.getContext('2d');
canvas.width = 400;
canvas.height = 400;
document.body.appendChild(canvas);

const GRID_SIZE = 8;
const CELL_SIZE = 50;
const BOARD_SIZE = GRID_SIZE * CELL_SIZE;

let board = [];
let selected = null;
let state = 'menu';

function initBoard() {
  board = Array.from({ length: GRID_SIZE }, () =>
    Array.from({ length: GRID_SIZE }, () => Math.floor(Math.random() * 3))
  );
}

function drawBoard() {
  ctx.clearRect(0, 0, BOARD_SIZE, BOARD_SIZE);
  for (let y = 0; y < GRID_SIZE; y++) {
    for (let x = 0; x < GRID_SIZE; x++) {
      ctx.fillStyle = `hsl(${board[y][x] * 60}, 70%, 50%)`;
      ctx.fillRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
      ctx.strokeStyle = '#000';
      ctx.strokeRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
    }
  }
}

function drawMenu() {
  ctx.clearRect(0, 0, BOARD_SIZE, BOARD_SIZE);
  ctx.font = '24px Arial';
  ctx.fillStyle = '#000';
  ctx.textAlign = 'center';
  ctx.fillText('Match-3 Game', BOARD_SIZE / 2, BOARD_SIZE / 2 - 30);
  ctx.fillText('Click to Start', BOARD_SIZE / 2, BOARD_SIZE / 2 + 30);
}

function drawPaused() {
  ctx.clearRect(0, 0, BOARD_SIZE, BOARD_SIZE);
  ctx.font = '24px Arial';
  ctx.fillStyle = '#000';
  ctx.textAlign = 'center';
  ctx.fillText('Game Paused', BOARD_SIZE / 2, BOARD_SIZE / 2);
}

function drawGameOver() {
  ctx.clearRect(0, 0, BOARD_SIZE, BOARD_SIZE);
  ctx.font = '24px Arial';
  ctx.fillStyle = '#000';
  ctx.textAlign = 'center';
  ctx.fillText('Game Over', BOARD_SIZE / 2, BOARD_SIZE / 2 - 30);
  ctx.fillText('Click to Restart', BOARD_SIZE / 2, BOARD_SIZE / 2 + 30);
}

function handleMenuClick(event) {
  const x = Math.floor(event.offsetX / CELL_SIZE);
  const y = Math.floor(event.offsetY / CELL_SIZE);
  if (x >= GRID_SIZE / 2 - 1 && x <= GRID_SIZE / 2 && y >= GRID_SIZE / 2 && y <= GRID_SIZE / 2 + 1) {
    state = 'playing';
    initBoard();
  }
}

function handleGameOverClick(event) {
  const x = Math.floor(event.offsetX / CELL_SIZE);
  const y = Math.floor(event.offsetY / CELL_SIZE);
  if (x >= GRID_SIZE / 2 - 1 && x <= GRID_SIZE / 2 && y >= GRID_SIZE / 2 && y <= GRID_SIZE / 2 + 1) {
    state = 'playing';
    initBoard();
  }
}

function handlePlayingClick(event) {
  const x = Math.floor(event.offsetX / CELL_SIZE);
  const y = Math.floor(event.offsetY / CELL_SIZE);
  if (selected) {
    const [sx, sy] = selected;
    if (Math.abs(sx - x) + Math.abs(sy - y) === 1) {
      [board[sy][sx], board[y][x]] = [board[y][x], board[sy][sx]];
      checkAndRemoveMatches();
      selected = null;
    } else {
      selected = [x, y];
    }
  } else {
    selected = [x, y];
  }
}

function checkAndRemoveMatches() {
  let matches = findMatches();
  while (matches.length > 0) {
    removeMatches(matches);
    dropTiles();
    matches = findMatches();
  }
}

function findMatches() {
  let matches = [];
  for (let y = 0; y < GRID_SIZE; y++) {
    for (let x = 0; x < GRID_SIZE; x++) {
      const value = board[y][x];
      if (value !== -1) {
        let horizontal = 1;
        let vertical = 1;
        for (let i = x + 1; i < GRID_SIZE && board[y][i] === value; i++) horizontal++;
        for (let i = y + 1; i < GRID_SIZE && board[i][x] === value; i++) vertical++;
        if (horizontal >= 3) {
          for (let i = 0; i < horizontal; i++) matches.push([y, x + i]);
        }
        if (vertical >= 3) {
          for (let i = 0; i < vertical; i++) matches.push([y + i, x]);
        }
      }
    }
  }
  return matches;
}

function removeMatches(matches) {
  matches.forEach(([y, x]) => board[y][x] = -1);
}

function dropTiles() {
  for (let x = 0; x < GRID_SIZE; x++) {
    let emptyCount = 0;
    for (let y = GRID_SIZE - 1; y >= 0; y--) {
      if (board[y][x] === -1) {
        emptyCount++;
      } else {
        board[y + emptyCount][x] = board[y][x];
        if (emptyCount > 0) {
          board[y][x] = -1;
        }
      }
    }
    for (let y = emptyCount - 1; y >= 0; y--) {
      board[y][x] = Math.floor(Math.random() * 3);
    }
  }
}

function update() {
  switch (state) {
    case 'menu':
      drawMenu();
      break;
    case 'playing':
      drawBoard();
      break;
    case 'paused':
      drawPaused();
      break;
    case 'gameover':
      drawGameOver();
      break;
  }
}

function gameLoop() {
  update();
  requestAnimationFrame(gameLoop);
}

canvas.addEventListener('click', (event) => {
  switch (state) {
    case 'menu':
      handleMenuClick(event);
      break;
    case 'playing':
      handlePlayingClick(event);
      break;
    case 'gameover':
      handleGameOverClick(event);
      break;
  }
});

gameLoop();
