```js
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = 800;
canvas.height = 600;

const states = {
    MENU: 'menu',
    PLAYING: 'playing',
    PAUSED: 'paused',
    GAMEOVER: 'gameover'
};

let currentState = states.MENU;

const keys = {
    LEFT: false,
    RIGHT: false,
    UP: false,
    SPACE: false,
    PAUSE: false
};

const asteroids = [];
const bullets = [];
const player = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    radius: 10,
    angle: Math.PI / 2,
    speed: 5,
    rotationSpeed: 0.05,
    bullets: []
};

function spawnAsteroid() {
    const x = Math.random() * canvas.width;
    const y = Math.random() * canvas.height;
    const radius = Math.random() * 20 + 10;
    const speed = Math.random() * 2 + 1;
    const angle = Math.random() * Math.PI * 2;
    asteroids.push({ x, y, radius, speed, angle });
}

function updateAsteroids(dt) {
    for (let i = asteroids.length - 1; i >= 0; i--) {
        const asteroid = asteroids[i];
        asteroid.x += Math.cos(asteroid.angle) * asteroid.speed * dt;
        asteroid.y += Math.sin(asteroid.angle) * asteroid.speed * dt;
        if (asteroid.x < -asteroid.radius || asteroid.x > canvas.width + asteroid.radius ||
            asteroid.y < -asteroid.radius || asteroid.y > canvas.height + asteroid.radius) {
            asteroids.splice(i, 1);
        }
    }
}

function updateBullets(dt) {
    for (let i = bullets.length - 1; i >= 0; i--) {
        const bullet = bullets[i];
        bullet.x += Math.cos(bullet.angle) * 10 * dt;
        bullet.y += Math.sin(bullet.angle) * 10 * dt;
        if (bullet.x < -bullet.radius || bullet.x > canvas.width + bullet.radius ||
            bullet.y < -bullet.radius || bullet.y > canvas.height + bullet.radius) {
            bullets.splice(i, 1);
        }
    }
}

function checkCollisions() {
    for (let i = asteroids.length - 1; i >= 0; i--) {
        const asteroid = asteroids[i];
        for (let j = bullets.length - 1; j >= 0; j--) {
            const bullet = bullets[j];
            const dx = asteroid.x - bullet.x;
            const dy = asteroid.y - bullet.y;
            const distance = Math.sqrt(dx * dx + dy * dy);
            if (distance < asteroid.radius + bullet.radius) {
                asteroids.splice(i, 1);
                bullets.splice(j, 1);
                break;
            }
        }
        const dx = asteroid.x - player.x;
        const dy = asteroid.y - player.y;
        const distance = Math.sqrt(dx * dx + dy * dy);
        if (distance < asteroid.radius + player.radius) {
            currentState = states.GAMEOVER;
        }
    }
}

function renderMenu() {
    ctx.fillStyle = 'black';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.font = '30px Arial';
    ctx.fillStyle = 'white';
    ctx.textAlign = 'center';
    ctx.fillText('Asteroids', canvas.width / 2, canvas.height / 2 - 20);
    ctx.fillText('Press Enter to Start', canvas.width / 2, canvas.height / 2 + 20);
}

function renderPlaying() {
    ctx.fillStyle = 'black';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.beginPath();
    ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
    ctx.fillStyle = 'white';
    ctx.fill();
    for (const bullet of bullets) {
        ctx.beginPath();
        ctx.arc(bullet.x, bullet.y, bullet.radius, 0, Math.PI * 2);
        ctx.fillStyle = 'red';
        ctx.fill();
    }
    for (const asteroid of asteroids) {
        ctx.beginPath();
        ctx.arc(asteroid.x, asteroid.y, asteroid.radius, 0, Math.PI * 2);
        ctx.fillStyle = 'gray';
        ctx.fill();
    }
}

function renderPaused() {
    ctx.fillStyle = 'black';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.font = '30px Arial';
    ctx.fillStyle = 'white';
    ctx.textAlign = 'center';
    ctx.fillText('Paused', canvas.width / 2, canvas.height / 2);
}

function renderGameOver() {
    ctx.fillStyle = 'black';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.font = '30px Arial';
    ctx.fillStyle = 'white';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2 - 20);
    ctx.fillText('Press Enter to Restart', canvas.width / 2, canvas.height / 2 + 20);
}

function render() {
    switch (currentState) {
        case states.MENU:
            renderMenu();
            break;
        case states.PLAYING:
            renderPlaying();
            break;
        case states.PAUSED:
            renderPaused();
            break;
        case states.GAMEOVER:
            renderGameOver();
            break;
    }
}

function update(dt) {
    switch (currentState) {
        case states.PLAYING:
            if (keys.LEFT) player.angle -= player.rotationSpeed * dt;
            if (keys.RIGHT) player.angle += player.rotationSpeed * dt;
            if (keys.UP) {
                player.x += Math.cos(player.angle) * player.speed * dt;
                player.y += Math.sin(player.angle) * player.speed * dt;
            }
            if (keys.SPACE) {
                if (player.bullets.length === 0) {
                    bullets.push({
                        x: player.x + Math.cos(player.angle) * player.radius,
                        y: player.y + Math.sin(player.angle) * player.radius,
                        radius: 3,
                        angle: player.angle
                    });
                }
                keys.SPACE = false;
            }
            updateAsteroids(dt);
            updateBullets(dt);
            checkCollisions();
            break;
    }
}

function gameLoop(timestamp) {
    const dt = 1 / 60;
    update(dt);
    render();
    requestAnimationFrame(gameLoop);
}

function handleKeyDown(event) {
    switch (event.key) {
        case 'ArrowLeft':
            keys.LEFT = true;
            break;
        case 'ArrowRight':
            keys.RIGHT = true;
            break;
        case 'ArrowUp':
            keys.UP = true;
            break;
        case 'Space':
            keys.SPACE = true;
            break;
        case 'p':
            keys.PAUSE = true;
            break;
        case 'Enter':
            if (currentState === states.MENU || currentState === states.GAMEOVER) {
                currentState = states.PLAYING;
                asteroids.length = 0;
                bullets.length = 0;
            }
            break;
    }
}

function handleKeyUp(event) {
    switch (event.key) {
        case 'ArrowLeft':
            keys.LEFT = false;
            break;
        case 'ArrowRight':
            keys.RIGHT = false;
            break;
        case 'ArrowUp':
            keys.UP = false;
            break;
        case 'p':
            keys.PAUSE = false;
            currentState = currentState === states.PAUSED ? states.PLAYING : states.PAUSED;
            break;
    }
}

document.addEventListener('keydown', handleKeyDown);
document.addEventListener('keyup', handleKeyUp);

gameLoop();
