let elapsedTime = 0;
let pausedTime = 0;
let gameOver = false;

function getRandomText() {
  const words = ['hello', 'world', 'javascript', 'finite', 'state', 'machine', 'typing', 'speed'];
  return words[Math.floor(Math.random() * words.length)];
}

function updateMenu(dt) {
  if (inputText.length > 0) {
    startGame();
  }
}

function updatePlaying(dt) {
  if (inputText === targetText) {
    gameOver = true;
    elapsedTime = Date.now() - startTime;
  }
  if (gameOver) {
    currentState = states.gameover;
  }
}

function updatePaused(dt) {
  pausedTime += dt;
}

function updateGameover(dt) {
  // Stay in gameover state
}

const updateFunctions = {
  [states.menu]: updateMenu,
  [states.playing]: updatePlaying,
  [states.paused]: updatePaused,
  [states.gameover]: updateGameover
};

function renderMenu() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'white';
  ctx.font = '48px Arial';
  ctx.fillText('Type the word:', 50, 100);
