class Building {
    constructor(name, resourcesRequired = {}) {
        this.name = name;
        this.resourcesRequired = resourcesRequired;
    }

    canBuild(economy) {
        for (const [resource, amount] of Object.entries(this.resourcesRequired)) {
            if (economy.getResource(resource) < amount) {
                return false;
            }
        }
        return true;
    }

    build(economy) {
        if (this.canBuild(economy)) {
            for (const [resource, amount] of Object.entries(this.resourcesRequired)) {
                economy.spendResource(resource, amount);
            }
            console.log(`${this.name} built successfully.`);
            return true;
        } else {
            console.log(`Cannot build ${this.name}: insufficient resources.`);
            return false;
        }
    }
}

class Resource {
    constructor(name, initialAmount = 0) {
        this.name = name;
        this.amount = initialAmount;
    }

    getName() {
        return this.name;
    }

    getAmount() {
        return this.amount;
    }

    add(amount) {
        this.amount += amount;
        console.log(`Added ${amount} ${this.name}. Total: ${this.amount}.`);
    }

    spend(amount) {
        if (this.amount >= amount) {
            this.amount -= amount;
            console.log(`Spent ${amount} ${this.name}. Remaining: ${this.amount}.`);
            return true;
        } else {
            console.log(`Insufficient ${this.name} to spend ${amount}.`);
            return false;
        }
    }
}

class Economy {
    constructor() {
        this.resources = {};
    }

    addResource(resource) {
        this.resources[resource.getName()] = resource;
    }

    getResource(name) {
        const resource = this.resources[name];
        if (resource) {
            return resource.getAmount();
        } else {
            console.log(`Resource ${name} not found.`);
            return 0;
        }
    }

    earnResource(name, amount) {
