canvas.height = CANVAS_HEIGHT;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Player controls
function movePlayer(event) {
    const key = event.key;
    if (key === 'ArrowLeft' && player.x > 0) {
        player.x -= PLAYER_SPEED;
    } else if (key === 'ArrowRight' && player.x < CANVAS_WIDTH - player.width) {
        player.x += PLAYER_SPEED;
    }
}

document.addEventListener('keydown', movePlayer);

// Shooting
function shoot() {
    if (Date.now() - lastShotTime >= SHOT_INTERVAL) {
        bullets.push({
            x: player.x + player.width / 2,
            y: player.y,
            width: 5,
            height: 5,
            color: 'red'
        });
        lastShotTime = Date.now();
    }
}

document.addEventListener('click', shoot);

// Enemy spawning
function spawnEnemy() {
    enemies.push({
        x: Math.random() * (CANVAS_WIDTH - 20),
        y: 0,
        width: 20,
        height: 20,
        color: 'green'
    });
}

setInterval(spawnEnemy, 1000);

// Game loop
function gameLoop() {
    if (gameOver) return;

    // Clear screen
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Move bullets
    bullets = bullets.filter(bullet => {
        bullet.y -= BULLET_SPEED;
        return bullet.y > 0;
    });

    // Move enemies
    enemies.forEach(enemy => {
        enemy.y += ENEMY_SPEED;
    });

    // Collision detection
    bullets.forEach(bullet => {
        enemies = enemies.filter(enemy => {
            if (bullet.x < enemy.x + enemy.width &&
                bullet.x + bullet.width > enemy.x &&
                bullet.y < enemy.y + enemy.height &&
                bullet.y + bullet.height > enemy.y) {
                score++;
                return false;
            }
            return true;
        });
    });

    // Check for game over
    if (enemies.some(enemy => enemy.y > CANVAS_HEIGHT - enemy.height)) {
        gameOver = true;
        alert(`Game Over! Your score: ${score}`);
    }

    // Draw player
    ctx.fillStyle = player.color;
    ctx.fillRect(player.x, player.y, player.width, player.height);

    // Draw bullets
    bullets.forEach(bullet => {
        ctx.fillStyle = bullet.color;
        ctx.fillRect(bullet.x, bullet.y, bullet.width, bullet.height);
    });

    // Draw enemies
    enemies.forEach(enemy => {
        ctx.fillStyle = enemy.color;
        ctx.fillRect(enemy.x, enemy.y, enemy.width, enemy.height);
    });

    // Draw score
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);

    // Next frame
    requestAnimationFrame(gameLoop);
}

// Start game loop
requestAnimationFrame(gameLoop);
