class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Hunger {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.hungerLevel = 100;
    this.eventBus.subscribe('tick', this.onTick.bind(this));
    this.eventBus.subscribe('eat', this.onEat.bind(this));
  }

  onTick() {
    this.hungerLevel -= 1;
    if (this.hungerLevel <= 0) {
      console.log('You are starving!');
    } else {
      console.log(`Hunger level: ${this.hungerLevel}`);
    }
  }

  onEat(amount = 10) {
    this.hungerLevel += amount;
    if (this.hungerLevel > 100) {
      this.hungerLevel = 100;
    }
    console.log(`Ate ${amount}. Hunger level now: ${this.hungerLevel}`);
  }
}

class Energy {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.energyLevel = 100;
    this.eventBus.subscribe('tick', this.onTick.bind(this));
    this.eventBus.subscribe('rest', this.onRest.bind(this));
  }

  onTick() {
    this.energyLevel -= 1;
    if (this.energyLevel <= 0) {
      console.log('You are completely drained!');
    } else {
      console.log(`Energy level: ${this.energyLevel}`);
    }
  }

  onRest(amount = 10) {
    this.energyLevel += amount;
    if (this.energyLevel > 100) {
      this.energyLevel = 100;
    }
    console.log(`Rested ${amount}. Energy level now: ${this.energyLevel}`);
  }
}

class Clock {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.time = 0;
    setInterval(() => this.tick(), 1000);
  }

  tick() {
    this.time += 1;
    console.log(`Time elapsed: ${this.time} seconds`);
    this.eventBus.emit('tick');
  }
}

