  y: height / 2,
  size: 20,
  health: 100
};

let ball = {
  x: Math.random() * width,
  y: 0,
  size: 10,
  speed: 2
};

function drawPlayer() {
  ctx.beginPath();
  ctx.arc(player.x, player.y, player.size * devicePixelRatio, 0, Math.PI * 2);
  ctx.fillStyle = 'blue';
  ctx.fill();
}

function drawBall() {
  ctx.beginPath();
  ctx.arc(ball.x * devicePixelRatio, ball.y * devicePixelRatio, ball.size * devicePixelRatio, 0, Math.PI * 2);
  ctx.fillStyle = 'red';
  ctx.fill();
}

function drawHealthBar() {
  ctx.fillStyle = 'green';
  ctx.fillRect(10 * devicePixelRatio, 10 * devicePixelRatio, player.health * 2 * devicePixelRatio, 20 * devicePixelRatio);
}

function update() {
  ball.y += ball.speed;
  if (ball.y > height) {
    ball.y = 0;
    ball.x = Math.random() * width;
  }

  if (Math.abs(player.x - ball.x) < player.size + ball.size &&
      Math.abs(player.y - ball.y) < player.size + ball.size) {
    player.health -= 10;
    if (player.health <= 0) {
      player.health = 100;
      player.x = width / 2;
      player.y = height / 2;
    }
  }

  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawPlayer();
  drawBall();
  drawHealthBar();
}

window.addEventListener('resize', () => {
