// Constants
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
const gravity = 0.5;
const jumpPower = -10;
const platformWidth = 100;
const platformHeight = 20;
const playerWidth = 30;
const playerHeight = 50;
const playerColor = 'blue';
const platformColor = 'green';
const backgroundColor = 'lightblue';
const countdownTime = 30; // seconds

// Player
let player = {
  x: 50,
  y: 50,
  width: playerWidth,
  height: playerHeight,
  velocityY: 0,
  isJumping: false
};

// Platforms
let platforms = [
  { x: 100, y: canvas.height - platformHeight, width: platformWidth, height: platformHeight },
  { x: 300, y: canvas.height - 200, width: platformWidth, height: platformHeight },
  { x: 500, y: canvas.height - 300, width: platformWidth, height: platformHeight }
];

// Countdown
let countdown = countdownTime;
let gameRunning = true;
let lastTime = 0;

// Functions
function drawPlayer() {
  ctx.fillStyle = playerColor;
  ctx.fillRect(player.x, player.y, player.width, player.height);
}

function drawPlatforms() {
  platforms.forEach(platform => {
    ctx.fillStyle = platformColor;
    ctx.fillRect(platform.x, platform.y, platform.width, platform.height);
  });
}

function drawCountdown() {
  ctx.fillStyle = 'black';
  ctx.font = '30px Arial';
  ctx.fillText(`Time: ${countdown}`, 10, 30);
}

function checkCollision(player, platform) {
  return (player.x < platform.x + platform.width &&
          player.x + player.width > platform.x &&
          player.y < platform.y + platform.height &&
          player.y + player.height > platform.y);
}

function updatePlayer() {
  player.velocityY += gravity;
  player.y += player.velocityY;

  platforms.forEach(platform => {
    if (checkCollision(player, platform) && player.velocityY > 0) {
      player.y = platform.y - player.height;
      player.velocityY = 0;
      player.isJumping = false;
    }
  });

  if (player.y + player.height > canvas.height) {
    player.y = canvas.height - player.height;
    player.velocityY = 0;
    player.isJumping = false;
  }
}

function updateCountdown(deltaTime) {
  countdown -= deltaTime / 1000;
  if (countdown <= 0) {
    countdown = 0;
    gameRunning = false;
  }
}

function gameLoop(timestamp) {
  if (!gameRunning) {
    ctx.fillStyle = 'black';
    ctx.font = '50px Arial';
    ctx.fillText('Game Over!', canvas.width / 2 - 100, canvas.height / 2);
    return;
  }

  const deltaTime = timestamp - lastTime;
  lastTime = timestamp;

  ctx.fillStyle = backgroundColor;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  updateCountdown(deltaTime);
  updatePlayer();

  drawPlatforms();
  drawPlayer();
  drawCountdown();

  requestAnimationFrame(gameLoop);
}

// Event listeners
window.addEventListener('keydown', event => {
  if (event.code === 'Space' && !player.isJumping) {
    player.velocityY = jumpPower;
    player.isJumping = true;
  }
});

// Start game loop
requestAnimationFrame(gameLoop);
