const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 300;
canvas.height = 300;
const ctx = canvas.getContext('2d');

const boardSize = 8;
const cellSize = 30;
const colors = ['red', 'blue', 'green', 'yellow', 'purple', 'orange'];

let board = [];
let selected = null;
let dragging = false;
let startX, startY;

function initBoard() {
    board = Array.from({ length: boardSize }, () => 
        Array.from({ length: boardSize }, () => Math.floor(Math.random() * colors.length))
    );
}

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let y = 0; y < boardSize; y++) {
        for (let x = 0; x < boardSize; x++) {
            ctx.fillStyle = colors[board[y][x]];
            ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
            ctx.strokeStyle = 'black';
            ctx.strokeRect(x * cellSize, y * cellSize, cellSize, cellSize);
        }
    }
}

function findMatches() {
    let matches = [];
    for (let y = 0; y < boardSize; y++) {
        for (let x = 0; x < boardSize - 2; x++) {
            const color = board[y][x];
            if (board[y][x + 1] === color && board[y][x + 2] === color) {
                matches.push([[x, y], [x + 1, y], [x + 2, y]]);
            }
        }
    }
    for (let x = 0; x < boardSize; x++) {
        for (let y = 0; y < boardSize - 2; y++) {
            const color = board[y][x];
            if (board[y + 1][x] === color && board[y + 2][x] === color) {
                matches.push([[x, y], [x, y + 1], [x, y + 2]]);
            }
        }
    }
    return matches;
}

function removeMatches(matches) {
    matches.forEach(match => {
        match.forEach(([x, y]) => {
            board[y][x] = null;
        });
    });
}

function dropCells() {
    for (let x = 0; x < boardSize; x++) {
        let nullCount = 0;
        for (let y = boardSize - 1; y >= 0; y--) {
            if (board[y][x] === null) {
                nullCount++;
            } else if (nullCount > 0) {
                board[y + nullCount][x] = board[y][x];
                board[y][x] = null;
            }
        }
    }
}

function fillBoard() {
    for (let y = 0; y < boardSize; y++) {
        for (let x = 0; x < boardSize; x++) {
            if (board[y][x] === null) {
                board[y][x] = Math.floor(Math.random() * colors.length);
            }
        }
    }
}

function update() {
    const matches = findMatches();
    if (matches.length > 0) {
        removeMatches(matches);
        dropCells();
        fillBoard();
    }
}

function swapCells(x1, y1, x2, y2) {
    [board[y1][x1], board[y2][x2]] = [board[y2][x2], board[y1][x1]];
}

function selectCell(x, y) {
    if (selected) {
        const [sx, sy] = selected;
        if (Math.abs(x - sx) + Math.abs(y - sy) === 1) {
            swapCells(sx, sy, x, y);
            update();
            selected = null;
        } else {
            selected = [x, y];
        }
    } else {
        selected = [x, y];
    }
}

function mouseDown(e) {
    startX = e.offsetX;
    startY = e.offsetY;
    dragging = true;
}

function mouseUp(e) {
    if (dragging) {
        const x = Math.floor(e.offsetX / cellSize);
        const y = Math.floor(e.offsetY / cellSize);
        selectCell(x, y);
    }
    dragging = false;
}

function mouseMove(e) {
    if (dragging) {
        const x = Math.floor(e.offsetX / cellSize);
        const y = Math.floor(e.offsetY / cellSize);
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        drawBoard();
        ctx.strokeStyle = 'black';
        ctx.strokeRect(x * cellSize, y * cellSize, cellSize, cellSize);
    }
}

function keyDown(e) {
    if (selected) {
        const [x, y] = selected;
        let nx, ny;
        switch (e.key) {
            case 'ArrowUp': nx = x; ny = y - 1; break;
            case 'ArrowDown': nx = x; ny = y + 1; break;
            case 'ArrowLeft': nx = x - 1; ny = y; break;
            case 'ArrowRight': nx = x + 1; ny = y; break;
        }
        if (nx >= 0 && nx < boardSize && ny >= 0 && ny < boardSize) {
            swapCells(x, y, nx, ny);
            update();
            selected = null;
        }
    }
}

canvas.addEventListener('mousedown', mouseDown);
canvas.addEventListener('mouseup', mouseUp);
canvas.addEventListener('mousemove', mouseMove);
document.addEventListener('keydown', keyDown);

initBoard();
function gameLoop() {
    drawBoard();
    requestAnimationFrame(gameLoop);
}
gameLoop();
