// Health System
class Health {
    constructor() {
        this.healthMap = {};
    }

    setHealth(entity, health) {
        this.healthMap[entity] = health;
        console.log(`${entity} now has ${health} health.`);
    }

    takeDamage(entity, damage) {
        if (this.healthMap[entity] !== undefined) {
            this.healthMap[entity] -= damage;
            if (this.healthMap[entity] <= 0) {
                this.healthMap[entity] = 0;
                console.log(`${entity} has been defeated.`);
            } else {
                console.log(`${entity} took ${damage} damage and now has ${this.healthMap[entity]} health.`);
            }
        } else {
            console.log(`${entity} does not exist in the health system.`);
        }
    }
}

// Loot System
class Loot {
    constructor() {
        this.lootMap = {};
    }

    addLoot(entity, loot) {
        if (!this.lootMap[entity]) {
            this.lootMap[entity] = [];
        }
        this.lootMap[entity].push(loot);
        console.log(`${entity} received ${loot}.`);
    }

    getLoot(entity) {
        return this.lootMap[entity] || [];
    }
}

// Demo
