class Skill {
    constructor(name) {
        this.name = name;
        this.level = 1;
    }

    getName() {
        return this.name;
    }

    getLevel() {
        return this.level;
    }

    upgrade() {
        this.level++;
        console.log(`Skill ${this.name} upgraded to level ${this.level}`);
    }
}

class Experience {
    constructor(skill) {
        this.skill = skill;
        this.points = 0;
    }

    addPoints(points) {
        this.points += points;
        console.log(`Added ${points} experience points to ${this.skill.getName()}. Total: ${this.points}`);
    }

    getPoints() {
        return this.points;
    }

    isLevelUp() {
        return this.points >= 100;
    }

    resetPoints() {
        this.points = 0;
    }
}

class LevelUp {
    constructor(skill, experience) {
        this.skill = skill;
        this.experience = experience;
    }

    checkAndLevelUp() {
        if (this.experience.isLevelUp()) {
            this.skill.upgrade();
            this.experience.resetPoints();
            console.log(`Levelled up ${this.skill.getName()}! Experience points reset.`);
        }
    }
}

class GameCoordinator {
    constructor() {
        this.skill = new Skill("Swordsman");
        this.experience = new Experience(this.skill);
        this.levelUp = new LevelUp(this.skill, this.experience);
    }

    gainExperience(points) {
        this.experience.addPoints(points);
        this.levelUp.checkAndLevelUp();
    }
}

// Demo
