// Economy system
class Economy {
    constructor() {
        this.balance = 0;
    }

    getBalance() {
        return this.balance;
    }

    deposit(amount) {
        this.balance += amount;
    }

    withdraw(amount) {
        if (amount > this.balance) {
            throw new Error("Insufficient funds");
        }
        this.balance -= amount;
    }
}

// Store system
class Store {
    constructor() {
        this.items = {
            "sword": { price: 50 },
            "potion": { price: 20 }
        };
    }

    getItemPrice(itemName) {
        return this.items[itemName]?.price || 0;
    }

    purchase(itemName, economy) {
        const price = this.getItemPrice(itemName);
        if (price > 0) {
            economy.withdraw(price);
            return true;
        }
        return false;
    }
}

// Inventory system
class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(itemName, quantity = 1) {
        if (this.items[itemName]) {
            this.items[itemName] += quantity;
        } else {
            this.items[itemName] = quantity;
        }
    }

    getItemCount(itemName) {
        return this.items[itemName] || 0;
    }
}

// Coordinator to wire the systems together
class GameCoordinator {
    constructor() {
        this.economy = new Economy();
        this.store = new Store();
        this.inventory = new Inventory();
    }

    buyItem(itemName) {
        try {
            if (this.store.purchase(itemName, this.economy)) {
                this.inventory.addItem(itemName);
                console.log(`Purchased ${itemName}. New balance: ${this.economy.getBalance()}`);
            } else {
                console.log(`Failed to purchase ${itemName}. Item not found or out of stock.`);
            }
        } catch (error) {
            console.error(error.message);
        }
    }

    depositMoney(amount) {
        this.economy.deposit(amount);
        console.log(`Deposited ${amount}. New balance: ${this.economy.getBalance()}`);
    }

    checkInventory() {
        console.log("Inventory:");
        for (const [itemName, quantity] of Object.entries(this.inventory.items)) {
            console.log(`${itemName}: ${quantity}`);
        }
    }
}

