  ctx.restore();
}

function drawAsteroid(asteroid) {
  drawCircle(asteroid.x, asteroid.y, asteroid.radius, 'red');
}

function drawBullet(bullet) {
  drawCircle(bullet.x, bullet.y, bullet.radius, 'yellow');
}

function drawScore() {
  ctx.fillStyle = 'white';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score.value}`, score.displayX, score.displayY);
}

function updatePlayer() {
  player.thrust.x = player.speed * Math.cos(player.angle);
  player.thrust.y = player.speed * Math.sin(player.angle);
  player.x += player.thrust.x;
  player.y += player.thrust.y;

  if (player.x < 0) player.x = canvas.width;
  if (player.x > canvas.width) player.x = 0;
  if (player.y < 0) player.y = canvas.height;
  if (player.y > canvas.height) player.y = 0;
}

function updateAsteroids() {
  asteroids.forEach(asteroid => {
    asteroid.x += asteroid.velocityX;
    asteroid.y += asteroid.velocityY;

    if (asteroid.x < 0) asteroid.x = canvas.width;
    if (asteroid.x > canvas.width) asteroid.x = 0;
    if (asteroid.y < 0) asteroid.y = canvas.height;
    if (asteroid.y > canvas.height) asteroid.y = 0;
  });
}

function updateBullets() {
  bullets.forEach((bullet, index) => {
    bullet.x += bullet.speed * Math.cos(bullet.angle);
    bullet.y += bullet.speed * Math.sin(bullet.angle);

    if (bullet.x < 0 || bullet.x > canvas.width || bullet.y < 0 || bullet.y > canvas.height) {
      bullets.splice(index, 1);
    }
  });
}

function checkCollisions() {
  asteroids.forEach((asteroid, index) => {
    const distance = Math.hypot(asteroid.x - player.x, asteroid.y - player.y);
    if (distance < asteroid.radius + player.radius) {
      // Game Over
      alert(`Game Over! Your score: ${score.value}`);
      location.reload();
    }

    bullets.forEach((bullet, bulletIndex) => {
      const distance = Math.hypot(asteroid.x - bullet.x, asteroid.y - bullet.y);
      if (distance < asteroid.radius + bullet.radius) {
        score.value += 100;
        asteroids.splice(index, 1);
        bullets.splice(bulletIndex, 1);
        // Split asteroid if needed
      }
    });
  });
}

function spawnAsteroid() {
  const radius = Math.random() * 20 + 10;
  const x = Math.random() * canvas.width;
  const y = Math.random() * canvas.height;
  const velocityX = (Math.random() - 0.5) * 3;
  const velocityY = (Math.random() - 0.5) * 3;
  asteroids.push(createAsteroid(x, y, radius, velocityX, velocityY));
}

function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  updatePlayer();
  updateAsteroids();
  updateBullets();
  checkCollisions();

  drawPlayer();
  asteroids.forEach(drawAsteroid);
  bullets.forEach(drawBullet);
  drawScore();

  requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', e => {
