(function() {
    const canvas = document.createElement('canvas');
    document.body.appendChild(canvas);
    const ctx = canvas.getContext('2d');
    let dpr = window.devicePixelRatio || 1;
    let width = window.innerWidth;
    let height = window.innerHeight;
    canvas.width = width * dpr;
    canvas.height = height * dpr;
    ctx.scale(dpr, dpr);

    const CARD_WIDTH = 80;
    const CARD_HEIGHT = 120;
    const MARGIN = 10;
    const CARDS = [
        'A', 'A', 'B', 'B', 'C', 'C', 'D', 'D', 'E', 'E', 'F', 'F', 'G', 'G', 'H', 'H'
    ];
    let shuffledCards = [];
    let flippedCards = [];
    let matchedCards = [];
    let moves = 0;
    let level = 1;

    function shuffle(array) {
        for (let i = array.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [array[i], array[j]] = [array[j], array[i]];
        }
    }

    function drawCard(x, y, card) {
        ctx.strokeStyle = '#000';
        ctx.lineWidth = 2;
        ctx.strokeRect(x, y, CARD_WIDTH, CARD_HEIGHT);
        if (card) {
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.font = '30px Arial';
            ctx.fillText(card, x + CARD_WIDTH / 2, y + CARD_HEIGHT / 2);
        }
    }

    function render() {
        ctx.clearRect(0, 0, width, height);
        let startX = (width - (CARD_WIDTH + MARGIN) * 4) / 2;
        let startY = (height - (CARD_HEIGHT + MARGIN) * 4) / 2;
        for (let i = 0; i < 4; i++) {
            for (let j = 0; j < 4; j++) {
                let cardIndex = i * 4 + j;
                let card = flippedCards.includes(cardIndex) || matchedCards.includes(cardIndex) ? shuffledCards[cardIndex] : null;
                drawCard(startX + j * (CARD_WIDTH + MARGIN), startY + i * (CARD_HEIGHT + MARGIN), card);
            }
        }
        ctx.font = '20px Arial';
        ctx.fillText(`Level: ${level}`, 10, 30);
        ctx.fillText(`Moves: ${moves}`, 10, 60);
    }

    function checkForMatch() {
        if (flippedCards.length === 2) {
            let [first, second] = flippedCards;
            if (shuffledCards[first] === shuffledCards[second]) {
                matchedCards.push(first, second);
            } else {
                setTimeout(() => {
                    flippedCards = [];
                    render();
                }, 1000);
            }
            flippedCards = [];
            moves++;
            if (matchedCards.length === shuffledCards.length) {
                level++;
                nextLevel();
            }
        }
    }

    function nextLevel() {
        if (level > 5) {
            ctx.font = '30px Arial';
            ctx.fillText('You Win!', width / 2 - 60, height / 2);
            return;
        }
        shuffledCards = [...CARDS.slice(0, level * 8)];
        shuffle(shuffledCards);
        flippedCards = [];
        matchedCards = [];
        moves = 0;
        render();
    }

    function handleClick(x, y) {
        let startX = (width - (CARD_WIDTH + MARGIN) * 4) / 2;
        let startY = (height - (CARD_HEIGHT + MARGIN) * 4) / 2;
        for (let i = 0; i < 4; i++) {
            for (let j = 0; j < 4; j++) {
                let cardIndex = i * 4 + j;
                let cardX = startX + j * (CARD_WIDTH + MARGIN);
                let cardY = startY + i * (CARD_HEIGHT + MARGIN);
                if (x > cardX && x < cardX + CARD_WIDTH && y > cardY && y < cardY + CARD_HEIGHT) {
                    if (!flippedCards.includes(cardIndex) && !matchedCards.includes(cardIndex)) {
                        flippedCards.push(cardIndex);
                        checkForMatch();
                        render();
                    }
                    break;
                }
            }
        }
    }

    canvas.addEventListener('click', (event) => {
        let rect = canvas.getBoundingClientRect();
        let x = (event.clientX - rect.left) * dpr;
        let y = (event.clientY - rect.top) * dpr;
        handleClick(x, y);
    });

    window.addEventListener('resize', () => {
        width = window.innerWidth;
        height = window.innerHeight;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);
        render();
    });

    nextLevel();
})();
