class Economy {
  constructor() {
    this.balance = 0;
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    this.balance += amount;
  }

  withdraw(amount) {
    if (amount <= this.balance) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Store {
  constructor() {
    this.items = {
      bread: 10,
      milk: 5,
      apple: 3
    };
    this.prices = {
      bread: 2,
      milk: 3,
      apple: 1
    };
  }

  getItemPrice(item) {
    return this.prices[item] || 0;
  }

  buyItem(item, quantity) {
    if (this.items[item] >= quantity) {
      this.items[item] -= quantity;
      return true;
    }
    return false;
  }
}

class Inventory {
  constructor() {
    this.stock = {};
  }

  addItem(item, quantity) {
    if (this.stock[item]) {
      this.stock[item] += quantity;
    } else {
      this.stock[item] = quantity;
    }
  }

  getStock(item) {
    return this.stock[item] || 0;
  }
}

class GameCoordinator {
  constructor() {
    this.economy = new Economy();
    this.store = new Store();
    this.inventory = new Inventory();
  }

  buyAndStoreItem(item, quantity) {
    const price = this.store.getItemPrice(item);
    const totalCost = price * quantity;

    if (this.economy.withdraw(totalCost)) {
      if (this.store.buyItem(item, quantity)) {
        this.inventory.addItem(item, quantity);
        console.log(`Bought ${quantity} ${item}(s) for ${totalCost}.`);
      } else {
        console.log(`Failed to buy ${quantity} ${item}(s). Not enough stock.`);
      }
