class Economy {
    constructor(initialMoney = 100) {
        this.money = initialMoney;
    }

    getMoney() {
        return this.money;
    }

    addMoney(amount) {
        this.money += amount;
    }

    subtractMoney(amount) {
        if (amount > this.money) {
            throw new Error("Not enough money");
        }
        this.money -= amount;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity = 1) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    removeItem(item, quantity = 1) {
        if (!this.items[item] || this.items[item] < quantity) {
            throw new Error("Not enough inventory");
        }
        this.items[item] -= quantity;
        if (this.items[item] === 0) {
            delete this.items[item];
        }
    }

    getInventory() {
        return this.items;
    }
}

class Store {
    constructor(economy, inventory) {
        this.economy = economy;
        this.inventory = inventory;
        this.prices = {
            "apple": 10,
            "banana": 5,
            "orange": 8
        };
    }

    buyItem(item, quantity = 1) {
        const price = this.prices[item] * quantity;
        if (!price) {
            throw new Error("Item not available");
        }
        this.economy.subtractMoney(price);
        this.inventory.addItem(item, quantity);
    }

    sellItem(item, quantity = 1) {
        if (!this.inventory.items[item]) {
            throw new Error("Item not in inventory");
        }
        const price = this.prices[item] * quantity;
        this.economy.addMoney(price);
        this.inventory.removeItem(item, quantity);
    }

    getPrices() {
        return this.prices;
    }
}

// Demo
