const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const towerDefense = {
  enemies: [],
  towers: [],
  bullets: [],
  money: 100,
  wave: 1,
  waveTimer: 0,
  waveInterval: 5000,
  enemySpeed: 1,
  gameLoop: null,
  selectedTower: null,
  grid: Array.from({ length: 20 }, () => Array(20).fill(null)),
  towerCost: 50,
  bulletSpeed: 5,
  enemySpawnInterval: 2000,
  enemySpawnTimer: 0,
};

function createEnemy() {
  const x = canvas.width;
  const y = Math.random() * canvas.height;
  towerDefense.enemies.push({ x, y, width: 20, height: 20, health: 5 });
}

function spawnEnemies() {
  if (towerDefense.waveTimer > towerDefense.waveInterval) {
    for (let i = 0; i < towerDefense.wave; i++) {
      createEnemy();
    }
    towerDefense.wave++;
    towerDefense.waveTimer = 0;
  }
}

function moveEnemies() {
  towerDefense.enemies.forEach(enemy => {
    enemy.x -= towerDefense.enemySpeed;
  });
}

function drawEnemies() {
  towerDefense.enemies.forEach(enemy => {
    ctx.fillStyle = 'red';
    ctx.fillRect(enemy.x, enemy.y, enemy.width, enemy.height);
  });
}

function placeTower(x, y) {
  const gridX = Math.floor(x / 40);
  const gridY = Math.floor(y / 40);
  if (towerDefense.grid[gridY][gridX] === null && towerDefense.money >= towerDefense.towerCost) {
    towerDefense.grid[gridY][gridX] = { x: gridX * 40, y: gridY * 40, width: 40, height: 40 };
    towerDefense.towers.push(towerDefense.grid[gridY][gridX]);
    towerDefense.money -= towerDefense.towerCost;
  }
}

function drawTowers() {
  towerDefense.towers.forEach(tower => {
    ctx.fillStyle = 'blue';
    ctx.fillRect(tower.x, tower.y, tower.width, tower.height);
  });
}

function shootBullets() {
  towerDefense.towers.forEach(tower => {
    const target = towerDefense.enemies.find(enemy => {
      return enemy.x + enemy.width > tower.x && enemy.x < tower.x + tower.width &&
             enemy.y + enemy.height > tower.y && enemy.y < tower.y + tower.height;
    });
    if (target) {
      towerDefense.bullets.push({ x: tower.x + tower.width / 2, y: tower.y + tower.height / 2, target });
    }
  });
}

function moveBullets() {
  towerDefense.bullets.forEach(bullet => {
    const dx = bullet.target.x - bullet.x;
    const dy = bullet.target.y - bullet.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    bullet.x += (dx / distance) * towerDefense.bulletSpeed;
    bullet.y += (dy / distance) * towerDefense.bulletSpeed;
  });
}

function drawBullets() {
  towerDefense.bullets.forEach(bullet => {
    ctx.fillStyle = 'yellow';
    ctx.beginPath();
    ctx.arc(bullet.x, bullet.y, 5, 0, Math.PI * 2);
    ctx.fill();
  });
}

function checkCollisions() {
  towerDefense.bullets.forEach((bullet, index) => {
    towerDefense.enemies.forEach((enemy, enemyIndex) => {
      if (bullet.x > enemy.x && bullet.x < enemy.x + enemy.width &&
          bullet.y > enemy.y && bullet.y < enemy.y + enemy.height) {
        enemy.health--;
        if (enemy.health <= 0) {
          towerDefense.enemies.splice(enemyIndex, 1);
          towerDefense.money += 25;
        }
        towerDefense.bullets.splice(index, 1);
      }
    });
  });
}

function drawMoney() {
  ctx.fillStyle = 'black';
  ctx.fillText(`Money: ${towerDefense.money}`, 10, 20);
}

function drawWave() {
  ctx.fillStyle = 'black';
  ctx.fillText(`Wave: ${towerDefense.wave}`, 10, 40);
}

function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  towerDefense.waveTimer += 16;
  towerDefense.enemySpawnTimer += 16;

  spawnEnemies();
  moveEnemies();
  drawEnemies();
  moveBullets();
  drawBullets();
  checkCollisions();
  drawTowers();
  drawMoney();
  drawWave();

  if (towerDefense.enemySpawnTimer > towerDefense.enemySpawnInterval) {
    createEnemy();
    towerDefense.enemySpawnTimer = 0;
  }

  requestAnimationFrame(gameLoop);
}

canvas.addEventListener('click', (e) => {
  const rect = canvas.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;
  placeTower(x, y);
});

gameLoop();
