const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let dpr = window.devicePixelRatio || 1;
let lastTime = performance.now();
let score = 0;
let countdown = 3;

function resizeCanvas() {
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    ctx.scale(dpr, dpr);
}

window.addEventListener('resize', resizeCanvas);
resizeCanvas();

const player = {
    x: 50,
    y: canvas.height / 2,
    width: 20,
    height: 20,
    velocity: 0,
    gravity: 0.5,
    jumpPower: -10,
    draw() {
        ctx.fillStyle = 'blue';
        ctx.fillRect(this.x, this.y, this.width, this.height);
    },
    update() {
        this.velocity += this.gravity;
        this.y += this.velocity;
        if (this.y > canvas.height - this.height) {
            this.y = canvas.height - this.height;
            this.velocity = 0;
        }
    },
    jump() {
        this.velocity = this.jumpPower;
    }
};

const gap = {
    x: canvas.width,
    y: canvas.height / 2,
    width: 50,
    height: 100,
    draw() {
        ctx.fillStyle = 'green';
        ctx.fillRect(this.x, 0, this.width, this.y - this.height / 2);
        ctx.fillRect(this.x, this.y + this.height / 2, this.width, canvas.height - (this.y + this.height / 2));
    },
    update() {
        this.x -= 2;
        if (this.x < -this.width) {
            this.x = canvas.width;
            this.y = Math.random() * (canvas.height - this.height);
        }
    }
};

function checkCollision() {
    return player.x < gap.x + gap.width &&
           player.x + player.width > gap.x &&
           (player.y < gap.y - gap.height / 2 || player.y + player.height > gap.y + gap.height / 2);
}

function drawCountdown() {
    ctx.font = '48px Arial';
    ctx.fillStyle = 'red';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(countdown, canvas.width / 2, canvas.height / 2);
}

function update() {
    if (countdown > 0) {
        countdown--;
        if (countdown === 0) {
            gap.x = canvas.width;
        }
    } else {
        player.update();
        gap.update();
        if (checkCollision()) {
            alert(`Game Over! Score: ${score}`);
            document.location.reload();
        }
        score++;
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    if (countdown > 0) {
        drawCountdown();
    } else {
        player.draw();
        gap.draw();
    }
}

function gameLoop(timestamp) {
    const deltaTime = timestamp - lastTime;
    lastTime = timestamp;
    update();
    draw();
    requestAnimationFrame(gameLoop);
}

window.addEventListener('keydown', (e) => {
    if (e.code === 'Space' && countdown === 0) {
        player.jump();
    }
});

requestAnimationFrame(gameLoop);
