class Pricing {
  constructor(prices = {}) {
    this.prices = prices;
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }

  setPrice(item, price) {
    this.prices[item] = price;
  }
}

class Demand {
  constructor(demand = {}) {
    this.demand = demand;
  }

  getDemand(item) {
    return this.demand[item] || 0;
  }

  setDemand(item, demand) {
    this.demand[item] = demand;
  }
}

class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
    this.inventory = {};
  }

  purchase(item, quantity) {
    const pricePerItem = this.pricing.getPrice(item);
    const totalCost = pricePerItem * quantity;

    if (this.demand.getDemand(item) >= quantity) {
      console.log(`Purchased ${quantity} of ${item} for ${totalCost}`);
      this.demand.setDemand(item, this.demand.getDemand(item) - quantity);
      this.inventory[item] = (this.inventory[item] || 0) + quantity;
      return true;
    } else {
      console.log(`Not enough demand for ${quantity} of ${item}`);
      return false;
    }
  }

  getInventory() {
    return this.inventory;
  }
}

// Demo
const pricing = new Pricing({
  apple: 1,
  banana: 0.5,
  orange: 0.75
});

const demand = new Demand({
  apple: 10,
  banana: 5,
  orange: 8
});

const store = new Store(pricing, demand);

store.purchase('apple', 3); // Purchased 3 of apple for 3
store.purchase('banana', 6); // Not enough demand for 6 of banana
store.purchase('orange', 4); // Purchased 4 of orange for 3

console.log('Inventory:', store.getInventory());
