// Event Bus
class EventBus {
  constructor() {
    this.listeners = {};
  }

  subscribe(event, callback) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(callback);
  }

  emit(event, data) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(callback => callback(data));
    }
  }
}

// Spawner System
class Spawner {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.spawnInterval = 2000; // 2 seconds
  }

  start() {
    setInterval(() => {
      const enemy = { id: Date.now(), type: 'basic' };
      this.eventBus.emit('enemy.spawn', enemy);
      console.log(`Enemy spawned:`, enemy);
    }, this.spawnInterval);
  }
}

// EnemyPool System
class EnemyPool {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.enemies = [];
  }

  initialize() {
    this.eventBus.subscribe('enemy.spawn', enemy => {
      this.enemies.push(enemy);
      console.log(`Enemy added to pool:`, enemy);
    });

    this.eventBus.subscribe('enemy.kill', enemyId => {
      const index = this.enemies.findIndex(enemy => enemy.id === enemyId);
      if (index !== -1) {
        const killedEnemy = this.enemies.splice(index, 1)[0];
        console.log(`Enemy killed and removed from pool:`, killedEnemy);
      }
    });
  }
}

// Score System
class Score {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.score = 0;
  }

  initialize() {
    this.eventBus.subscribe('enemy.kill', () => {
      this.score += 10; // 10 points for each enemy killed
