const canvas = document.createElement('canvas');
canvas.width = 600;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const boardSize = 8;
const cellSize = canvas.width / boardSize;

const colors = ['#FF5733', '#33FF57', '#3357FF', '#F3FF33', '#FF33F6', '#33FFF6'];

let board = [];

function createBoard() {
    for (let i = 0; i < boardSize; i++) {
        board[i] = [];
        for (let j = 0; j < boardSize; j++) {
            board[i][j] = Math.floor(Math.random() * colors.length);
        }
    }
}

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let i = 0; i < boardSize; i++) {
        for (let j = 0; j < boardSize; j++) {
            ctx.fillStyle = colors[board[i][j]];
            ctx.fillRect(j * cellSize, i * cellSize, cellSize, cellSize);
            ctx.strokeStyle = '#000';
            ctx.strokeRect(j * cellSize, i * cellSize, cellSize, cellSize);
        }
    }
}

function checkMatches() {
    let matches = [];

    // Check horizontal matches
    for (let i = 0; i < boardSize; i++) {
        for (let j = 0; j < boardSize - 2; j++) {
            if (board[i][j] === board[i][j + 1] && board[i][j] === board[i][j + 2]) {
                matches.push([i, j], [i, j + 1], [i, j + 2]);
            }
        }
    }

    // Check vertical matches
    for (let j = 0; j < boardSize; j++) {
        for (let i = 0; i < boardSize - 2; i++) {
            if (board[i][j] === board[i + 1][j] && board[i][j] === board[i + 2][j]) {
                matches.push([i, j], [i + 1, j], [i + 2, j]);
            }
        }
    }

    return matches;
}

function removeMatches(matches) {
    matches.forEach(([i, j]) => {
        board[i][j] = null;
    });
}

function dropItems() {
    for (let j = 0; j < boardSize; j++) {
        let emptyCount = 0;
        for (let i = boardSize - 1; i >= 0; i--) {
            if (board[i][j] === null) {
                emptyCount++;
            } else {
                board[i + emptyCount][j] = board[i][j];
                if (emptyCount > 0) {
                    board[i][j] = null;
                }
            }
        }
        for (let i = 0; i < emptyCount; i++) {
            board[i][j] = Math.floor(Math.random() * colors.length);
        }
    }
}

function aiTurn() {
    let matches = [];
    for (let i = 0; i < boardSize; i++) {
        for (let j = 0; j < boardSize; j++) {
            // Simulate swapping with right
            if (j < boardSize - 1) {
                [board[i][j], board[i][j + 1]] = [board[i][j + 1], board[i][j]];
                matches = matches.concat(checkMatches());
                [board[i][j], board[i][j + 1]] = [board[i][j + 1], board[i][j]];
            }
            // Simulate swapping with down
            if (i < boardSize - 1) {
                [board[i][j], board[i + 1][j]] = [board[i + 1][j], board[i][j]];
                matches = matches.concat(checkMatches());
                [board[i][j], board[i + 1][j]] = [board[i + 1][j], board[i][j]];
            }
        }
    }

    if (matches.length > 0) {
        removeMatches(matches);
        dropItems();
    }
}

function gameLoop() {
    aiTurn();
    drawBoard();
    requestAnimationFrame(gameLoop);
}

createBoard();
drawBoard();
gameLoop();
