const gravity = 0.5;
const jumpVelocity = -10;
const gapHeight = 150;
const gapWidth = 75;
const birdSize = 20;
let birdX = 50;
let birdY = 50;
let birdVelocity = 0;
let pipes = [];
let score = 0;
let isGameOver = false;

function createPipe() {
  const y = Math.random() * (canvas.height - gapHeight - birdSize);
  pipes.push({ x: canvas.width, y, passed: false });
}

function update() {
  if (isGameOver) return;
  birdVelocity += gravity;
  birdY += birdVelocity;

  if (birdY + birdSize > canvas.height || birdY < 0) {
    gameOver();
    return;
  }

  if (pipes.length === 0 || pipes[pipes.length - 1].x < canvas.width - 200) {
    createPipe();
  }

  pipes.forEach(pipe => {
    pipe.x -= 5;
    if (pipe.x < -gapWidth) pipes.shift();
    if (
      birdX + birdSize > pipe.x &&
      birdX < pipe.x + gapWidth &&
      (birdY < pipe.y || birdY + birdSize > pipe.y + gapHeight)
    ) {
      gameOver();
      return;
    }
    if (pipe.x + gapWidth < birdX && !pipe.passed) {
      score++;
      pipe.passed = true;
    }
  });

  requestAnimationFrame(update);
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = '#00FF00';
  ctx.fillRect(birdX, birdY, birdSize, birdSize);

  pipes.forEach(pipe => {
    ctx.fillStyle = '#8B4513';
    ctx.fillRect(pipe.x, 0, gapWidth, pipe.y);
    ctx.fillRect(pipe.x, pipe.y + gapHeight, gapWidth, canvas.height - pipe.y - gapHeight);
  });

  ctx.fillStyle = '#000';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);

  if (isGameOver) {
    ctx.font = '40px Arial';
    ctx.fillText('Game Over', canvas.width / 2 - 100, canvas.height / 2);
  }

  requestAnimationFrame(draw);
}

function jump() {
