// Event Bus
class EventBus {
    constructor() {
        this.events = {};
    }

    subscribe(event, listener) {
        if (!this.events[event]) {
            this.events[event] = [];
        }
        this.events[event].push(listener);
    }

    emit(event, data) {
        if (this.events[event]) {
            this.events[event].forEach(listener => listener(data));
        }
    }
}

// Spawner System
class Spawner {
    constructor(eventBus) {
        this.eventBus = eventBus;
    }

    spawnEnemy() {
        console.log("Spawning enemy");
        this.eventBus.emit("enemySpawned", { type: "BasicEnemy" });
    }
}

// EnemyPool System
class EnemyPool {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.pool = [];
    }

    init() {
        this.eventBus.subscribe("enemySpawned", this.onEnemySpawned.bind(this));
        this.eventBus.subscribe("enemyDestroyed", this.onEnemyDestroyed.bind(this));
    }

    onEnemySpawned(enemy) {
        console.log("Enemy added to pool:", enemy.type);
        this.pool.push(enemy);
    }

    onEnemyDestroyed(enemy) {
        console.log("Enemy removed from pool:", enemy.type);
        this.pool = this.pool.filter(e => e !== enemy);
    }
}

// Score System
class Score {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.score = 0;
    }

    init() {
        this.eventBus.subscribe("enemyDestroyed", this.onEnemyDestroyed.bind(this));
    }

    onEnemyDestroyed(enemy) {
        console.log("Enemy destroyed, +10 points");
        this.score += 10;
        console.log("Current score:", this.score);
    }
}

// Demo
