class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, callback) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(callback);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(callback => callback(data));
    }
  }
}

class Recipe {
  constructor(name, ingredients, result) {
    this.name = name;
    this.ingredients = ingredients;
    this.result = result;
  }

  canCraft(inventory) {
    for (const [item, quantity] of Object.entries(this.ingredients)) {
      if (!inventory[item] || inventory[item] < quantity) {
        return false;
      }
    }
    return true;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
    }
  }

  getItemQuantity(item) {
    return this.items[item] || 0;
  }
}

class Crafting {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.recipes = [];

    this.eventBus.subscribe('craft', this.handleCraft.bind(this));
  }

  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  handleCraft(data) {
    const { recipeName, inventory } = data;
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (recipe && recipe.canCraft(inventory)) {
      for (const [item, quantity] of Object.entries(recipe.ingredients)) {
        inventory.removeItem(item, quantity);
      }
      inventory.addItem(recipe.result, 1);
      console.log(`Crafted ${recipe.result}`);
    } else {
      console.log(`Cannot craft ${recipeName}`);
    }
  }
}

