const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let width, height;
function resize() {
    width = window.innerWidth;
    height = window.innerHeight;
    canvas.width = width * devicePixelRatio;
    canvas.height = height * devicePixelRatio;
    ctx.scale(devicePixelRatio, devicePixelRatio);
    canvas.style.width = `${width}px`;
    canvas.style.height = `${height}px`;
}
window.addEventListener('resize', resize);
resize();

const rhythm = [
    { time: 1000, key: 'ArrowUp' },
    { time: 2000, key: 'ArrowDown' },
    { time: 3000, key: 'ArrowLeft' },
    { time: 4000, key: 'ArrowRight' },
];

let score = 0;
let currentTime = 0;
let gameStarted = false;
let tapRects = [];

function startGame() {
    gameStarted = true;
    score = 0;
    currentTime = 0;
    tapRects = [];
    requestAnimationFrame(gameLoop);
}

function gameLoop(timestamp) {
    if (!gameStarted) return;
    ctx.clearRect(0, 0, width, height);
    currentTime = timestamp;

    rhythm.forEach(note => {
        if (note.time < currentTime && !tapRects.some(rect => rect.id === note.time)) {
            tapRects.push({ id: note.time, x: Math.random() * (width - 50), y: height - 100, key: note.key });
        }
    });

    tapRects = tapRects.filter(rect => rect.y > -50);

    tapRects.forEach(rect => {
        ctx.fillStyle = 'blue';
        ctx.fillRect(rect.x, rect.y, 50, 50);
        rect.y -= 2;
    });

    ctx.fillStyle = 'black';
    ctx.font = '24px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);

    requestAnimationFrame(gameLoop);
}

canvas.addEventListener('click', (e) => {
    if (!gameStarted) return;
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    tapRects.forEach(rect => {
        if (x > rect.x && x < rect.x + 50 && y > rect.y && y < rect.y + 50) {
            score++;
            tapRects = tapRects.filter(r => r.id !== rect.id);
        }
    });
});

window.addEventListener('keydown', (e) => {
    if (!gameStarted) return;
    const rect = tapRects.find(r => r.key === e.key);
    if (rect) {
        score++;
        tapRects = tapRects.filter(r => r.id !== rect.id);
    }
});

document.addEventListener('DOMContentLoaded', () => {
    document.getElementById('startButton').addEventListener('click', startGame);
});
