    this.eventBus = eventBus;
    this.eventBus.on('purchase', this.handlePurchase.bind(this));
    this.eventBus.on('sell', this.handleSell.bind(this));
  }

  handlePurchase(amount) {
    if (amount > 0) {
      this.balance += amount;
      console.log(`Added ${amount} to balance. New balance: ${this.balance}`);
    } else {
      console.log('Invalid purchase amount');
    }
  }

  handleSell(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      console.log(`Removed ${amount} from balance. New balance: ${this.balance}`);
    } else {
      console.log('Invalid sell amount');
    }
  }
}

class Store {
  constructor(eventBus) {
    this.items = {
      sword: { price: 10 },
      shield: { price: 5 }
    };
