class TradeSystem {
  constructor() {
    this.resources = { gold: 100, wood: 50, stone: 30 };
  }

  getResources() {
    return { ...this.resources };
  }

  trade(resource, amount, price) {
    if (this.resources[resource] >= amount && this.resources.gold >= price) {
      this.resources[resource] -= amount;
      this.resources.gold += price;
      return true;
    }
    return false;
  }
}

class ReputationSystem {
  constructor() {
    this.reputation = 50;
  }

  getReputation() {
    return this.reputation;
  }

  updateReputation(amount) {
    this.reputation += amount;
    if (this.reputation < 0) this.reputation = 0;
    if (this.reputation > 100) this.reputation = 100;
  }
}

class FactionSystem {
  constructor() {
    this.factionStanding = { allies: 50, enemies: 50 };
  }

  getFactionStanding() {
    return { ...this.factionStanding };
  }

  updateFactionStanding(allyChange, enemyChange) {
    this.factionStanding.allies += allyChange;
    this.factionStanding.enemies += enemyChange;

    if (this.factionStanding.allies < 0) this.factionStanding.allies = 0;
    if (this.factionStanding.allies > 100) this.factionStanding.allies = 100;

    if (this.factionStanding.enemies < 0) this.factionStanding.enemies = 0;
    if (this.factionStanding.enemies > 100) this.factionStanding.enemies = 100;
  }
}

class GameCoordinator {
  constructor() {
    this.tradeSystem = new TradeSystem();
    this.reputationSystem = new ReputationSystem();
    this.factionSystem = new FactionSystem();
  }

  tradeResource(resource, amount, price) {
    const success = this.tradeSystem.trade(resource, amount, price);
    if (success) {
      this.reputationSystem.updateReputation(1);
      this.factionSystem.updateFactionStanding(1, -1);
    } else {
      this.reputationSystem.updateReputation(-1);
      this.factionSystem.updateFactionStanding(-1, 1);
    }
    return success;
  }

  getResources() {
    return this.tradeSystem.getResources();
  }

  getReputation() {
    return this.reputationSystem.getReputation();
  }

  getFactionStanding() {
    return this.factionSystem.getFactionStanding();
  }
}

// Demo
