  const velocity = {
    x: Math.cos(angle) * 10,
    y: Math.sin(angle) * 10
  };
  bullets.push({
    x: player.x,
    y: player.y,
    velocity,
    radius: 3,
    color: 'white'
  });
  for (let i = 0; i < 10; i++) {
    createParticle(player.x, player.y, 'white', {
      x: (Math.random() - 0.5) * 5,
      y: (Math.random() - 0.5) * 5
    });
  }
});

