class Loot {
  constructor(name, rarity) {
    this.name = name;
    this.rarity = rarity;
  }

  describe() {
    return `${this.name} (Rarity: ${this.rarity})`;
  }
}

class RarityTable {
  constructor() {
    this.table = {
      common: { min: 1, max: 10 },
      uncommon: { min: 11, max: 20 },
      rare: { min: 21, max: 30 },
      epic: { min: 31, max: 40 },
      legendary: { min: 41, max: 50 }
    };
  }

  rollRarity() {
    const roll = Math.floor(Math.random() * 100) + 1;
    for (const [rarity, range] of Object.entries(this.table)) {
      if (roll >= range.min && roll <= range.max) {
        return rarity;
      }
    }
    return 'common'; // Default to common if no match
  }
}

class Inventory {
  constructor() {
    this.items = [];
  }

  addItem(item) {
    this.items.push(item);
  }

  listItems() {
    return this.items.map(item => item.describe()).join('\n');
  }
}

class Economy {
  constructor() {
    this.balance = 1000; // Starting balance
    this.prices = {
      common: 10,
      uncommon: 20,
      rare: 30,
      epic: 40,
      legendary: 50
    };
  }

  getBalance() {
    return this.balance;
  }

  debit(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getPrice(rarity) {
    return this.prices[rarity] || 10; // Default to 10 if rarity not found
  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
  }

  purchaseItem() {
    const rarityTable = new RarityTable();
    const rarity = rarityTable.rollRarity();
    const price = this.economy.getPrice(rarity);

    if (this.economy.debit(price)) {
      const loot = new Loot(`Loot of ${rarity}`, rarity);
      this.inventory.addItem(loot);
      console.log(`Purchased ${loot.describe()} for ${price} gold. Remaining balance: ${this.economy.getBalance()} gold.`);
    } else {
      console.log(`Insufficient funds to purchase a ${rarity} item.`);
    }
  }
}

// Demo
const economy = new Economy();
const inventory = new Inventory();
const store = new Store(economy, inventory);

store.purchaseItem();
store.purchaseItem();
console.log('Inventory items:');
console.log(inventory.listItems());
