// Define the canvas and context
const canvas = document.createElement('canvas');
canvas.width = 400;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Game state
let blocks = [];
let score = 0;
let timer = 60;
let gameRunning = true;

// Block properties
const blockWidth = 40;
const blockHeight = 20;
const colors = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#00FFFF', '#FF00FF'];

// Create a new block
function createBlock() {
    return {
        x: Math.floor(Math.random() * (canvas.width - blockWidth)),
        y: -blockHeight,
        color: colors[Math.floor(Math.random() * colors.length)]
    };
}

// Update game state
function update() {
    if (!gameRunning) return;

    // Move blocks down
    blocks.forEach(block => block.y += 2);

    // Create new block if needed
    if (Math.random() > 0.95) {
        blocks.push(createBlock());
    }

    // Remove blocks that fall off the screen
    blocks = blocks.filter(block => block.y < canvas.height);

    // Decrease timer
    timer -= 0.016; // Assuming 60 FPS
    if (timer <= 0) {
        gameRunning = false;
    }
}

// Render the game
function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw blocks
    blocks.forEach(block => {
        ctx.fillStyle = block.color;
        ctx.fillRect(block.x, block.y, blockWidth, blockHeight);
    });

    // Draw score and timer
    ctx.fillStyle = '#000';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
    ctx.fillText(`Time: ${timer.toFixed(2)}`, 10, 60);
}

// Game loop
function gameLoop() {
    if (!gameRunning) {
        ctx.fillStyle = '#000';
        ctx.font = '50px Arial';
        ctx.fillText('Game Over', canvas.width / 2 - 100, canvas.height / 2);
        return;
    }

    update();
    render();
    requestAnimationFrame(gameLoop);
}

// Start the game
gameLoop();
