class Recipe {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.recipes = {
      'wood + stone': 'axe',
      'leather + cloth': 'boots'
    };
    this.eventBus.subscribe('craft', this.handleCraft.bind(this));
  }

  handleCraft(data) {
    const { ingredients } = data;
    const recipeKey = ingredients.sort().join(' + ');
    const result = this.recipes[recipeKey];
    if (result) {
      this.eventBus.emit('craftSuccess', { result });
    } else {
      this.eventBus.emit('craftFailure', { message: 'No recipe found' });
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {
      wood: 5,
      stone: 3,
      leather: 2,
      cloth: 4
    };
    this.eventBus.subscribe('craftSuccess', this.handleCraftSuccess.bind(this));
    this.eventBus.subscribe('craftFailure', this.handleCraftFailure.bind(this));
  }

  craft(ingredients) {
    const canCraft = ingredients.every(ingredient => {
      return this.items[ingredient] > 0;
    });
    if (canCraft) {
      ingredients.forEach(ingredient => {
        this.items[ingredient]--;
      });
      this.eventBus.emit('craft', { ingredients });
    } else {
      this.eventBus.emit('craftFailure', { message: 'Not enough ingredients' });
    }
  }

  handleCraftSuccess(data) {
    const { result } = data;
    if (!this.items[result]) {
      this.items[result] = 0;
    }
    this.items[result]++;
    console.log(`Crafted ${result}. Inventory:`, this.items);
  }

  handleCraftFailure(data) {
    console.log('Craft failed:', data.message);
  }
}

