const room = Array.from({ length: ROOM_HEIGHT }, () =>
  Array.from({ length: ROOM_WIDTH }, () => '#')
);

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let y = 0; y < ROOM_HEIGHT; y++) {
    for (let x = 0; x < ROOM_WIDTH; x++) {
      const tile = room[y][x];
      ctx.fillStyle = tile === '#' ? 'black' : 'white';
      ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
    }
  }
  ctx.fillStyle = 'green';
  ctx.fillRect(player.x * TILE_SIZE, player.y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
  ctx.fillStyle = 'red';
  ctx.fillRect(enemy.x * TILE_SIZE, enemy.y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
}

function update(dt) {
  const keys = Object.fromEntries(
    Array.from({ length: 256 }, (_, i) => [i, false])
  );
  document.addEventListener('keydown', (e) => (keys[e.keyCode] = true));
  document.addEventListener('keyup', (e) => (keys[e.keyCode] = false));

  if (keys[37]) player.x -= player.speed * dt; // Left
  if (keys[38]) player.y -= player.speed * dt; // Up
  if (keys[39]) player.x += player.speed * dt; // Right
  if (keys[40]) player.y += player.speed * dt; // Down

  if (enemy.x < player.x) enemy.x += enemy.speed * dt;
  if (enemy.x > player.x) enemy.x -= enemy.speed * dt;
  if (enemy.y < player.y) enemy.y += enemy.speed * dt;
  if (enemy.y > player.y) enemy.y -= enemy.speed * dt;
}

const targetFPS = 60;
const timeStep = 1000 / targetFPS;
let lastTime = 0;

function gameLoop(currentTime) {
  const deltaTime = currentTime - lastTime;
  lastTime = currentTime;
  update(deltaTime / 1000);
  render();
  requestAnimationFrame(gameLoop);
}

