// Event Bus Implementation
class EventBus {
    constructor() {
        this.events = {};
    }

    subscribe(event, listener) {
        if (!this.events[event]) {
            this.events[event] = [];
        }
        this.events[event].push(listener);
    }

    emit(event, data) {
        if (this.events[event]) {
            this.events[event].forEach(listener => listener(data));
        }
    }
}

// Farm System
class Farm {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('harvest', this.harvest.bind(this));
    }

    plantCrop(cropType) {
        console.log(`Planting ${cropType}...`);
        // Simulate crop growth
        setTimeout(() => {
            this.eventBus.emit('harvest', cropType);
        }, 2000); // Simulate 2 seconds for crop to grow
    }

    harvest(cropType) {
        console.log(`Harvesting ${cropType} from the farm!`);
        this.eventBus.emit('cropAvailable', cropType);
    }
}

// Crop System
class Crop {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.crops = [];
        this.eventBus.subscribe('cropAvailable', this.storeCrop.bind(this));
    }

    storeCrop(cropType) {
        this.crops.push(cropType);
        console.log(`Storing ${cropType} in the crop storage.`);
        this.eventBus.emit('cropStored', cropType);
    }

    getCrops() {
        return this.crops;
    }
}

// Market System
class Market {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('cropStored', this.sellCrop.bind(this));
    }

    sellCrop(cropType) {
        console.log(`Selling ${cropType} at the market.`);
    }
}

