class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients; // { ingredientName: quantity }
  }
}

class Crafting {
  constructor() {
    this.recipes = [];
  }

  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  canCraft(recipeName, inventory) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (!recipe) return false;

    for (const [ingredient, quantity] of Object.entries(recipe.ingredients)) {
      if (inventory.getItemCount(ingredient) < quantity) {
        return false;
      }
    }
    return true;
  }

  craft(recipeName, inventory) {
    if (this.canCraft(recipeName, inventory)) {
      const recipe = this.recipes.find(r => r.name === recipeName);
      for (const [ingredient, quantity] of Object.entries(recipe.ingredients)) {
        inventory.removeItem(ingredient, quantity);
      }
      console.log(`Crafted: ${recipeName}`);
      return true;
    }
    console.log(`Cannot craft: ${recipeName}`);
    return false;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
    } else {
      console.log(`Not enough ${item} to remove ${quantity}`);
    }
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

// Top-level coordinator
class GameCoordinator {
  constructor() {
    this.crafting = new Crafting();
    this.inventory = new Inventory();
  }

  setup() {
    // Add recipes
    this.crafting.addRecipe(new Recipe('Sword', { 'Iron Bar': 1, 'Wood': 2 }));
    this.crafting.addRecipe(new Recipe('Shield', { 'Wood': 3, 'Leather': 1 }));

    // Add items to inventory
    this.inventory.addItem('Iron Bar', 5);
    this.inventory.addItem('Wood', 10);
    this.inventory.addItem('Leather', 2);
  }

  start() {
    this.setup();

    // Craft items
    this.crafting.craft('Sword', this.inventory);
    this.crafting.craft('Shield', this.inventory);
    this.crafting.craft('Sword', this.inventory);

    // Check inventory
    console.log('Inventory after crafting:');
    for (const [item, quantity] of Object.entries(this.inventory.items)) {
      console.log(`${item}: ${quantity}`);
    }
  }
}

