  if (keys.length > 0) {
    const angle = Math.atan2(
      player.keysPressed['ArrowUp'] - player.keysPressed['ArrowDown'],
      player.keysPressed['ArrowRight'] - player.keysPressed['ArrowLeft']
    );
    player.x += player.speed * Math.cos(angle);
    player.y += player.speed * Math.sin(angle);
  }
  player.angle = Math.atan2(mouseY - player.y, mouseX - player.x);
}

function updateBullets() {
  player.bullets.forEach((bullet, index) => {
    bullet.x += 5 * Math.cos(bullet.angle);
    bullet.y += 5 * Math.sin(bullet.angle);
    if (bullet.x < 0 || bullet.x > canvas.width || bullet.y < 0 || bullet.y > canvas.height) {
      player.bullets.splice(index, 1);
