class CombatSystem {
  constructor() {
    this.enemies = [];
  }

  addEnemy(enemy) {
    this.enemies.push(enemy);
  }

  attack(player, enemyIndex) {
    if (this.enemies[enemyIndex]) {
      console.log(`${player.name} attacks ${this.enemies[enemyIndex].name}!`);
      this.enemies[enemyIndex].takeDamage(10);
    }
  }
}

class HealthSystem {
  constructor(entity, maxHealth = 100) {
    this.entity = entity;
    this.currentHealth = maxHealth;
    this.maxHealth = maxHealth;
  }

  takeDamage(amount) {
    this.currentHealth -= amount;
    if (this.currentHealth <= 0) {
      this.currentHealth = 0;
      console.log(`${this.entity.name} has been defeated!`);
    } else {
      console.log(`${this.entity.name} takes ${amount} damage. Remaining health: ${this.currentHealth}`);
    }
  }

  heal(amount) {
    this.currentHealth += amount;
    if (this.currentHealth > this.maxHealth) {
      this.currentHealth = this.maxHealth;
    }
    console.log(`${this.entity.name} heals for ${amount}. Current health: ${this.currentHealth}`);
  }
}

class LootSystem {
  constructor() {
    this.lootPool = [];
  }

  addLoot(item) {
    this.lootPool.push(item);
  }

  dropLoot() {
    if (this.lootPool.length > 0) {
      const loot = this.lootPool[Math.floor(Math.random() * this.lootPool.length)];
      console.log(`Loot dropped: ${loot}`);
      return loot;
    }
    console.log("No loot to drop.");
    return null;
  }
}

class GameCoordinator {
  constructor() {
    this.combat = new CombatSystem();
    this.loot = new LootSystem();
  }

  setupEnemies() {
    const goblin = { name: "Goblin" };
