    console.log("Crops are growing");
    return true; // Simulate successful growth
  }
}

class Market {
  constructor() {
    this.stock = 0;
  }

  buyCrops(amount) {
    if (amount <= this.stock) {
      this.stock -= amount;
      console.log(`Bought ${amount} crops from the market`);
      return amount;
    } else {
      console.log("Not enough crops in the market");
      return 0;
    }
  }

  sellCrops(amount) {
    this.stock += amount;
    console.log(`Sold ${amount} crops to the market`);
  }

  getStock() {
    return this.stock;
  }
}

class Coordinator {
  constructor(farm, market) {
    this.farm = farm;
    this.market = market;
  }

  cycle() {
    Crop.grow();
    const harvested = this.farm.harvest();
    this.market.sellCrops(harvested);
    const bought = this.market.buyCrops(5);
    this.farm.plant(bought);
  }
}

