const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const waves = [
    { name: 'Calm', duration: 30, fishCount: 5, fishSpeed: 1 },
    { name: 'Moderate', duration: 25, fishCount: 7, fishSpeed: 2 },
    { name: 'Rough', duration: 20, fishCount: 10, fishSpeed: 3 },
    { name: 'Stormy', duration: 15, fishCount: 12, fishSpeed: 4 },
];

let currentWave = 0;
let waveTimer = 0;
let fish = [];
let score = 0;
let rodPosition = { x: canvas.width / 2, y: canvas.height };
let rodAngle = 0;
let fishing = false;

class Fish {
    constructor() {
        this.x = Math.random() * canvas.width;
        this.y = Math.random() * canvas.height * 0.5;
        this.speed = waves[currentWave].fishSpeed;
        this.size = Math.random() * 10 + 5;
    }

    update() {
        this.y += this.speed;
        if (this.y > canvas.height) {
            this.y = 0;
            this.x = Math.random() * canvas.width;
        }
        if (this.isCaught()) {
            score++;
            fish.splice(fish.indexOf(this), 1);
        }
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx.fillStyle = 'blue';
        ctx.fill();
    }

    isCaught() {
        const dx = this.x - rodPosition.x;
        const dy = this.y - rodPosition.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        return dist < 20 + this.size;
    }
}

function startWave() {
    fish = [];
    for (let i = 0; i < waves[currentWave].fishCount; i++) {
        fish.push(new Fish());
    }
    waveTimer = waves[currentWave].duration;
}

function update() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (waveTimer <= 0) {
        currentWave++;
        if (currentWave >= waves.length) {
            alert('Game Over! Final Score: ' + score);
            return;
        }
        startWave();
    } else {
        waveTimer--;
    }

    if (fishing) {
        ctx.beginPath();
        ctx.moveTo(rodPosition.x, rodPosition.y);
        ctx.lineTo(rodPosition.x + Math.cos(rodAngle) * 100, rodPosition.y + Math.sin(rodAngle) * 100);
        ctx.strokeStyle = 'brown';
        ctx.lineWidth = 5;
        ctx.stroke();
    }

    fish.forEach(fish => {
        fish.update();
        fish.draw();
    });

    ctx.fillStyle = 'black';
    ctx.font = '24px Arial';
    ctx.fillText('Wave: ' + waves[currentWave].name, 10, 30);
    ctx.fillText('Score: ' + score, 10, 60);

    requestAnimationFrame(update);
}

canvas.addEventListener('mousedown', () => {
    fishing = true;
});

canvas.addEventListener('mouseup', () => {
    fishing = false;
});

canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    rodPosition = { x, y };
    rodAngle = Math.atan2(y - rodPosition.y, x - rodPosition.x);
});

startWave();
update();
