const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const ASTEROID_COUNT = 5;
const ASTEROID_RADIUS = 20;
const SHIP_RADIUS = 10;
const PARTICLE_COUNT = 100;
const PARTICLE_LIFETIME = 50;

class Vector {
    constructor(x, y) {
        this.x = x;
        this.y = y;
    }

    add(v) {
        return new Vector(this.x + v.x, this.y + v.y);
    }

    subtract(v) {
        return new Vector(this.x - v.x, this.y - v.y);
    }

    multiply(scalar) {
        return new Vector(this.x * scalar, this.y * scalar);
    }

    magnitude() {
        return Math.sqrt(this.x * this.x + this.y * this.y);
    }

    normalize() {
        const mag = this.magnitude();
        return new Vector(this.x / mag, this.y / mag);
    }

    static fromAngle(angle) {
        return new Vector(Math.cos(angle), Math.sin(angle));
    }
}

class Asteroid {
    constructor(position, velocity) {
        this.position = position;
        this.velocity = velocity;
        this.radius = ASTEROID_RADIUS;
    }

    update(dt) {
        this.position = this.position.add(this.velocity.multiply(dt));
        if (this.position.x < -this.radius) this.position.x = canvas.width + this.radius;
        if (this.position.x > canvas.width + this.radius) this.position.x = -this.radius;
        if (this.position.y < -this.radius) this.position.y = canvas.height + this.radius;
        if (this.position.y > canvas.height + this.radius) this.position.y = -this.radius;
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.position.x, this.position.y, this.radius, 0, Math.PI * 2);
        ctx.fillStyle = 'gray';
        ctx.fill();
    }
}

class Ship {
    constructor(position) {
        this.position = position;
        this.velocity = new Vector(0, 0);
        this.angle = Math.PI / 2;
        this.thrust = false;
        this.radius = SHIP_RADIUS;
    }

    update(dt) {
        if (this.thrust) {
            const thrustVector = Vector.fromAngle(this.angle).multiply(0.1);
            this.velocity = this.velocity.add(thrustVector);
        }
        this.velocity = this.velocity.multiply(0.99); // Friction
        this.position = this.position.add(this.velocity.multiply(dt));
        if (this.position.x < 0) this.position.x = 0;
        if (this.position.x > canvas.width) this.position.x = canvas.width;
        if (this.position.y < 0) this.position.y = 0;
        if (this.position.y > canvas.height) this.position.y = canvas.height;
    }

    draw() {
        ctx.save();
        ctx.translate(this.position.x, this.position.y);
        ctx.rotate(this.angle);
        ctx.beginPath();
        ctx.moveTo(SHIP_RADIUS, 0);
        ctx.lineTo(-SHIP_RADIUS, SHIP_RADIUS);
        ctx.lineTo(-SHIP_RADIUS, -SHIP_RADIUS);
        ctx.closePath();
        ctx.fillStyle = 'green';
        ctx.fill();
        ctx.restore();
    }

    setThrust(thrust) {
        this.thrust = thrust;
    }

    rotate(angle) {
        this.angle += angle;
    }
}

class Particle {
    constructor(position, velocity, lifetime) {
        this.position = position;
        this.velocity = velocity;
        this.lifetime = lifetime;
    }

    update(dt) {
        this.position = this.position.add(this.velocity.multiply(dt));
        this.lifetime -= dt;
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.position.x, this.position.y, 1, 0, Math.PI * 2);
        ctx.fillStyle = 'white';
        ctx.fill();
    }
}

let asteroids = [];
let ship = new Ship(new Vector(canvas.width / 2, canvas.height / 2));
let particles = [];

function spawnAsteroids() {
    for (let i = 0; i < ASTEROID_COUNT; i++) {
        const angle = Math.random() * Math.PI * 2;
        const position = new Vector(
            Math.random() * canvas.width,
            Math.random() * canvas.height
        );
        const velocity = Vector.fromAngle(angle).multiply(Math.random() * 2);
        asteroids.push(new Asteroid(position, velocity));
    }
}

function createParticleBurst(position, count) {
    for (let i = 0; i < count; i++) {
        const angle = Math.random() * Math.PI * 2;
        const velocity = Vector.fromAngle(angle).multiply(Math.random() * 5);
        particles.push(new Particle(position, velocity, PARTICLE_LIFETIME));
    }
}

function update(dt) {
    ship.update(dt);
    asteroids.forEach(asteroid => asteroid.update(dt));
    particles = particles.filter(particle => particle.lifetime > 0);
    particles.forEach(particle => particle.update(dt));
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ship.draw();
    asteroids.forEach(asteroid => asteroid.draw());
    particles.forEach(particle => particle.draw());
}

let lastTime = performance.now();
function gameLoop() {
    const now = performance.now();
    const dt = (now - lastTime) / 1000;
    update(dt);
    draw();
    lastTime = now;
    requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowLeft') ship.rotate(-0.1);
    if (e.key === 'ArrowRight') ship.rotate(0.1);
    if (e.key === 'ArrowUp') ship.setThrust(true);
});

document.addEventListener('keyup', (e) => {
    if (e.key === 'ArrowUp') ship.setThrust(false);
});

document.addEventListener('click', (e) => {
    const position = new Vector(e.clientX, e.clientY);
    createParticleBurst(position, PARTICLE_COUNT);
});

spawnAsteroids();
gameLoop();
