// Trade System
class TradeSystem {
  constructor(prices) {
    this.prices = prices;
  }

  getTradePrice(item) {
    return this.prices[item] || null;
  }

  trade(item, quantity, faction) {
    const price = this.getTradePrice(item);
    if (price !== null) {
      faction.modifyResources(quantity * price);
      return true;
    }
    return false;
  }
}

// Reputation System
class ReputationSystem {
  constructor(startingReputation) {
    this.reputation = startingReputation;
  }

  getReputation() {
    return this.reputation;
  }

  modifyReputation(amount) {
    this.reputation += amount;
    return this.reputation;
  }
}

// Faction System
class FactionSystem {
  constructor(reputationSystem, startingResources) {
    this.reputationSystem = reputationSystem;
    this.resources = startingResources;
  }

  getResources() {
    return this.resources;
  }

  modifyResources(amount) {
    this.resources += amount;
    this.reputationSystem.modifyReputation(amount > 0 ? 1 : -1);
    return this.resources;
  }
}

