class EventBus {
    constructor() {
        this.events = {};
    }

    emit(eventName, data) {
        if (this.events[eventName]) {
            this.events[eventName].forEach(handler => handler(data));
        }
    }

    subscribe(eventName, handler) {
        if (!this.events[eventName]) {
            this.events[eventName] = [];
        }
        this.events[eventName].push(handler);
    }
}

class Farm {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.crops = [];
        this.eventBus.subscribe('market:buyCrop', this.sellCrop.bind(this));
    }

    plantCrop(cropType) {
        const crop = { type: cropType, ready: false };
        this.crops.push(crop);
        console.log(`Planted a ${cropType} crop.`);
        this.eventBus.emit('farm:cropPlanted', crop);
    }

    harvestCrops() {
        const readyCrops = this.crops.filter(crop => crop.ready);
        this.crops = this.crops.filter(crop => !crop.ready);
        console.log(`Harvested ${readyCrops.length} crops.`);
        this.eventBus.emit('farm:cropsHarvested', readyCrops);
        return readyCrops;
    }

    sellCrop(cropType) {
        const cropIndex = this.crops.findIndex(crop => crop.type === cropType && !crop.ready);
        if (cropIndex !== -1) {
            const crop = this.crops[cropIndex];
            crop.ready = true;
            console.log(`Crop ${cropType} is now ready for sale.`);
        }
    }
}

class Crop {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('farm:cropPlanted', this.grow.bind(this));
    }

    grow(crop) {
        setTimeout(() => {
            crop.ready = true;
            console.log(`The ${crop.type} crop is ready.`);
            this.eventBus.emit('crop:ready', crop);
        }, Math.random() * 5000 + 5000); // Random time between 5 to 10 seconds
    }
}

class Market {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('crop:ready', this.listCrop.bind(this));
    }

    listCrop(crop) {
        console.log(`Listing ${crop.type} crop for sale.`);
        this.eventBus.emit('market:buyCrop', crop.type);
    }
}

// Demo
