const canvas = document.createElement('canvas');
canvas.width = 600;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const boardSize = 8;
const cellSize = canvas.width / boardSize;
const colors = ['#FF5733', '#33FF57', '#3357FF', '#F3FF33', '#FF33F3', '#33FFF3'];
let board = [];

function initBoard() {
    board = Array.from({ length: boardSize }, () =>
        Array.from({ length: boardSize }, () => Math.floor(Math.random() * colors.length))
    );
}

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let y = 0; y < boardSize; y++) {
        for (let x = 0; x < boardSize; x++) {
            ctx.fillStyle = colors[board[y][x]];
            ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
            ctx.strokeStyle = '#000';
            ctx.strokeRect(x * cellSize, y * cellSize, cellSize, cellSize);
        }
    }
}

function checkMatches() {
    let matches = [];
    for (let y = 0; y < boardSize; y++) {
        for (let x = 0; x < boardSize - 2; x++) {
            if (board[y][x] === board[y][x + 1] && board[y][x] === board[y][x + 2]) {
                matches.push([[x, y], [x + 1, y], [x + 2, y]]);
            }
        }
    }
    for (let x = 0; x < boardSize; x++) {
        for (let y = 0; y < boardSize - 2; y++) {
            if (board[y][x] === board[y + 1][x] && board[y][x] === board[y + 2][x]) {
                matches.push([[x, y], [x, y + 1], [x, y + 2]]);
            }
        }
    }
    return matches;
}

function clearMatches(matches) {
    matches.forEach(match => {
        match.forEach(([x, y]) => {
            board[y][x] = null;
        });
    });
}

function fillBoard() {
    for (let x = 0; x < boardSize; x++) {
        let nullCount = 0;
        for (let y = boardSize - 1; y >= 0; y--) {
            if (board[y][x] === null) {
                nullCount++;
            } else if (nullCount > 0) {
                board[y + nullCount][x] = board[y][x];
                board[y][x] = null;
            }
        }
    }
    for (let x = 0; x < boardSize; x++) {
        for (let y = 0; y < nullCount; y++) {
            board[y][x] = Math.floor(Math.random() * colors.length);
        }
    }
}

let particles = [];

function createParticles(x, y, color) {
    const particleCount = 20;
    for (let i = 0; i < particleCount; i++) {
        particles.push({
            x: x * cellSize + cellSize / 2,
            y: y * cellSize + cellSize / 2,
            color: color,
            size: Math.random() * 2 + 1,
            vx: (Math.random() - 0.5) * 3,
            vy: (Math.random() - 0.5) * 3,
            life: 60
        });
    }
}

function updateParticles() {
    particles = particles.filter(particle => particle.life > 0);
    particles.forEach(particle => {
        particle.x += particle.vx;
        particle.y += particle.vy;
        particle.life--;
    });
}

function drawParticles() {
    particles.forEach(particle => {
        ctx.beginPath();
        ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2);
        ctx.fillStyle = particle.color;
        ctx.fill();
    });
}

function gameLoop() {
    const matches = checkMatches();
    if (matches.length > 0) {
        matches.forEach(match => {
            const [x, y] = match[0];
            createParticles(x, y, colors[board[y][x]]);
        });
        clearMatches(matches);
        fillBoard();
    }
    updateParticles();
    drawBoard();
    drawParticles();
    requestAnimationFrame(gameLoop);
}

initBoard();
gameLoop();
