// Constants
const CANVAS_ID = 'gameCanvas';
const FPS = 60;
const POWER_UP_INTERVAL = 5000; // 5 seconds
const POWER_UP_RADIUS = 10;
const POWER_UP_SPEED = 2;

// Game state
let canvas;
let ctx;
let player1;
let player2;
let powerUps = [];
let powerUpTimer;

// Player class
class Player {
  constructor(x, y, color) {
    this.x = x;
    this.y = y;
    this.color = color;
    this.width = 20;
    this.height = 20;
    this.speed = 5;
  }

  draw() {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x, this.y, this.width, this.height);
  }

  move(dx, dy) {
    this.x += dx;
    this.y += dy;
  }
}

// PowerUp class
class PowerUp {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.color = 'green';
  }

  draw() {
    ctx.fillStyle = this.color;
    ctx.beginPath();
    ctx.arc(this.x, this.y, POWER_UP_RADIUS, 0, Math.PI * 2);
    ctx.fill();
  }

  update() {
    this.x += Math.random() * POWER_UP_SPEED * (Math.random() > 0.5 ? 1 : -1);
    this.y += Math.random() * POWER_UP_SPEED * (Math.random() > 0.5 ? 1 : -1);
  }
}

// Initialize game
function init() {
  canvas = document.getElementById(CANVAS_ID);
  ctx = canvas.getContext('2d');
  const dpr = window.devicePixelRatio || 1;
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  ctx.scale(dpr, dpr);

  player1 = new Player(50, 50, 'blue');
  player2 = new Player(canvas.width - 70, canvas.height - 70, 'red');

  powerUpTimer = setInterval(() => {
    powerUps.push(new PowerUp(Math.random() * canvas.width, Math.random() * canvas.height));
  }, POWER_UP_INTERVAL);

  window.addEventListener('keydown', handleKeyDown);
  requestAnimationFrame(gameLoop);
}

// Game loop
function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  player1.draw();
  player2.draw();

  powerUps.forEach(powerUp => {
    powerUp.update();
    powerUp.draw();
  });

  requestAnimationFrame(gameLoop);
}

// Handle keyboard input
function handleKeyDown(e) {
  const speed = player1.speed;
  switch (e.key) {
    case 'ArrowUp':
      player1.move(0, -speed);
      break;
    case 'ArrowDown':
      player1.move(0, speed);
      break;
    case 'ArrowLeft':
      player1.move(-speed, 0);
      break;
    case 'ArrowRight':
      player1.move(speed, 0);
      break;
    case 'w':
      player2.move(0, -speed);
      break;
    case 's':
      player2.move(0, speed);
      break;
    case 'a':
      player2.move(-speed, 0);
      break;
    case 'd':
      player2.move(speed, 0);
      break;
  }
}

// Start game
init();
