        this.name = name;
        this.ingredients = ingredients;
    }

    getName() {
        return this.name;
    }

    getIngredients() {
        return this.ingredients;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    removeItem(item, quantity) {
        if (this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            return true;
        }
        return false;
    }

    getQuantity(item) {
        return this.items[item] || 0;
    }

    getItems() {
        return { ...this.items };
    }
}

class Crafting {
    constructor(recipeSystem, inventorySystem) {
        this.recipeSystem = recipeSystem;
        this.inventorySystem = inventorySystem;
    }

    canCraft(recipeName) {
        const recipe = this.recipeSystem.findRecipe(recipeName);
        if (!recipe) return false;

        const ingredients = recipe.getIngredients();
        for (const [item, quantity] of Object.entries(ingredients)) {
            if (this.inventorySystem.getQuantity(item) < quantity) {
                return false;
            }
        }
        return true;
    }

    craft(recipeName) {
        const recipe = this.recipeSystem.findRecipe(recipeName);
        if (!recipe || !this.canCraft(recipeName)) return false;

        const ingredients = recipe.getIngredients();
        for (const [item, quantity] of Object.entries(ingredients)) {
            this.inventorySystem.removeItem(item, quantity);
        }

        console.log(`Crafted: ${recipe.getName()}`);
        return true;
    }
}

