  ctx.fillText(`Enemy Health: ${enemyHealth}`, 10, 60);
  ctx.fillText('Press Space to Attack', 10, 90);
}

function renderPaused() {
  ctx.clearRect(0, 0, width, height);
  ctx.font = '30px Arial';
  ctx.fillText('Game Paused', width / 2 - 100, height / 2);
}

function renderGameOver() {
  ctx.clearRect(0, 0, width, height);
  ctx.font = '30px Arial';
  ctx.fillText('Game Over', width / 2 - 80, height / 2);
}

function update() {
  switch (state) {
    case 'menu':
      renderMenu();
      break;
    case 'playing':
      renderPlaying();
      if (playerHealth <= 0 || enemyHealth <= 0) {
        state = 'gameover';
      }
      break;
    case 'paused':
      renderPaused();
      break;
    case 'gameover':
      renderGameOver();
      break;
  }
}

function handleInput(event) {
