    switch (state) {
      case 'menu':
        state = 'playing';
        break;
      case 'playing':
        enemyHealth -= 10;
        playerHealth -= 5;
        break;
      case 'paused':
        state = 'playing';
        break;
      case 'gameover':
        state = 'menu';
        playerHealth = 100;
        enemyHealth = 100;
        break;
    }
  } else if (event.key === 'p') {
    if (state === 'playing') {
      state = 'paused';
    } else if (state === 'paused') {
      state = 'playing';
    }
  }
}

