const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const TICK_RATE = 1000 / 60;
let lastTime = 0;

const states = {
    MENU: 'menu',
    PLAYING: 'playing',
    PAUSED: 'paused',
    GAMEOVER: 'gameover'
};

let currentState = states.MENU;
let player = { x: 400, y: 300, size: 20 };
let maze = generateMaze();
let goal = { x: 800 - 40, y: 600 - 40, size: 20 };
let score = 0;
let paused = false;
let gameOver = false;

function generateMaze() {
    const maze = [];
    const width = 10;
    const height = 8;
    for (let y = 0; y < height; y++) {
        const row = [];
        for (let x = 0; x < width; x++) {
            row.push(Math.random() > 0.5 ? 0 : 1);
        }
        maze.push(row);
    }
    return maze;
}

function drawMaze() {
    const cellSize = 50;
    maze.forEach((row, y) => {
        row.forEach((cell, x) => {
            if (cell) {
                ctx.fillStyle = 'black';
                ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
            }
        });
    });
}

function updatePlayer(dt) {
    const speed = 50;
    if (keys['ArrowUp'] && player.y > 0) player.y -= speed * dt;
    if (keys['ArrowDown'] && player.y < canvas.height - player.size) player.y += speed * dt;
    if (keys['ArrowLeft'] && player.x > 0) player.x -= speed * dt;
    if (keys['ArrowRight'] && player.x < canvas.width - player.size) player.x += speed * dt;
}

function checkCollision() {
    const cellSize = 50;
    const playerCellX = Math.floor(player.x / cellSize);
    const playerCellY = Math.floor(player.y / cellSize);
    if (maze[playerCellY][playerCellX]) {
        player.x = Math.max(0, Math.min(canvas.width - player.size, player.x));
        player.y = Math.max(0, Math.min(canvas.height - player.size, player.y));
    }
    if (Math.hypot(player.x - goal.x, player.y - goal.y) < player.size + goal.size) {
        score++;
        goal = { x: 800 - 40, y: 600 - 40, size: 20 };
        maze = generateMaze();
    }
}

function drawPlayer() {
    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x, player.y, player.size, player.size);
}

function drawGoal() {
    ctx.fillStyle = 'green';
    ctx.fillRect(goal.x, goal.y, goal.size, goal.size);
}

function drawScore() {
    ctx.fillStyle = 'white';
    ctx.font = '24px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
}

function drawMenu() {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = 'white';
    ctx.font = '36px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('Maze Chase Game', canvas.width / 2, canvas.height / 2 - 40);
    ctx.font = '24px Arial';
    ctx.fillText('Press Enter to Start', canvas.width / 2, canvas.height / 2);
}

function drawPaused() {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = 'white';
    ctx.font = '24px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('Paused', canvas.width / 2, canvas.height / 2);
}

function drawGameOver() {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = 'white';
    ctx.font = '36px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2 - 40);
    ctx.font = '24px Arial';
    ctx.fillText('Press Enter to Restart', canvas.width / 2, canvas.height / 2);
}

function update(dt) {
    updatePlayer(dt);
    checkCollision();
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawMaze();
    drawPlayer();
    drawGoal();
    drawScore();
    if (currentState === states.MENU) {
        drawMenu();
    } else if (currentState === states.PAUSED) {
        drawPaused();
    } else if (currentState === states.GAMEOVER) {
        drawGameOver();
    }
}

function gameLoop(timestamp) {
    const dt = (timestamp - lastTime) / 1000;
    lastTime = timestamp;

    if (currentState === states.PLAYING) {
        update(dt);
    }

    render();

    requestAnimationFrame(gameLoop);
}

const keys = {};
window.addEventListener('keydown', (e) => {
    keys[e.key] = true;
    if (currentState === states.MENU && e.key === 'Enter') {
        currentState = states.PLAYING;
    } else if (currentState === states.PLAYING && e.key === 'Escape') {
        paused = !paused;
        currentState = paused ? states.PAUSED : states.PLAYING;
    } else if (currentState === states.GAMEOVER && e.key === 'Enter') {
        currentState = states.MENU;
        player = { x: 400, y: 300, size: 20 };
        maze = generateMaze();
        goal = { x: 800 - 40, y: 600 - 40, size: 20 };
        score = 0;
        gameOver = false;
    }
});
window.addEventListener('keyup', (e) => {
    keys[e.key] = false;
});

requestAnimationFrame(gameLoop);
