class Wallet {
    constructor(initialBalance = 0) {
        this.balance = initialBalance;
    }

    getBalance() {
        return this.balance;
    }

    debit(amount) {
        if (amount > this.balance) {
            throw new Error("Insufficient funds");
        }
        this.balance -= amount;
    }

    credit(amount) {
        this.balance += amount;
    }
}

class Shop {
    constructor(prices) {
        this.prices = prices;
    }

    getPrices() {
        return this.prices;
    }

    purchaseItem(itemName, wallet) {
        const price = this.prices[itemName];
        if (!price) {
            throw new Error("Item not found");
        }
        wallet.debit(price);
        return itemName;
    }
}

class Inventory {
    constructor() {
        this.items = [];
    }

    getItems() {
        return this.items;
    }

    addItem(item) {
        this.items.push(item);
    }
}

class Economy {
    constructor(initialPrices = {}) {
        this.prices = initialPrices;
    }

    getPrices() {
        return this.prices;
    }

    updatePrice(itemName, newPrice) {
        this.prices[itemName] = newPrice;
    }
}

