    this.lootPool = new Map();
  }

  addLoot(entity, loot) {
    if (!this.lootPool.has(entity)) {
      this.lootPool.set(entity, []);
    }
    this.lootPool.get(entity).push(loot);
    console.log(`Added ${loot} to ${entity}'s loot.`);
