    if (gameOver) {
        ctx.fillStyle = 'red';
        ctx.fillText('Game Over!', canvas.width / 2 - 50, canvas.height / 2);
    } else {
        ctx.fillStyle = 'blue';
        ctx.fillRect(canvas.width / 2 - 25, canvas.height / 2 - 25, 50, 50);
    }
}

