class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Skill {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('levelUp', this.onLevelUp.bind(this));
    this.skills = {};
  }

  learn(skill, points) {
    this.skills[skill] = (this.skills[skill] || 0) + points;
    console.log(`Learned ${points} points in ${skill}. Total: ${this.skills[skill]}`);
  }

  onLevelUp(level) {
    console.log(`Level up to ${level}. Gaining new skills...`);
    this.learn('NewSkill', 10); // Example skill gain on level up
  }
}

class Experience {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.experience = 0;
  }

  gain(amount) {
    this.experience += amount;
    console.log(`Gained ${amount} experience. Total: ${this.experience}`);
    this.checkLevelUp();
  }

  checkLevelUp() {
    const level = Math.floor(this.experience / 100) + 1;
    if (this.experience % 100 === 0) {
      this.eventBus.emit('levelUp', level);
    }
  }
}

class LevelUp {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('levelUp', this.onLevelUp.bind(this));
    this.level = 1;
  }

  onLevelUp(newLevel) {
    this.level = newLevel;
    console.log(`Reached level ${this.level}!`);
  }
}

