class EventBus {
    constructor() {
        this.events = {};
    }

    subscribe(event, listener) {
        if (!this.events[event]) {
            this.events[event] = [];
        }
        this.events[event].push(listener);
    }

    emit(event, data) {
        if (this.events[event]) {
            this.events[event].forEach(listener => listener(data));
        }
    }
}

class Crop {
    constructor(eventBus, name, growthTime) {
        this.eventBus = eventBus;
        this.name = name;
        this.growthTime = growthTime;
        this.isReady = false;
        this.grow();
    }

    grow() {
        setTimeout(() => {
            this.isReady = true;
            this.eventBus.emit('crop-ready', { crop: this });
        }, this.growthTime);
    }

    harvest() {
        if (this.isReady) {
            console.log(`Harvested ${this.name}`);
            this.isReady = false;
            this.grow();
        } else {
            console.log(`${this.name} is not ready yet`);
        }
    }
}

class Market {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('crop-ready', this.onCropReady.bind(this));
    }

    onCropReady(data) {
        console.log(`Market received ready crop: ${data.crop.name}`);
        // Simulate selling the crop
        console.log(`Sold ${data.crop.name} at the market`);
    }
}

class Farm {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.crops = [];
    }

    plantCrop(name, growthTime) {
        const crop = new Crop(this.eventBus, name, growthTime);
        this.crops.push(crop);
        console.log(`Planted ${name}`);
    }

    harvestAll() {
        this.crops.forEach(crop => crop.harvest());
    }
}

// Demo
const eventBus = new EventBus();
const farm = new Farm(eventBus);
const market = new Market(eventBus);

farm.plantCrop('Carrot', 2000); // Plant a carrot that takes 2 seconds to grow
farm.plantCrop('Potato', 3000); // Plant a potato that takes 3 seconds to grow

setTimeout(() => {
    farm.harvestAll(); // Try harvesting after 2.5 seconds
}, 2500);
