const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

canvas.width = 800;
canvas.height = 600;

const gravity = 0.5;
const jumpPower = -10;
const player = {
    x: 100,
    y: 100,
    width: 50,
    height: 50,
    velocityX: 0,
    velocityY: 0,
    isJumping: false
};

const platforms = [
    { x: 0, y: 500, width: 800, height: 20 },
    { x: 200, y: 400, width: 200, height: 20 },
    { x: 500, y: 300, width: 100, height: 20 }
];

const powerUps = [
    { x: 150, y: 450, width: 20, height: 20, collected: false },
    { x: 450, y: 250, width: 20, height: 20, collected: false }
];

function drawRect(x, y, width, height, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x, y, width, height);
}

function updatePlayer() {
    player.velocityY += gravity;
    player.x += player.velocityX;
    player.y += player.velocityY;

    // Collision with platforms
    platforms.forEach(platform => {
        if (player.x < platform.x + platform.width &&
            player.x + player.width > platform.x &&
            player.y < platform.y + platform.height &&
            player.y + player.height > platform.y) {
            if (player.velocityY > 0) {
                player.y = platform.y - player.height;
                player.velocityY = 0;
                player.isJumping = false;
            }
        }
    });

    // Collect power-ups
    powerUps.forEach(powerUp => {
        if (!powerUp.collected &&
            player.x < powerUp.x + powerUp.width &&
            player.x + player.width > powerUp.x &&
            player.y < powerUp.y + powerUp.height &&
            player.y + player.height > powerUp.y) {
            powerUp.collected = true;
        }
    });
}

function drawPlayer() {
    drawRect(player.x, player.y, player.width, player.height, 'blue');
}

function drawPlatforms() {
    platforms.forEach(platform => {
        drawRect(platform.x, platform.y, platform.width, platform.height, 'green');
    });
}

function drawPowerUps() {
    powerUps.forEach(powerUp => {
        if (!powerUp.collected) {
            drawRect(powerUp.x, powerUp.y, powerUp.width, powerUp.height, 'red');
        }
    });
}

function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    drawPlatforms();
    drawPowerUps();
    drawPlayer();

    updatePlayer();

    requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowLeft') {
        player.velocityX = -5;
    } else if (e.key === 'ArrowRight') {
        player.velocityX = 5;
    } else if (e.key === ' ' && !player.isJumping) {
        player.velocityY = jumpPower;
        player.isJumping = true;
    }
});

document.addEventListener('keyup', (e) => {
    if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
        player.velocityX = 0;
    }
});

gameLoop();
