      this.score += 10;
    } else {
      this.score -= 5;
    }
  }

  getScore() {
    return this.score;
  }
}

class Faction {
  constructor() {
    this.membership = 'Neutral';
  }

  updateMembership(reputationScore) {
    if (reputationScore > 50) {
      this.membership = 'Faction A';
    } else if (reputationScore < -50) {
      this.membership = 'Faction B';
    } else {
      this.membership = 'Neutral';
    }
  }

  getMembership() {
    return this.membership;
  }
}

class Economy {
  constructor(initialMoney) {
    this.money = initialMoney;
  }

  hasEnoughMoney(price) {
    return this.money >= price;
  }

  debit(price) {
    this.money -= price;
  }

  getCurrentMoney() {
    return this.money;
  }
}

class Inventory {
