// Flappy-style gap dodger with combo multiplier
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = 800;
canvas.height = 600;

const bird = {
  x: 50,
  y: canvas.height / 2,
  width: 30,
  height: 30,
  speed: 0,
  gravity: 0.5,
  jump: -10,
  draw() {
    ctx.fillStyle = 'yellow';
    ctx.fillRect(this.x, this.y, this.width, this.height);
  },
  update() {
    this.speed += this.gravity;
    this.y += this.speed;
    if (this.y + this.height > canvas.height) {
      this.y = canvas.height - this.height;
      this.speed = 0;
    }
  },
  jump() {
    this.speed = this.jump;
  }
};

const pipes = [];
const pipeWidth = 50;
const pipeGap = 150;
const pipeSpeed = 2;

function createPipe() {
  const height = Math.random() * (canvas.height - pipeGap);
  pipes.push({ x: canvas.width, y: 0, height, width: pipeWidth });
  pipes.push({ x: canvas.width, y: height + pipeGap, height: canvas.height - height - pipeGap, width: pipeWidth });
}

function updatePipes() {
  pipes.forEach(pipe => pipe.x -= pipeSpeed);
  if (pipes[0] && pipes[0].x + pipeWidth < 0) {
    pipes.shift();
    pipes.shift();
    createPipe();
    combo = 0;
  }
}

function drawPipes() {
  ctx.fillStyle = 'green';
  pipes.forEach(pipe => ctx.fillRect(pipe.x, pipe.y, pipe.width, pipe.height));
}

let combo = 0;
let score = 0;
let gameLoop;
let gameOver = false;

function collisionCheck() {
  pipes.forEach(pipe => {
    if (bird.x < pipe.x + pipe.width && bird.x + bird.width > pipe.x && bird.y < pipe.y + pipe.height && bird.y + bird.height > pipe.y) {
      gameOver = true;
    }
  });
  if (bird.y + bird.height > canvas.height) {
    gameOver = true;
  }
}

function updateScore() {
  if (pipes[0] && pipes[0].x + pipeWidth < bird.x) {
    score += combo + 1;
    combo += 1;
  }
}

function drawScore() {
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`Combo: ${combo}`, 10, 60);
}

function gameLoopFunction() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  if (!gameOver) {
    bird.update();
    bird.draw();
    updatePipes();
    drawPipes();
    collisionCheck();
    updateScore();
  } else {
    ctx.fillStyle = 'red';
    ctx.font = '48px Arial';
    ctx.fillText('Game Over', canvas.width / 2 - 100, canvas.height / 2);
  }
  drawScore();
  if (!gameOver) {
    requestAnimationFrame(gameLoopFunction);
  }
}

document.addEventListener('keydown', e => {
  if (e.code === 'Space' && !gameOver) {
    bird.jump();
  }
  if (e.code === 'Space' && gameOver) {
    gameOver = false;
    bird.y = canvas.height / 2;
    pipes.length = 0;
    score = 0;
    combo = 0;
    createPipe();
    requestAnimationFrame(gameLoopFunction);
  }
});

