class Clock {
  constructor() {
    this.time = 0;
  }

  tick() {
    this.time++;
    return this.time;
  }

  getCurrentTime() {
    return this.time;
  }
}

class Energy {
  constructor(clock) {
    this.clock = clock;
    this.energyLevel = 100;
  }

  useEnergy(amount) {
    if (this.energyLevel >= amount) {
      this.energyLevel -= amount;
    } else {
      this.energyLevel = 0;
    }
    return this.energyLevel;
  }

  regenerateEnergy() {
    if (this.clock.getCurrentTime() % 10 === 0) {
      this.energyLevel = Math.min(this.energyLevel + 10, 100);
    }
    return this.energyLevel;
  }

  getEnergyLevel() {
    return this.energyLevel;
  }
}

class Hunger {
  constructor(clock) {
    this.clock = clock;
    this.hungerLevel = 100;
  }

  eat(foodAmount) {
    if (this.hungerLevel >= foodAmount) {
      this.hungerLevel -= foodAmount;
    } else {
      this.hungerLevel = 0;
    }
    return this.hungerLevel;
  }

  increaseHunger() {
    if (this.clock.getCurrentTime() % 5 === 0) {
      this.hungerLevel = Math.min(this.hungerLevel + 5, 100);
    }
    return this.hungerLevel;
  }

  getHungerLevel() {
    return this.hungerLevel;
  }
}

// Demo
