// Tower Class
class Tower {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.cost = TOWER_COST;
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, TOWER_RADIUS, 0, Math.PI * 2);
        ctx.fillStyle = 'blue';
        ctx.fill();
        ctx.closePath();
    }

    shoot() {
        enemies.forEach(enemy => {
            const distance = Math.sqrt(Math.pow(this.x - enemy.x, 2) + Math.pow(this.y - enemy.y, 2));
            if (distance < TOWER_RADIUS) {
                enemy.health -= 1;
                if (enemy.health <= 0) {
                    this.killEnemy(enemy);
                }
            }
        });
    }

    killEnemy(enemy) {
        score += ENEMY_REWARD * combo;
        money += ENEMY_REWARD;
        enemies.splice(enemies.indexOf(enemy), 1);
        lastEnemyKillTime = performance.now();
        combo = Math.min(combo + 0.25, 5); // Max combo of 5
    }
}

// Enemy Class
class Enemy {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.health = ENEMY_HEALTH;
    }

    move() {
        this.x -= ENEMY_SPEED;
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, 5, 0, Math.PI * 2);
        ctx.fillStyle = 'red';
        ctx.fill();
        ctx.closePath();
    }
}

// Game Loop
function gameLoop() {
    // Clear Canvas
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Draw Turrets
    turrets.forEach(turret => {
        turret.draw();
        turret.shoot();
    });

    // Draw Enemies
    enemies.forEach(enemy => {
        enemy.move();
        enemy.draw();
    });

    // Remove enemies that have moved off screen
    enemies = enemies.filter(enemy => enemy.x > 0);

    // Check for combo reset
    if (performance.now() - lastEnemyKillTime > COMBO_TIMEOUT) {
        combo = 1;
    }

    // Render UI
    ctx.fillStyle = 'black';
    ctx.fillText(`Money: ${money}`, 10, 20);
    ctx.fillText(`Score: ${score}`, 10, 40);
    ctx.fillText(`Combo: ${combo.toFixed(2)}x`, 10, 60);

    // Spawn Enemies
