const gridSize = 4;
const tileWidth = canvas.width / gridSize;
const tileHeight = canvas.height / gridSize;

let tiles = Array(gridSize).fill().map(() => Array(gridSize).fill(0));
let score = 0;
let gameOver = false;
let timer = 60; // 1 minute countdown

function spawnTile() {
    let emptyTiles = [];
    for (let y = 0; y < gridSize; y++) {
        for (let x = 0; x < gridSize; x++) {
            if (tiles[y][x] === 0) {
                emptyTiles.push({ y, x });
            }
        }
    }
    if (emptyTiles.length > 0) {
        const { y, x } = emptyTiles[Math.floor(Math.random() * emptyTiles.length)];
        tiles[y][x] = Math.random() < 0.9 ? 2 : 4;
    }
}

function mergeTiles() {
    let moved = false;
    for (let y = 0; y < gridSize; y++) {
        for (let x = 0; x < gridSize; x++) {
            if (tiles[y][x] !== 0) {
                for (let newX = x + 1; newX < gridSize; newX++) {
                    if (tiles[y][newX] !== 0) {
                        if (tiles[y][newX] === tiles[y][x]) {
                            tiles[y][newX] *= 2;
                            tiles[y][x] = 0;
                            score += tiles[y][newX];
                            moved = true;
                        }
                        break;
                    } else {
                        tiles[y][newX] = tiles[y][x];
                        tiles[y][x] = 0;
                        moved = true;
                    }
                }
            }
        }
    }
    return moved;
}

function slideTiles(dir) {
    let moved = false;
    if (dir === 'up') {
        for (let x = 0; x < gridSize; x++) {
            for (let y = 1; y < gridSize; y++) {
                if (tiles[y][x] !== 0) {
                    for (let newY = y - 1; newY >= 0; newY--) {
                        if (tiles[newY][x] !== 0) {
                            if (tiles[newY][x] === tiles[y][x]) {
                                tiles[newY][x] *= 2;
                                tiles[y][x] = 0;
                                score += tiles[newY][x];
                                moved = true;
                            }
                            break;
                        } else {
