// EventBus class to handle communication between systems
class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

// Building system
class Building {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('resourceGathered', this.onResourceGathered.bind(this));
  }

  constructBuilding(type) {
    console.log(`Building constructed: ${type}`);
    this.eventBus.emit('buildingConstructed', { type });
  }

  onResourceGathered(data) {
    console.log(`Resources gathered: ${data.amount} ${data.type}`);
  }
}

// Resource system
class Resource {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('buildingConstructed', this.onBuildingConstructed.bind(this));
  }

  gatherResource(type, amount) {
    console.log(`Gathering ${amount} ${type}`);
    this.eventBus.emit('resourceGathered', { type, amount });
  }

  onBuildingConstructed(data) {
    if (data.type === 'mine') {
      this.gatherResource('ore', 10);
    }
  }
}

// Economy system
class Economy {
