// 2048-style slide game with player health bar and respawn
// Rendered on a canvas sized to the window with devicePixelRatio handling

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let tileCount = 4;
let tileSize = 0;
let health = 3;
let tiles = Array.from({ length: tileCount * tileCount }, () => 0);
let score = 0;
let gameOver = false;
let playerX = 0;
let playerY = 0;
let moveCooldown = false;
const moveCooldownDuration = 100;

function resizeCanvas() {
  const dpr = window.devicePixelRatio || 1;
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  ctx.scale(dpr, dpr);
  tileSize = Math.min(canvas.width, canvas.height) / tileCount;
}

function spawnTile() {
  const emptyTiles = tiles.reduce((acc, tile, index) => {
    if (tile === 0) acc.push(index);
    return acc;
  }, []);

  if (emptyTiles.length > 0) {
    const randomIndex = emptyTiles[Math.floor(Math.random() * emptyTiles.length)];
    tiles[randomIndex] = Math.random() < 0.9 ? 2 : 4;
  }
}

function resetGame() {
  tiles = Array.from({ length: tileCount * tileCount }, () => 0);
  health = 3;
  score = 0;
  gameOver = false;
  spawnTile();
  spawnTile();
}

function drawTile(x, y, value) {
  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(x * tileSize, y * tileSize, tileSize, tileSize);
  ctx.strokeStyle = '#000000';
  ctx.strokeRect(x * tileSize, y * tileSize, tileSize, tileSize);
  if (value > 0) {
    ctx.fillStyle = '#000000';
    ctx.font = `${Math.min(48, tileSize * 0.8)}px Arial`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(value.toString(), x * tileSize + tileSize / 2, y * tileSize + tileSize / 2);
  }
}

function drawHealthBar() {
  ctx.fillStyle = '#FF0000';
  ctx.fillRect(0, canvas.height - tileSize, canvas.width * (health / 3), tileSize);
}

function drawGameOverScreen() {
  ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#FFFFFF';
  ctx.font = '48px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
  ctx.font = '24px Arial';
  ctx.fillText('Press R to restart', canvas.width / 2, canvas.height / 2 + 48);
}

function slideLeft() {
  for (let row = 0; row < tileCount; row++) {
    let merged = false;
    let buffer = [];
    for (let col = 0; col < tileCount; col++) {
      const tile = tiles[row * tileCount + col];
      if (tile !== 0) {
        if (buffer.length > 0 && buffer[buffer.length - 1] === tile && !merged) {
          buffer[buffer.length - 1] *= 2;
          score += buffer[buffer.length - 1];
          merged = true;
        } else {
          buffer.push(tile);
          merged = false;
        }
      }
    }
    for (let col = 0; col < tileCount; col++) {
      tiles[row * tileCount + col] = col < buffer.length ? buffer[col] : 0;
    }
  }
}

function slideRight() {
  for (let row = 0; row < tileCount; row++) {
    let merged = false;
    let buffer = [];
    for (let col = tileCount - 1; col >= 0; col--) {
      const tile = tiles[row * tileCount + col];
      if (tile !== 0) {
        if (buffer.length > 0 && buffer[buffer.length - 1] === tile && !merged) {
          buffer[buffer.length - 1] *= 2;
          score += buffer[buffer.length - 1];
          merged = true;
        } else {
          buffer.push(tile);
          merged = false;
        }
      }
    }
    for (let col = tileCount - 1; col >= 0; col--) {
      tiles[row * tileCount + col] = col < tileCount - buffer.length ? buffer[buffer.length - 1 - (col - (tileCount - buffer.length))] : 0;
    }
  }
}

function slideUp() {
  for (let col = 0; col < tileCount; col++) {
    let merged = false;
    let buffer = [];
    for (let row = 0; row < tileCount; row++) {
      const tile = tiles[row * tileCount + col];
      if (tile !== 0) {
        if (buffer.length > 0 && buffer[buffer.length - 1] === tile && !merged) {
          buffer[buffer.length - 1] *= 2;
          score += buffer[buffer.length - 1];
          merged = true;
        } else {
          buffer.push(tile);
          merged = false;
        }
      }
    }
    for (let row = 0; row < tileCount; row++) {
      tiles[row * tileCount + col] = row < buffer.length ? buffer[row] : 0;
    }
  }
}

function slideDown() {
  for (let col = 0; col < tileCount; col++) {
    let merged = false;
    let buffer = [];
    for (let row = tileCount - 1; row >= 0; row--) {
      const tile = tiles[row * tileCount + col];
      if (tile !== 0) {
        if (buffer.length > 0 && buffer[buffer.length - 1] === tile && !merged) {
          buffer[buffer.length - 1] *= 2;
          score += buffer[buffer.length - 1];
          merged = true;
        } else {
          buffer.push(tile);
          merged = false;
        }
      }
    }
    for (let row = tileCount - 1; row >= 0; row--) {
      tiles[row * tileCount + col] = row < tileCount - buffer.length ? buffer[buffer.length - 1 - (row - (tileCount - buffer.length))] : 0;
    }
  }
}

function checkGameOver() {
  if (tiles.every(tile => tile !== 0)) {
    for (let i = 0; i < tileCount * tileCount; i++) {
      const row = Math.floor(i / tileCount);
      const col = i % tileCount;
      const currentValue = tiles[i];
      if (row > 0 && tiles[(row - 1) * tileCount + col] === currentValue) return false;
      if (row < tileCount - 1 && tiles[(row + 1) * tileCount + col] === currentValue) return false;
      if (col > 0 && tiles[row * tileCount + col - 1] === currentValue) return false;
      if (col < tileCount - 1 && tiles[row * tileCount + col + 1] === currentValue) return false;
    }
    gameOver = true;
  }
}

function update() {
  if (!gameOver && !moveCooldown) {
    let moved = false;
    switch (playerX) {
      case -1:
        slideLeft();
        moved = true;
        break;
      case 1:
        slideRight();
        moved = true;
        break;
      case 0:
        switch (playerY) {
          case -1:
            slideUp();
            moved = true;
            break;
          case 1:
            slideDown();
            moved = true;
            break;
        }
    }
    if (moved) {
      spawnTile();
      checkGameOver();
      moveCooldown = true;
      setTimeout(() => {
        moveCooldown = false;
      }, moveCooldownDuration);
    }
  }
  playerX = 0;
  playerY = 0;
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let row = 0; row < tileCount; row++) {
    for (let col = 0; col < tileCount; col++) {
      drawTile(col, row, tiles[row * tileCount + col]);
    }
  }
  drawHealthBar();
  if (gameOver) {
    drawGameOverScreen();
  }
}

function handleKeyDown(event) {
  if (gameOver && event.key === 'r') {
    resetGame();
  } else if (!moveCooldown) {
    switch (event.key) {
      case 'ArrowLeft':
        playerX = -1;
        break;
      case 'ArrowRight':
        playerX = 1;
        break;
      case 'ArrowUp':
        playerY = -1;
        break;
      case 'ArrowDown':
        playerY = 1;
        break;
    }
  }
}

function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

resizeCanvas();
window.addEventListener('resize', resizeCanvas);
window.addEventListener('keydown', handleKeyDown);
resetGame();
gameLoop();
```

