    return { ...this.prices };
  }

  sellItem(item) {
    if (this.prices[item]) {
      return this.prices[item];
    }
    return null; // Item not found
  }
}

class Reputation {
  constructor() {
    this.standing = {};
  }

  getStanding(faction) {
    return this.standing[faction] || 0;
  }

  adjustStanding(faction, amount) {
    if (!this.standing[faction]) {
      this.standing[faction] = 0;
    }
    this.standing[faction] += amount;
  }
}

class Faction {
  constructor(name) {
    this.name = name;
  }

  getName() {
    return this.name;
  }
}

class Economy {
  constructor() {
    this.inventory = {};
    this.balance = 1000; // Starting balance
  }

  getBalance() {
    return this.balance;
  }

  debit(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  addItem(item) {
    if (!this.inventory[item]) {
      this.inventory[item] = 0;
    }
    this.inventory[item] += 1;
  }
}

class Store {
