  speed: 5,
  respawnDelay: 3000,
  lastRespawn: 0
};

const enemy = {
  health: 50,
  position: { x: 200, y: 300 },
  velocity: { x: 2, y: 0 },
  speed: 3
};

const bullet = {
  position: { x: 0, y: 0 },
  velocity: { x: 0, y: 0 },
  speed: 10,
  active: false
};

const bulletSize = 5;
const playerSize = 20;
const enemySize = 15;

const fixedTimestep = 16; // approximately 60 FPS
