function update(deltaTime) {
  // Player movement
  if (keys['ArrowRight']) player.velocity.x = player.speed;
  else if (keys['ArrowLeft']) player.velocity.x = -player.speed;
  else player.velocity.x = 0;

  if (keys['ArrowDown']) player.velocity.y = player.speed;
  else if (keys['ArrowUp']) player.velocity.y = -player.speed;
  else player.velocity.y = 0;

  player.position.x += player.velocity.x * deltaTime;
  player.position.y += player.velocity.y * deltaTime;

  // Enemy movement
  enemy.position.x += enemy.velocity.x * deltaTime;
  if (enemy.position.x < 0 || enemy.position.x > canvas.width - enemySize) {
    enemy.velocity.x *= -1;
  }

  // Bullet movement
  if (bullet.active) {
    bullet.position.x += bullet.velocity.x * deltaTime;
    bullet.position.y += bullet.velocity.y * deltaTime;
    if (bullet.position.x < 0 || bullet.position.x > canvas.width || bullet.position.y < 0 || bullet.position.y > canvas.height) {
      bullet.active = false;
    }
  }

  // Collision detection
  if (isColliding(player, enemy)) {
    player.health -= 10;
    if (player.health <= 0) {
      player.lastRespawn = performance.now();
      player.health = player.maxHealth;
    }
  }

  if (bullet.active && isColliding(bullet, enemy)) {
    enemy.health -= 10;
    if (enemy.health <= 0) {
      resetEnemy();
    }
    bullet.active = false;
  }

  // Respawn player
  if (performance.now() - player.lastRespawn > player.respawnDelay) {
    player.position = { x: 400, y: 300 };
  }
}

