  ctx.fillStyle = 'blue';
  ctx.fillRect(player.position.x, player.position.y, playerSize, playerSize);

  // Draw enemy
  ctx.fillStyle = 'red';
  ctx.fillRect(enemy.position.x, enemy.position.y, enemySize, enemySize);

  // Draw bullet
  if (bullet.active) {
    ctx.fillStyle = 'black';
    ctx.fillRect(bullet.position.x, bullet.position.y, bulletSize, bulletSize);
  }

  // Draw health bar
  ctx.fillStyle = 'green';
  ctx.fillRect(10, 10, (player.health / player.maxHealth) * 100, 20);
}

function isColliding(obj1, obj2) {
  return obj1.position.x < obj2.position.x + obj2.size &&
         obj1.position.x + obj1.size > obj2.position.x &&
         obj1.position.y < obj2.position.y + obj2.size &&
         obj1.position.y + obj1.size > obj2.position.y;
}

