function createBoard() {
  const numCards = cardImages.length * 2;
  const cardIndices = [];
  for (let i = 0; i < numCards; i++) {
    cardIndices.push(Math.floor(i / 2));
  }
  cardIndices.sort(() => Math.random() - 0.5);

  for (let i = 0; i < numCards; i++) {
    const index = cardIndices[i];
    const x = (i % 8) * (cardWidth + 20) + 50;
    const y = Math.floor(i / 8) * (cardHeight + 20) + 50;
    cards.push({ x, y, index, flipped: false });
  }
}

createBoard();

function flipCard(card) {
  if (flippedCards.length < 2 && !card.flipped) {
    card.flipped = true;
    flippedCards.push(card);
    if (flippedCards.length === 2) {
      setTimeout(checkForMatch, 500);
    }
  }
}

function checkForMatch() {
  const [card1, card2] = flippedCards;
  if (card1.index !== card2.index) {
    card1.flipped = card2.flipped = false;
    health--;
    if (health <= 0) {
      respawnCooldown = 3000;
    }
  } else {
    // Cards match, do nothing (they stay flipped)
  }
  flippedCards = [];
}

function respawn() {
  if (respawnCooldown > 0) {
    respawnCooldown -= 16; // 60 FPS
  } else {
    health = maxHealth;
    flippedCards = [];
    cards.forEach(card => card.flipped = false);
    createBoard();
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  cards.forEach(card => {
    if (card.flipped) {
      ctx.drawImage(images[card.index], card.x, card.y, cardWidth, cardHeight);
