        ctx.fillRect(boardSize * 100, 0, 200, 100);
        ctx.fillStyle = '#776e65';
        ctx.font = '30px Arial';
        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';
        ctx.fillText(`Score: ${score}`, boardSize * 100 + 190, 50);
        ctx.fillText(`High Score: ${highScore}`, boardSize * 100 + 190, 150);
