                }
                for (let i = 0; i < newRow.length - 1; i++) {
                    if (newRow[i] === newRow[i + 1]) {
                        newRow[i] *= 2;
                        newRow[i + 1] = 0;
                        score += newRow[i];
                    }
                }
                newRow = newRow.filter(tile => tile !== 0);
                while (newRow.length < boardSize) {
                    newRow.unshift(0);
                }
                for (let x = boardSize - 1; x >= 0; x--) {
                    if (board[y][x] !== newRow[boardSize - 1 - x]) {
                        board[y][x] = newRow[boardSize - 1 - x];
                        moved = true;
                    }
                }
            }
        }
        if (moved) {
            newTile();
        }
        if (score > highScore) {
            highScore = score;
            localStorage.setItem('2048HighScore', highScore);
        }
    }

    function gameLoop() {
        resizeCanvas();
        drawBoard();
        requestAnimationFrame(gameLoop);
    }

    function resetGame() {
        board = Array(boardSize).fill().map(() => Array(boardSize).fill(0));
        score = 0;
        newTile();
        newTile();
    }

    window.addEventListener('resize', gameLoop);
    window.addEventListener('keydown', (e) => {
        move(e.code);
    });
    window.addEventListener('load', resetGame);
    gameLoop();
})();
