// Asteroids-style space game with wave progression

const canvas = document.createElement('canvas');
const ctx = canvas.getContext('2d');
document.body.appendChild(canvas);
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

const keys = { ArrowUp: false, ArrowLeft: false, ArrowRight: false, Space: false };
window.addEventListener('keydown', (e) => keys[e.key] = true);
window.addEventListener('keyup', (e) => keys[e.key] = false);

const player = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  radius: 10,
  angle: 0,
  thrust: 0.1,
  rotationSpeed: 0.04,
  bullets: [],
  maxBullets: 10
};

const asteroids = [];
const asteroidSpeed = 0.5;
const maxAsteroids = 5;
let wave = 1;

function createAsteroid() {
  const x = Math.random() * canvas.width;
  const y = Math.random() * canvas.height;
  const radius = Math.random() * 15 + 5;
  const angle = Math.random() * Math.PI * 2;
  asteroids.push({ x, y, radius, angle });
}

function spawnAsteroids() {
  for (let i = 0; i < maxAsteroids; i++) {
    createAsteroid();
  }
}

function updatePlayer() {
  if (keys.ArrowUp) {
    player.x += Math.cos(player.angle) * player.thrust;
    player.y += Math.sin(player.angle) * player.thrust;
  }
  if (keys.ArrowLeft) {
    player.angle -= player.rotationSpeed;
  }
  if (keys.ArrowRight) {
    player.angle += player.rotationSpeed;
  }
  if (keys.Space && player.bullets.length < player.maxBullets) {
    player.bullets.push({
      x: player.x,
      y: player.y,
      radius: 2,
      angle: player.angle,
      speed: 5
    });
  }
  player.bullets = player.bullets.filter(bullet => {
    bullet.x += Math.cos(bullet.angle) * bullet.speed;
    bullet.y += Math.sin(bullet.angle) * bullet.speed;
    return bullet.x > 0 && bullet.x < canvas.width && bullet.y > 0 && bullet.y < canvas.height;
  });
}

function updateAsteroids() {
  for (let i = 0; i < asteroids.length; i++) {
    asteroids[i].x += Math.cos(asteroids[i].angle) * asteroidSpeed;
    asteroids[i].y += Math.sin(asteroids[i].angle) * asteroidSpeed;
    if (asteroids[i].x < 0 || asteroids[i].x > canvas.width || asteroids[i].y < 0 || asteroids[i].y > canvas.height) {
      asteroids.splice(i, 1);
      i--;
    }
  }
}

function checkCollisions() {
  for (let i = 0; i < asteroids.length; i++) {
    const asteroid = asteroids[i];
    const dx = asteroid.x - player.x;
    const dy = asteroid.y - player.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    if (distance < asteroid.radius + player.radius) {
      // Collision detected, game over
      alert('Game Over! Your score: ' + (wave - 1));
      resetGame();
    }
  }
}

function drawPlayer() {
  ctx.beginPath();
  ctx.moveTo(player.x, player.y);
  ctx.lineTo(player.x + Math.cos(player.angle) * 20, player.y + Math.sin(player.angle) * 20);
  ctx.lineTo(player.x + Math.cos(player.angle + Math.PI / 3) * 10, player.y + Math.sin(player.angle + Math.PI / 3) * 10);
  ctx.lineTo(player.x + Math.cos(player.angle - Math.PI / 3) * 10, player.y + Math.sin(player.angle - Math.PI / 3) * 10);
  ctx.closePath();
  ctx.fillStyle = 'green';
  ctx.fill();
}

function drawBullets() {
  player.bullets.forEach(bullet => {
    ctx.beginPath();
    ctx.arc(bullet.x, bullet.y, bullet.radius, 0, Math.PI * 2);
    ctx.fillStyle = 'white';
    ctx.fill();
  });
}

function drawAsteroids() {
  asteroids.forEach(asteroid => {
    ctx.beginPath();
    ctx.arc(asteroid.x, asteroid.y, asteroid.radius, 0, Math.PI * 2);
    ctx.fillStyle = 'red';
    ctx.fill();
  });
}

function drawScore() {
  ctx.fillStyle = 'white';
  ctx.font = '24px Arial';
  ctx.fillText('Wave: ' + wave, 10, 30);
}

function resetGame() {
  player.x = canvas.width / 2;
  player.y = canvas.height / 2;
  player.angle = 0;
  player.bullets = [];
  asteroids.length = 0;
  wave = 1;
  spawnAsteroids();
}

function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  updatePlayer();
  updateAsteroids();
  checkCollisions();
  drawPlayer();
  drawBullets();
  drawAsteroids();
  drawScore();
  if (asteroids.length === 0) {
    wave++;
    spawnAsteroids();
  }
  requestAnimationFrame(gameLoop);
}

spawnAsteroids();
gameLoop();
