const jumpVelocity = -10;
const player = { x: 50, y: 50, width: 50, height: 50, velocity: { x: 0, y: 0 }, jumping: false };
const enemy = { x: 300, y: 50, width: 50, height: 50, velocity: { x: -2, y: 0 } };
const platforms = [
    { x: 0, y: canvas.height - 50, width: canvas.width, height: 50 },
    { x: 200, y: canvas.height - 150, width: 200, height: 50 }
];

function drawRect(rect, color) {
    ctx.fillStyle = color;
    ctx.fillRect(rect.x, rect.y, rect.width, rect.height);
}

function updatePlayer() {
    player.velocity.y += gravity;
    player.x += player.velocity.x;
    player.y += player.velocity.y;

    if (player.jumping && player.velocity.y > 0) {
        player.jumping = false;
    }

    platforms.forEach(platform => {
        if (player.x < platform.x + platform.width && player.x + player.width > platform.x &&
            player.y < platform.y + platform.height && player.y + player.height > platform.y) {
            if (player.velocity.y > 0) {
                player.y = platform.y - player.height;
                player.velocity.y = 0;
                player.jumping = false;
            }
        }
    });

    if (player.x + player.width > canvas.width) {
        player.x = canvas.width - player.width;
    } else if (player.x < 0) {
        player.x = 0;
    }
}

function updateEnemy() {
    enemy.x += enemy.velocity.x;

    if (enemy.x < 0 || enemy.x + enemy.width > canvas.width) {
        enemy.velocity.x = -enemy.velocity.x;
    }

    platforms.forEach(platform => {
        if (enemy.x < platform.x + platform.width && enemy.x + enemy.width > platform.x &&
            enemy.y < platform.y + platform.height && enemy.y + enemy.height > platform.y) {
            if (enemy.velocity.y > 0) {
                enemy.y = platform.y - enemy.height;
                enemy.velocity.y = 0;
            }
        }
    });
}

function update() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    updatePlayer();
    updateEnemy();

