// Tile-based roguelike room with wave progression on an HTML5 canvas
// Fixed timestep main loop for deterministic behavior

const canvas = document.createElement('canvas');
const ctx = canvas.getContext('2d');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;

const TILE_SIZE = 32;
const ROOM_WIDTH = 20;
const ROOM_HEIGHT = 15;
const LEVEL_WAVES = 5;

let level = 1;
let wave = 1;
let entities = [];
let lastTime = 0;
let fps = 60;
const dt = 1000 / fps;

function Entity(x, y) {
    this.x = x;
    this.y = y;
    this.width = TILE_SIZE;
    this.height = TILE_SIZE;
    this.color = 'blue';
    this.speed = 2;
    this.update = function() {
        if (Math.random() < 0.5) {
            this.x += this.speed;
        } else {
            this.x -= this.speed;
        }
    };
    this.draw = function() {
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x, this.y, this.width, this.height);
    };
}

function generateWave() {
    entities.length = 0;
    for (let i = 0; i < wave * 10; i++) {
        const x = Math.random() * canvas.width;
        const y = Math.random() * canvas.height;
        entities.push(new Entity(x, y));
    }
}

function update() {
    if (wave > LEVEL_WAVES) {
        level++;
        wave = 1;
        generateWave();
    }
    entities.forEach(entity => entity.update());
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    entities.forEach(entity => entity.draw());
    ctx.fillStyle = 'black';
    ctx.font = '24px Arial';
    ctx.fillText(`Level: ${level}, Wave: ${wave}`, 10, 30);
}

function mainLoop(timestamp) {
    const deltaTime = timestamp - lastTime;
    if (deltaTime >= dt) {
        update();
        render();
        lastTime = timestamp;
    }
    requestAnimationFrame(mainLoop);
}

generateWave();
mainLoop(0);
