// Constants
const CELL_SIZE = 20;
const POWER_UP_INTERVAL = 10000; // 10 seconds

// Game state
let canvas, ctx;
let snake = [{ x: 10, y: 10 }];
let direction = { x: 1, y: 0 };
let food = { x: 15, y: 15 };
let powerUp = null;
let score = 0;
let powerUpTimer;

// Initialize canvas
function initCanvas() {
    canvas = document.createElement('canvas');
    document.body.appendChild(canvas);
    ctx = canvas.getContext('2d');
    const dpr = window.devicePixelRatio;
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    ctx.scale(dpr, dpr);
    canvas.style.width = window.innerWidth + 'px';
    canvas.style.height = window.innerHeight + 'px';
}

// Random position generator
function getRandomPosition() {
    return {
        x: Math.floor(Math.random() * (canvas.width / CELL_SIZE)),
        y: Math.floor(Math.random() * (canvas.height / CELL_SIZE))
    };
}

// Spawn power-up
function spawnPowerUp() {
    powerUp = getRandomPosition();
    powerUpTimer = setTimeout(() => {
        powerUp = null;
    }, POWER_UP_INTERVAL);
}

// Game loop
function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Move snake
    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };
    snake.unshift(head);

    // Check for collisions
    if (head.x === food.x && head.y === food.y) {
        score++;
        food = getRandomPosition();
        if (powerUpTimer) clearTimeout(powerUpTimer);
        spawnPowerUp();
    } else {
        snake.pop();
    }

    // Power-up collision
    if (powerUp && head.x === powerUp.x && head.y === powerUp.y) {
        score += 5;
        powerUp = null;
        clearTimeout(powerUpTimer);
    }

    // Draw snake
    ctx.fillStyle = 'green';
    snake.forEach(segment => {
        ctx.fillRect(segment.x * CELL_SIZE, segment.y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
    });

    // Draw food
    ctx.fillStyle = 'red';
    ctx.fillRect(food.x * CELL_SIZE, food.y * CELL_SIZE, CELL_SIZE, CELL_SIZE);

    // Draw power-up
    if (powerUp) {
        ctx.fillStyle = 'blue';
        ctx.fillRect(powerUp.x * CELL_SIZE, powerUp.y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
    }

    // Draw score
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);

    requestAnimationFrame(gameLoop);
}

// Change direction
function changeDirection(event) {
    const keyPressed = event.key;
    const goingUp = direction.y === -1;
    const goingDown = direction.y === 1;
    const goingRight = direction.x === 1;
    const goingLeft = direction.x === -1;

    if (keyPressed === 'ArrowUp' && !goingDown) {
        direction = { x: 0, y: -1 };
    }
    if (keyPressed === 'ArrowDown' && !goingUp) {
        direction = { x: 0, y: 1 };
    }
    if (keyPressed === 'ArrowRight' && !goingLeft) {
        direction = { x: 1, y: 0 };
    }
    if (keyPressed === 'ArrowLeft' && !goingRight) {
        direction = { x: -1, y: 0 };
    }
}

// Start game
initCanvas();
spawnPowerUp();
document.addEventListener('keydown', changeDirection);
gameLoop();
