        this.points += amount;
    }

    getRequiredPointsForNextLevel(currentLevel) {
        return currentLevel * 100; // Simplified formula
    }
}

class LevelUp {
    constructor(experienceSystem, skillSystem) {
        this.experienceSystem = experienceSystem;
        this.skillSystem = skillSystem;
    }

