// Economy system
class Economy {
    constructor(prices) {
        this.prices = prices; // { itemName: price }
        this.balance = 1000; // Starting balance
    }

    getBalance() {
        return this.balance;
    }

    debit(price) {
        if (this.balance >= price) {
            this.balance -= price;
            return true;
        }
        return false;
    }

    getItemPrice(itemName) {
        return this.prices[itemName] || 0;
    }
}

// Wallet system
class Wallet {
    constructor(economy) {
        this.economy = economy;
    }

    getBalance() {
        return this.economy.getBalance();
    }

    canAfford(itemName) {
        const price = this.economy.getItemPrice(itemName);
        return this.economy.getBalance() >= price;
    }

    purchase(itemName) {
        const price = this.economy.getItemPrice(itemName);
        if (this.economy.debit(price)) {
            return true;
        }
        return false;
    }
}

// Inventory system
class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(itemName) {
        if (this.items[itemName]) {
            this.items[itemName]++;
        } else {
            this.items[itemName] = 1;
        }
    }

    getInventory() {
        return this.items;
    }
}

// Shop system
class Shop {
    constructor(wallet, inventory) {
        this.wallet = wallet;
        this.inventory = inventory;
    }

    purchaseItem(itemName) {
        if (this.wallet.canAfford(itemName)) {
            if (this.wallet.purchase(itemName)) {
                this.inventory.addItem(itemName);
                return true;
            }
        }
        return false;
    }
}

