let lastTime = 0;

function Ball(x, y) {
  this.x = x;
  this.y = y;
  this.vx = Math.random() * 5 - 2.5;
  this.vy = -5 - Math.random() * 2;
}

Ball.prototype.update = function() {
  this.vx += WIND;
  this.vy += GRAVITY;
  this.x += this.vx;
  this.y += this.vy;

  if (this.y + BALL_RADIUS > canvas.height) {
    this.y = canvas.height - BALL_RADIUS;
    this.vy *= -0.8;
  }

  if (this.x - BALL_RADIUS < 0 || this.x + BALL_RADIUS > canvas.width) {
    this.vx *= -1;
  }
};

Ball.prototype.draw = function() {
  ctx.beginPath();
  ctx.arc(this.x, this.y, BALL_RADIUS, 0, Math.PI * 2);
  ctx.fillStyle = `hsl(${level * 30}, 100%, 50%)`;
  ctx.fill();
  ctx.closePath();
};

function spawnBalls() {
  for (let i = 0; i < INITIAL_BALL_COUNT; i++) {
    balls.push(new Ball(canvas.width / 2, 50));
  }
}

function update() {
  const now = Date.now();
  const dt = (now - lastTime) / 1000;
  const steps = Math.floor(dt / TIME_STEP);
  lastTime = now;

  for (let i = 0; i < steps; i++) {
    balls.forEach(ball => ball.update());
    if (balls.length < LEVEL_CHANGE_THRESHOLD) {
      spawnBalls();
      level++;
    }
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  balls.forEach(ball => ball.draw());
  ctx.fillStyle = '#000';
  ctx.fillText(`Level: ${level}`, 10, 20);
}

function gameLoop() {
  update();
  render();
  requestAnimationFrame(gameLoop);
}

