const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

class Player {
    constructor() {
        this.x = canvas.width / 2;
        this.y = canvas.height / 2;
        this.radius = 10;
        this.color = 'blue';
        this.speed = 5;
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.fill();
        ctx.closePath();
    }

    move(dx, dy) {
        this.x += dx;
        this.y += dy;
    }
}

class Enemy {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.radius = 8;
        this.color = 'red';
        this.speed = 2;
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.fill();
        ctx.closePath();
    }

    moveTowardsPlayer(player) {
        const dx = player.x - this.x;
        const dy = player.y - this.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist > 0) {
            this.x += (dx / dist) * this.speed;
            this.y += (dy / dist) * this.speed;
        }
    }
}

class Game {
    constructor() {
        this.player = new Player();
        this.enemies = [];
        this.enemySpawnRate = 1000; // milliseconds
        this.difficultyMultiplier = 1;
        this.lastSpawnTime = performance.now();
        this.deltaTime = 0;
        this.lastTime = performance.now();
    }

    spawnEnemy() {
        const x = Math.random() * canvas.width;
        const y = Math.random() * canvas.height;
        this.enemies.push(new Enemy(x, y));
    }

    update() {
        const now = performance.now();
        this.deltaTime += (now - this.lastTime) / 1000;
        this.lastTime = now;

        if (this.deltaTime >= 1) {
            this.difficultyMultiplier += 0.1;
            this.deltaTime = 0;
        }

        if (now - this.lastSpawnTime > this.enemySpawnRate / this.difficultyMultiplier) {
            this.spawnEnemy();
            this.lastSpawnTime = now;
        }

        this.enemies.forEach(enemy => enemy.moveTowardsPlayer(this.player));
    }

    draw() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        this.player.draw();
        this.enemies.forEach(enemy => enemy.draw());
    }

    run() {
        this.update();
        this.draw();
        requestAnimationFrame(() => this.run());
    }
}

const game = new Game();
game.run();

document.addEventListener('keydown', (e) => {
    const speed = game.player.speed;
    switch (e.key) {
        case 'ArrowUp':
            game.player.move(0, -speed);
            break;
        case 'ArrowDown':
            game.player.move(0, speed);
            break;
        case 'ArrowLeft':
            game.player.move(-speed, 0);
            break;
        case 'ArrowRight':
            game.player.move(speed, 0);
            break;
    }
});
