class Quest {
    constructor() {
        this._currentQuest = null;
    }

    startQuest(questName) {
        this._currentQuest = questName;
        console.log(`Started quest: ${questName}`);
    }

    completeQuest() {
        if (this._currentQuest) {
            console.log(`Completed quest: ${this._currentQuest}`);
            this._currentQuest = null;
            return true;
        } else {
            console.log("No quest to complete.");
            return false;
        }
    }

    getCurrentQuest() {
        return this._currentQuest;
    }
}

class Reward {
    constructor() {
        this._rewards = [];
    }

    grantReward(reward) {
        this._rewards.push(reward);
        console.log(`Granted reward: ${reward}`);
    }

    collectRewards() {
        if (this._rewards.length > 0) {
            const collected = this._rewards.slice();
            this._rewards = [];
            console.log(`Collected rewards: ${collected.join(', ')}`);
            return collected;
        } else {
            console.log("No rewards to collect.");
            return [];
        }
    }

    getAvailableRewards() {
        return this._rewards.slice();
    }
}

class Inventory {
    constructor() {
        this._items = {};
    }

    addItem(item, quantity = 1) {
        if (this._items[item]) {
            this._items[item] += quantity;
        } else {
            this._items[item] = quantity;
        }
        console.log(`Added ${quantity}x ${item} to inventory.`);
    }

    useItem(item, quantity = 1) {
        if (this._items[item] && this._items[item] >= quantity) {
            this._items[item] -= quantity;
            if (this._items[item] === 0) {
                delete this._items[item];
            }
            console.log(`Used ${quantity}x ${item}.`);
            return true;
        } else {
            console.log(`Not enough ${item} in inventory.`);
            return false;
        }
    }

    getInventory() {
        return { ...this._items };
    }
}

class GameCoordinator {
    constructor() {
        this._questSystem = new Quest();
        this._rewardSystem = new Reward();
        this._inventorySystem = new Inventory();
    }

    startNewQuest(questName) {
        this._questSystem.startQuest(questName);
    }

    completeCurrentQuest() {
        if (this._questSystem.completeQuest()) {
            this._rewardSystem.grantReward("Experience Points");
            this._rewardSystem.grantReward("Gold");
        }
    }

    collectRewards() {
        return this._rewardSystem.collectRewards();
    }

    addItemToInventory(item, quantity) {
        this._inventorySystem.addItem(item, quantity);
    }

    useItemFromInventory(item, quantity) {
        this._inventorySystem.useItem(item, quantity);
    }

    getCurrentQuest() {
        return this._questSystem.getCurrentQuest();
    }

    getInventory() {
        return this._inventorySystem.getInventory();
    }
}

