// HTML5 Canvas Endless Runner Game

const canvas = document.createElement('canvas');
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const player = {
  x: 50,
  y: canvas.height / 2,
  width: 20,
  height: 20,
  speed: 5,
  dy: 0,
  gravity: 0.5,
  jumpPower: -10,
  isJumping: false
};

const enemies = [];
const spawnRate = 100; // Higher = slower spawn rate
let lastSpawnTime = 0;
let difficulty = 1;

function spawnEnemy() {
  const enemy = {
    x: canvas.width,
    y: canvas.height - 50,
    width: 30,
    height: 30,
    speed: 3 + difficulty * 0.5
  };
  enemies.push(enemy);
}

function update() {
  if (Date.now() - lastSpawnTime > spawnRate) {
    spawnEnemy();
    lastSpawnTime = Date.now();
    difficulty += 0.01; // Increase difficulty over time
  }

  // Player movement
  if (player.isJumping) {
    player.dy += player.gravity;
    player.y += player.dy;
    if (player.y + player.height > canvas.height) {
      player.y = canvas.height - player.height;
      player.isJumping = false;
      player.dy = 0;
    }
  }

  // Enemy movement
  enemies.forEach((enemy, index) => {
    enemy.x -= enemy.speed;
    if (enemy.x + enemy.width < 0) {
      enemies.splice(index, 1);
    }
  });

  // Collision detection
  enemies.forEach(enemy => {
    if (player.x < enemy.x + enemy.width &&
        player.x + player.width > enemy.x &&
        player.y < enemy.y + enemy.height &&
        player.y + player.height > enemy.y) {
      alert('Game Over!');
      document.location.reload(); // Reload the page to restart
    }
  });
}

function draw() {
  // Clear canvas
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw player
  ctx.fillStyle = 'blue';
  ctx.fillRect(player.x, player.y, player.width, player.height);

  // Draw enemies
  ctx.fillStyle = 'red';
  enemies.forEach(enemy => {
    ctx.fillRect(enemy.x, enemy.y, enemy.width, enemy.height);
  });

  // Draw ground
  ctx.fillStyle = 'green';
  ctx.fillRect(0, canvas.height - 50, canvas.width, 50);
}

function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

// Handle jump input
window.addEventListener('keydown', e => {
  if (e.code === 'Space' && !player.isJumping) {
    player.isJumping = true;
    player.dy = player.jumpPower;
  }
});

// Start the game loop
gameLoop();
