        this.x = x;
        this.y = y;
        this.width = width;
        this.height = height;
    }
    draw() {
        ctx.fillStyle = 'green';
        ctx.fillRect(this.x, this.y, this.width, this.height);
    }
}

const player = new Player();
const platforms = [
    new Platform(100, canvas.height - 60, 200, 20),
    new Platform(400, canvas.height - 160, 200, 20),
    new Platform(700, canvas.height - 260, 200, 20)
];
let gameOver = false;

function checkCollision(player, platform) {
    const playerBottom = player.y + player.height;
    const platformTop = platform.y;
    const playerTop = player.y;
    const platformBottom = platform.y + platform.height;
    const playerRight = player.x + player.width;
    const platformLeft = platform.x;
    const platformRight = platform.x + platform.width;

    const verticalCollide = playerBottom >= platformTop && playerTop <= platformBottom;
    const horizontalCollide = playerRight >= platformLeft && player.x <= platformRight;

    return verticalCollide && horizontalCollide;
}

function update() {
    if (gameOver) return;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    player.update();
    platforms.forEach(platform => {
        platform.draw();
        if (checkCollision(player, platform)) {
            player.velocityY = 0;
            player.onGround = true;
            player.y = platform.y - player.height;
        }
    });
    player.draw();
    ctx.fillStyle = 'black';
    ctx.fillText(`Score: ${player.score}`, 10, 30);

    if (player.y > canvas.height) {
        gameOver = true;
        ctx.fillStyle = 'red';
        ctx.font = '48px Arial';
        ctx.fillText('Game Over', canvas.width / 4, canvas.height / 2);
    }

    requestAnimationFrame(update);
}

update();

window.addEventListener('keydown', (e) => {
    if (e.code === 'Space') {
        player.jump();
    }
