// Fishing Mini-Game with Collectible Power-Ups

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.style.width = '100vw';
canvas.style.height = '100vh';
canvas.width = canvas.clientWidth * devicePixelRatio;
canvas.height = canvas.clientHeight * devicePixelRatio;
const ctx = canvas.getContext('2d');

class Fish {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.size = 20;
    this.speed = Math.random() * 2 + 1;
    this.direction = Math.random() > 0.5 ? 1 : -1;
  }

  draw() {
    ctx.fillStyle = 'blue';
    ctx.fillRect(this.x, this.y, this.size, this.size);
  }

  update() {
    this.x += this.direction * this.speed;
    if (this.x + this.size < 0 || this.x > canvas.width) {
      this.direction *= -1;
    }
  }
}

class PowerUp {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.size = 10;
    this.collected = false;
  }

  draw() {
    if (!this.collected) {
      ctx.fillStyle = 'red';
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  collect() {
    this.collected = true;
  }
}

const fish = new Fish(canvas.width / 2, canvas.height / 2);
const powerUp = new PowerUp(canvas.width / 4, canvas.height / 4);

let score = 0;
let powerUpActive = false;
let powerUpTimer = 0;

function handleInput(event) {
  if (event.key === ' ') {
    if (powerUpActive) {
      score += 10;
      fish.size += 5;
    } else if (Math.abs(fish.x - powerUp.x) < fish.size + powerUp.size && Math.abs(fish.y - powerUp.y) < fish.size + powerUp.size) {
      powerUp.collect();
      powerUpActive = true;
      powerUpTimer = 100;
    }
  }
}

function update() {
  fish.update();
  if (powerUpActive) {
    powerUpTimer--;
    if (powerUpTimer <= 0) {
      powerUpActive = false;
      fish.size = 20;
    }
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  fish.draw();
