const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
let tileSize = 64;
let grid = Array.from({ length: 4 }, () => Array(4).fill(0));
let score = 0;

function setup() {
  const dpr = window.devicePixelRatio;
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  canvas.style.width = `${window.innerWidth}px`;
  canvas.style.height = `${window.innerHeight}px`;
  tileSize = Math.floor(canvas.width / 4);
  ctx.scale(dpr, dpr);
  resetGame();
}

function resetGame() {
  grid = Array.from({ length: 4 }, () => Array(4).fill(0));
  addRandomTile();
  addRandomTile();
  render();
}

function addRandomTile() {
  const emptyCells = [];
  for (let i = 0; i < 4; i++) {
    for (let j = 0; j < 4; j++) {
      if (grid[i][j] === 0) {
        emptyCells.push({ i, j });
      }
    }
  }
  if (emptyCells.length > 0) {
    const { i, j } = emptyCells[Math.floor(Math.random() * emptyCells.length)];
    grid[i][j] = Math.random() < 0.9 ? 2 : 4;
  }
}

function slide(row) {
  const filtered = row.filter(num => num !== 0);
  for (let i = 0; i < filtered.length - 1; i++) {
    if (filtered[i] === filtered[i + 1]) {
      filtered[i] *= 2;
      score += filtered[i];
      filtered.splice(i + 1, 1);
    }
  }
  return filtered.concat(Array(4 - filtered.length).fill(0));
}

function move(direction) {
  let moved = false;
  if (direction === 'up') {
    for (let j = 0; j < 4; j++) {
      const column = [grid[0][j], grid[1][j], grid[2][j], grid[3][j]];
      const newColumn = slide(column);
      if (JSON.stringify(column) !== JSON.stringify(newColumn)) {
        moved = true;
        for (let i = 0; i < 4; i++) {
          grid[i][j] = newColumn[i];
        }
      }
    }
  } else if (direction === 'down') {
    for (let j = 0; j < 4; j++) {
      const column = [grid[3][j], grid[2][j], grid[1][j], grid[0][j]];
      const newColumn = slide(column);
      if (JSON.stringify(column) !== JSON.stringify(newColumn)) {
        moved = true;
        for (let i = 0; i < 4; i++) {
          grid[3 - i][j] = newColumn[i];
        }
      }
    }
  } else if (direction === 'left') {
    for (let i = 0; i < 4; i++) {
      const newRow = slide(grid[i]);
      if (JSON.stringify(grid[i]) !== JSON.stringify(newRow)) {
        moved = true;
        grid[i] = newRow;
      }
    }
  } else if (direction === 'right') {
    for (let i = 0; i < 4; i++) {
      const newRow = slide(grid[i].slice().reverse()).reverse();
      if (JSON.stringify(grid[i]) !== JSON.stringify(newRow)) {
        moved = true;
        grid[i] = newRow;
      }
    }
  }
  if (moved) {
    addRandomTile();
    checkGameOver();
  }
}

function checkGameOver() {
  let hasEmpty = false;
  for (let i = 0; i < 4; i++) {
    for (let j = 0; j < 4; j++) {
      if (grid[i][j] === 0) {
        hasEmpty = true;
      }
      if (i < 3 && grid[i][j] === grid[i + 1][j] ||
          j < 3 && grid[i][j] === grid[i][j + 1]) {
        return;
      }
    }
  }
  if (!hasEmpty) {
    alert(`Game Over! Your score: ${score}`);
    resetGame();
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let i = 0; i < 4; i++) {
    for (let j = 0; j < 4; j++) {
      const value = grid[i][j];
      ctx.fillStyle = value === 0 ? '#ccc' : `hsl(${15 * Math.log2(value)}, 100%, 50%)`;
      ctx.fillRect(j * tileSize, i * tileSize, tileSize, tileSize);
      ctx.fillStyle = '#fff';
      ctx.font = '32px Arial';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      if (value !== 0) {
        ctx.fillText(value, j * tileSize + tileSize / 2, i * tileSize + tileSize / 2);
      }
    }
  }
}

function handleKey(e) {
  switch (e.key) {
    case 'ArrowUp':
      move('up');
      break;
    case 'ArrowDown':
      move('down');
      break;
    case 'ArrowLeft':
      move('left');
      break;
    case 'ArrowRight':
      move('right');
      break;
    case 'r':
      resetGame();
      break;
  }
}

window.addEventListener('resize', setup);
window.addEventListener('keydown', handleKey);
setup();
