const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let width = window.innerWidth;
let height = window.innerHeight;
const ratio = window.devicePixelRatio;

canvas.width = width * ratio;
canvas.height = height * ratio;
canvas.style.width = `${width}px`;
canvas.style.height = `${height}px`;

ctx.scale(ratio, ratio);

let fishX = width / 2;
let fishY = height / 2;
let fishSize = 50;
let fishSpeed = 2;

let timer = 60;
let timerInterval;
let score = 0;

function drawFish() {
    ctx.fillStyle = 'gold';
    ctx.beginPath();
    ctx.ellipse(fishX, fishY, fishSize, fishSize * 0.5, Math.PI / 4, 0, 2 * Math.PI);
    ctx.fill();
}

function drawScore() {
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
}

function drawTimer() {
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Time: ${timer}`, width - 100, 30);
}

function update() {
    ctx.clearRect(0, 0, width, height);

    fishX += fishSpeed;
    if (fishX + fishSize > width || fishX - fishSize < 0) {
        fishSpeed *= -1;
    }

    if (isFished()) {
        score++;
        resetFish();
    }

    drawFish();
    drawScore();
    drawTimer();
}

function isFished() {
    const rect = canvas.getBoundingClientRect();
    const mouseX = (event.clientX - rect.left) * ratio;
    const mouseY = (event.clientY - rect.top) * ratio;
    const distance = Math.sqrt((mouseX - fishX) ** 2 + (mouseY - fishY) ** 2);
    return distance < fishSize;
}

function resetFish() {
    fishX = width / 2;
    fishY = height / 2;
}

function startTimer() {
    timerInterval = setInterval(() => {
        timer--;
        if (timer <= 0) {
            clearInterval(timerInterval);
            alert(`Game Over! Your score: ${score}`);
            location.reload();
        }
    }, 1000);
}

canvas.addEventListener('click', () => {
    if (isFished()) {
        score++;
        resetFish();
    }
});

canvas.addEventListener('mousemove', (event) => {
    const rect = canvas.getBoundingClientRect();
    const mouseX = (event.clientX - rect.left) * ratio;
    const mouseY = (event.clientY - rect.top) * ratio;
    ctx.fillStyle = 'red';
    ctx.beginPath();
    ctx.arc(mouseX, mouseY, 5, 0, 2 * Math.PI);
    ctx.fill();
});

startTimer();
