typingArea.style.position = 'absolute';
typingArea.style.top = '10px';
typingArea.style.left = '10px';
typingArea.style.width = '300px';
typingArea.style.height = '100px';
document.body.appendChild(typingArea);

let startTime, endTime, wordCount;
let isGameActive = false;
const words = ['hello', 'world', 'javascript', 'canvas', 'requestAnimationFrame'];

function randomWord() {
    return words[Math.floor(Math.random() * words.length)];
}

function startGame() {
    isGameActive = true;
    wordCount = 0;
    startTime = Date.now();
    endTime = startTime + 10000; // 10 seconds
    nextWord();
}

function nextWord() {
    typingArea.value = '';
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.font = '30px Arial';
    ctx.fillText(randomWord(), canvas.width / 2 - 100, canvas.height / 2);
}

function endGame() {
    isGameActive = false;
    alert(`Game Over! Your typing speed was ${wordCount / (endTime - startTime) * 60000} words per minute.`);
}

function gameLoop() {
    if (!isGameActive) return;
    const now = Date.now();
    const timeLeft = (endTime - now) / 1000;
    if (timeLeft <= 0) {
        endGame();
        return;
    }
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.font = '30px Arial';
    ctx.fillText(`Time Left: ${timeLeft.toFixed(2)}`, 10, 50);
    requestAnimationFrame(gameLoop);
}

typingArea.addEventListener('input', () => {
    if (!isGameActive) return;
    const word = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
    if (word) {
        const typedWord = typingArea.value.trim();
        if (typedWord === randomWord()) {
            wordCount++;
            nextWord();
        }
    }
});

document.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && !isGameActive) {
        startGame();
        gameLoop();
    }
});
