class Economy {
  constructor() {
    this.balance = 100;
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    this.balance += amount;
  }

  withdraw(amount) {
    if (amount <= this.balance) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Store {
  constructor(prices) {
    this.prices = prices;
  }

  getPrices() {
    return { ...this.prices };
  }

  getItemPrice(item) {
    return this.prices[item];
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  getItems() {
    return { ...this.items };
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }
}

class GameCoordinator {
  constructor() {
    this.economy = new Economy();
    this.store = new Store({ sword: 50, shield: 30, potion: 20 });
    this.inventory = new Inventory();
  }

  buyItem(item) {
    const price = this.store.getItemPrice(item);
    if (price !== undefined && this.economy.withdraw(price)) {
      this.inventory.addItem(item);
      console.log(`Bought ${item}. Remaining balance: ${this.economy.getBalance()}`);
      return true;
    }
    console.log(`Failed to buy ${item}. Insufficient funds or item not available.`);
    return false;
  }

  sellItem(item) {
    const price = this.store.getItemPrice(item);
    if (price !== undefined && this.inventory.removeItem(item)) {
      this.economy.deposit(price);
      console.log(`Sold ${item}. New balance: ${this.economy.getBalance()}`);
      return true;
    }
    console.log(`Failed to sell ${item}. Item not in inventory.`);
    return false;
  }

  displayStatus() {
    console.log('Economy Balance:', this.economy.getBalance());
    console.log('Store Prices:', this.store.getPrices());
    console.log('Inventory Items:', this.inventory.getItems());
  }
}

