const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
let dpr = window.devicePixelRatio || 1;
canvas.width = window.innerWidth * dpr;
canvas.height = window.innerHeight * dpr;
ctx.scale(dpr, dpr);

const gravity = 0.5;
const birdSize = 20;
const gapSize = 100;
const pipeWidth = 50;
const pipeSpeed = 3;
const jumpStrength = -10;

let birdY = canvas.height / 2;
let birdVelocity = 0;
let pipes = [];
let score = 0;
let state = 'menu';

function setState(newState) {
    state = newState;
    if (newState === 'playing') {
        birdY = canvas.height / 2;
        birdVelocity = 0;
        pipes = [];
        score = 0;
    }
}

function drawRect(x, y, width, height, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x, y, width, height);
}

function drawText(text, x, y, color) {
    ctx.fillStyle = color;
    ctx.font = '20px Arial';
    ctx.fillText(text, x, y);
}

function update() {
    if (state === 'playing') {
        birdVelocity += gravity;
        birdY += birdVelocity;

        if (birdY + birdSize > canvas.height || birdY < 0) {
            setState('gameover');
        }

        pipes.forEach(pipe => {
            pipe.x -= pipeSpeed;
            if (pipe.x < -pipeWidth) {
                pipes.shift();
                score++;
            }
            if (birdY < pipe.y + pipeWidth || birdY + birdSize > pipe.y + pipeWidth + gapSize) {
                if (birdX + birdSize > pipe.x && birdX < pipe.x + pipeWidth) {
                    setState('gameover');
                }
            }
        });

        if (Math.random() < 0.02) {
            pipes.push({
                x: canvas.width,
                y: Math.random() * (canvas.height - gapSize - pipeWidth)
            });
        }
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (state === 'menu') {
        drawText('Press space to start', canvas.width / 2 - 100, canvas.height / 2, 'black');
    } else if (state === 'playing' || state === 'gameover') {
        drawRect(birdX, birdY, birdSize, birdSize, 'yellow');

        pipes.forEach(pipe => {
            drawRect(pipe.x, 0, pipeWidth, pipe.y + pipeWidth, 'green');
            drawRect(pipe.x, pipe.y + pipeWidth + gapSize, pipeWidth, canvas.height - pipe.y - pipeWidth - gapSize, 'green');
        });

        drawText(`Score: ${score}`, 10, 30, 'black');
    }

    if (state === 'gameover') {
        drawText('Game Over', canvas.width / 2 - 60, canvas.height / 2, 'red');
        drawText('Press space to restart', canvas.width / 2 - 100, canvas.height / 2 + 30, 'black');
    }
}

function gameLoop() {
    update();
    draw();
    requestAnimationFrame(gameLoop);
}

canvas.addEventListener('keydown', (e) => {
    if (e.code === 'Space') {
        if (state === 'menu' || state === 'gameover') {
            setState('playing');
        } else if (state === 'playing') {
            birdVelocity = jumpStrength;
        }
    }
});

let birdX = canvas.width / 4;
gameLoop();
