// Tile-based Roguelike Room with High Score
const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const TILE_SIZE = 32;
const ROOM_WIDTH = 20;
const ROOM_HEIGHT = 15;
const player = { x: 0, y: 0 };
const tiles = [];
const enemies = [];

for (let y = 0; y < ROOM_HEIGHT; y++) {
    for (let x = 0; x < ROOM_WIDTH; x++) {
        tiles.push({ x, y, type: Math.random() < 0.8 ? 'floor' : 'wall' });
    }
}

function drawTile(x, y, type) {
    ctx.fillStyle = type === 'floor' ? '#000' : '#fff';
    ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
}

function drawPlayer(x, y) {
    ctx.fillStyle = '#f00';
    ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
}

function update() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    tiles.forEach(tile => drawTile(tile.x, tile.y, tile.type));
    drawPlayer(player.x, player.y);
}

function saveHighScore(score) {
    localStorage.setItem('highScore', score);
}

function getHighScore() {
    return localStorage.getItem('highScore') || 0;
}

function gameLoop() {
    update();
    requestAnimationFrame(gameLoop);
}

gameLoop();

document.addEventListener('keydown', (e) => {
    switch (e.key) {
        case 'ArrowUp':
            if (player.y > 0 && tiles.find(t => t.x === player.x && t.y === player.y - 1).type === 'floor') {
                player.y--;
            }
            break;
        case 'ArrowDown':
            if (player.y < ROOM_HEIGHT - 1 && tiles.find(t => t.x === player.x && t.y === player.y + 1).type === 'floor') {
                player.y++;
            }
            break;
        case 'ArrowLeft':
            if (player.x > 0 && tiles.find(t => t.x === player.x - 1 && t.y === player.y).type === 'floor') {
                player.x--;
            }
            break;
        case 'ArrowRight':
            if (player.x < ROOM_WIDTH - 1 && tiles.find(t => t.x === player.x + 1 && t.y === player.y).type === 'floor') {
                player.x++;
            }
            break;
    }
});
