const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
const ctx = canvas.getContext('2d');

const player = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  radius: 10,
  speed: 5,
  angle: 0,
  dx: 0,
  dy: 0
};

const keys = {
  up: false,
  left: false,
  right: false
};

const asteroids = [];
const bullets = [];
const enemies = [];

const asteroidSpeed = 1;
const maxAsteroids = 10;
const enemySpeed = 2;
const maxEnemies = 3;
let enemySpawnRate = 2000; // milliseconds
let lastEnemySpawn = Date.now();

function getRandom(min, max) {
  return Math.random() * (max - min) + min;
}

function createAsteroid() {
  if (asteroids.length < maxAsteroids) {
    asteroids.push({
      x: getRandom(0, canvas.width),
      y: getRandom(0, canvas.height),
      radius: getRandom(10, 30),
      angle: getRandom(0, Math.PI * 2),
      speed: asteroidSpeed + getRandom(0, 1)
    });
  }
}

function createEnemy() {
  if (enemies.length < maxEnemies) {
    enemies.push({
      x: getRandom(0, canvas.width),
      y: getRandom(0, canvas.height),
      radius: 20,
      angle: getRandom(0, Math.PI * 2),
      speed: enemySpeed
    });
  }
}

function updatePlayer() {
  if (keys.up) {
    player.dx = player.speed * Math.cos(player.angle);
    player.dy = player.speed * Math.sin(player.angle);
  } else {
    player.dx = 0;
    player.dy = 0;
  }

  if (keys.left) {
    player.angle -= 0.05;
  }
  if (keys.right) {
    player.angle += 0.05;
  }

  player.x += player.dx;
  player.y += player.dy;

  if (player.x < 0) player.x = canvas.width;
  if (player.x > canvas.width) player.x = 0;
  if (player.y < 0) player.y = canvas.height;
  if (player.y > canvas.height) player.y = 0;
}

function updateAsteroids() {
  asteroids.forEach((asteroid, index) => {
    asteroid.x += asteroid.speed * Math.cos(asteroid.angle);
    asteroid.y += asteroid.speed * Math.sin(asteroid.angle);

    if (asteroid.x < 0) asteroid.x = canvas.width;
    if (asteroid.x > canvas.width) asteroid.x = 0;
    if (asteroid.y < 0) asteroid.y = canvas.height;
    if (asteroid.y > canvas.height) asteroid.y = 0;
  });
}

function updateEnemies() {
  if (Date.now() - lastEnemySpawn > enemySpawnRate) {
    createEnemy();
    lastEnemySpawn = Date.now();
  }

  enemies.forEach((enemy, index) => {
    enemy.x += enemy.speed * Math.cos(enemy.angle);
    enemy.y += enemy.speed * Math.sin(enemy.angle);

    if (enemy.x < 0) enemy.x = canvas.width;
    if (enemy.x > canvas.width) enemy.x = 0;
    if (enemy.y < 0) enemy.y = canvas.height;
    if (enemy.y > canvas.height) enemy.y = 0;
  });
}

function updateBullets() {
  bullets.forEach((bullet, index) => {
    bullet.x += bullet.speed * Math.cos(bullet.angle);
    bullet.y += bullet.speed * Math.sin(bullet.angle);

    if (bullet.x < 0 || bullet.x > canvas.width || bullet.y < 0 || bullet.y > canvas.height) {
      bullets.splice(index, 1);
    }
  });
}

function checkCollisions() {
  asteroids.forEach((asteroid, aIndex) => {
    bullets.forEach((bullet, bIndex) => {
      const distance = Math.sqrt(Math.pow(asteroid.x - bullet.x, 2) + Math.pow(asteroid.y - bullet.y, 2));
      if (distance < asteroid.radius + bullet.radius) {
        asteroids.splice(aIndex, 1);
        bullets.splice(bIndex, 1);
      }
    });
  });

  enemies.forEach((enemy, eIndex) => {
    bullets.forEach((bullet, bIndex) => {
      const distance = Math.sqrt(Math.pow(enemy.x - bullet.x, 2) + Math.pow(enemy.y - bullet.y, 2));
      if (distance < enemy.radius + bullet.radius) {
        enemies.splice(eIndex, 1);
        bullets.splice(bIndex, 1);
      }
    });
  });

  enemies.forEach((enemy, eIndex) => {
    const distance = Math.sqrt(Math.pow(enemy.x - player.x, 2) + Math.pow(enemy.y - player.y, 2));
    if (distance < enemy.radius + player.radius) {
      alert('Game Over!');
      resetGame();
    }
  });
}

function resetGame() {
  player.x = canvas.width / 2;
  player.y = canvas.height / 2;
  asteroids.length = 0;
  enemies.length = 0;
  bullets.length = 0;
  enemySpawnRate = 2000;
  lastEnemySpawn = Date.now();
}

function drawPlayer() {
  ctx.beginPath();
  ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
  ctx.fillStyle = 'blue';
  ctx.fill();
  ctx.closePath();
}

function drawAsteroids() {
  asteroids.forEach(asteroid => {
    ctx.beginPath();
    ctx.arc(asteroid.x, asteroid.y, asteroid.radius, 0, Math.PI * 2);
    ctx.fillStyle = 'red';
    ctx.fill();
    ctx.closePath();
  });
}

function drawEnemies() {
  enemies.forEach(enemy => {
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, enemy.radius, 0, Math.PI * 2);
    ctx.fillStyle = 'green';
    ctx.fill();
    ctx.closePath();
  });
}

function drawBullets() {
  bullets.forEach(bullet => {
    ctx.beginPath();
    ctx.arc(bullet.x, bullet.y, 2, 0, Math.PI * 2);
    ctx.fillStyle = 'yellow';
    ctx.fill();
    ctx.closePath();
  });
}

function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  updatePlayer();
  updateAsteroids();
  updateEnemies();
  updateBullets();
  checkCollisions();

  drawPlayer();
  drawAsteroids();
  drawEnemies();
  drawBullets();

  requestAnimationFrame(gameLoop);
}

