let level = 1;
let targetWPM = 20;
let wordsPerLevel = 10;
let wordsTyped = 0;
let words = [];
let input = '';
let startTime = null;
let wave = 1;
let waveSize = 5;

function generateWord() {
  const length = Math.floor(Math.random() * 5) + 3;
  let word = '';
  for (let i = 0; i < length; i++) {
    word += String.fromCharCode(Math.floor(Math.random() * 26) + 97);
  }
  return word;
}

function nextWave() {
  words = [];
  for (let i = 0; i < waveSize; i++) {
    words.push(generateWord());
  }
  input = '';
  wordsTyped = 0;
  startTime = performance.now();
  wave++;
}

nextWave();

function update() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.font = '24px Arial';
  ctx.fillStyle = '#333';
  ctx.fillText(`Wave: ${wave}`, 10, 30);
  ctx.fillText(`Level: ${level}`, 10, 60);
  ctx.fillText(`Words Typed: ${wordsTyped}/${words.length}`, 10, 90);

  let x = 10;
  let y = 120;
  for (let i = 0; i < words.length; i++) {
    if (i < wordsTyped) {
      ctx.fillStyle = '#0f0';
    } else if (i === wordsTyped) {
      ctx.fillStyle = '#f00';
    } else {
      ctx.fillStyle = '#333';
    }
    ctx.fillText(words[i], x, y);
    x += ctx.measureText(words[i] + ' ').width;
  }

  if (wordsTyped === words.length) {
    const elapsedTime = performance.now() - startTime;
    const wpm = Math.round((words.length / (elapsedTime / 60000)) * 60);
    if (wpm >= targetWPM) {
      level++;
      targetWPM += 5;
      waveSize += 2;
    }
    nextWave();
  }

  requestAnimationFrame(update);
}

update();

document.addEventListener('keydown', (e) => {
  if (e.key === 'Backspace') {
    input = input.slice(0, -1);
  } else if (e.key === 'Enter') {
    if (input === words[wordsTyped]) {
      wordsTyped++;
    }
    input = '';
  } else if (/^[a-z]$/i.test(e.key)) {
    input += e.key.toLowerCase();
  }
});
