const UPDATE_DT = 1000 / UPDATE_RATE; // Time per update in milliseconds
const POWERUP_COUNT = 5;
const PLAYER_SPEED = 5;
const BULLET_SPEED = 10;
const BULLET_LIFETIME = 1000; // Bullet lifespan in milliseconds

// Game state
let lastUpdateTime = 0;
let player = { x: CANVAS_WIDTH / 2, y: CANVAS_HEIGHT / 2, width: 20, height: 20, color: 'blue' };
let bullets = [];
let powerups = [];
