canvas.width = CANVAS_WIDTH;
canvas.height = CANVAS_HEIGHT;
document.body.appendChild(canvas);

// Initialize powerups
for (let i = 0; i < POWERUP_COUNT; i++) {
    powerups.push({
        x: Math.random() * CANVAS_WIDTH,
        y: Math.random() * CANVAS_HEIGHT,
        radius: 10,
        color: 'green'
    });
}

// Input handling
let keys = { left: false, right: false, up: false, down: false, space: false };

document.addEventListener('keydown', function(event) {
    switch (event.key) {
        case 'ArrowLeft': keys.left = true; break;
        case 'ArrowRight': keys.right = true; break;
        case 'ArrowUp': keys.up = true; break;
        case 'ArrowDown': keys.down = true; break;
        case ' ': keys.space = true; break;
    }
});

document.addEventListener('keyup', function(event) {
    switch (event.key) {
        case 'ArrowLeft': keys.left = false; break;
        case 'ArrowRight': keys.right = false; break;
        case 'ArrowUp': keys.up = false; break;
        case 'ArrowDown': keys.down = false; break;
        case ' ': keys.space = false; break;
    }
});

// Main game loop
function gameLoop(timestamp) {
    let deltaTime = timestamp - lastUpdateTime;
    if (deltaTime >= UPDATE_DT) {
        lastUpdateTime = timestamp;
        update(deltaTime);
    }
    render();
    requestAnimationFrame(gameLoop);
}

// Update game state
function update(deltaTime) {
    // Player movement
    if (keys.left) player.x -= PLAYER_SPEED;
    if (keys.right) player.x += PLAYER_SPEED;
    if (keys.up) player.y -= PLAYER_SPEED;
    if (keys.down) player.y += PLAYER_SPEED;

    // Bullet movement and cleanup
    for (let i = bullets.length - 1; i >= 0; i--) {
        bullets[i].x += bullets[i].vx;
        bullets[i].y += bullets[i].vy;
        if (timestamp - bullets[i].spawnTime > BULLET_LIFETIME) {
            bullets.splice(i, 1);
        }
    }

    // Bullet spawning
    if (keys.space && (timestamp - (bullets[bullets.length - 1]?.spawnTime || 0)) > 100) {
        bullets.push({
            x: player.x + player.width / 2,
            y: player.y + player.height / 2,
            vx: Math.cos(player.rotation) * BULLET_SPEED,
            vy: Math.sin(player.rotation) * BULLET_SPEED,
            spawnTime: timestamp
        });
    }

    // Powerup collection
    for (let i = powerups.length - 1; i >= 0; i--) {
        let dx = player.x - powerups[i].x;
        let dy = player.y - powerups[i].y;
        let distance = Math.sqrt(dx * dx + dy * dy);
        if (distance < player.width / 2 + powerups[i].radius) {
            powerups.splice(i, 1);
            // Handle powerup effect (e.g., increase speed, add health)
        }
    }
}

// Render the game
function render() {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Draw player
    ctx.fillStyle = player.color;
    ctx.fillRect(player.x, player.y, player.width, player.height);

    // Draw bullets
    ctx.fillStyle = 'red';
    bullets.forEach(bullet => {
        ctx.beginPath();
        ctx.arc(bullet.x, bullet.y, 2, 0, Math.PI * 2);
        ctx.fill();
    });

    // Draw powerups
    ctx.fillStyle = 'green';
    powerups.forEach(powerup => {
        ctx.beginPath();
        ctx.arc(powerup.x, powerup.y, powerup.radius, 0, Math.PI * 2);
        ctx.fill();
    });
}

// Start the game loop
gameLoop(performance.now());
