class TradeSystem {
  constructor() {
    this.resources = { gold: 100, wood: 50, stone: 30 };
  }

  getResources() {
    return { ...this.resources };
  }

  trade(resource, amount, price) {
    if (this.resources[resource] >= amount && this.resources.gold >= price) {
      this.resources[resource] -= amount;
      this.resources.gold += price;
      return true;
    }
    return false;
  }
}

class ReputationSystem {
  constructor() {
    this.reputation = 50;
  }

  getReputation() {
    return this.reputation;
  }

  modifyReputation(change) {
    this.reputation += change;
    this.reputation = Math.max(0, Math.min(100, this.reputation));
  }
}

class FactionSystem {
  constructor() {
    this.alliances = {};
  }

  getAlliances() {
    return { ...this.alliances };
  }

  formAlliance(faction, reputationThreshold) {
    if (this.reputation.getReputation() >= reputationThreshold) {
      this.alliances[faction] = true;
      this.reputation.modifyReputation(-10); // Cost for forming an alliance
      return true;
    }
    return false;
  }
}

class GameCoordinator {
  constructor() {
    this.trade = new TradeSystem();
    this.reputation = new ReputationSystem();
    this.faction = new FactionSystem();
  }

  performTrade(resource, amount, price) {
    const success = this.trade.trade(resource, amount, price);
    console.log(`Trade ${resource}: ${success ? 'Success' : 'Failed'}`);
    return success;
  }

  modifyReputation(change) {
    this.reputation.modifyReputation(change);
    console.log(`Reputation: ${this.reputation.getReputation()}`);
  }

  formAlliance(faction, reputationThreshold) {
    const success = this.faction.formAlliance(faction, reputationThreshold);
    console.log(`Form Alliance with ${faction}: ${success ? 'Success' : 'Failed'}`);
    return success;
  }
}

// Demo
