class Bank {
    constructor() {
        this.balance = 1000; // Starting balance
    }

    getBalance() {
        return this.balance;
    }

    debit(amount) {
        if (amount <= this.balance) {
            this.balance -= amount;
            return true;
        }
        return false;
    }

    credit(amount) {
        this.balance += amount;
    }
}

class Market {
    constructor() {
        this.prices = {
            apple: 5,
            banana: 3,
            orange: 7
        };
    }

    getPrice(item) {
        return this.prices[item] || 0;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    getInventory() {
        return this.items;
    }
}

class Store {
    constructor(bank, market, inventory) {
        this.bank = bank;
        this.market = market;
        this.inventory = inventory;
    }

    purchase(item, quantity) {
        const price = this.market.getPrice(item);
        const totalCost = price * quantity;

        if (this.bank.debit(totalCost)) {
            this.inventory.addItem(item, quantity);
            return true;
        }
        return false;
    }
}

