// Constants and settings
const CANVAS_ID = 'gameCanvas';
const HIGH_SCORE_KEY = 'farmingPlotHighScore';
const INITIAL_SEED_COST = 10;
const SEED_PRODUCTION = 5;
const GROWTH_TIME = 2000; // 2 seconds
const REFRESH_INTERVAL = 100; // 100ms

// Game state
let canvas, ctx;
let score = 0;
let highScore = 0;
let seeds = 0;
let growingPlots = [];
let timer = null;

// Initialize the game
function init() {
    canvas = document.getElementById(CANVAS_ID);
    ctx = canvas.getContext('2d');

    // Handle window resizing
    window.addEventListener('resize', resizeCanvas, false);
    resizeCanvas();

    // Load high score
    loadHighScore();

    // Start the game loop
    requestAnimationFrame(gameLoop);
}

// Resize the canvas
function resizeCanvas() {
    const dpr = window.devicePixelRatio || 1;
    const width = window.innerWidth;
    const height = window.innerHeight;

    canvas.width = width * dpr;
    canvas.height = height * dpr;
    canvas.style.width = `${width}px`;
    canvas.style.height = `${height}px`;

    ctx.scale(dpr, dpr);
    ctx.font = '16px Arial';
}

// Load high score from localStorage
function loadHighScore() {
    const savedHighScore = localStorage.getItem(HIGH_SCORE_KEY);
    highScore = savedHighScore ? parseInt(savedHighScore, 10) : 0;
}

// Save high score to localStorage
function saveHighScore() {
    if (score > highScore) {
        highScore = score;
        localStorage.setItem(HIGH_SCORE_KEY, highScore);
    }
}

// Game loop
function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Update and render growing plots
    growingPlots.forEach((plot, index) => {
        plot.timer += REFRESH_INTERVAL;
        if (plot.timer >= GROWTH_TIME) {
            seeds += SEED_PRODUCTION;
            growingPlots.splice(index, 1);
        } else {
            ctx.fillText(`Growing...`, 10, 30 + index * 20);
        }
    });

    // Render score and high score
    ctx.fillText(`Score: ${score}`, 10, 50);
    ctx.fillText(`High Score: ${highScore}`, 10, 70);

    // Render seeds
    ctx.fillText(`Seeds: ${seeds}`, 10, 90);

    // Check for game over
    if (seeds <= 0) {
        ctx.fillText(`Game Over!`, canvas.width / 2 - 40, canvas.height / 2);
        saveHighScore();
        cancelAnimationFrame(timer);
        return;
    }

    // Continue the game loop
    timer = requestAnimationFrame(gameLoop);
}

// Handle key presses
function handleKeyPress(event) {
    if (event.key === 'Enter' && seeds >= INITIAL_SEED_COST) {
        seeds -= INITIAL_SEED_COST;
        score++;
        growingPlots.push({ timer: 0 });
    }
}

// Start the game
document.addEventListener('DOMContentLoaded', init);
document.addEventListener('keydown', handleKeyPress);
