// Constants
const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 600;
const PLAYER_SIZE = 20;
const FISH_SIZE = 10;
const SPAWN_INTERVAL = 2000; // milliseconds
const HEALTH_DECREASE = 10;
const HEALTH_INCREASE = 20;
const MAX_HEALTH = 100;

// HTML5 Canvas Setup
const canvas = document.createElement('canvas');
canvas.width = CANVAS_WIDTH;
canvas.height = CANVAS_HEIGHT;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Player Object
const player = {
  x: CANVAS_WIDTH / 2,
  y: CANVAS_HEIGHT / 2,
  health: MAX_HEALTH,
  color: 'blue'
};

// Fish Array
let fish = [];

// Game State
let gameRunning = true;

// Spawn Fish Function
function spawnFish() {
  if (!gameRunning) return;
  const x = Math.random() * CANVAS_WIDTH;
  const y = Math.random() * CANVAS_HEIGHT;
  fish.push({ x, y, color: 'green' });
}

// Handle Collisions
function handleCollisions() {
  fish.forEach((f, index) => {
    const dx = player.x - f.x;
    const dy = player.y - f.y;
    const distance = Math.sqrt(dx * dx + dy * dy);

    if (distance < PLAYER_SIZE / 2 + FISH_SIZE / 2) {
      player.health += HEALTH_INCREASE;
      fish.splice(index, 1);
    }
  });

  // Decrease health over time
  player.health -= HEALTH_DECREASE;
  if (player.health <= 0) {
    respawnPlayer();
  }
}

// Respawn Player Function
function respawnPlayer() {
  player.x = CANVAS_WIDTH / 2;
  player.y = CANVAS_HEIGHT / 2;
  player.health = MAX_HEALTH;
}

// Draw Player Function
function drawPlayer() {
  ctx.fillStyle = player.color;
  ctx.fillRect(player.x - PLAYER_SIZE / 2, player.y - PLAYER_SIZE / 2, PLAYER_SIZE, PLAYER_SIZE);
}

// Draw Fish Function
function drawFish() {
  fish.forEach(f => {
    ctx.fillStyle = f.color;
    ctx.fillRect(f.x - FISH_SIZE / 2, f.y - FISH_SIZE / 2, FISH_SIZE, FISH_SIZE);
  });
}

// Draw Health Bar Function
function drawHealthBar() {
  ctx.fillStyle = 'black';
  ctx.fillRect(10, 10, 120, 20);
  ctx.fillStyle = 'red';
  ctx.fillRect(10, 10, (player.health / MAX_HEALTH) * 120, 20);
}

// Game Loop
function gameLoop() {
  if (!gameRunning) return;
  ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
  handleCollisions();
  spawnFish();
  drawPlayer();
  drawFish();
  drawHealthBar();
  requestAnimationFrame(gameLoop);
}

// Start Game
setInterval(spawnFish, SPAWN_INTERVAL);
gameLoop();

// Event Listeners
canvas.addEventListener('mousemove', (e) => {
  const rect = canvas.getBoundingClientRect();
  player.x = e.clientX - rect.left;
  player.y = e.clientY - rect.top;
});

canvas.addEventListener('click', () => {
  gameRunning = !gameRunning;
});
