class Building {
  constructor(name, resourceCosts) {
    this.name = name;
    this.resourceCosts = resourceCosts; // { resourceType: amount }
  }

  canBuild(resources) {
    for (let [resource, amount] of Object.entries(this.resourceCosts)) {
      if (resources[resource] < amount) {
        return false;
      }
    }
    return true;
  }

  build(resources) {
    if (this.canBuild(resources)) {
      for (let [resource, amount] of Object.entries(this.resourceCosts)) {
        resources[resource] -= amount;
      }
      return true;
    }
    return false;
  }
}

class Resource {
  constructor(name, quantity) {
    this.name = name;
    this.quantity = quantity;
  }

  getAmount() {
    return this.quantity;
  }

  setAmount(amount) {
    this.quantity = amount;
  }
}

class Economy {
  constructor(buildings, resources) {
    this.buildings = buildings; // Array of Building instances
    this.resources = {}; // { resourceName: Resource instance }
    resources.forEach(resource => this.resources[resource.name] = resource);
  }

  addResource(name, amount) {
    if (this.resources[name]) {
      this.resources[name].setAmount(this.resources[name].getAmount() + amount);
    } else {
      this.resources[name] = new Resource(name, amount);
    }
  }

  canAffordBuilding(building) {
    return building.canBuild(this.getResourcesAmounts());
  }

  buildBuilding(building) {
    if (building.build(this.getResourcesAmounts())) {
      console.log(`Built ${building.name}`);
    } else {
      console.log(`Cannot build ${building.name}`);
    }
  }

  getResourcesAmounts() {
    return Object.fromEntries(Object.entries(this.resources).map(([name, resource]) => [name, resource.getAmount()]));
  }
}

// Demo
const wood = new Resource('Wood', 100);
const stone = new Resource('Stone', 50);
const hut = new Building('Hut', { Wood: 30, Stone: 20 });

const economy = new Economy([hut], [wood, stone]);

console.log('Initial resources:', economy.getResourcesAmounts());
economy.buildBuilding(hut);
console.log('Resources after building hut:', economy.getResourcesAmounts());

economy.addResource('Wood', 50);
console.log('Resources after adding more wood:', economy.getResourcesAmounts());
economy.buildBuilding(hut);
console.log('Resources after attempting to build hut again:', economy.getResourcesAmounts());
