class Bank {
    constructor(initialBalance = 0) {
        this.balance = initialBalance;
    }

    deposit(amount) {
        if (amount > 0) {
            this.balance += amount;
            return true;
        }
        return false;
    }

    withdraw(amount) {
        if (amount > 0 && this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }

    getBalance() {
        return this.balance;
    }
}

class Market {
    constructor(prices) {
        this.prices = prices;
    }

    getItemPrice(item) {
        return this.prices[item] || null;
    }

    getAvailableItems() {
        return Object.keys(this.prices);
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity) {
        if (quantity > 0) {
            this.items[item] = (this.items[item] || 0) + quantity;
            return true;
        }
        return false;
    }

    getItemCount(item) {
        return this.items[item] || 0;
    }

    getInventory() {
        return { ...this.items };
    }
}

class Store {
    constructor(bank, market, inventory) {
        this.bank = bank;
        this.market = market;
        this.inventory = inventory;
    }

    purchaseItem(item, quantity) {
        const pricePerItem = this.market.getItemPrice(item);
        const totalCost = pricePerItem * quantity;

        if (pricePerItem !== null && this.bank.withdraw(totalCost)) {
            this.inventory.addItem(item, quantity);
            return true;
        }
        return false;
    }
}

