class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Wallet {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('purchaseMade', this.onPurchaseMade.bind(this));
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Deposited ${amount}. Current balance: ${this.balance}`);
  }

  withdraw(amount) {
    if (amount <= this.balance) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}. Current balance: ${this.balance}`);
      return true;
    } else {
      console.log(`Insufficient funds. Current balance: ${this.balance}`);
      return false;
    }
  }

  onPurchaseMade(data) {
    if (this.withdraw(data.amount)) {
      this.eventBus.emit('purchaseCompleted', { item: data.item });
    }
  }
}

class Shop {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {
      sword: 50,
      shield: 30,
      potion: 20
    };
    this.eventBus.subscribe('buyItem', this.onBuyItem.bind(this));
  }

  buyItem(item) {
    if (this.items[item]) {
      console.log(`Attempting to buy ${item} for ${this.items[item]}`);
      this.eventBus.emit('purchaseMade', { item, amount: this.items[item] });
    } else {
      console.log(`Item ${item} not found in shop.`);
    }
  }

  onPurchaseCompleted(data) {
    console.log(`Purchase of ${data.item} completed.`);
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {};
    this.eventBus.subscribe('purchaseCompleted', this.onPurchaseCompleted.bind(this));
  }

  onPurchaseCompleted(data) {
    if (!this.items[data.item]) {
      this.items[data.item] = 0;
    }
    this.items[data.item]++;
    console.log(`Added 1 ${data.item} to inventory. Total: ${this.items[data.item]}`);
  }
}

