// Economy System
class Economy {
    constructor(resources = {}) {
        this.resources = Object.keys(resources).reduce((acc, key) => {
            acc[key] = new Resource(key, resources[key]);
            return acc;
        }, {});
    }

    addResource(name, amount) {
        if (this.resources[name]) {
            this.resources[name].add(amount);
        } else {
            this.resources[name] = new Resource(name, amount);
            console.log(`Added new resource ${name} with amount ${amount}`);
        }
    }

    deductResources(costs) {
        for (const [resourceName, amount] of Object.entries(costs)) {
            if (!this.resources[resourceName] || !this.resources[resourceName].deduct(amount)) {
                console.log(`Failed to deduct ${amount} of ${resourceName}`);
                return false;
            }
        }
        console.log(`Deducted resources for construction`);
        return true;
    }

    canAfford(costs) {
        for (const [resourceName, amount] of Object.entries(costs)) {
            if (!this.resources[resourceName] || this.resources[resourceName].getAmount() < amount) {
                return false;
            }
        }
        return true;
    }
}

