  if (countdown > 0) {
    ctx.fillStyle = 'black';
    ctx.font = '48px Arial';
    ctx.textAlign = 'center';
    ctx.fillText(countdown, canvas.width / 2, canvas.height / 2);
    countdown--;
    requestAnimationFrame(draw);
    return;
  }

  ctx.fillStyle = 'green';
