class Bank {
    constructor(initialBalance = 0) {
        this.balance = initialBalance;
    }

    deposit(amount) {
        if (amount > 0) {
            this.balance += amount;
            return true;
        }
        return false;
    }

    withdraw(amount) {
        if (amount > 0 && this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }

    getBalance() {
        return this.balance;
    }
}

class Market {
    constructor(prices = {}) {
        this.prices = prices;
    }

    getPrice(item) {
        return this.prices[item] || null;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity = 1) {
        if (quantity > 0) {
            this.items[item] = (this.items[item] || 0) + quantity;
            return true;
        }
        return false;
    }

    getInventory() {
        return this.items;
    }
}

class Economy {
    constructor(bank, market, inventory) {
        this.bank = bank;
        this.market = market;
        this.inventory = inventory;
    }

    purchaseItem(item, quantity = 1) {
        const price = this.market.getPrice(item);
        if (price !== null && this.bank.withdraw(price * quantity)) {
            this.inventory.addItem(item, quantity);
