    'https://via.placeholder.com/50/0000FF/FFFFFF?text=Carrot'
  ]
};

// Plant class
class Plant {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.growth = 0;
    this.image = gameState.plantImages[Math.floor(Math.random() * gameState.plantImages.length)];
  }

  update() {
    this.growth += gameState.plantGrowthSpeed;
  }

  draw() {
    ctx.drawImage(new Image(), this.image, this.x, this.y, 50, 50);
    ctx.fillStyle = 'black';
    ctx.fillText((this.growth * 100).toFixed(0) + '%', this.x + 20, this.y + 60);
  }

  isReady() {
    return this.growth >= gameState.plantHarvestThreshold;
  }
}

// Plant placement
function placePlant(x, y) {
  if (!gameState.gameOver) {
    const plant = new Plant(x, y);
    gameState.plants.push(plant);
  }
}

// Event listeners
canvas.addEventListener('click', (event) => {
  const rect = canvas.getBoundingClientRect();
  const x = event.clientX - rect.left;
  const y = event.clientY - rect.top;
  placePlant(x, y);
});

// Game loop
function gameLoop() {
  if (gameState.gameOver) {
    ctx.fillStyle = 'red';
    ctx.font = '48px Arial';
    ctx.fillText('Game Over!', canvas.width / 2 - 100, canvas.height / 2);
    return;
  }

  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Update and draw plants
  gameState.plants.forEach((plant, index) => {
    plant.update();
    plant.draw();
    if (plant.isReady()) {
      gameState.score += 10;
      gameState.plants.splice(index, 1);
    }
  });

  // Draw score
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.fillText('Score: ' + gameState.score, 10, 30);

  // Check for game over condition
  if (gameState.plants.length > 100) {
    gameState.gameOver = true;
  }

  requestAnimationFrame(gameLoop);
}

// Start the game loop
