    }
}

class EnemyPool {
    constructor(maxEnemies) {
        this.maxEnemies = maxEnemies;
        this.enemies = [];
    }

    addEnemy() {
        if (this.enemies.length < this.maxEnemies) {
            this.enemies.push(new Date().toISOString());
            console.log("Enemy added to pool");
            return true;
        }
        console.log("Enemy pool is full");
        return false;
    }

    removeEnemy() {
        if (this.enemies.length > 0) {
            const enemy = this.enemies.pop();
            console.log(`Enemy removed from pool: ${enemy}`);
            return true;
        }
        console.log("No enemies in pool to remove");
        return false;
    }
}

class Score {
    constructor() {
        this.score = 0;
    }

    increment() {
        this.score++;
        console.log(`Score incremented: ${this.score}`);
    }

    decrement() {
        if (this.score > 0) {
            this.score--;
            console.log(`Score decremented: ${this.score}`);
        } else {
            console.log("Score cannot go below zero");
        }
    }

    getScore() {
        return this.score;
    }
}

class Coordinator {
    constructor(spawner, enemyPool, score) {
        this.spawner = spawner;
        this.enemyPool = enemyPool;
        this.score = score;

        this.spawner.start();
    }

    handleEnemySpawn() {
        if (this.enemyPool.addEnemy()) {
            this.score.increment();
        }
    }

    handleEnemyDefeat() {
        if (this.enemyPool.removeEnemy()) {
            this.score.decrement();
        }
    }

    stop() {
        this.spawner.stop();
    }
}

