// Typing Speed Game with Wave/Level Progression

// Constants
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = 800;
canvas.height = 600;
const TARGET_FPS = 60;
const TIME_STEP = 1000 / TARGET_FPS;
const LEVEL_DURATION = 10; // seconds
const WAVE_INTERVAL = 5; // seconds
const LETTER_SPEED = 100; // pixels per second

// Game state
let lastTime = 0;
let accumulatedTime = 0;
let currentLevel = 1;
let waveCount = 0;
let currentWave = [];
let typedLetters = '';
let score = 0;
let startTime = Date.now();

// Letter class
class Letter {
    constructor(text, x, y) {
        this.text = text;
        this.x = x;
        this.y = y;
        this.speed = LETTER_SPEED;
    }

    update(delta) {
        this.x -= this.speed * delta / 1000;
    }

    draw() {
        ctx.font = '30px Arial';
        ctx.fillText(this.text, this.x, this.y);
    }
}

// Generate random letters
function generateLetters(count) {
    const letters = [];
    for (let i = 0; i < count; i++) {
        const text = String.fromCharCode(Math.floor(Math.random() * 26) + 65);
        const y = Math.random() * (canvas.height - 50) + 25;
        letters.push(new Letter(text, canvas.width, y));
    }
    return letters;
}

// Update game state
function update(delta) {
    if (Date.now() - startTime > (currentLevel * LEVEL_DURATION + waveCount * WAVE_INTERVAL) * 1000) {
        waveCount++;
        currentWave = generateLetters(10 * currentLevel);
    }

    currentWave.forEach(letter => letter.update(delta));

    // Remove letters that have moved off the screen
    currentWave = currentWave.filter(letter => letter.x > -20);
}

// Render game
function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    currentWave.forEach(letter => letter.draw());

    ctx.font = '20px Arial';
    ctx.fillText(`Level: ${currentLevel}`, 10, 30);
    ctx.fillText(`Score: ${score}`, 10, 60);
    ctx.fillText(`Typed: ${typedLetters}`, 10, 90);
}

// Main game loop
function gameLoop(timestamp) {
    const delta = timestamp - lastTime;
    accumulatedTime += delta;

    while (accumulatedTime >= TIME_STEP) {
        update(TIME_STEP);
        accumulatedTime -= TIME_STEP;
    }

    render();
    lastTime = timestamp;
    requestAnimationFrame(gameLoop);
}

// Event listeners
document.addEventListener('keydown', (event) => {
    const nextLetter = currentWave[0];
    if (nextLetter && nextLetter.text.toLowerCase() === event.key.toLowerCase()) {
        score++;
        typedLetters += event.key;
        currentWave.shift();
    }
});

// Start the game
startTime = Date.now();
requestAnimationFrame(gameLoop);
