// Event Bus Implementation
class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

// Hunger System
class Hunger {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.hungerLevel = 50;
    this.eventBus.subscribe('eat', () => this.decreaseHunger());
  }

  decreaseHunger(amount = 10) {
    this.hungerLevel = Math.max(0, this.hungerLevel - amount);
    this.eventBus.emit('hungerLevelChanged', this.hungerLevel);
  }

  getHungerLevel() {
    return this.hungerLevel;
  }
}

// Energy System
class Energy {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.energyLevel = 50;
    this.eventBus.subscribe('rest', () => this.increaseEnergy());
