// Event Bus Implementation
class EventBus {
    constructor() {
        this.events = {};
    }

    subscribe(event, listener) {
        if (!this.events[event]) {
            this.events[event] = [];
        }
        this.events[event].push(listener);
    }

    emit(event, data) {
        if (this.events[event]) {
            this.events[event].forEach(listener => listener(data));
        }
    }
}

// Crafting System
class Crafting {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('recipeAdded', this.onRecipeAdded.bind(this));
        this.eventBus.subscribe('itemUsed', this.onItemUsed.bind(this));
    }

    addRecipe(recipe) {
        this.eventBus.emit('recipeAdded', recipe);
    }

    onRecipeAdded(recipe) {
        console.log(`Recipe added: ${recipe.name}`);
    }

    onItemUsed(item) {
        console.log(`Item used: ${item}`);
    }
}

// Recipe System
class Recipe {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.recipes = [];
        this.eventBus.subscribe('recipeAdded', this.onRecipeAdded.bind(this));
    }

    onRecipeAdded(recipe) {
        this.recipes.push(recipe);
        console.log(`Recipe stored: ${recipe.name}`);
    }

    getRecipes() {
        return this.recipes;
    }
}

// Inventory System
class Inventory {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.items = {};
        this.eventBus.subscribe('itemUsed', this.onItemUsed.bind(this));
    }

    addItem(item, quantity = 1) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
        console.log(`Item added: ${item} x${quantity}`);
    }

    useItem(item, quantity = 1) {
        if (this.items[item] >= quantity) {
            this.items[item] -= quantity;
            this.eventBus.emit('itemUsed', item);
            console.log(`Item used: ${item} x${quantity}`);
        } else {
            console.log(`Not enough ${item} in inventory.`);
        }
    }

    getItemCount(item) {
        return this.items[item] || 0;
    }
}

