const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const fixedTimestep = 16; // approximately 60 FPS
let lastTimestamp = 0;

const player = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  size: 20,
  speed: 5,
  angle: 0,
  shooting: false
};

const enemies = [];
const particles = [];

function spawnEnemy() {
  const x = Math.random() < 0.5 ? -10 : canvas.width + 10;
  const y = Math.random() * canvas.height;
  enemies.push({ x, y, size: 15, speed: 3 });
}

function spawnParticle(x, y) {
  particles.push({
    x, y,
    size: Math.random() * 2 + 1,
    speed: Math.random() * 3 + 1,
    angle: Math.random() * Math.PI * 2
  });
}

function updatePlayer(delta) {
  if (player.shooting) {
    spawnParticle(player.x, player.y);
    player.shooting = false;
  }
  if (keys['ArrowUp']) player.y -= player.speed * delta;
  if (keys['ArrowDown']) player.y += player.speed * delta;
  if (keys['ArrowLeft']) player.x -= player.speed * delta;
  if (keys['ArrowRight']) player.x += player.speed * delta;
  player.x = Math.max(player.size, Math.min(player.x, canvas.width - player.size));
  player.y = Math.max(player.size, Math.min(player.y, canvas.height - player.size));
}

function updateEnemies(delta) {
  for (const enemy of enemies) {
    const angle = Math.atan2(player.y - enemy.y, player.x - enemy.x);
    enemy.x += Math.cos(angle) * enemy.speed * delta;
    enemy.y += Math.sin(angle) * enemy.speed * delta;
    if (Math.hypot(player.x - enemy.x, player.y - enemy.y) < player.size + enemy.size) {
      spawnParticle(player.x, player.y);
      enemies.splice(enemies.indexOf(enemy), 1);
    }
  }
  if (Math.random() < 0.01) spawnEnemy();
}

function updateParticles(delta) {
  for (let i = particles.length - 1; i >= 0; i--) {
    particles[i].x += Math.cos(particles[i].angle) * particles[i].speed * delta;
    particles[i].y += Math.sin(particles[i].angle) * particles[i].speed * delta;
    particles[i].size -= delta * 0.1;
    if (particles[i].size < 0) particles.splice(i, 1);
  }
}

function drawPlayer() {
  ctx.beginPath();
  ctx.arc(player.x, player.y, player.size, 0, Math.PI * 2);
  ctx.fillStyle = 'blue';
  ctx.fill();
}

function drawEnemies() {
  for (const enemy of enemies) {
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, enemy.size, 0, Math.PI * 2);
    ctx.fillStyle = 'red';
    ctx.fill();
  }
}

function drawParticles() {
  for (const particle of particles) {
    ctx.beginPath();
    ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2);
    ctx.fillStyle = 'white';
    ctx.fill();
  }
}

const keys = {};
document.addEventListener('keydown', e => keys[e.key] = true);
document.addEventListener('keyup', e => keys[e.key] = false);
document.addEventListener('mousedown', () => player.shooting = true);

function gameLoop(timestamp) {
  const delta = (timestamp - lastTimestamp) / 1000;
  lastTimestamp = timestamp;

  ctx.clearRect(0, 0, canvas.width, canvas.height);

  updatePlayer(delta);
  updateEnemies(delta);
  updateParticles(delta);

  drawPlayer();
  drawEnemies();
  drawParticles();

  requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
