class RarityTable {
    constructor() {
        this.rarityMap = {
            "common": 0.6,
            "uncommon": 0.3,
            "rare": 0.09,
            "epic": 0.01
        };
    }

    getRandomItem() {
        const random = Math.random();
        let cumulativeProbability = 0;

        for (const [item, probability] of Object.entries(this.rarityMap)) {
            cumulativeProbability += probability;
            if (random < cumulativeProbability) {
                return item;
            }
        }
        return null; // This line should never be reached
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item) {
        if (this.items[item]) {
            this.items[item]++;
        } else {
            this.items[item] = 1;
        }
    }

    getInventory() {
        return this.items;
    }
}

