        const price = this.prices[item];
        if (price !== undefined && amount > 0) {
            return price * amount;
        }
        return null;
    }

    setPrice(item, price) {
        if (price >= 0) {
            this.prices[item] = price;
            return true;
        }
        return false;
    }
}

class Inventory {
