class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
    this.inventory = {};
    this.economy = { balance: 0 };
  }

  purchase(item) {
    const price = this.pricing.getPrice(item);
    const demand = this.demand.getDemand(item);

    if (demand > 0 && this.economy.balance >= price) {
      this.economy.balance -= price;
      this.inventory[item] = (this.inventory[item] || 0) + 1;
      this.demand.demandLevels[item]--;
      console.log(`Purchased ${item} for ${price}. Inventory: ${JSON.stringify(this.inventory)}, Economy Balance: ${this.economy.balance}`);
