class Farm {
  constructor(cropSystem, marketSystem) {
    this.cropSystem = cropSystem;
    this.marketSystem = marketSystem;
    this.crops = [];
  }

  plantCrop(name, quantity) {
    const crop = this.cropSystem.createCrop(name);
    for (let i = 0; i < quantity; i++) {
      this.crops.push(crop);
    }
    console.log(`Planted ${quantity} ${name}(s)`);
  }

  harvestCrop(name, quantity) {
    const harvested = this.crops.filter(crop => crop.name === name).slice(0, quantity);
    harvested.forEach(crop => this.crops.splice(this.crops.indexOf(crop), 1));
    this.marketSystem.sellCrop(harvested);
    console.log(`Harvested and sold ${quantity} ${name}(s)`);
  }
}

