class Loot {
  constructor(name, value) {
    this.name = name;
    this.value = value;
  }

  static createLoot(name, value) {
    return new Loot(name, value);
  }

  getName() {
    return this.name;
  }

  getValue() {
    return this.value;
  }
}

class RarityTable {
  constructor() {
    this.rarityLevels = {
      common: 0.7,
      uncommon: 0.2,
      rare: 0.08,
      epic: 0.01,
      legendary: 0.01
    };
  }

  generateLoot() {
    const rand = Math.random();
    let cumulativeProbability = 0;

    for (const [rarity, probability] of Object.entries(this.rarityLevels)) {
      cumulativeProbability += probability;
      if (rand <= cumulativeProbability) {
        return Loot.createLoot(rarity, this.calculateValue(rarity));
      }
    }

    throw new Error("Failed to generate loot");
  }

  calculateValue(rarity) {
    switch (rarity) {
      case 'common': return 10;
      case 'uncommon': return 25;
      case 'rare': return 50;
      case 'epic': return 100;
      case 'legendary': return 500;
      default: throw new Error("Unknown rarity");
    }
  }
}

class Inventory {
  constructor() {
    this.items = [];
  }

  addItem(item) {
    this.items.push(item);
  }

  getItems() {
    return this.items;
  }
}

class Economy {
  constructor(initialBalance) {
    this.balance = initialBalance;
  }

  debit(amount) {
    if (amount > this.balance) {
      throw new Error("Insufficient funds");
    }
    this.balance -= amount;
  }

  credit(amount) {
    this.balance += amount;
  }

  getBalance() {
    return this.balance;
  }
}

class Store {
  constructor(economy, rarityTable) {
    this.economy = economy;
    this.rarityTable = rarityTable;
  }

  purchaseItem() {
    const loot = this.rarityTable.generateLoot();
    const price = loot.getValue();
    this.economy.debit(price);
    return loot;
  }
}

// Demo
const economy = new Economy(1000);
const rarityTable = new RarityTable();
const inventory = new Inventory();
const store = new Store(economy, rarityTable);

try {
