  console.log(`Purchased ${loot.getName()} for ${loot.getValue()} gold.`);
  console.log(`Remaining balance: ${economy.getBalance()} gold.`);
  console.log(`Inventory:`, inventory.getItems().map(item => `${item.getName()} (${item.getValue()} gold)`).join(', '));
} catch (error) {
  console.error(error.message);
}
