    x: canvas.width / 2,
    y: 20,
    radius: 15,
    dy: 2
};

const gravity = 0.5;
let score = 0;
let highScore = parseInt(localStorage.getItem('highScore')) || 0;

function drawBall() {
    ctx.beginPath();
    ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
    ctx.fillStyle = '#0095DD';
    ctx.fill();
    ctx.closePath();
}

function drawScore() {
    ctx.font = '16px Arial';
    ctx.fillStyle = '#0095DD';
    ctx.fillText(`Score: ${score}`, 8, 20);
    ctx.fillText(`High Score: ${highScore}`, 8, 40);
}

