const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let width, height, dpr;
function resize() {
    width = window.innerWidth;
    height = window.innerHeight;
    dpr = window.devicePixelRatio;
    canvas.width = width * dpr;
    canvas.height = height * dpr;
    canvas.style.width = `${width}px`;
    canvas.style.height = `${height}px`;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
}
window.addEventListener('resize', resize);
resize();

let player = {
    x: width / 2,
    y: height / 2,
    radius: 10,
    angle: 0,
    speed: 5
};

let bullets = [];
let enemies = [];
let level = 1;
let wave = 1;
let score = 0;
let gameLoop;

function spawnEnemies() {
    const count = level + wave * 2;
    for (let i = 0; i < count; i++) {
        enemies.push({
            x: Math.random() * width,
            y: Math.random() * height,
            radius: 5,
            speed: 1 + level / 10
        });
    }
}

function update() {
    player.x += Math.cos(player.angle) * player.speed;
    player.y += Math.sin(player.angle) * player.speed;
    player.x = Math.max(player.radius, Math.min(width - player.radius, player.x));
    player.y = Math.max(player.radius, Math.min(height - player.radius, player.y));

    bullets.forEach(bullet => {
        bullet.x += Math.cos(bullet.angle) * 10;
        bullet.y += Math.sin(bullet.angle) * 10;
    });

    enemies.forEach(enemy => {
        enemy.x += Math.cos(Math.atan2(player.y - enemy.y, player.x - enemy.x)) * enemy.speed;
        enemy.y += Math.sin(Math.atan2(player.y - enemy.y, player.x - enemy.x)) * enemy.speed;
    });

    bullets = bullets.filter(bullet => bullet.x > 0 && bullet.x < width && bullet.y > 0 && bullet.y < height);
    enemies = enemies.filter(enemy => Math.hypot(player.x - enemy.x, player.y - enemy.y) > player.radius + enemy.radius);

    for (let i = bullets.length - 1; i >= 0; i--) {
        for (let j = enemies.length - 1; j >= 0; j--) {
            if (Math.hypot(bullets[i].x - enemies[j].x, bullets[i].y - enemies[j].y) < bullets[i].radius + enemies[j].radius) {
                bullets.splice(i, 1);
                enemies.splice(j, 1);
                score++;
            }
        }
    }

    if (enemies.length === 0) {
        wave++;
        if (wave > level * 2) {
            level++;
            wave = 1;
        }
        spawnEnemies();
    }
}

function draw() {
    ctx.clearRect(0, 0, width, height);

    ctx.beginPath();
    ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
    ctx.fillStyle = 'blue';
    ctx.fill();

    bullets.forEach(bullet => {
        ctx.beginPath();
        ctx.arc(bullet.x, bullet.y, 2, 0, Math.PI * 2);
        ctx.fillStyle = 'white';
        ctx.fill();
    });

    enemies.forEach(enemy => {
        ctx.beginPath();
        ctx.arc(enemy.x, enemy.y, enemy.radius, 0, Math.PI * 2);
        ctx.fillStyle = 'red';
        ctx.fill();
    });

    ctx.font = '20px Arial';
    ctx.fillStyle = 'black';
    ctx.fillText(`Score: ${score}`, 10, 30);
    ctx.fillText(`Level: ${level}`, 10, 60);
    ctx.fillText(`Wave: ${wave}`, 10, 90);
}

function game() {
    update();
    draw();
    gameLoop = requestAnimationFrame(game);
}

document.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowLeft') player.angle -= 0.1;
    if (e.key === 'ArrowRight') player.angle += 0.1;
    if (e.key === 'ArrowUp') {
        bullets.push({
            x: player.x + Math.cos(player.angle) * player.radius,
            y: player.y + Math.sin(player.angle) * player.radius,
            angle: player.angle,
            radius: 2
        });
    }
});

spawnEnemies();
game();
