const ctx = canvas.getContext('2d');

const player = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    radius: 10,
    health: 100,
    maxHealth: 100,
    speed: 5,
    dx: 0,
    dy: 0
};

const enemies = [];
const enemyCount = 5;
const enemyRadius = 5;
const enemySpeed = 3;

function spawnEnemy() {
    const x = Math.random() * canvas.width;
    const y = Math.random() * canvas.height;
    enemies.push({ x, y, radius: enemyRadius, dx: (Math.random() - 0.5) * enemySpeed, dy: (Math.random() - 0.5) * enemySpeed });
}

for (let i = 0; i < enemyCount; i++) {
    spawnEnemy();
}

const bullet = {
    x: 0,
    y: 0,
    radius: 2,
    speed: 10,
    active: false,
    dx: 0,
    dy: 0
};

function updatePlayer() {
    player.x += player.dx;
    player.y += player.dy;

    if (player.x - player.radius < 0) player.x = player.radius;
    if (player.x + player.radius > canvas.width) player.x = canvas.width - player.radius;
    if (player.y - player.radius < 0) player.y = player.radius;
    if (player.y + player.radius > canvas.height) player.y = canvas.height - player.radius;
}

function updateEnemies() {
    enemies.forEach(enemy => {
        enemy.x += enemy.dx;
        enemy.y += enemy.dy;

        if (enemy.x - enemy.radius < 0 || enemy.x + enemy.radius > canvas.width) {
            enemy.dx = -enemy.dx;
        }
        if (enemy.y - enemy.radius < 0 || enemy.y + enemy.radius > canvas.height) {
            enemy.dy = -enemy.dy;
        }

        if (checkCollision(player, enemy)) {
            player.health -= 10;
            if (player.health <= 0) {
                player.health = player.maxHealth;
                player.x = canvas.width / 2;
                player.y = canvas.height / 2;
            }
        }

        if (bullet.active && checkCollision(enemy, bullet)) {
            const index = enemies.indexOf(enemy);
            if (index !== -1) {
                enemies.splice(index, 1);
                spawnEnemy();
                bullet.active = false;
            }
        }
    });
}

function checkCollision(a, b) {
    return Math.sqrt((a.x - b.x) ** 2 + (a.y - b.y) ** 2) < a.radius + b.radius;
}

function updateBullet() {
    if (bullet.active) {
        bullet.x += bullet.dx;
        bullet.y += bullet.dy;

        if (bullet.x < 0 || bullet.x > canvas.width || bullet.y < 0 || bullet.y > canvas.height) {
            bullet.active = false;
        }
    }
}

function drawPlayer() {
    ctx.beginPath();
    ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
    ctx.fillStyle = 'blue';
    ctx.fill();
    ctx.closePath();
}

function drawEnemies() {
    enemies.forEach(enemy => {
        ctx.beginPath();
        ctx.arc(enemy.x, enemy.y, enemy.radius, 0, Math.PI * 2);
        ctx.fillStyle = 'red';
        ctx.fill();
        ctx.closePath();
    });
}

function drawBullet() {
    if (bullet.active) {
        ctx.beginPath();
        ctx.arc(bullet.x, bullet.y, bullet.radius, 0, Math.PI * 2);
        ctx.fillStyle = 'black';
        ctx.fill();
        ctx.closePath();
    }
}

function drawHealthBar() {
    ctx.fillStyle = 'black';
    ctx.fillRect(10, 10, 100, 10);
    ctx.fillStyle = 'green';
    ctx.fillRect(10, 10, player.health / player.maxHealth * 100, 10);
}

function update() {
    updatePlayer();
    updateEnemies();
    updateBullet();
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawPlayer();
    drawEnemies();
    drawBullet();
    drawHealthBar();
}

const fixedTimeStep = 1000 / 60;
let lastTime = 0;

function gameLoop(timestamp) {
    const deltaTime = timestamp - lastTime;
    if (deltaTime >= fixedTimeStep) {
        lastTime = timestamp - (deltaTime % fixedTimeStep);
        update();
    }
    draw();
    requestAnimationFrame(gameLoop);
}

