class Pricing {
  constructor(basePrice) {
    this.basePrice = basePrice;
  }

  calculatePrice(demand) {
    return this.basePrice * (1 + demand / 100);
  }
}

class Demand {
  constructor(initialDemand) {
    this.currentDemand = initialDemand;
  }

  adjustDemand(change) {
    this.currentDemand += change;
    return this.currentDemand;
  }
}

class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
  }

  updateDemand(change) {
    const newDemand = this.demand.adjustDemand(change);
    return newDemand;
  }

  calculateCurrentPrice() {
    const currentDemand = this.demand.currentDemand;
    const price = this.pricing.calculatePrice(currentDemand);
    return price;
  }
}

