// Tower Defense Skirmish with Particle Burst Effect on Key Events
// Rendered on an HTML5 Canvas with a Deterministic Main Loop

// Constants
const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 600;
const TARGET_FPS = 60;
const TIME_STEP = 1000 / TARGET_FPS;
const PARTICLE_COUNT = 50;
const PARTICLE_LIFESPAN = 1000; // in ms

// DOM Elements
const canvas = document.createElement('canvas');
canvas.width = CANVAS_WIDTH;
canvas.height = CANVAS_HEIGHT;
document.body.appendChild(canvas);

const ctx = canvas.getContext('2d');

// Game State
let lastTime = performance.now();
let particles = [];

// Entity Classes
class Entity {
  constructor(x, y) {
    this.x = x;
    this.y = y;
  }
}

class Tower extends Entity {
  constructor(x, y) {
    super(x, y);
    this.range = 100;
    this.damage = 10;
  }

  draw() {
    ctx.fillStyle = 'green';
    ctx.fillRect(this.x - 5, this.y - 5, 10, 10);
  }
}

class Enemy extends Entity {
  constructor(x, y, speed) {
    super(x, y);
    this.speed = speed;
    this.health = 50;
  }

  update() {
    this.x -= this.speed;
  }

  draw() {
    ctx.fillStyle = 'red';
    ctx.fillRect(this.x - 5, this.y - 5, 10, 10);
  }
}

class Particle extends Entity {
  constructor(x, y, color) {
    super(x, y);
    this.color = color;
    this.lifetime = PARTICLE_LIFESPAN;
  }

  update(dt) {
    this.lifetime -= dt;
    if (this.lifetime <= 0) {
      particles = particles.filter(p => p !== this);
    }
  }

  draw() {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x - 1, this.y - 1, 2, 2);
  }
}

// Game Entities
const towers = [new Tower(750, 300)];
const enemies = [new Enemy(50, 300, 2)];

// Main Loop
function mainLoop(currentTime) {
  const dt = currentTime - lastTime;
  lastTime = currentTime;

  if (dt < TIME_STEP) {
    requestAnimationFrame(mainLoop);
    return;
  }

  update(dt);
  draw();

  requestAnimationFrame(mainLoop);
}

// Update Function
function update(dt) {
  // Update Enemies
  enemies.forEach(enemy => {
    enemy.update(dt);
    if (enemy.x < 0) {
      enemies = enemies.filter(e => e !== enemy);
    }
  });

  // Update Particles
  particles.forEach(particle => particle.update(dt));

  // Collision Detection
  towers.forEach(tower => {
    const withinRange = enemies.filter(enemy => 
      Math.hypot(tower.x - enemy.x, tower.y - enemy.y) <= tower.range
    );

    if (withinRange.length > 0) {
      const target = withinRange[0];
      target.health -= tower.damage;

      if (target.health <= 0) {
        enemies = enemies.filter(e => e !== target);
        createParticleBurst(target.x, target.y, 'orange');
      }
    }
  });
}

// Draw Function
function draw() {
  ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

  // Draw Towers
  towers.forEach(tower => tower.draw());

  // Draw Enemies
  enemies.forEach(enemy => enemy.draw());

  // Draw Particles
  particles.forEach(particle => particle.draw());
}

// Particle Burst Creation
function createParticleBurst(x, y, color) {
  for (let i = 0; i < PARTICLE_COUNT; i++) {
    const angle = Math.random() * Math.PI * 2;
    const speed = Math.random() * 2;
    particles.push(new Particle(x, y, color));
  }
}

// Start the Game
requestAnimationFrame(mainLoop);
