const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);

const ctx = canvas.getContext('2d');

const plotSize = 200;
const plotX = (canvas.width - plotSize) / 2;
const plotY = (canvas.height - plotSize) / 2;

const seed = {
  position: { x: plotX + plotSize / 2, y: plotY + plotSize / 2 },
  radius: 5,
  color: 'green'
};

const particles = [];

function drawPlot() {
  ctx.fillStyle = 'brown';
  ctx.fillRect(plotX, plotY, plotSize, plotSize);
}

function drawSeed() {
  ctx.beginPath();
  ctx.arc(seed.position.x, seed.position.y, seed.radius, 0, Math.PI * 2);
  ctx.fillStyle = seed.color;
  ctx.fill();
}

function createParticle(x, y) {
  particles.push({
    position: { x, y },
    velocity: { x: (Math.random() - 0.5) * 5, y: (Math.random() - 0.5) * 5 },
    size: Math.random() * 3 + 1,
    color: 'rgba(0, 255, 0, 0.8)'
  });
}

function updateParticles() {
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.position.x += p.velocity.x;
    p.position.y += p.velocity.y;
    p.velocity.y += 0.1; // Gravity

    if (p.position.y > canvas.height) {
      particles.splice(i, 1);
    }
  }
}

function drawParticles() {
  ctx.globalCompositeOperation = 'lighter';
  particles.forEach(p => {
    ctx.beginPath();
    ctx.arc(p.position.x, p.position.y, p.size, 0, Math.PI * 2);
    ctx.fillStyle = p.color;
    ctx.fill();
  });
  ctx.globalCompositeOperation = 'source-over';
}

function plantSeed() {
  seed.color = 'black';
  createParticle(seed.position.x, seed.position.y);
  setTimeout(() => {
    seed.color = 'green';
  }, 500);
}

function growPlant() {
  seed.radius = 10;
  createParticle(seed.position.x, seed.position.y);
  setTimeout(() => {
    seed.radius = 15;
  }, 500);
}

function harvestPlant() {
  seed.radius = 5;
  seed.color = 'green';
  createParticle(seed.position.x, seed.position.y);
  for (let i = 0; i < 50; i++) {
    createParticle(seed.position.x, seed.position.y);
  }
}

let stage = 0;

function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawPlot();
  drawSeed();
  updateParticles();
  drawParticles();

  if (stage === 0) {
    plantSeed();
    stage = 1;
  } else if (stage === 1) {
    setTimeout(() => {
      growPlant();
      stage = 2;
    }, 2000);
  } else if (stage === 2) {
    setTimeout(() => {
      harvestPlant();
      stage = 0;
    }, 3000);
  }

  requestAnimationFrame(gameLoop);
}

gameLoop();
