// Crafting System
class Crafting {
  constructor(recipeSystem, inventorySystem) {
    this.recipeSystem = recipeSystem;
    this.inventorySystem = inventorySystem;
  }

  craft(itemName) {
    const recipe = this.recipeSystem.getRecipe(itemName);
    if (!recipe) {
      console.log(`Recipe for ${itemName} not found.`);
      return false;
    }

    if (this.inventorySystem.hasIngredients(recipe.ingredients)) {
      this.inventorySystem.removeIngredients(recipe.ingredients);
      this.inventorySystem.addItem(itemName);
      console.log(`Crafted ${itemName} successfully.`);
      return true;
    } else {
      console.log(`Not enough ingredients to craft ${itemName}.`);
      return false;
    }
  }
}

// Recipe System
class Recipe {
  constructor() {
    this.recipes = {
      sword: { ingredients: { iron: 5, wood: 3 } },
      shield: { ingredients: { leather: 4, wood: 2 } }
    };
  }

  getRecipe(itemName) {
    return this.recipes[itemName];
  }
}

// Inventory System
class Inventory {
  constructor() {
    this.items = {
      iron: 10,
      wood: 10,
      leather: 5
    };
  }

  hasIngredients(ingredients) {
    for (const [item, amount] of Object.entries(ingredients)) {
      if (this.items[item] < amount) {
        return false;
      }
    }
    return true;
  }

  removeIngredients(ingredients) {
    for (const [item, amount] of Object.entries(ingredients)) {
      this.items[item] -= amount;
    }
  }

  addItem(itemName) {
    if (this.items[itemName]) {
      this.items[itemName]++;
    } else {
      this.items[itemName] = 1;
    }
  }
}

