    this.balance = 1000;
    this.prices = {
      food: 10,
      rest: 5
    };
  }

  debit(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      console.log(`Debited ${amount}, new balance: ${this.balance}`);
