let spawnInterval = ENEMY_SPAWN_INTERVAL;
let spawnTimer = spawnInterval;

class Ball {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.velocityY = 0;
  }

  update(deltaTime) {
    this.velocityY += GRAVITY * deltaTime;
    this.y += this.velocityY * deltaTime;
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, BALL_RADIUS, 0, Math.PI * 2);
    ctx.fillStyle = BALL_COLOR;
    ctx.fill();
    ctx.closePath();
  }

  reset() {
    this.y = 50;
  }
}

class Enemy {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.velocityY = 0;
  }

  update(deltaTime) {
    this.velocityY += GRAVITY * deltaTime;
    this.y += this.velocityY * deltaTime;
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, ENEMY_RADIUS, 0, Math.PI * 2);
    ctx.fillStyle = ENEMY_COLOR;
    ctx.fill();
    ctx.closePath();
  }

  isCollidingWith(ball) {
    return Math.hypot(this.x - ball.x, this.y - ball.y) < BALL_RADIUS + ENEMY_RADIUS;
  }
}

