// Constants
const ROOM_WIDTH = 20;
const ROOM_HEIGHT = 15;
const TILE_SIZE = 20;
const POWER_UPS = ['speed', 'health', 'strength'];
const POWER_UP_PROBABILITY = 0.05;

// Canvas setup
const canvas = document.createElement('canvas');
canvas.width = ROOM_WIDTH * TILE_SIZE;
canvas.height = ROOM_HEIGHT * TILE_SIZE;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Room generation
function generateRoom() {
    const room = [];
    for (let y = 0; y < ROOM_HEIGHT; y++) {
        const row = [];
        for (let x = 0; x < ROOM_WIDTH; x++) {
            const tile = { type: 'floor', powerUp: null };
            if (Math.random() < POWER_UP_PROBABILITY) {
                tile.powerUp = POWER_UPS[Math.floor(Math.random() * POWER_UPS.length)];
            }
            row.push(tile);
        }
        room.push(row);
    }
    return room;
}

// Player setup
const player = { x: 0, y: 0, powerUps: [] };

// Rendering
function render(room) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let y = 0; y < ROOM_HEIGHT; y++) {
        for (let x = 0; x < ROOM_WIDTH; x++) {
            const tile = room[y][x];
            ctx.fillStyle = tile.type === 'floor' ? '#999' : '#333';
            ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
            if (tile.powerUp) {
                ctx.fillStyle = 'gold';
                ctx.fillText(tile.powerUp, x * TILE_SIZE + 5, y * TILE_SIZE + 15);
            }
        }
    }
    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x * TILE_SIZE, player.y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
}

// Game loop
function gameLoop() {
    render(room);
    requestAnimationFrame(gameLoop);
}

// Player movement
canvas.addEventListener('keydown', (e) => {
    switch (e.key) {
        case 'ArrowUp':
            if (player.y > 0) player.y--;
            break;
        case 'ArrowDown':
            if (player.y < ROOM_HEIGHT - 1) player.y++;
            break;
        case 'ArrowLeft':
            if (player.x > 0) player.x--;
            break;
        case 'ArrowRight':
            if (player.x < ROOM_WIDTH - 1) player.x++;
            break;
    }
    const tile = room[player.y][player.x];
    if (tile.powerUp) {
        player.powerUps.push(tile.powerUp);
        tile.powerUp = null;
    }
});

// Initialize game
const room = generateRoom();
gameLoop();
