      console.log(`Bought ${quantity} ${item}(s) for ${price} gold.`);
      return true;
    }
    console.log(`Failed to buy ${quantity} ${item}(s).`);
    return false;
  }

  sellItem(item, quantity) {
    const price = this.prices[item] * quantity;
    if (price && this.economy.deposit(price) && this.inventory.removeItem(item, quantity)) {
      console.log(`Sold ${quantity} ${item}(s) for ${price} gold.`);
      return true;
    }
    console.log(`Failed to sell ${quantity} ${item}(s).`);
    return false;
  }
}

