// Economy System
class Economy {
  constructor() {
    this.balance = 100; // Starting balance
    this.prices = {
      sword: 20,
      shield: 15,
      potion: 10
    };
  }

  getBalance() {
    return this.balance;
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }

  debit(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

// Inventory System
class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  getItems() {
    return this.items;
  }
}

// Store System
class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
  }

  purchase(item) {
    const price = this.economy.getPrice(item);
    if (price > 0 && this.economy.debit(price)) {
      this.inventory.addItem(item);
      return true;
    }
    return false;
  }
}

// Combat System
class Combat {
  constructor(health) {
    this.health = health;
  }

  takeDamage(amount) {
    this.health -= amount;
    if (this.health < 0) {
      this.health = 0;
    }
  }

  getHealth() {
    return this.health;
  }
}

// Health System
class Health {
  constructor(initialHealth = 100) {
    this.currentHealth = initialHealth;
  }

  takeDamage(amount) {
    this.currentHealth -= amount;
    if (this.currentHealth < 0) {
      this.currentHealth = 0;
    }
  }

  heal(amount) {
    this.currentHealth += amount;
    if (this.currentHealth > 100) {
      this.currentHealth = 100;
    }
  }

  getHealth() {
    return this.currentHealth;
  }
}

// Loot System
class Loot {
  constructor() {
    this.lootTable = {
      sword: 0.3,
      shield: 0.3,
      potion: 0.4
    };
  }

  rollLoot() {
    const roll = Math.random();
    let cumulativeProbability = 0;

    for (const item in this.lootTable) {
      cumulativeProbability += this.lootTable[item];
      if (roll <= cumulativeProbability) {
        return item;
      }
    }

    return null; // Should never reach here due to cumulative probability
  }
}

