canvas.width = 800;
canvas.height = 600;

const gravity = 0.5;
const player = {
  x: 50,
  y: 100,
  width: 30,
  height: 50,
  velocityX: 0,
  velocityY: 0,
  onGround: false
};

const platforms = [
  { x: 0, y: 550, width: 800, height: 50 },
  { x: 200, y: 400, width: 200, height: 20 },
  { x: 500, y: 300, width: 100, height: 20 }
];

let gameState = 'menu';

const states = {
  menu: {
    update: () => {},
    draw: () => {
      ctx.fillStyle = 'black';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = 'white';
      ctx.font = '24px Arial';
      ctx.fillText('Press Enter to Start', canvas.width / 2 - 100, canvas.height / 2);
    }
  },
  playing: {
    update: () => {
      player.velocityY += gravity;
      if (player.onGround) player.velocityY = 0;

      player.x += player.velocityX;
      player.y += player.velocityY;

      if (player.y > canvas.height) {
        gameState = 'gameover';
      }

      platforms.forEach(platform => {
        if (player.x < platform.x + platform.width &&
            player.x + player.width > platform.x &&
            player.y < platform.y + platform.height &&
            player.y + player.height > platform.y) {
          player.onGround = true;
          player.velocityY = 0;
          player.y = platform.y - player.height;
        } else {
          player.onGround = false;
        }
      });
    },
    draw: () => {
      ctx.fillStyle = 'black';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = 'green';
      platforms.forEach(platform => {
        ctx.fillRect(platform.x, platform.y, platform.width, platform.height);
      });
      ctx.fillStyle = 'blue';
      ctx.fillRect(player.x, player.y, player.width, player.height);
    }
  },
  paused: {
    update: () => {},
    draw: () => {
      ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = 'white';
      ctx.font = '24px Arial';
      ctx.fillText('Paused', canvas.width / 2 - 50, canvas.height / 2);
    }
  },
  gameover: {
    update: () => {},
    draw: () => {
      ctx.fillStyle = 'black';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = 'white';
      ctx.font = '24px Arial';
      ctx.fillText('Game Over', canvas.width / 2 - 50, canvas.height / 2);
    }
  }
};

function update() {
  states[gameState].update();
}

function draw() {
  states[gameState].draw();
}

function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

canvas.addEventListener('keydown', (e) => {
  switch (e.key) {
    case 'Enter':
      if (gameState === 'menu') {
        gameState = 'playing';
      } else if (gameState === 'playing') {
        gameState = 'paused';
      } else if (gameState === 'paused') {
        gameState = 'playing';
      }
      break;
    case 'ArrowLeft':
      if (gameState === 'playing') player.velocityX = -5;
      break;
    case 'ArrowRight':
      if (gameState === 'playing') player.velocityX = 5;
      break;
    case 'ArrowUp':
      if (gameState === 'playing' && player.onGround) player.velocityY = -10;
      break;
  }
});

canvas.addEventListener('keyup', (e) => {
  if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
    player.velocityX = 0;
  }
});

gameLoop();
