const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let dpr = window.devicePixelRatio || 1;
function resizeCanvas() {
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  canvas.style.width = `${window.innerWidth}px`;
  canvas.style.height = `${window.innerHeight}px`;
}
resizeCanvas();
window.addEventListener('resize', resizeCanvas);

const boardSize = 8;
const cellSize = Math.floor(Math.min(canvas.width, canvas.height) / boardSize);
const enemySpawnRate = 1000; // Initial spawn rate in ms
let difficultyMultiplier = 1; // Increase to ramp up difficulty

class Match3Board {
  constructor(size) {
    this.size = size;
    this.board = this.initializeBoard();
    this.enemies = [];
  }

  initializeBoard() {
    const board = [];
    for (let i = 0; i < this.size; i++) {
      const row = [];
      for (let j = 0; j < this.size; j++) {
        row.push(Math.floor(Math.random() * 3) + 1); // 3 types of gems
      }
      board.push(row);
    }
    return board;
  }

  render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    this.board.forEach((row, y) => {
      row.forEach((gem, x) => {
        ctx.fillStyle = `hsl(${gem * 60}, 100%, 50%)`;
        ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
      });
    });
    this.enemies.forEach(enemy => {
      ctx.fillStyle = 'red';
      ctx.fillRect(enemy.x * cellSize, enemy.y * cellSize, cellSize, cellSize);
    });
  }

  spawnEnemy() {
    const x = Math.floor(Math.random() * this.size);
    const y = Math.floor(Math.random() * this.size);
    this.enemies.push({ x, y });
  }

  update() {
    if (Math.random() * 1000 < enemySpawnRate * difficultyMultiplier) {
      this.spawnEnemy();
    }
    this.enemies = this.enemies.filter(enemy => {
      // Simple enemy movement logic for demonstration
      if (Math.random() > 0.5) enemy.x = (enemy.x + 1) % this.size;
      else enemy.y = (enemy.y + 1) % this.size;
      return true; // Always keep enemies for simplicity
    });
    this.render();
  }
}

const board = new Match3Board(boardSize);

function gameLoop() {
  board.update();
  difficultyMultiplier += 0.001; // Gradually increase difficulty
