// Constants
const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
const FPS = 60;
const FIXED_TIMESTEP = 1000 / FPS;

// Game state
let lastTime = 0;
let accumulator = 0;
let countdown = 60; // seconds

// Entities
const enemies = [];
const towers = [];
const projectiles = [];

// Enemy class
class Enemy {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.speed = 1;
  }

  update(dt) {
    this.x -= this.speed * dt;
  }

  draw() {
    ctx.fillStyle = 'red';
    ctx.fillRect(this.x, this.y, 20, 20);
  }
}

// Tower class
class Tower {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.range = 100;
    this.fireRate = 1; // seconds
    this.lastFired = 0;
  }

  update(dt) {
    const now = performance.now() / 1000;
    if (now - this.lastFired > this.fireRate) {
      this.lastFired = now;
      this.shoot();
    }
  }

  shoot() {
    const enemy = enemies.find(e => Math.hypot(e.x - this.x, e.y - this.y) <= this.range);
    if (enemy) {
      projectiles.push(new Projectile(this.x + 10, this.y + 10, enemy.x, enemy.y));
    }
  }

  draw() {
    ctx.fillStyle = 'green';
    ctx.fillRect(this.x, this.y, 20, 20);
  }
}

// Projectile class
class Projectile {
  constructor(x, y, targetX, targetY) {
    this.x = x;
    this.y = y;
    this.targetX = targetX;
    this.targetY = targetY;
    this.speed = 5;
    this.angle = Math.atan2(targetY - y, targetX - x);
  }

  update(dt) {
    this.x += this.speed * Math.cos(this.angle) * dt;
    this.y += this.speed * Math.sin(this.angle) * dt;
  }

  draw() {
    ctx.fillStyle = 'blue';
    ctx.fillRect(this.x, this.y, 5, 5);
  }
}

// Initial setup
enemies.push(new Enemy(canvas.width, Math.random() * canvas.height));
towers.push(new Tower(100, canvas.height / 2));

// Main loop
function mainLoop(timestamp) {
  const now = timestamp;
  const dt = now - lastTime;
  lastTime = now;
  accumulator += dt;

  while (accumulator >= FIXED_TIMESTEP) {
    update(FIXED_TIMESTEP);
    accumulator -= FIXED_TIMESTEP;
  }

  render();
  requestAnimationFrame(mainLoop);
}

// Update game state
function update(dt) {
  enemies.forEach(e => e.update(dt));
  towers.forEach(t => t.update(dt));
  projectiles.forEach(p => p.update(dt));

  // Check for projectile hits
  projectiles.forEach((p, index) => {
    enemies.forEach((e, eIndex) => {
      if (Math.hypot(p.x - e.x, p.y - e.y) <= 10) {
        enemies.splice(eIndex, 1);
        projectiles.splice(index, 1);
      }
    });
  });

  // Spawn new enemies
  if (Math.random() > 0.98) {
    enemies.push(new Enemy(canvas.width, Math.random() * canvas.height));
  }

  // Countdown
  if (countdown > 0) {
    countdown -= dt;
  } else {
    alert('Game Over!');
    document.location.reload();
  }
}

// Render the game
function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.fillText(`Countdown: ${Math.ceil(countdown)}`, 10, 30);

  enemies.forEach(e => e.draw());
  towers.forEach(t => t.draw());
  projectiles.forEach(p => p.draw());
}

// Start the game loop
requestAnimationFrame(mainLoop);
