class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Bank {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('deposit', this.deposit.bind(this));
    this.eventBus.subscribe('withdraw', this.withdraw.bind(this));
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      console.log(`Deposited: ${amount}, New Balance: ${this.balance}`);
      this.eventBus.emit('balanceUpdated', this.balance);
    } else {
      console.log('Deposit amount must be positive.');
    }
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      console.log(`Withdrew: ${amount}, New Balance: ${this.balance}`);
      this.eventBus.emit('balanceUpdated', this.balance);
    } else {
      console.log('Insufficient funds or invalid amount.');
    }
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.prices = { apple: 1, banana: 2, carrot: 3 };
    this.eventBus.subscribe('buy', this.buy.bind(this));
  }

  buy(item, quantity) {
    const price = this.prices[item];
    if (price && quantity > 0) {
      const totalCost = price * quantity;
      this.eventBus.emit('withdraw', totalCost);
      console.log(`Bought ${quantity} ${item}(s) for ${totalCost}.`);
    } else {
      console.log('Invalid item or quantity.');
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = { apple: 0, banana: 0, carrot: 0 };
    this.eventBus.subscribe('balanceUpdated', this.checkAffordability.bind(this));
  }

  checkAffordability(balance) {
    if (balance >= this.prices.apple) {
      this.eventBus.emit('buy', 'apple', 1);
    }
  }

  getItems() {
    return this.items;
  }
}

