class Quest {
    constructor() {
        this.tasks = {};
    }

    addTask(key, description) {
        this.tasks[key] = { description, completed: false };
    }

    completeTask(key) {
        if (this.tasks[key]) {
            this.tasks[key].completed = true;
        }
    }

    getTaskStatus(key) {
        return this.tasks[key] ? this.tasks[key].completed : false;
    }
}

class GameCoordinator {
