        this.dialogue = new Dialogue();
        this.flags = new Flags();
        this.quest = new Quest();

        // Wire up interactions
        this.dialogue.addResponse('greet', () => {
            console.log("Hello! How can I help you today?");
            this.flags.setFlag('greeted', true);
        });

        this.dialogue.addResponse('questStatus', () => {
            const questCompleted = this.quest.getTaskStatus('fetchApple');
            console.log(questCompleted ? "You have completed the quest!" : "You need to fetch an apple.");
        });

        this.dialogue.addResponse('completeQuest', () => {
            if (!this.flags.getFlag('greeted')) {
                console.log("Please greet me first!");
                return;
            }
            if (this.flags.getFlag('appleFetched')) {
                this.quest.completeTask('fetchApple');
                console.log("Thank you for fetching the apple. Quest completed!");
            } else {
