            }
        });

        this.dialogue.addResponse('fetchApple', () => {
            console.log("Go fetch an apple!");
            this.flags.setFlag('appleFetched', true);
        });
    }

    interact(input) {
        const response = this.dialogue.getResponse(input);
        if (typeof response === 'function') {
            response();
        } else {
            console.log(response);
        }
    }
}

