const COLS = canvas.width / BLOCK_SIZE;
const ROWS = canvas.height / BLOCK_SIZE;
const colors = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#00FFFF', '#FF00FF'];

class Block {
  constructor(x, y, color) {
    this.x = x;
    this.y = y;
    this.color = color;
  }

  draw() {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x * BLOCK_SIZE, this.y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
    ctx.strokeStyle = '#000';
    ctx.strokeRect(this.x * BLOCK_SIZE, this.y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
  }

  moveLeft() {
    this.x = Math.max(0, this.x - 1);
  }

  moveRight() {
    this.x = Math.min(COLS - 1, this.x + 1);
  }

  fall() {
    this.y++;
  }
}

let currentBlock;
let gameLoop;
let gameSpeed = 1000;

function generateBlock() {
  const x = Math.floor(COLS / 2);
  const y = 0;
  const color = colors[Math.floor(Math.random() * colors.length)];
  return new Block(x, y, color);
}

function checkCollision(block, blocks) {
  if (block.y >= ROWS) return true;
  for (let b of blocks) {
    if (block.x === b.x && block.y + 1 === b.y) {
      return true;
    }
  }
  return false;
}

function clearFullRows(blocks) {
  let newBlocks = [];
  for (let y = ROWS - 1; y >= 0; y--) {
    let rowFull = true;
    for (let x = 0; x < COLS; x++) {
      if (!blocks.some(b => b.x === x && b.y === y)) {
        rowFull = false;
        break;
      }
    }
    if (!rowFull) {
      for (let b of blocks) {
        if (b.y < y) {
          b.y++;
        }
        newBlocks.push(b);
      }
    }
  }
  return newBlocks;
}

function drawBoard(blocks) {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  blocks.forEach(block => block.draw());
  currentBlock.draw();
}

function update() {
  if (checkCollision(currentBlock, blocks)) {
    blocks.push(currentBlock);
    currentBlock = generateBlock();
    blocks = clearFullRows(blocks);
    gameSpeed = Math.max(500, gameSpeed - 50);
  } else {
    currentBlock.fall();
  }
}

function aiMove(blocks) {
  const testBlock = new Block(currentBlock.x, currentBlock.y, currentBlock.color);
  while (!checkCollision(testBlock, blocks)) {
    testBlock.fall();
  }
  testBlock.y--;

  let bestMove = { x: currentBlock.x, score: 0 };
  for (let x = 0; x < COLS; x++) {
    testBlock.x = x;
    let score = 0;
    for (let y = 0; y < ROWS; y++) {
      if (blocks.some(b => b.x === x && b.y === y)) {
        score += ROWS - y;
        break;
      }
    }
    if (score > bestMove.score) {
      bestMove = { x, score };
    }
  }
  currentBlock.x = bestMove.x;
}

function gameLoopFunction() {
  aiMove(blocks);
  update();
  drawBoard(blocks);
  gameLoop = requestAnimationFrame(gameLoopFunction);
}

let blocks = [];
currentBlock = generateBlock();
gameLoopFunction();

canvas.addEventListener('keydown', e => {
  if (e.key === 'ArrowLeft') {
    currentBlock.moveLeft();
  } else if (e.key === 'ArrowRight') {
    currentBlock.moveRight();
  } else if (e.key === 'ArrowDown') {
    currentBlock.fall();
    update();
    drawBoard(blocks);
  }
});
