class Economy {
  constructor(prices) {
    this.prices = prices;
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }

  debit(amount) {
    if (amount > this.balance) {
      throw new Error("Insufficient funds");
    }
    this.balance -= amount;
  }

  credit(amount) {
    this.balance += amount;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

class Recipe {
  constructor(name, ingredients, output) {
    this.name = name;
    this.ingredients = ingredients;
    this.output = output;
  }

  isCraftable(inventory) {
    for (const [item, quantity] of Object.entries(this.ingredients)) {
      if (inventory.getItemCount(item) < quantity) {
        return false;
      }
    }
    return true;
  }

  craft(inventory) {
    for (const [item, quantity] of Object.entries(this.ingredients)) {
      inventory.addItem(item, -quantity);
    }
    inventory.addItem(this.output);
  }
}

class Crafting {
  constructor(inventory, recipeBook) {
    this.inventory = inventory;
    this.recipeBook = recipeBook;
  }

  canCraft(recipeName) {
    const recipe = this.recipeBook[recipeName];
    if (!recipe) {
      throw new Error(`Recipe ${recipeName} not found`);
    }
    return recipe.isCraftable(this.inventory);
  }

  craft(recipeName) {
    const recipe = this.recipeBook[recipeName];
    if (!recipe) {
      throw new Error(`Recipe ${recipeName} not found`);
    }
    if (!this.canCraft(recipeName)) {
      throw new Error(`Insufficient ingredients to craft ${recipeName}`);
    }
    recipe.craft(this.inventory);
  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
  }

  purchase(item) {
    const price = this.economy.getPrice(item);
    if (price === 0) {
      throw new Error(`Item ${item} not available in store`);
    }
    this.economy.debit(price);
    this.inventory.addItem(item);
  }
}

// Demo
