const economy = new Economy(prices);
economy.credit(100); // Give the player some starting money

const inventory = new Inventory();

const recipeBook = {
  sword: new Recipe("sword", { wood: 1, iron: 1 }, "sword"),
};

const crafting = new Crafting(inventory, recipeBook);

const store = new Store(economy, inventory);

// Player buys materials from the store
