const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

const cardWidth = 100;
const cardHeight = 150;
const margin = 20;
let cards = [];
let flippedCards = [];
let matchedPairs = 0;
let enemies = [];
let enemySpawnRate = 2000;
let enemySpeed = 2;
let startTime = Date.now();

function createCard(x, y, value) {
  return {
    x, y,
    value,
    flipped: false,
    matched: false,
    render() {
      ctx.fillStyle = this.flipped || this.matched ? '#333' : '#fff';
      ctx.fillRect(this.x, this.y, cardWidth, cardHeight);
      if (this.flipped) {
        ctx.fillStyle = '#fff';
        ctx.font = '24px Arial';
        ctx.fillText(this.value, this.x + cardWidth / 2 - 10, this.y + cardHeight / 2 + 10);
      }
    },
    checkCollision(x, y) {
      return x > this.x && x < this.x + cardWidth && y > this.y && y < this.y + cardHeight;
    }
  };
}

function spawnEnemy() {
  const enemy = {
    x: canvas.width,
    y: Math.random() * (canvas.height - cardHeight),
    render() {
      ctx.fillStyle = 'red';
      ctx.fillRect(this.x, this.y, cardWidth, cardHeight);
      this.x -= enemySpeed;
    }
  };
  enemies.push(enemy);
  setTimeout(spawnEnemy, enemySpawnRate);
}

function createBoard() {
  const values = ['A', 'A', 'B', 'B', 'C', 'C', 'D', 'D', 'E', 'E', 'F', 'F'];
  for (let i = 0; i < values.length; i++) {
    const x = (i % 4) * (cardWidth + margin) + margin;
    const y = Math.floor(i / 4) * (cardHeight + margin) + margin;
    cards.push(createCard(x, y, values[i]));
  }
}

function update() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  cards.forEach(card => card.render());
  enemies.forEach(enemy => enemy.render());

  if (Date.now() - startTime > 10000) {
    enemySpawnRate -= 100;
    enemySpeed += 0.1;
    startTime = Date.now();
  }

  requestAnimationFrame(update);
}

function checkForMatch() {
  if (flippedCards.length === 2) {
    if (flippedCards[0].value === flippedCards[1].value) {
      flippedCards.forEach(card => card.matched = true);
      matchedPairs++;
    } else {
      flippedCards.forEach(card => card.flipped = false);
    }
    flippedCards = [];
  }
}

canvas.addEventListener('click', (e) => {
  const { offsetX, offsetY } = e;
  cards.forEach(card => {
    if (!card.matched && card.checkCollision(offsetX, offsetY)) {
      card.flipped = true;
      flippedCards.push(card);
      checkForMatch();
    }
  });
});

createBoard();
spawnEnemy();
update();
