class Economy {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (quantity > 0) {
      if (this.items[item]) {
        this.items[item] += quantity;
      } else {
        this.items[item] = quantity;
      }
      return true;
    }
    return false;
  }

  removeItem(item, quantity = 1) {
    if (quantity > 0 && this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
    this.prices = {};
  }

  setPrice(item, price) {
    if (price > 0) {
      this.prices[item] = price;
      return true;
    }
    return false;
  }

  buyItem(item, quantity = 1) {
    const price = this.prices[item];
    if (price && this.inventory.addItem(item, quantity) && this.economy.withdraw(price * quantity)) {
      return true;
    }
    return false;
  }

  sellItem(item, quantity = 1) {
    const price = this.prices[item];
    if (price && this.inventory.removeItem(item, quantity) && this.economy.deposit(price * quantity)) {
      return true;
    }
    return false;
  }
}

// Demo
const economy = new Economy(100);
const inventory = new Inventory();
const store = new Store(economy, inventory);

store.setPrice('sword', 20);
store.setPrice('potion', 10);

console.log('Initial Balance:', economy.getBalance()); // 100
console.log('Initial Inventory:', inventory.items); // {}

console.log('Buying 1 sword:', store.buyItem('sword')); // true
console.log('Buying 2 potions:', store.buyItem('potion', 2)); // true

console.log('Balance after purchases:', economy.getBalance()); // 60
console.log('Inventory after purchases:', inventory.items); // { sword: 1, potion: 2 }

console.log('Selling 1 potion:', store.sellItem('potion')); // true

console.log('Balance after sale:', economy.getBalance()); // 70
console.log('Inventory after sale:', inventory.items); // { sword: 1, potion: 1 }
