const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

canvas.width = 800;
canvas.height = 600;

const fixedTimestep = 1000 / 60; // 60 FPS
let lastTimestamp = 0;
let highScore = parseInt(localStorage.getItem('highScore')) || 0;
let currentScore = 0;
let isPlaying = false;
let tapPosition = { x: 0, y: 0 };
let tapTarget = { x: canvas.width / 2, y: canvas.height / 2 };
let tapRadius = 50;
let tapCooldown = 0;

function mainLoop(timestamp) {
    const deltaTime = timestamp - lastTimestamp;
    lastTimestamp = timestamp;

    update(deltaTime);
    render();

    if (isPlaying) {
        requestAnimationFrame(mainLoop);
    }
}

function update(deltaTime) {
    if (tapCooldown > 0) {
        tapCooldown -= deltaTime;
    }

    if (Math.abs(tapPosition.x - tapTarget.x) < tapRadius && Math.abs(tapPosition.y - tapTarget.y) < tapRadius && tapCooldown <= 0) {
        currentScore++;
        tapCooldown = 500; // 500ms cooldown
        tapTarget = {
            x: Math.random() * canvas.width,
            y: Math.random() * canvas.height
        };
    }

    if (currentScore > highScore) {
        highScore = currentScore;
        localStorage.setItem('highScore', highScore);
    }
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = 'lightgray';
    ctx.beginPath();
    ctx.arc(tapTarget.x, tapTarget.y, tapRadius, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = 'black';
    ctx.font = '24px Arial';
    ctx.fillText(`Score: ${currentScore}`, 10, 30);
    ctx.fillText(`High Score: ${highScore}`, 10, 60);
}

function startGame() {
    isPlaying = true;
    currentScore = 0;
    lastTimestamp = performance.now();
    requestAnimationFrame(mainLoop);
}

function handleTap(event) {
    const rect = canvas.getBoundingClientRect();
    tapPosition = {
        x: event.clientX - rect.left,
        y: event.clientY - rect.top
    };

    if (!isPlaying) {
        startGame();
    }
}

canvas.addEventListener('click', handleTap);
canvas.addEventListener('touchstart', (event) => {
    event.preventDefault();
    const touch = event.touches[0];
    handleTap(touch);
});
