        const pricePerItem = this.economy.getPrice(item);
        const totalCost = pricePerItem * quantity;

        if (this.economy.debit(totalCost)) {
            this.addItemToInventory(item, quantity);
            console.log(`Bought ${quantity} ${item}(s) for ${totalCost}. New balance: ${this.economy.getBalance()}`);
