// Tap Event
let lastTap = 0;
const tapThreshold = 300; // milliseconds

function handleTap(event) {
    const now = Date.now();
    if (now - lastTap > tapThreshold) {
        lastTap = now;
        createParticles(event.clientX, event.clientY);
    }
}

