class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
    this.inventory = {};
  }

  purchase(item, quantity) {
    const price = this.pricing.getPrice(item);
    const availableDemand = this.demand.getDemand(item);

    if (quantity > availableDemand) {
      console.log(`Not enough demand for ${quantity} ${item}. Available demand: ${availableDemand}`);
      return false;
    }

    if (quantity > 0) {
      this.demand.setDemand(item, availableDemand - quantity);
      this.inventory[item] = (this.inventory[item] || 0) + quantity;
      console.log(`Purchased ${quantity} ${item} for ${price * quantity}.`);
      return true;
    } else {
      console.log(`Invalid purchase quantity: ${quantity}`);
      return false;
    }
  }

  getInventory() {
    return { ...this.inventory };
  }
}

