const ctx = canvas.getContext('2d');

const player = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    size: 20,
    speed: 5
};

const enemies = [];
const numEnemies = 5;
for (let i = 0; i < numEnemies; i++) {
    enemies.push({
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        size: 15,
        speed: 3
    });
}

const maze = [];
const mazeSize = 20;
const mazeCellSize = canvas.width / mazeSize;
for (let i = 0; i < mazeSize; i++) {
    maze.push([]);
    for (let j = 0; j < mazeSize; j++) {
        maze[i].push(Math.random() > 0.7 ? 1 : 0);
    }
}

let highScore = localStorage.getItem('highScore') || 0;
let score = 0;
let lastTime = 0;
const fixedTimeStep = 1000 / 60;

function update(dt) {
    const keys = Object.keys(input.keysDown);
    const velocity = { x: 0, y: 0 };

    if (keys.includes('ArrowUp') || keys.includes('w')) velocity.y = -player.speed;
    if (keys.includes('ArrowDown') || keys.includes('s')) velocity.y = player.speed;
    if (keys.includes('ArrowLeft') || keys.includes('a')) velocity.x = -player.speed;
    if (keys.includes('ArrowRight') || keys.includes('d')) velocity.x = player.speed;

    player.x += velocity.x * dt;
    player.y += velocity.y * dt;

    enemies.forEach(enemy => {
        const dx = player.x - enemy.x;
        const dy = player.y - enemy.y;
        const distance = Math.sqrt(dx * dx + dy * dy);
        if (distance < player.size + enemy.size) {
            alert('Game Over! Your score: ' + score);
            if (score > highScore) {
                highScore = score;
                localStorage.setItem('highScore', highScore);
            }
            document.location.reload();
        }
        enemy.x += (player.x - enemy.x) * enemy.speed * dt / distance;
        enemy.y += (player.y - enemy.y) * enemy.speed * dt / distance;
    });

    score += dt;
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = 'black';
    maze.forEach((row, y) => {
        row.forEach((cell, x) => {
            if (cell) {
                ctx.fillRect(x * mazeCellSize, y * mazeCellSize, mazeCellSize, mazeCellSize);
            }
        });
    });

    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x - player.size / 2, player.y - player.size / 2, player.size, player.size);

