const cardWidth = 100;
const cardHeight = 150;
const margin = 10;
const grid = { rows: 4, cols: 4 };
const cards = [];
let flippedCards = [];
let matchedPairs = 0;
let enemyCount = 0;
let enemySpawnInterval = 2000; // milliseconds

class Card {
    constructor(x, y, value) {
        this.x = x;
        this.y = y;
        this.value = value;
        this.flipped = false;
    }

    draw() {
        ctx.beginPath();
        ctx.rect(this.x, this.y, cardWidth, cardHeight);
        ctx.strokeStyle = 'black';
        ctx.stroke();
        if (this.flipped) {
            ctx.fillStyle = 'lightblue';
            ctx.fillRect(this.x, this.y, cardWidth, cardHeight);
            ctx.fillStyle = 'black';
            ctx.font = '20px Arial';
            ctx.fillText(this.value, this.x + 20, this.y + 50);
        }
    }

    flip() {
        this.flipped = true;
    }

    unflip() {
        this.flipped = false;
    }
}

function createBoard() {
    const values = [];
    for (let i = 1; i <= (grid.rows * grid.cols) / 2; i++) {
        values.push(i, i);
    }
    values.sort(() => Math.random() - 0.5);

    for (let row = 0; row < grid.rows; row++) {
        for (let col = 0; col < grid.cols; col++) {
            const x = col * (cardWidth + margin);
            const y = row * (cardHeight + margin);
            const value = values[row * grid.cols + col];
            cards.push(new Card(x, y, value));
        }
    }
}

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    cards.forEach(card => card.draw());
}

function checkForMatch() {
    if (flippedCards.length === 2) {
        const [card1, card2] = flippedCards;
        if (card1.value === card2.value) {
            matchedPairs++;
        } else {
            setTimeout(() => {
                card1.unflip();
                card2.unflip();
                flippedCards = [];
            }, 1000);
        }
        flippedCards = [];
    }
}

function handleMouseClick(event) {
    const { offsetX, offsetY } = event;
    const card = cards.find(c => offsetX >= c.x && offsetX <= c.x + cardWidth &&
                                  offsetY >= c.y && offsetY <= c.y + cardHeight);
    if (card && !card.flipped) {
        card.flip();
        flippedCards.push(card);
        checkForMatch();
        if (matchedPairs === (grid.rows * grid.cols) / 2) {
            alert('You won!');
            resetGame();
        }
    }
}

canvas.addEventListener('click', handleMouseClick);

function spawnEnemy() {
    enemyCount++;
    const value = Math.floor(Math.random() * 10) + 1;
    const row = Math.floor(Math.random() * grid.rows);
    const col = Math.floor(Math.random() * grid.cols);
    const x = col * (cardWidth + margin);
    const y = row * (cardHeight + margin);
    const enemyCard = new Card(x, y, value);
    enemyCard.flip();
    cards.push(enemyCard);
    setTimeout(() => {
        cards = cards.filter(c => c !== enemyCard);
        drawBoard();
    }, 2000);
    if (enemyCount % 5 === 0) {
        enemySpawnInterval -= 500;
        enemySpawnInterval = Math.max(enemySpawnInterval, 1000);
    }
    setTimeout(spawnEnemy, enemySpawnInterval);
}

function resetGame() {
    cards.length = 0;
    flippedCards.length = 0;
    matchedPairs = 0;
    enemyCount = 0;
    createBoard();
    spawnEnemy();
}

createBoard();
spawnEnemy();
drawBoard();

function gameLoop() {
    drawBoard();
    requestAnimationFrame(gameLoop);
}

gameLoop();
