const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
const ctx = canvas.getContext('2d');

let score = 0;
let highScore = localStorage.getItem('highScore') ? parseInt(localStorage.getItem('highScore')) : 0;
const player = { x: 50, y: canvas.height / 2, width: 20, height: 20, speed: 5, jumping: false, jumpHeight: 10 };
const obstacles = [];
const obstacleWidth = 20;
const obstacleHeight = 50;
const obstacleSpeed = 5;
const jumpCooldown = 10;
let jumpTimer = 0;

function drawPlayer() {
    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x, player.y, player.width, player.height);
}

function drawObstacles() {
    ctx.fillStyle = 'red';
    obstacles.forEach(obstacle => {
        ctx.fillRect(obstacle.x, obstacle.y, obstacleWidth, obstacleHeight);
    });
}

function drawScore() {
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
    ctx.fillText(`High Score: ${highScore}`, 10, 50);
}

function updatePlayer() {
    if (player.jumping) {
        player.y -= player.jumpHeight;
        player.jumpHeight -= 1;
        if (player.jumpHeight <= -10) {
            player.jumping = false;
            player.jumpHeight = 10;
        }
    } else {
        player.y += 5;
        if (player.y + player.height > canvas.height) {
            player.y = canvas.height - player.height;
        }
    }
}

function updateObstacles() {
    obstacles.forEach(obstacle => {
        obstacle.x -= obstacleSpeed;
    });
    if (obstacles.length === 0 || obstacles[obstacles.length - 1].x < canvas.width - 200) {
        const y = Math.random() * (canvas.height - obstacleHeight);
        obstacles.push({ x: canvas.width, y: y });
    }
}

function checkCollision() {
    for (let i = 0; i < obstacles.length; i++) {
        const obstacle = obstacles[i];
        if (player.x < obstacle.x + obstacleWidth &&
            player.x + player.width > obstacle.x &&
            player.y < obstacle.y + obstacleHeight &&
            player.y + player.height > obstacle.y) {
            if (score > highScore) {
                localStorage.setItem('highScore', score);
                highScore = score;
            }
            location.reload();
        }
    }
}

function update() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    updatePlayer();
    updateObstacles();
    checkCollision();
    drawPlayer();
    drawObstacles();
    drawScore();
    requestAnimationFrame(update);
}

function jump() {
    if (!player.jumping && jumpTimer <= 0) {
        player.jumping = true;
        jumpTimer = jumpCooldown;
    }
}

function resetGame() {
    score = 0;
    obstacles.length = 0;
    player.x = 50;
    player.y = canvas.height / 2;
    player.jumping = false;
    player.jumpHeight = 10;
