class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, callback) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(callback);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(callback => callback(data));
    }
  }
}

class Skill {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.skills = {};
    this.eventBus.subscribe('levelUp', this.levelUp.bind(this));
  }

  learn(skillName, points) {
    if (!this.skills[skillName]) {
      this.skills[skillName] = 0;
    }
    this.skills[skillName] += points;
    console.log(`Learned ${skillName}: ${this.skills[skillName]} points`);
  }

  levelUp() {
    console.log('Skill: Player leveled up, skill points increased by 10');
    for (const skill in this.skills) {
      this.skills[skill] += 10;
    }
    console.log(`Skills after level up:`, this.skills);
  }
}

class Experience {
