const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const FPS = 60;
const FIXED_TIMESTEP = 1000 / FPS;
let accumulator = 0;

let gameOver = false;
let score = 0;
let lives = 5;

const enemies = [];
const bullets = [];
const towers = [];

function createTower(x, y) {
    towers.push({ x, y, range: 100, fireRate: 1000, lastFire: Date.now() });
}

function createEnemy() {
    const x = canvas.width;
    const y = Math.random() * (canvas.height - 20) + 10;
    enemies.push({ x, y, speed: 2, size: 10, hitPoints: 5 });
}

function update(dt) {
    if (gameOver) return;

    // Enemy movement
    enemies.forEach(enemy => {
        enemy.x -= enemy.speed * dt;
        if (enemy.x < 0) {
            lives--;
            enemies.splice(enemies.indexOf(enemy), 1);
            if (lives <= 0) {
                gameOver = true;
            }
        }
    });

    // Tower shooting
    towers.forEach(tower => {
        const now = Date.now();
        if (now - tower.lastFire > tower.fireRate) {
            tower.lastFire = now;
            const target = enemies.find(e => Math.hypot(e.x - tower.x, e.y - tower.y) < tower.range);
            if (target) {
                bullets.push({ x: tower.x, y: tower.y, target, speed: 5 });
            }
        }
    });

    // Bullet movement and collision detection
    bullets.forEach(bullet => {
        const dx = bullet.target.x - bullet.x;
        const dy = bullet.target.y - bullet.y;
        const distance = Math.hypot(dx, dy);
        const moveX = dx / distance * bullet.speed;
        const moveY = dy / distance * bullet.speed;
        bullet.x += moveX;
        bullet.y += moveY;

        if (Math.hypot(bullet.x - bullet.target.x, bullet.y - bullet.target.y) < bullet.target.size) {
            bullet.target.hitPoints--;
            if (bullet.target.hitPoints <= 0) {
                enemies.splice(enemies.indexOf(bullet.target), 1);
                score += 100;
            }
            bullets.splice(bullets.indexOf(bullet), 1);
        }
    });
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw towers
    towers.forEach(tower => {
        ctx.fillStyle = 'blue';
        ctx.fillRect(tower.x, tower.y, 10, 10);
    });

    // Draw enemies
    enemies.forEach(enemy => {
        ctx.fillStyle = 'red';
        ctx.fillRect(enemy.x, enemy.y, enemy.size, enemy.size);
    });

    // Draw bullets
    bullets.forEach(bullet => {
        ctx.fillStyle = 'green';
        ctx.fillRect(bullet.x, bullet.y, 3, 3);
    });

    // Draw score and lives
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
    ctx.fillText(`Lives: ${lives}`, 10, 60);

    if (gameOver) {
        ctx.fillStyle = 'red';
        ctx.font = '40px Arial';
        ctx.fillText('Game Over', canvas.width / 2 - 100, canvas.height / 2);
    }
}

function gameLoop(timestamp) {
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    accumulator += dt;

    while (accumulator >= FIXED_TIMESTEP) {
        update(FIXED_TIMESTEP);
        accumulator -= FIXED_TIMESTEP;
    }

    draw();

    requestAnimationFrame(gameLoop);
}

