// Constants for the game
const CANVAS_ID = 'gameCanvas';
const TIMER_DURATION = 30; // seconds
const UNIT_SIZE = 50;
const FPS = 60;

// Game state
let canvas, ctx;
let player1, player2;
let timer;
let isGameOver = false;

// Player class
class Player {
    constructor(x, y, color) {
        this.x = x;
        this.y = y;
        this.color = color;
    }

    draw() {
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x, this.y, UNIT_SIZE, UNIT_SIZE);
    }

    move(dx, dy) {
        this.x += dx;
        this.y += dy;
    }
}

// Initialize game
function init() {
    canvas = document.getElementById(CANVAS_ID);
    ctx = canvas.getContext('2d');

    // Handle devicePixelRatio
    const dpr = window.devicePixelRatio || 1;
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    ctx.scale(dpr, dpr);

    // Create players
    player1 = new Player(50, 50, 'blue');
    player2 = new Player(canvas.width - 100, canvas.height - 100, 'red');

    // Start timer
    timer = TIMER_DURATION;
    setInterval(updateTimer, 1000);

    // Start game loop
    requestAnimationFrame(gameLoop);
}

// Update timer
function updateTimer() {
    if (timer > 0) {
        timer--;
    } else {
        isGameOver = true;
    }
}

// Game loop
function gameLoop() {
    if (isGameOver) {
        endGame();
        return;
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    player1.draw();
    player2.draw();

    requestAnimationFrame(gameLoop);
}

// Handle keydown events
function handleKeyDown(event) {
    const speed = UNIT_SIZE;
    switch (event.key) {
        case 'ArrowUp':
            player1.move(0, -speed);
            break;
        case 'ArrowDown':
            player1.move(0, speed);
            break;
        case 'ArrowLeft':
            player1.move(-speed, 0);
            break;
        case 'ArrowRight':
            player1.move(speed, 0);
            break;
        case 'w':
            player2.move(0, -speed);
            break;
        case 's':
            player2.move(0, speed);
            break;
        case 'a':
            player2.move(-speed, 0);
            break;
        case 'd':
            player2.move(speed, 0);
            break;
    }
}

// End game
function endGame() {
    ctx.fillStyle = 'black';
    ctx.font = '48px Arial';
    ctx.fillText('Game Over', canvas.width / 2 - 100, canvas.height / 2);
}

// Event listeners
document.addEventListener('DOMContentLoaded', init);
document.addEventListener('keydown', handleKeyDown);
