const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const player = {
  x: 100,
  y: 100,
  width: 32,
  height: 32,
  velocityX: 0,
  velocityY: 0,
  gravity: 0.5,
  jumpForce: -10,
  grounded: false,
  color: 'blue',
};

const platforms = [
  { x: 0, y: 560, width: 800, height: 40 },
  { x: 200, y: 460, width: 100, height: 20 },
  { x: 400, y: 360, width: 150, height: 30 },
];

const particles = [];

const fixedTimeStep = 1 / 60;
let accumulator = 0;
let lastTime = performance.now();

function update(deltaTime) {
  player.velocityY += player.gravity;
  player.x += player.velocityX * deltaTime;
  player.y += player.velocityY * deltaTime;

  player.grounded = false;
  for (const platform of platforms) {
    if (
      player.x < platform.x + platform.width &&
      player.x + player.width > platform.x &&
      player.y < platform.y + platform.height &&
      player.y + player.height > platform.y
    ) {
      if (player.velocityY > 0) {
        player.y = platform.y - player.height;
        player.velocityY = 0;
        player.grounded = true;
      }
    }
  }

  if (player.y > canvas.height) {
    player.y = 100;
    player.x = 100;
    player.velocityY = 0;
    createParticleBurst(player.x, player.y);
  }

  accumulator += deltaTime;
  while (accumulator >= fixedTimeStep) {
    updatePlayerInput();
    updatePhysics(fixedTimeStep);
    accumulator -= fixedTimeStep;
  }
}

function updatePlayerInput() {
  if (keys['ArrowLeft']) {
    player.velocityX = -5;
  } else if (keys['ArrowRight']) {
    player.velocityX = 5;
  } else {
    player.velocityX = 0;
  }

  if (keys['ArrowUp'] && player.grounded) {
    player.velocityY = player.jumpForce;
    createParticleBurst(player.x, player.y);
  }
}

function updatePhysics(timeStep) {
  player.x += player.velocityX * timeStep;
  player.y += player.velocityY * timeStep;
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = 'green';
  for (const platform of platforms) {
    ctx.fillRect(platform.x, platform.y, platform.width, platform.height);
  }

  ctx.fillStyle = player.color;
  ctx.fillRect(player.x, player.y, player.width, player.height);

  ctx.fillStyle = 'red';
  for (const particle of particles) {
    ctx.fillRect(particle.x, particle.y, particle.size, particle.size);
  }
}

function createParticleBurst(x, y) {
  for (let i = 0; i < 10; i++) {
    particles.push({
      x: x,
      y: y,
      size: Math.random() * 2 + 1,
      velocityX: (Math.random() - 0.5) * 5,
      velocityY: (Math.random() - 0.5) * 5,
    });
  }
}

function updateParticles(deltaTime) {
  for (let i = particles.length - 1; i >= 0; i--) {
    particles[i].x += particles[i].velocityX * deltaTime;
    particles[i].y += particles[i].velocityY * deltaTime;
    particles[i].velocityY += 0.1 * deltaTime;

    if (particles[i].y > canvas.height) {
      particles.splice(i, 1);
    }
  }
}

function gameLoop() {
  const now = performance.now();
  const deltaTime = (now - lastTime) / 1000;
  lastTime = now;

  update(deltaTime);
  updateParticles(deltaTime);
  render();

  requestAnimationFrame(gameLoop);
