class Recipe {
  constructor(name, ingredients, result) {
    this.name = name;
    this.ingredients = ingredients;
    this.result = result;
  }

  getName() {
    return this.name;
  }

  getIngredients() {
    return this.ingredients;
  }

  getResult() {
    return this.result;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  hasItems(items) {
    for (const [item, quantity] of Object.entries(items)) {
      if (!this.items[item] || this.items[item] < quantity) {
        return false;
      }
    }
    return true;
  }

  getItems() {
    return { ...this.items };
  }
}

class Crafting {
  constructor() {
    this.recipes = [];
  }

  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  canCraft(recipeName, inventory) {
    const recipe = this.recipes.find(r => r.getName() === recipeName);
    if (recipe) {
      return inventory.hasItems(recipe.getIngredients());
    }
    return false;
  }

  craft(recipeName, inventory) {
    const recipe = this.recipes.find(r => r.getName() === recipeName);
    if (recipe && inventory.hasItems(recipe.getIngredients())) {
      for (const [item, quantity] of Object.entries(recipe.getIngredients())) {
        inventory.removeItem(item, quantity);
      }
      inventory.addItem(recipe.getResult());
      return true;
    }
    return false;
  }
}

