const particles = [];
const maxParticles = 100;

function createParticle(x, y) {
    if (particles.length < maxParticles) {
        particles.push({
            x: x,
            y: y,
            size: Math.random() * 5 + 2,
            color: `hsl(${Math.random() * 360}, 100%, 50%)`,
            vx: (Math.random() - 0.5) * 5,
            vy: (Math.random() - 0.5) * 5,
            lifespan: Math.random() * 50 + 50
        });
    }
}

function updateParticles() {
    for (let i = particles.length - 1; i >= 0; i--) {
        const p = particles[i];
        p.x += p.vx;
        p.y += p.vy;
        p.lifespan--;
        if (p.lifespan <= 0) {
            particles.splice(i, 1);
        }
    }
}

function drawParticles() {
    ctx.globalCompositeOperation = 'lighter';
    for (const p of particles) {
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fillStyle = p.color;
        ctx.fill();
    }
    ctx.globalCompositeOperation = 'source-over';
}

function drawFish() {
    ctx.beginPath();
    ctx.arc(fish.x, fish.y, fish.size, 0, Math.PI * 2);
    ctx.fillStyle = fish.color;
    ctx.fill();
}

function updateFish() {
    fish.x += Math.random() * fish.speed - fish.speed / 2;
    fish.y += Math.random() * fish.speed - fish.speed / 2;
}

function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    updateParticles();
    drawParticles();
    updateFish();
    drawFish();
    requestAnimationFrame(gameLoop);
}

function handleMouseMove(e) {
    const rect = canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) * devicePixelRatio;
    const y = (e.clientY - rect.top) * devicePixelRatio;
    if (Math.hypot(x - fish.x, y - fish.y) < fish.size) {
        createParticle(fish.x, fish.y);
    }
}

