class Trade {
  constructor(itemDatabase) {
    this.itemDatabase = itemDatabase;
  }

  getItemPrice(itemName) {
    const item = this.itemDatabase.find(item => item.name === itemName);
    return item ? item.price : null;
  }

  tradeItem(buyer, seller, itemName, quantity) {
    const price = this.getItemPrice(itemName);
    if (!price) {
      console.log(`Item ${itemName} not found.`);
      return false;
    }

    const totalCost = price * quantity;
    if (buyer.balance < totalCost) {
      console.log(`${buyer.name} does not have enough money to buy ${quantity} of ${itemName}.`);
      return false;
    }

    buyer.balance -= totalCost;
    seller.balance += totalCost;
    console.log(`${buyer.name} bought ${quantity} of ${itemName} from ${seller.name} for ${totalCost}.`);
    return true;
  }
}

