  ctx.fillText(`Final Score: ${score}`, canvas.width / 2, canvas.height / 2 + 20);
}

function updatePlaying() {
  if (catchTimer) {
    const elapsed = Date.now() - catchTimer;
    if (elapsed > 2000) {
      score += 10;
      catchTimer = null;
      fishPosition = { x: Math.random() * canvas.width, y: Math.random() * (canvas.height - 200) + 100 };
