class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Economy {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;

    this.eventBus.subscribe('transaction', this.handleTransaction.bind(this));
  }

  deposit(amount) {
    this.balance += amount;
    this.eventBus.emit('balanceUpdated', this.balance);
  }

  withdraw(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      this.eventBus.emit('balanceUpdated', this.balance);
      return true;
    }
    return false;
  }

  handleTransaction(transaction) {
    if (transaction.type === 'buy') {
      this.withdraw(transaction.amount);
    } else if (transaction.type === 'sell') {
      this.deposit(transaction.amount);
    }
  }

  getBalance() {
    return this.balance;
  }
}

class Store {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {
      sword: { price: 50 },
      shield: { price: 30 }
    };
  }

  buyItem(itemName) {
    const item = this.items[itemName];
    if (item) {
      this.eventBus.emit('transaction', { type: 'buy', amount: item.price });
      return true;
    }
    return false;
  }

  sellItem(itemName, price) {
    this.eventBus.emit('transaction', { type: 'sell', amount: price });
  }

  getItemPrice(itemName) {
    return this.items[itemName] ? this.items[itemName].price : null;
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {};

    this.eventBus.subscribe('transaction', this.handleTransaction.bind(this));
  }

  addItem(itemName, quantity = 1) {
    if (this.items[itemName]) {
      this.items[itemName] += quantity;
    } else {
      this.items[itemName] = quantity;
    }
  }

  removeItem(itemName, quantity = 1) {
    if (this.items[itemName] && this.items[itemName] >= quantity) {
      this.items[itemName] -= quantity;
      if (this.items[itemName] === 0) {
        delete this.items[itemName];
      }
      return true;
    }
    return false;
  }

  handleTransaction(transaction) {
    if (transaction.type === 'sell') {
      this.addItem('gold', transaction.amount);
    }
  }

  getInventory() {
    return this.items;
  }
}

// Demo
const eventBus = new EventBus();
const economy = new Economy(eventBus);
const store = new Store(eventBus);
const inventory = new Inventory(eventBus);

console.log('Initial balance:', economy.getBalance());

store.buyItem('sword');
console.log('Balance after buying sword:', economy.getBalance());

store.sellItem('gold', 20);
console.log('Balance after selling gold:', economy.getBalance());

console.log('Inventory:', inventory.getInventory());
