class Bank {
  constructor() {
    this.balance = 0;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(prices) {
    this.prices = prices;
  }

  buy(item, bank) {
    const price = this.prices[item];
    if (price && bank.withdraw(price)) {
      return { success: true, item, price };
    }
    return { success: false };
  }

  sell(item, bank) {
    const price = this.prices[item];
    if (price && bank.deposit(price)) {
      return { success: true, item, price };
    }
    return { success: false };
  }

  getPrice(item) {
    return this.prices[item];
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getInventory() {
    return { ...this.items };
  }
}

class GameCoordinator {
  constructor() {
    this.bank = new Bank();
    this.market = new Market({ apple: 5, banana: 3, orange: 4 });
    this.inventory = new Inventory();
  }

  buyItem(item) {
    const result = this.market.buy(item, this.bank);
    if (result.success) {
      this.inventory.addItem(item);
      console.log(`Bought ${item} for ${result.price}. Balance: ${this.bank.getBalance()}`);
    } else {
      console.log(`Failed to buy ${item}. Not enough money or item not available.`);
    }
  }

  sellItem(item) {
    const result = this.market.sell(item, this.bank);
    if (result.success) {
      this.inventory.removeItem(item);
      console.log(`Sold ${item} for ${result.price}. Balance: ${this.bank.getBalance()}`);
    } else {
      console.log(`Failed to sell ${item}. Item not in inventory.`);
    }
  }

  checkInventory() {
    console.log('Current Inventory:', this.inventory.getInventory());
  }

  checkBalance() {
    console.log('Current Balance:', this.bank.getBalance());
  }
}

// Demo
const game = new GameCoordinator();
game.buyItem('apple'); // Bought apple for 5. Balance: -5
game.buyItem('banana'); // Bought banana for 3. Balance: -8
game.checkInventory(); // Current Inventory: { apple: 1, banana: 1 }
game.checkBalance(); // Current Balance: -8
game.sellItem('apple'); // Sold apple for 5. Balance: -3
game.checkInventory(); // Current Inventory: { banana: 1 }
