class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Wallet {
  constructor(eventBus) {
    this.balance = 0;
    this.eventBus = eventBus;
    this.eventBus.subscribe('purchaseMade', this.onPurchaseMade.bind(this));
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Deposited ${amount}. New balance: ${this.balance}`);
  }

  withdraw(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}. New balance: ${this.balance}`);
      return true;
    } else {
      console.log('Insufficient funds');
      return false;
    }
  }

  onPurchaseMade({ item, price }) {
    if (this.withdraw(price)) {
      console.log(`Purchase successful for ${item}`);
    } else {
      console.log(`Failed to purchase ${item}. Insufficient funds`);
    }
  }
}

class Shop {
  constructor(eventBus) {
    this.items = {
      sword: 10,
      shield: 5,
      potion: 2
    };
    this.eventBus = eventBus;
    this.eventBus.subscribe('addToInventory', this.onAddToInventory.bind(this));
  }

  listItems() {
    console.log('Available items in shop:');
    Object.entries(this.items).forEach(([item, price]) => {
      console.log(`${item}: ${price} gold`);
    });
  }

  purchase(item) {
    const price = this.items[item];
    if (price) {
      this.eventBus.emit('purchaseMade', { item, price });
    } else {
      console.log('Item not found in shop');
    }
  }

  onAddToInventory({ item, quantity }) {
    if (this.items[item]) {
      console.log(`Stock updated for ${item}: ${quantity}`);
      this.items[item] = quantity;
    } else {
      console.log(`Item ${item} not sold in this shop`);
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.items = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('purchaseSuccessful', this.onPurchaseSuccessful.bind(this));
  }

  addItem(item, quantity) {
