const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const states = {
  MENU: 'menu',
  PLAYING: 'playing',
  PAUSED: 'paused',
  GAMEOVER: 'gameover'
};

let currentState = states.MENU;
let score = 0;
let asteroids = [];
let ship = { x: canvas.width / 2, y: canvas.height / 2, radius: 10, angle: 0, velocity: { x: 0, y: 0 } };
let keys = {};

const asteroidColors = ['#ff0000', '#00ff00', '#0000ff', '#ffff00', '#00ffff', '#ff00ff'];

function resetGame() {
  score = 0;
  asteroids = [];
  ship = { x: canvas.width / 2, y: canvas.height / 2, radius: 10, angle: 0, velocity: { x: 0, y: 0 } };
  for (let i = 0; i < 5; i++) {
    asteroids.push(createAsteroid());
  }
}

function createAsteroid() {
  const size = Math.random() * 20 + 10;
  const x = Math.random() * canvas.width;
  const y = Math.random() * canvas.height;
  const angle = Math.random() * Math.PI * 2;
  const velocity = { x: Math.cos(angle) * (Math.random() * 2 + 1), y: Math.sin(angle) * (Math.random() * 2 + 1) };
  return { x, y, size, angle, velocity, color: asteroidColors[Math.floor(Math.random() * asteroidColors.length)] };
}

function update() {
  switch (currentState) {
    case states.PLAYING:
      updateShip();
      updateAsteroids();
      checkCollisions();
      break;
  }
}

function updateShip() {
  if (keys['ArrowLeft']) ship.angle -= 0.05;
  if (keys['ArrowRight']) ship.angle += 0.05;
  if (keys['ArrowUp']) {
    ship.velocity.x += Math.cos(ship.angle) * 0.1;
    ship.velocity.y += Math.sin(ship.angle) * 0.1;
  }
  ship.x += ship.velocity.x;
  ship.y += ship.velocity.y;
  ship.x = (ship.x + canvas.width) % canvas.width;
  ship.y = (ship.y + canvas.height) % canvas.height;
}

function updateAsteroids() {
  asteroids.forEach(asteroid => {
    asteroid.x += asteroid.velocity.x;
    asteroid.y += asteroid.velocity.y;
    asteroid.x = (asteroid.x + canvas.width) % canvas.width;
    asteroid.y = (asteroid.y + canvas.height) % canvas.height;
  });
}

function checkCollisions() {
  asteroids.forEach((asteroid, index) => {
    const dx = asteroid.x - ship.x;
    const dy = asteroid.y - ship.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    if (distance < ship.radius + asteroid.size / 2) {
      currentState = states.GAMEOVER;
    }
  });
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  switch (currentState) {
    case states.MENU:
      ctx.fillStyle = 'black';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = 'white';
      ctx.font = '30px Arial';
      ctx.fillText('Asteroids', canvas.width / 2 - 80, canvas.height / 2);
      ctx.fillText('Press Space to Start', canvas.width / 2 - 120, canvas.height / 2 + 40);
      break;
    case states.PLAYING:
      renderShip();
      renderAsteroids();
      ctx.fillStyle = 'white';
      ctx.font = '20px Arial';
      ctx.fillText(`Score: ${score}`, 10, 30);
      break;
    case states.PAUSED:
      ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = 'white';
      ctx.font = '30px Arial';
      ctx.fillText('Paused', canvas.width / 2 - 40, canvas.height / 2);
      break;
    case states.GAMEOVER:
      ctx.fillStyle = 'black';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = 'white';
      ctx.font = '30px Arial';
      ctx.fillText('Game Over', canvas.width / 2 - 60, canvas.height / 2);
      ctx.fillText(`Score: ${score}`, canvas.width / 2 - 50, canvas.height / 2 + 40);
      ctx.fillText('Press Space to Restart', canvas.width / 2 - 120, canvas.height / 2 + 80);
      break;
  }
}

function renderShip() {
  ctx.save();
  ctx.translate(ship.x, ship.y);
  ctx.rotate(ship.angle);
  ctx.beginPath();
  ctx.moveTo(0, -ship.radius);
  ctx.lineTo(-ship.radius, ship.radius);
  ctx.lineTo(ship.radius, ship.radius);
  ctx.closePath();
  ctx.fillStyle = 'white';
  ctx.fill();
  ctx.restore();
}

function renderAsteroids() {
  asteroids.forEach(asteroid => {
    ctx.beginPath();
    ctx.arc(asteroid.x, asteroid.y, asteroid.size / 2, 0, Math.PI * 2);
    ctx.fillStyle = asteroid.color;
    ctx.fill();
  });
}

function gameLoop() {
  update();
  render();
  requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', e => {
  keys[e.code] = true;
  if (e.code === 'Space' && currentState === states.MENU) {
    currentState = states.PLAYING;
    resetGame();
  } else if (e.code === 'Space' && currentState === states.GAMEOVER) {
    currentState = states.PLAYING;
    resetGame();
  } else if (e.code === 'Escape' && currentState === states.PLAYING) {
    currentState = states.PAUSED;
  } else if (e.code === 'Escape' && currentState === states.PAUSED) {
    currentState = states.PLAYING;
  }
});

document.addEventListener('keyup', e => {
  keys[e.code] = false;
});

gameLoop();
