// Tower Defense Skirmish with Particle Burst Effect

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let windowWidth = window.innerWidth;
let windowHeight = window.innerHeight;
let pixelRatio = window.devicePixelRatio || 1;

function resizeCanvas() {
    windowWidth = window.innerWidth;
    windowHeight = window.innerHeight;
    pixelRatio = window.devicePixelRatio || 1;
    canvas.width = windowWidth * pixelRatio;
    canvas.height = windowHeight * pixelRatio;
    canvas.style.width = `${windowWidth}px`;
    canvas.style.height = `${windowHeight}px`;
    ctx.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
}

resizeCanvas();
window.addEventListener('resize', resizeCanvas);

const particles = [];
const enemies = [];
const towers = [];

class Particle {
    constructor(x, y, color, size, lifespan) {
        this.x = x;
        this.y = y;
        this.color = color;
        this.size = size;
        this.lifespan = lifespan;
    }

    update() {
        this.lifespan -= 1;
        if (this.lifespan <= 0) {
            particles.splice(particles.indexOf(this), 1);
        }
    }

    draw() {
        ctx.fillStyle = this.color;
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx.fill();
    }
}

class Enemy {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.speed = 2;
    }

    update() {
        this.x -= this.speed;
    }

    draw() {
        ctx.fillStyle = 'red';
        ctx.fillRect(this.x, this.y, 10, 10);
    }
}

class Tower {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.range = 50;
        this.cooldown = 0;
    }

    update() {
        if (this.cooldown > 0) this.cooldown--;

        const target = enemies.find(e => 
            Math.hypot(e.x - this.x, e.y - this.y) <= this.range
        );

        if (target) {
            if (this.cooldown === 0) {
                this.shoot(target);
                this.cooldown = 60;
            }
        }
    }

    shoot(target) {
        const angle = Math.atan2(target.y - this.y, target.x - this.x);
        const bulletSpeed = 5;
        const bullet = {
            x: this.x,
            y: this.y,
            dx: Math.cos(angle) * bulletSpeed,
            dy: Math.sin(angle) * bulletSpeed,
            radius: 2,
            color: 'blue'
        };
        bullets.push(bullet);
        createParticleBurst(this.x, this.y, 10, 5, 'blue');
    }

    draw() {
        ctx.fillStyle = 'green';
        ctx.fillRect(this.x, this.y, 10, 10);
    }
}

const bullets = [];

function createParticleBurst(x, y, count, size, color) {
    for (let i = 0; i < count; i++) {
        const angle = Math.random() * Math.PI * 2;
        const speed = Math.random() * 2 + 1;
        particles.push(new Particle(x, y, color, size, 30 + Math.random() * 20));
    }
}

function spawnEnemy() {
    const y = Math.random() * (windowHeight - 20);
    enemies.push(new Enemy(windowWidth, y));
}

setInterval(spawnEnemy, 1000);

function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    enemies.forEach(enemy => {
        enemy.update();
        enemy.draw();
    });

    towers.forEach(tower => {
        tower.update();
        tower.draw();
    });

    bullets.forEach((bullet, index) => {
        bullet.x += bullet.dx;
        bullet.y += bullet.dy;

        const enemy = enemies.find(e => 
            Math.hypot(e.x - bullet.x, e.y - bullet.y) <= e.size + bullet.radius
        );

        if (enemy) {
            enemies.splice(enemies.indexOf(enemy), 1);
            bullets.splice(index, 1);
            createParticleBurst(bullet.x, bullet.y, 10, 5, 'red');
        } else {
            bullet.draw();
        }
    });

    particles.forEach(particle => {
        particle.update();
        particle.draw();
    });

    requestAnimationFrame(gameLoop);
}

towers.push(new Tower(100, 100));
towers.push(new Tower(100, 200));
towers.push(new Tower(100, 300));

gameLoop();
