    return this.experience.getTotal() >= this.experience.levelUpRequired(this.skill.getLevel() + 1);
  }

  levelUp() {
    if (this.canLevelUp()) {
      this.experience.addExperience(-this.experience.levelUpRequired(this.skill.getLevel() + 1));
      this.skill.levelUp();
    }
  }
}

