    this.level = 100; // Max hunger level
  }

  eat(amount = 20) {
    this.level = Math.min(this.level + amount, 100);
    console.log(`Eaten. Hunger level: ${this.level}`);
  }

  consume(amount = 10) {
    this.level = Math.max(this.level - amount, 0);
    console.log(`Consumed. Hunger level: ${this.level}`);
  }

  getLevel() {
    return this.level;
  }
}

class Energy {
  constructor() {
    this.level = 100; // Max energy level
  }

  rest(amount = 20) {
    this.level = Math.min(this.level + amount, 100);
    console.log(`Rested. Energy level: ${this.level}`);
  }

  spend(amount = 10) {
    this.level = Math.max(this.level - amount, 0);
    console.log(`Spent. Energy level: ${this.level}`);
  }

  getLevel() {
    return this.level;
  }
}

class Clock {
  constructor() {
    this.time = 0; // Time in hours
  }

  tick() {
    this.time += 1;
    console.log(`Time elapsed: ${this.time} hours`);
  }

  getTime() {
    return this.time;
  }
}

class GameCoordinator {
  constructor() {
    this.hunger = new Hunger();
    this.energy = new Energy();
    this.clock = new Clock();
  }

  update() {
    this.clock.tick();
    if (this.clock.getTime() % 4 === 0) {
      this.hunger.consume();
    }
    if (this.clock.getTime() % 6 === 0) {
      this.energy.spend();
    }
  }

  interact(action) {
    switch (action) {
      case 'eat':
        this.hunger.eat();
        break;
      case 'rest':
        this.energy.rest();
        break;
      default:
        console.log('Unknown action');
    }
  }

  reportStatus() {
    console.log(`Hunger level: ${this.hunger.getLevel()}`);
    console.log(`Energy level: ${this.energy.getLevel()}`);
    console.log(`Time: ${this.clock.getTime()} hours`);
  }
}

