    if (this.resources[resourceName]) {
      this.resources[resourceName].addResource(amount);
      return true;
    }
    return false;
  }

  spendResource(resourceName, amount) {
    if (this.resources[resourceName]) {
      return this.resources[resourceName].removeResource(amount);
    }
    return false;
  }

  getResourceAmount(resourceName) {
    if (this.resources[resourceName]) {
