// Constants and settings
const CANVAS_SCALE = window.devicePixelRatio;
const GRID_SIZE = 8;
const TILE_SIZE = 64;
const CANVAS_WIDTH = GRID_SIZE * TILE_SIZE;
const CANVAS_HEIGHT = GRID_SIZE * TILE_SIZE;

// Game state
let canvas, ctx, player, ai, turn = 'player';

// Player and AI objects
player = { x: 1, y: 1, health: 100 };
ai = { x: GRID_SIZE - 2, y: GRID_SIZE - 2, health: 100 };

// Initialize canvas
canvas = document.createElement('canvas');
canvas.width = CANVAS_WIDTH * CANVAS_SCALE;
canvas.height = CANVAS_HEIGHT * CANVAS_SCALE;
canvas.style.width = `${CANVAS_WIDTH}px`;
canvas.style.height = `${CANVAS_HEIGHT}px`;
document.body.appendChild(canvas);
ctx = canvas.getContext('2d');
ctx.scale(CANVAS_SCALE, CANVAS_SCALE);

// Render function
function render() {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Draw grid
    for (let i = 0; i < GRID_SIZE; i++) {
        for (let j = 0; j < GRID_SIZE; j++) {
            ctx.strokeRect(i * TILE_SIZE, j * TILE_SIZE, TILE_SIZE, TILE_SIZE);
        }
    }

    // Draw player and AI
    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x * TILE_SIZE, player.y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
    ctx.fillStyle = 'red';
    ctx.fillRect(ai.x * TILE_SIZE, ai.y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
}

// AI turn function
function aiTurn() {
    if (ai.health <= 0 || player.health <= 0) return;

    // Simple AI: move towards player
    if (ai.x < player.x) ai.x++;
    else if (ai.x > player.x) ai.x--;
    if (ai.y < player.y) ai.y++;
    else if (ai.y > player.y) ai.y--;

    // Attack player
    if (Math.abs(ai.x - player.x) <= 1 && Math.abs(ai.y - player.y) <= 1) {
        player.health -= 10;
        console.log(`AI attacks player! Player health: ${player.health}`);
    }

    turn = 'player';
}

// Player turn function
function playerTurn(event) {
    if (player.health <= 0 || ai.health <= 0) return;

    // Handle arrow keys
    switch (event.key) {
        case 'ArrowUp': if (player.y > 0) player.y--; break;
        case 'ArrowDown': if (player.y < GRID_SIZE - 1) player.y++; break;
        case 'ArrowLeft': if (player.x > 0) player.x--; break;
        case 'ArrowRight': if (player.x < GRID_SIZE - 1) player.x++; break;
    }

    // Attack AI
    if (Math.abs(ai.x - player.x) <= 1 && Math.abs(ai.y - player.y) <= 1) {
        ai.health -= 10;
        console.log(`Player attacks AI! AI health: ${ai.health}`);
    }

    turn = 'ai';
    aiTurn();
}

// Main game loop
function gameLoop() {
    render();
    if (turn === 'player') {
        document.addEventListener('keydown', playerTurn);
    } else {
        document.removeEventListener('keydown', playerTurn);
    }
}

// Start game
setInterval(gameLoop, 1000 / 60);
