const cardWidth = 100;
const cardHeight = 150;
const margin = 10;
const numPairs = 8;
const cards = [];
let firstCard = null;
let lockedBoard = false;

function getRandomColor() {
  const letters = '0123456789ABCDEF';
  let color = '#';
  for (let i = 0; i < 6; i++) {
    color += letters[Math.floor(Math.random() * 16)];
  }
  return color;
}

function createParticles(x, y, color) {
  const particles = [];
  for (let i = 0; i < 50; i++) {
    particles.push({
      x: x,
      y: y,
      size: Math.random() * 2 + 1,
      speedX: (Math.random() - 0.5) * 3,
      speedY: (Math.random() - 0.5) * 3,
      color: color
    });
  }
  return particles;
}

function updateParticles(particles) {
  particles.forEach(particle => {
    particle.x += particle.speedX;
    particle.y += particle.speedY;
    particle.speedY += 0.05;
  });
}

function drawParticles(particles) {
  particles.forEach(particle => {
    ctx.beginPath();
    ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2);
    ctx.fillStyle = particle.color;
    ctx.fill();
  });
}

function createBoard() {
  const colors = [];
  for (let i = 0; i < numPairs; i++) {
    colors.push(getRandomColor());
  }
  const allColors = [...colors, ...colors];
  allColors.sort(() => Math.random() - 0.5);

  for (let i = 0; i < allColors.length; i++) {
    cards.push({
      x: (i % 4) * (cardWidth + margin) + margin,
      y: Math.floor(i / 4) * (cardHeight + margin) + margin,
      color: allColors[i],
      flipped: false,
      particles: []
    });
  }
}

function flipCard(card) {
  card.flipped = true;
  if (firstCard) {
    checkForMatch();
  } else {
    firstCard = card;
  }
}

function checkForMatch() {
  lockedBoard = true;
  setTimeout(() => {
    if (firstCard.color === cards[cards.length - 1].color) {
      firstCard = null;
      cards[cards.length - 1] = null;
    } else {
      firstCard.flipped = false;
      cards[cards.length - 1].flipped = false;
      firstCard.particles = createParticles(firstCard.x + cardWidth / 2, firstCard.y + cardHeight / 2, firstCard.color);
      cards[cards.length - 1].particles = createParticles(cards[cards.length - 1].x + cardWidth / 2, cards[cards.length - 1].y + cardHeight / 2, cards[cards.length - 1].color);
    }
    firstCard = null;
    lockedBoard = false;
  }, 1000);
}

function draw() {
  ctx.clearRect(0, 0, width, height);
  cards.forEach(card => {
    if (card) {
      ctx.fillStyle = card.flipped ? card.color : 'white';
      ctx.fillRect(card.x, card.y, cardWidth, cardHeight);
      ctx.strokeStyle = 'black';
      ctx.strokeRect(card.x, card.y, cardWidth, cardHeight);
      if (card.particles.length > 0) {
        updateParticles(card.particles);
        drawParticles(card.particles);
        card.particles = card.particles.filter(particle => particle.size > 0.1);
      }
    }
  });
  requestAnimationFrame(draw);
}

canvas.addEventListener('click', event => {
  if (lockedBoard) return;
  const rect = canvas.getBoundingClientRect();
  const x = event.clientX - rect.left;
  const y = event.clientY - rect.top;

  cards.forEach(card => {
    if (card && !card.flipped && x > card.x && x < card.x + cardWidth && y > card.y && y < card.y + cardHeight) {
      flipCard(card);
    }
  });
});

createBoard();
draw();
