class Bank {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(prices = {}) {
    this.prices = prices;
  }

  buy(item, quantity, bank) {
    const totalPrice = this.prices[item] * quantity;
    if (bank.withdraw(totalPrice)) {
      return { success: true, quantity };
    }
    return { success: false, quantity: 0 };
  }

  sell(item, quantity, bank) {
    const totalPrice = this.prices[item] * quantity;
    bank.deposit(totalPrice);
    return quantity;
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
      return true;
    }
    return false;
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      return true;
    }
    return false;
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

