const canvas = document.createElement('canvas');
canvas.width = 300;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const BLOCK_SIZE = 30;
const ROWS = canvas.height / BLOCK_SIZE;
const COLS = canvas.width / BLOCK_SIZE;

let score = 0;
let gameRunning = true;
let lastTime = performance.now();
let dt = 0;
const fixedTimeStep = 1000 / 60; // 60 FPS

const colors = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#00FFFF', '#FF00FF', '#800000'];

class Block {
  constructor(x, y, color) {
    this.x = x;
    this.y = y;
    this.color = color;
  }

  draw() {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x * BLOCK_SIZE, this.y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
  }

  moveDown() {
    this.y++;
  }

  canMoveDown(occupied) {
    return this.y + 1 < ROWS && !occupied[this.y + 1][this.x];
  }
}

let currentBlock;
let nextBlock;
let occupied = Array.from({ length: ROWS }, () => Array(COLS).fill(false));

function createBlock() {
  const x = Math.floor(Math.random() * COLS);
  const color = colors[Math.floor(Math.random() * colors.length)];
  return new Block(x, 0, color);
}

function resetGame() {
  score = 0;
  gameRunning = true;
  occupied = Array.from({ length: ROWS }, () => Array(COLS).fill(false));
  currentBlock = createBlock();
  nextBlock = createBlock();
}

function checkLines() {
  for (let y = ROWS - 1; y >= 0; y--) {
    if (occupied[y].every(cell => cell)) {
      occupied.splice(y, 1);
      occupied.unshift(Array(COLS).fill(false));
      score += 100;
    }
  }
}

function drawNextBlock() {
  ctx.fillStyle = 'white';
  ctx.fillRect(10, 10, BLOCK_SIZE * 4, BLOCK_SIZE * 4);
  ctx.fillStyle = nextBlock.color;
  ctx.fillRect(10 + BLOCK_SIZE * nextBlock.x, 10 + BLOCK_SIZE * nextBlock.y, BLOCK_SIZE, BLOCK_SIZE);
}

function update() {
  if (!gameRunning) return;

  if (!currentBlock.canMoveDown(occupied)) {
    currentBlock.draw();
    occupied[currentBlock.y][currentBlock.x] = true;
    currentBlock = nextBlock;
    nextBlock = createBlock();

    if (!currentBlock.canMoveDown(occupied)) {
      gameRunning = false;
    }
  } else {
    currentBlock.moveDown();
  }

  checkLines();
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  for (let y = 0; y < ROWS; y++) {
    for (let x = 0; x < COLS; x++) {
      if (occupied[y][x]) {
        ctx.fillStyle = colors[Math.floor(Math.random() * colors.length)];
        ctx.fillRect(x * BLOCK_SIZE, y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
      }
    }
  }

  currentBlock.draw();
  drawNextBlock();

  ctx.fillStyle = 'white';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 50);
}

function gameLoop(timestamp) {
  dt += timestamp - lastTime;
  lastTime = timestamp;

  while (dt >= fixedTimeStep) {
    update();
    dt -= fixedTimeStep;
  }

  render();

  if (gameRunning) {
    requestAnimationFrame(gameLoop);
  } else {
    ctx.fillStyle = 'white';
    ctx.font = '40px Arial';
    ctx.fillText('Game Over', 70, 300);
  }
}

canvas.addEventListener('keydown', (e) => {
  if (!gameRunning) return;

  switch (e.key) {
    case 'ArrowLeft':
      if (currentBlock.x > 0 && !occupied[currentBlock.y][currentBlock.x - 1]) {
        currentBlock.x--;
      }
      break;
    case 'ArrowRight':
      if (currentBlock.x < COLS - 1 && !occupied[currentBlock.y][currentBlock.x + 1]) {
        currentBlock.x++;
      }
      break;
    case 'ArrowDown':
      if (currentBlock.canMoveDown(occupied)) {
        currentBlock.moveDown();
      }
      break;
  }
});

resetGame();
gameLoop(performance.now());
