const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 400;
canvas.height = 400;
const ctx = canvas.getContext('2d');

const TILE_SIZE = 80;
const GRID_SIZE = 4;
const HEALTHBAR_HEIGHT = 30;
const SPAWN_INTERVAL = 5; // seconds
const FIXED_TIMESTEP = 1 / 60; // 60 FPS
let lastTime = 0;
let accumulator = 0;
let health = 3;
let score = 0;
let grid = Array.from({ length: GRID_SIZE }, () => Array(GRID_SIZE).fill(0));
let spawnTimer = SPAWN_INTERVAL;
let direction = null;

function getRandomValue() {
    return Math.random() > 0.9 ? 4 : 2;
}

function spawnTile() {
    const emptyTiles = [];
    for (let y = 0; y < GRID_SIZE; y++) {
        for (let x = 0; x < GRID_SIZE; x++) {
            if (grid[y][x] === 0) {
                emptyTiles.push({ x, y });
            }
        }
    }
    if (emptyTiles.length > 0) {
        const { x, y } = emptyTiles[Math.floor(Math.random() * emptyTiles.length)];
        grid[y][x] = getRandomValue();
    }
}

function mergeTiles(row) {
    for (let i = GRID_SIZE - 2; i >= 0; i--) {
        if (row[i] !== 0 && row[i] === row[i + 1]) {
            row[i] *= 2;
            row[i + 1] = 0;
            score += row[i];
        }
    }
    return row;
}

function slideRow(row) {
    const nonZero = row.filter(num => num !== 0);
    const merged = mergeTiles(nonZero);
    const zeroFilled = [...merged, ...Array(GRID_SIZE - merged.length).fill(0)];
    return zeroFilled;
}

function slideGrid(direction) {
    let moved = false;
    switch (direction) {
        case 'up':
            for (let x = 0; x < GRID_SIZE; x++) {
                const column = Array.from({ length: GRID_SIZE }, (_, y) => grid[y][x]);
                const newColumn = slideRow(column);
                for (let y = 0; y < GRID_SIZE; y++) {
                    if (grid[y][x] !== newColumn[y]) {
                        moved = true;
                        grid[y][x] = newColumn[y];
                    }
                }
            }
            break;
        case 'down':
            for (let x = 0; x < GRID_SIZE; x++) {
                const column = Array.from({ length: GRID_SIZE }, (_, y) => grid[GRID_SIZE - 1 - y][x]).reverse();
                const newColumn = slideRow(column).reverse();
                for (let y = 0; y < GRID_SIZE; y++) {
                    if (grid[GRID_SIZE - 1 - y][x] !== newColumn[y]) {
                        moved = true;
                        grid[GRID_SIZE - 1 - y][x] = newColumn[y];
                    }
                }
            }
            break;
        case 'left':
            for (let y = 0; y < GRID_SIZE; y++) {
                const newRow = slideRow(grid[y]);
                if (grid[y].some((val, idx) => val !== newRow[idx])) {
                    moved = true;
                    grid[y] = newRow;
                }
            }
            break;
        case 'right':
            for (let y = 0; y < GRID_SIZE; y++) {
                const newRow = slideRow(grid[y].slice().reverse()).reverse();
                if (grid[y].some((val, idx) => val !== newRow[idx])) {
                    moved = true;
                    grid[y] = newRow;
                }
            }
            break;
    }
    if (moved) {
        spawnTile();
    }
    return moved;
}

function update(deltaTime) {
    spawnTimer -= deltaTime;
    if (spawnTimer <= 0) {
        spawnTile();
        spawnTimer = SPAWN_INTERVAL;
    }
    if (direction) {
        if (slideGrid(direction)) {
            direction = null;
        }
    }
}

function drawTile(x, y, value) {
    ctx.fillStyle = '#fff';
    ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
    ctx.fillStyle = '#000';
    ctx.font = '32px Arial';
    const text = value.toString();
    const textWidth = ctx.measureText(text).width;
    const textHeight = 24; // Approximate height
    ctx.fillText(text, x * TILE_SIZE + (TILE_SIZE - textWidth) / 2, y * TILE_SIZE + (TILE_SIZE + textHeight) / 2);
}

function drawGrid() {
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    for (let y = 0; y < GRID_SIZE; y++) {
        for (let x = 0; x < GRID_SIZE; x++) {
            drawTile(x, y, grid[y][x]);
        }
    }
}

function drawHealthBar() {
    ctx.fillStyle = '#f00';
    ctx.fillRect(0, canvas.height - HEALTHBAR_HEIGHT, (canvas.width * health) / 3, HEALTHBAR_HEIGHT);
    ctx.fillStyle = '#000';
    ctx.font = '16px Arial';
    ctx.fillText(`Health: ${health}`, 10, canvas.height - HEALTHBAR_HEIGHT / 2 + 8);
    ctx.fillText(`Score: ${score}`, canvas.width - 70, canvas.height - HEALTHBAR_HEIGHT / 2 + 8);
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawGrid();
    drawHealthBar();
}

function gameLoop(timestamp) {
    const deltaTime = timestamp - lastTime;
    lastTime = timestamp;
    accumulator += deltaTime;

    while (accumulator >= FIXED_TIMESTEP) {
        update(FIXED_TIMESTEP);
        accumulator -= FIXED_TIMESTEP;
    }

    draw();
    requestAnimationFrame(gameLoop);
}

function checkGameOver() {
    if (health <= 0) {
        alert(`Game Over! Your score: ${score}`);
        location.reload();
    }
}

document.addEventListener('keydown', (e) => {
    switch (e.key) {
        case 'ArrowUp':
            direction = 'up';
            break;
        case 'ArrowDown':
            direction = 'down';
            break;
        case 'ArrowLeft':
            direction = 'left';
            break;
        case 'ArrowRight':
            direction = 'right';
            break;
    }
    checkGameOver();
});

spawnTile();
spawnTile();
requestAnimationFrame(gameLoop);
