  { name: 'Tank', speed: 0.5, damage: 15, health: 100 }
];

function spawnWave() {
  for (let i = 0; i < waves * 3; i++) {
    let type = enemyTypes[Math.floor(Math.random() * enemyTypes.length)];
    enemies.push({
      x: 0,
      y: Math.random() * canvas.height,
      speed: type.speed,
      damage: type.damage,
      health: type.health,
      type: type.name
    });
  }
