  }

  getBalance() {
    return this.balance;
  }

  debit(amount) {
    if (amount > this.balance) {
      throw new Error("Insufficient funds");
    }
    this.balance -= amount;
    return this.balance;
  }

  credit(amount) {
    this.balance += amount;
    return this.balance;
  }
}

class RarityTable {
  constructor() {
    this.table = {
      common: 50,
      uncommon: 30,
      rare: 15,
      epic: 5
    };
  }

  getRandomItem() {
    const total = Object.values(this.table).reduce((a, b) => a + b, 0);
    const rand = Math.random() * total;
    let cumulative = 0;
    for (const [item, weight] of Object.entries(this.table)) {
      cumulative += weight;
      if (rand < cumulative) {
        return item;
      }
    }
    return "common"; // Fallback to common if no match
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item) {
    if (this.items[item]) {
      this.items[item]++;
    } else {
      this.items[item] = 1;
    }
    return this.items;
  }

  getInventory() {
    return this.items;
  }
}

