    this.prices = {};
  }

  setPrice(item, price) {
    if (price >= 0) {
      this.prices[item] = price;
      console.log(`Set price of ${item} to ${price}`);
    } else {
      console.log('Price must be non-negative');
    }
  }

  getPrice(item) {
    return this.prices[item] || null;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
      console.log(`Added ${quantity} of ${item}, new quantity: ${this.items[item]}`);
    } else {
      console.log('Quantity must be positive');
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] && quantity > 0 && quantity <= this.items[item]) {
      this.items[item] -= quantity;
      console.log(`Removed ${quantity} of ${item}, new quantity: ${this.items[item]}`);
    } else {
      console.log('Insufficient quantity or item does not exist');
    }
  }

  getQuantity(item) {
    return this.items[item] || 0;
  }
}

class Coordinator {
  constructor() {
    this.bank = new Bank();
    this.market = new Market();
    this.inventory = new Inventory();
  }

  buyItem(item, quantity) {
    const price = this.market.getPrice(item);
    if (price !== null) {
      const totalCost = price * quantity;
      if (this.bank.getBalance() >= totalCost) {
        this.bank.withdraw(totalCost);
        this.inventory.addItem(item, quantity);
        console.log(`Bought ${quantity} of ${item} for ${totalCost}`);
      } else {
        console.log('Insufficient balance');
      }
    } else {
      console.log(`Price for ${item} not set`);
    }
  }

  sellItem(item, quantity) {
    const price = this.market.getPrice(item);
    if (price !== null) {
      const totalEarnings = price * quantity;
      if (this.inventory.getQuantity(item) >= quantity) {
        this.inventory.removeItem(item, quantity);
        this.bank.deposit(totalEarnings);
        console.log(`Sold ${quantity} of ${item} for ${totalEarnings}`);
      } else {
        console.log('Insufficient quantity in inventory');
      }
    } else {
      console.log(`Price for ${item} not set`);
    }
  }
}

