// Memory Game with Basic AI Opponent

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = window.innerWidth * devicePixelRatio;
canvas.height = window.innerHeight * devicePixelRatio;
const ctx = canvas.getContext('2d');

const cardWidth = 80 * devicePixelRatio;
const cardHeight = 100 * devicePixelRatio;
const margin = 10 * devicePixelRatio;
const rows = 2;
const cols = 4;
const totalCards = rows * cols;
const cards = [];
let flippedCards = [];
let lockBoard = false;

const images = [
  'https://via.placeholder.com/80',
  'https://via.placeholder.com/80/ff0000',
  'https://via.placeholder.com/80/00ff00',
  'https://via.placeholder.com/80/0000ff',
];

images.forEach(img => {
  const imgObj = new Image();
  imgObj.src = img;
  cards.push({ img: imgObj, matched: false });
  cards.push({ img: imgObj, matched: false });
});

function shuffle(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
}

shuffle(cards);

function drawCard(card, x, y) {
  ctx.fillStyle = 'white';
  ctx.fillRect(x, y, cardWidth, cardHeight);
  ctx.strokeStyle = 'black';
  ctx.strokeRect(x, y, cardWidth, cardHeight);
  if (!card.matched) {
    ctx.drawImage(card.img, x + margin, y + margin, cardWidth - margin * 2, cardHeight - margin * 2);
  }
}

function drawBoard() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let i = 0; i < totalCards; i++) {
    const row = Math.floor(i / cols);
    const col = i % cols;
    const x = col * (cardWidth + margin);
    const y = row * (cardHeight + margin);
    drawCard(cards[i], x, y);
  }
}

function checkForMatch() {
  if (flippedCards.length === 2) {
    lockBoard = true;
    setTimeout(() => {
      const [card1, card2] = flippedCards;
      if (card1.img === card2.img) {
        card1.matched = true;
        card2.matched = true;
      } else {
        card1.flipped = false;
        card2.flipped = false;
      }
      flippedCards = [];
      lockBoard = false;
      aiTurn();
    }, 1000);
  }
}

canvas.addEventListener('click', function(event) {
  if (lockBoard) return;

  const rect = canvas.getBoundingClientRect();
  const x = event.clientX - rect.left;
  const y = event.clientY - rect.top;

  for (let i = 0; i < totalCards; i++) {
    const row = Math.floor(i / cols);
    const col = i % cols;
    const cardX = col * (cardWidth + margin);
    const cardY = row * (cardHeight + margin);

    if (x > cardX && x < cardX + cardWidth && y > cardY && y < cardY + cardHeight && !cards[i].matched) {
      cards[i].flipped = true;
      flippedCards.push(cards[i]);
      drawBoard();
      if (flippedCards.length === 2) {
        checkForMatch();
      }
      break;
    }
  }
});

function aiTurn() {
  if (lockBoard) return;

  let availableCards = cards.filter(card => !card.matched && !card.flipped);

  if (availableCards.length === 0) return;

  const randomIndex = Math.floor(Math.random() * availableCards.length);
  const aiCard = availableCards[randomIndex];

  aiCard.flipped = true;
  flippedCards.push(aiCard);
  drawBoard();

  if (flippedCards.length === 2) {
    checkForMatch();
  }
}

drawBoard();
