// Pricing System
class Pricing {
  constructor(basePrice) {
    this.basePrice = basePrice;
  }

  calculatePrice(quantity) {
    return this.basePrice * quantity;
  }

  applyDiscount(price, discount) {
    return price * (1 - discount);
  }
}

// Demand System
class Demand {
  constructor(initialDemand) {
    this.demand = initialDemand;
  }

  adjustDemand(change) {
    this.demand += change;
    return this.demand;
  }

  getCurrentDemand() {
    return this.demand;
  }
}

// Store System
class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
  }

  sellProduct(quantity, discount = 0) {
    const price = this.pricing.calculatePrice(quantity);
    const discountedPrice = this.pricing.applyDiscount(price, discount);
    const canSell = this.demand.adjustDemand(-quantity) >= 0;
    return { price: discountedPrice, canSell };
  }

  checkStock() {
    return this.demand.getCurrentDemand();
  }
}

// Top-level Coordinator
class GameCoordinator {
  constructor() {
    const pricing = new Pricing(10);
    const demand = new Demand(100);
    this.store = new Store(pricing, demand);
  }

  runDemo() {
    console.log("Initial stock:", this.store.checkStock());
    const sellResult = this.store.sellProduct(10, 0.1);
    console.log("Sold 10 products with 10% discount. Price:", sellResult.price, "Can sell:", sellResult.canSell);
    console.log("Current stock:", this.store.checkStock());
    const sellResult2 = this.store.sellProduct(20);
    console.log("Attempted to sell 20 products. Price:", sellResult2.price, "Can sell:", sellResult2.canSell);
    console.log("Current stock:", this.store.checkStock());
  }
}

// Runnable Demo
const coordinator = new GameCoordinator();
coordinator.runDemo();
