  }

  onQuestCompleted(questName) {
    console.log(`NPC: Oh, you completed ${questName}? That's wonderful!`);
  }
}

class Flags {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.flags = {};
  }

  setFlag(flag, value) {
    this.flags[flag] = value;
    this.eventBus.emit('flagSet', { flag, value });
  }

  getFlag(flag) {
    return this.flags[flag];
  }
}

class Quest {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('flagSet', this.onFlagSet.bind(this));
  }

