    this.dialogue.addResponse("greet", "Hello, traveler! What brings you here?");
    this.dialogue.addResponse("askQuest", "Do you want to embark on an adventure?");

    // Setup flags
    this.flags.setFlag("hasMet", false);
    this.flags.setFlag("questAccepted", false);

    // Setup quests
