    if (amount > this.balance) {
      console.log(`Insufficient funds. Current balance: ${this.balance}`);
      return false;
    }
    this.balance -= amount;
    console.log(`Withdrew ${amount}. New balance: ${this.balance}`);
    return true;
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(prices) {
    this.prices = prices;
  }

  getPrice(item) {
    return this.prices[item] || null;
  }

  getItems() {
    return Object.keys(this.prices);
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
