class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Building {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.buildings = {};
    this.eventBus.subscribe('resourceGathered', this.onResourceGathered.bind(this));
  }

  build(type, quantity) {
    if (!this.buildings[type]) {
      this.buildings[type] = 0;
    }
    this.buildings[type] += quantity;
    console.log(`Built ${quantity} ${type}(s). Total: ${this.buildings[type]}`);
    this.eventBus.emit('buildingConstructed', { type, quantity });
  }

  onResourceGathered(data) {
    console.log(`Resource ${data.resource} gathered. Quantity: ${data.quantity}`);
  }
}

class Resource {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.resources = {};
    this.eventBus.subscribe('buildingConstructed', this.onBuildingConstructed.bind(this));
  }

  gather(resource, quantity) {
    if (!this.resources[resource]) {
      this.resources[resource] = 0;
    }
    this.resources[resource] += quantity;
    console.log(`Gathered ${quantity} ${resource}(s). Total: ${this.resources[resource]}`);
    this.eventBus.emit('resourceGathered', { resource, quantity });
  }

  onBuildingConstructed(data) {
    console.log(`Building ${data.type} constructed. Quantity: ${data.quantity}`);
  }
}

class Economy {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('resourceGathered', this.onResourceGathered.bind(this));
    this.eventBus.subscribe('buildingConstructed', this.onBuildingConstructed.bind(this));
