// Tower Defense Skirmish Game

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.style.position = 'absolute';
canvas.style.top = '0';
canvas.style.left = '0';

function resizeCanvas() {
    const dpr = window.devicePixelRatio || 1;
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    canvas.style.width = `${window.innerWidth}px`;
    canvas.style.height = `${window.innerHeight}px`;
    ctx.scale(dpr, dpr);
}

window.addEventListener('resize', resizeCanvas);
resizeCanvas();

const ctx = canvas.getContext('2d');

// Game variables
let playerHealth = 100;
const maxHealth = 100;
let gameRunning = true;
let enemies = [];
let towers = [];
let spawnInterval = 1500; // in milliseconds
let nextSpawnTime = Date.now() + spawnInterval;
const enemySpeed = 1;

// Enemy properties
const enemySize = 10;
const enemyColor = 'red';

// Tower properties
const towerSize = 20;
const towerColor = 'blue';
const towerRange = 50;
const towerDamage = 1;

// Player health bar properties
const healthBarHeight = 20;
const healthBarColor = 'green';
const healthBarBackgroundColor = 'red';

// Functions
function spawnEnemy() {
    const x = canvas.width;
    const y = Math.random() * (canvas.height - enemySize);
    enemies.push({ x, y, speed: enemySpeed });
}

function drawHealthBar() {
    ctx.fillStyle = healthBarBackgroundColor;
    ctx.fillRect(0, 0, canvas.width, healthBarHeight);
    ctx.fillStyle = healthBarColor;
    ctx.fillRect(0, 0, (playerHealth / maxHealth) * canvas.width, healthBarHeight);
}

function drawEnemies() {
    ctx.fillStyle = enemyColor;
    enemies.forEach(enemy => {
        ctx.fillRect(enemy.x, enemy.y, enemySize, enemySize);
    });
}

function drawTowers() {
    ctx.fillStyle = towerColor;
    towers.forEach(tower => {
        ctx.beginPath();
        ctx.arc(tower.x, tower.y, towerSize, 0, Math.PI * 2);
        ctx.fill();
    });
}

function moveEnemies() {
    enemies.forEach(enemy => {
        enemy.x -= enemy.speed;
        if (enemy.x + enemySize < 0) {
            playerHealth -= 10;
            enemies = enemies.filter(e => e !== enemy);
        }
    });
}

function updateTowers() {
    towers.forEach(tower => {
        const enemyInRange = enemies.find(enemy =>
            Math.sqrt((enemy.x - tower.x) ** 2 + (enemy.y - tower.y) ** 2) < towerRange
        );
        if (enemyInRange) {
            enemyInRange.x += towerDamage;
            enemies = enemies.filter(enemy =>
                !(
                    Math.sqrt((enemy.x - tower.x) ** 2 + (enemy.y - tower.y) ** 2) < towerRange &&
                    enemyInRange.x < 0
                )
            );
        }
    });
}

function checkGameEnd() {
    if (playerHealth <= 0) {
        gameRunning = false;
        ctx.fillStyle = 'black';
        ctx.font = '20px Arial';
        ctx.fillText('Game Over', canvas.width / 2 - 50, canvas.height / 2);
    }
}

function gameLoop() {
    if (!gameRunning) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (Date.now() > nextSpawnTime) {
        spawnEnemy();
        nextSpawnTime = Date.now() + spawnInterval;
    }

    moveEnemies();
    updateTowers();
    drawHealthBar();
    drawEnemies();
    drawTowers();
    checkGameEnd();

    requestAnimationFrame(gameLoop);
}

// Start the game loop
gameLoop();

// Add event listener for placing towers
canvas.addEventListener('click', (event) => {
    const rect = canvas.getBoundingClientRect();
    const x = (event.clientX - rect.left) * (canvas.width / rect.width);
    const y = (event.clientY - rect.top) * (canvas.height / rect.height);
    towers.push({ x, y });
});
