// Match-3 Board with Collectible Power-ups
// Rendered on a canvas with devicePixelRatio handling

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let boardSize = 8; // 8x8 grid
let tileSize = 64;
let powerUpChance = 5; // 1 in 5 chance for a power-up

let board = [];
let powerUps = [];

function initBoard() {
    for (let i = 0; i < boardSize; i++) {
        board[i] = [];
        for (let j = 0; j < boardSize; j++) {
            let color = Math.floor(Math.random() * 3) + 1; // Colors 1-3
            board[i][j] = color;
            if (Math.random() * 100 < powerUpChance) {
                powerUps.push({ x: i, y: j });
            }
        }
    }
}

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let i = 0; i < boardSize; i++) {
        for (let j = 0; j < boardSize; j++) {
            ctx.fillStyle = `hsl(${board[i][j] * 60}, 100%, 50%)`;
            ctx.fillRect(i * tileSize, j * tileSize, tileSize, tileSize);
            ctx.strokeStyle = 'black';
            ctx.strokeRect(i * tileSize, j * tileSize, tileSize, tileSize);
        }
    }
    for (let { x, y } of powerUps) {
        ctx.fillStyle = 'gold';
        ctx.beginPath();
        ctx.arc(x * tileSize + tileSize / 2, y * tileSize + tileSize / 2, tileSize / 4, 0, Math.PI * 2);
        ctx.fill();
    }
}

function updateCanvasSize() {
    const dpr = window.devicePixelRatio || 1;
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
    ctx.scale(dpr, dpr);
}

window.addEventListener('resize', updateCanvasSize);
updateCanvasSize();

initBoard();
drawBoard();
