class Recipe {
    constructor(name, ingredients) {
        this.name = name;
        this.ingredients = ingredients; // { ingredientName: quantity }
    }

    canCraft(inventory) {
        for (let [ingredient, quantity] of Object.entries(this.ingredients)) {
            if (inventory[ingredient] < quantity) {
                return false;
            }
        }
        return true;
    }

    craft(inventory) {
        for (let [ingredient, quantity] of Object.entries(this.ingredients)) {
            inventory[ingredient] -= quantity;
        }
        return this.name;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity = 1) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    hasItem(item, quantity = 1) {
        return (this.items[item] || 0) >= quantity;
    }

    getItemCount(item) {
        return this.items[item] || 0;
    }
}

class Economy {
    constructor(prices) {
        this.prices = prices; // { itemName: price }
    }

    getPrice(item) {
        return this.prices[item] || Infinity;
    }

    debit(item, quantity) {
        const price = this.getPrice(item);
        if (price === Infinity) {
            return false; // Item not found
        }
        // For simplicity, we assume the transaction always succeeds
        return true;
    }
}

class Store {
    constructor(economy, inventory) {
        this.economy = economy;
        this.inventory = inventory;
    }

    purchase(item, quantity = 1) {
        const price = this.economy.getPrice(item);
        if (price === Infinity || !this.economy.debit(item, quantity)) {
            return false; // Purchase failed
        }
        this.inventory.addItem(item, quantity);
        return true;
    }
}

