  ctx.fillRect(pipe.x, 0, pipe.width, pipe.y - pipe.gap / 2);
  ctx.fillRect(pipe.x, pipe.y + pipe.gap / 2, pipe.width, canvas.height - (pipe.y + pipe.gap / 2));
