class Player {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.width = 50;
        this.height = 50;
        this.velocityY = 0;
        this.jumpForce = -15;
        this.gravity = 1.5;
        this.isOnGround = false;
    }

    update() {
        if (this.isOnGround) {
            this.velocityY = 0;
        } else {
            this.velocityY += this.gravity;
        }
        this.y += this.velocityY;

        if (this.y + this.height > canvas.height) {
            this.y = canvas.height - this.height;
            this.isOnGround = true;
        }
    }

    draw() {
        ctx.fillStyle = 'blue';
        ctx.fillRect(this.x, this.y, this.width, this.height);
    }

    jump() {
        if (this.isOnGround) {
            this.velocityY = this.jumpForce;
            this.isOnGround = false;
        }
    }
}

class Platform {
    constructor(x, y, width, height) {
        this.x = x;
        this.y = y;
        this.width = width;
        this.height = height;
    }

    draw() {
        ctx.fillStyle = 'green';
        ctx.fillRect(this.x, this.y, this.width, this.height);
    }
}

class Wave {
    constructor(level) {
        this.level = level;
        this.platforms = [];
        this.generatePlatforms();
    }

    generatePlatforms() {
        const platformCount = 5 + this.level;
        for (let i = 0; i < platformCount; i++) {
            const x = Math.random() * (canvas.width - 100) + 50;
            const y = Math.random() * (canvas.height - 100) + 50;
            const width = Math.random() * (100 - 50) + 50;
            const height = 20;
            this.platforms.push(new Platform(x, y, width, height));
        }
    }

    draw() {
        this.platforms.forEach(platform => platform.draw());
    }
}

const player = new Player(100, 100);
let currentWave = 1;
let waves = [new Wave(currentWave)];

function checkCollisions() {
    waves[currentWave - 1].platforms.forEach(platform => {
        if (player.x < platform.x + platform.width &&
            player.x + player.width > platform.x &&
            player.y < platform.y + platform.height &&
            player.y + player.height > platform.y) {
            player.isOnGround = true;
            player.y = platform.y - player.height;
        }
    });
}

function nextWave() {
    currentWave++;
    waves.push(new Wave(currentWave));
}

function update() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    player.update();
    checkCollisions();
    player.draw();

    waves.forEach(wave => wave.draw());

    if (player.x > canvas.width) {
        nextWave();
        player.x = 0;
    }

    requestAnimationFrame(update);
}

function handleInput(e) {
    if (e.key === 'ArrowUp') {
        player.jump();
    }
}

window.addEventListener('keydown', handleInput);

update();
