class Reward {
  constructor() {
    this.availableRewards = {};
  }

  addReward(quest, reward) {
    this.availableRewards[quest] = reward;
    console.log(`Reward added for ${quest}: ${reward}`);
  }

  claimReward(quest) {
    if (this.availableRewards[quest]) {
      const reward = this.availableRewards[quest];
      console.log(`Reward claimed for ${quest}: ${reward}`);
      delete this.availableRewards[quest];
      return reward;
    } else {
      console.log(`No reward available for ${quest}.`);
      return null;
    }
  }
}

class Inventory {
