// Match-3 Board Game with Combo Multiplier

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let width = window.innerWidth;
let height = window.innerHeight;
let dpr = window.devicePixelRatio;

canvas.width = width * dpr;
canvas.height = height * dpr;
canvas.style.width = `${width}px`;
canvas.style.height = `${height}px`;
ctx.scale(dpr, dpr);

const BOARD_SIZE = 8;
const TILE_SIZE = 40;
const COLORS = ['#FF5733', '#33FF57', '#3357FF', '#F333FF', '#33FFF3', '#FF33F3'];
let board = [];
let comboMultiplier = 1;
let score = 0;

function initBoard() {
    for (let i = 0; i < BOARD_SIZE; i++) {
        board[i] = [];
        for (let j = 0; j < BOARD_SIZE; j++) {
            board[i][j] = Math.floor(Math.random() * COLORS.length);
        }
    }
}

function drawBoard() {
    for (let i = 0; i < BOARD_SIZE; i++) {
        for (let j = 0; j < BOARD_SIZE; j++) {
            ctx.fillStyle = COLORS[board[i][j]];
            ctx.fillRect(j * TILE_SIZE, i * TILE_SIZE, TILE_SIZE, TILE_SIZE);
            ctx.strokeStyle = '#000';
            ctx.strokeRect(j * TILE_SIZE, i * TILE_SIZE, TILE_SIZE, TILE_SIZE);
        }
    }
    ctx.fillStyle = '#000';
    ctx.fillText(`Score: ${score}`, 10, 20);
    ctx.fillText(`Combo: ${comboMultiplier}x`, 10, 40);
}

function swap(i1, j1, i2, j2) {
    let temp = board[i1][j1];
    board[i1][j1] = board[i2][j2];
    board[i2][j2] = temp;
}

function checkMatches() {
    let matches = [];
    for (let i = 0; i < BOARD_SIZE; i++) {
        for (let j = 0; j < BOARD_SIZE; j++) {
            if (j < BOARD_SIZE - 2 && board[i][j] === board[i][j + 1] && board[i][j] === board[i][j + 2]) {
                matches.push([i, j], [i, j + 1], [i, j + 2]);
            }
            if (i < BOARD_SIZE - 2 && board[i][j] === board[i + 1][j] && board[i][j] === board[i + 2][j]) {
                matches.push([i, j], [i + 1, j], [i + 2, j]);
            }
        }
    }
    return matches;
}

function clearMatches(matches) {
    matches.forEach(([i, j]) => {
        board[i][j] = -1;
    });
    score += matches.length * comboMultiplier;
    comboMultiplier = matches.length > 0 ? comboMultiplier + 1 : 1;
}

function dropTiles() {
    for (let j = 0; j < BOARD_SIZE; j++) {
        let emptySlots = 0;
        for (let i = BOARD_SIZE - 1; i >= 0; i--) {
            if (board[i][j] === -1) {
                emptySlots++;
            } else if (emptySlots > 0) {
                board[i + emptySlots][j] = board[i][j];
                board[i][j] = -1;
            }
        }
        for (let i = 0; i < emptySlots; i++) {
            board[i][j] = Math.floor(Math.random() * COLORS.length);
        }
    }
}

function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawBoard();
    let matches = checkMatches();
    if (matches.length > 0) {
        clearMatches(matches);
        dropTiles();
    }
    requestAnimationFrame(gameLoop);
}

initBoard();
gameLoop();
