  }

  subscribe(eventName, callback) {
    if (!this.events[eventName]) {
      this.events[eventName] = [];
    }
    this.events[eventName].push(callback);
  }

  emit(eventName, data) {
    if (this.events[eventName]) {
      this.events[eventName].forEach(callback => callback(data));
    }
  }
}

class Skill {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.skills = {};
    this.eventBus.subscribe('levelUp', this.levelUp.bind(this));
  }

  addSkill(skillName, level) {
    this.skills[skillName] = level;
    console.log(`Skill ${skillName} added at level ${level}`);
  }

  levelUp(level) {
    for (let skill in this.skills) {
      this.skills[skill] += level;
      console.log(`Skill ${skill} leveled up to ${this.skills[skill]}`);
    }
  }
}

class Experience {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.experiencePoints = 0;
    this.levelUpThreshold = 1000;
    this.currentLevel = 1;
  }

  gainExperience(points) {
    this.experiencePoints += points;
    console.log(`Gained ${points} experience points. Total: ${this.experiencePoints}`);
    this.checkLevelUp();
  }

  checkLevelUp() {
    while (this.experiencePoints >= this.levelUpThreshold) {
      this.experiencePoints -= this.levelUpThreshold;
      this.currentLevel++;
      console.log(`Level up! New level: ${this.currentLevel}`);
      this.eventBus.emit('levelUp', this.currentLevel);
    }
  }
}

class LevelUp {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('levelUp', this.onLevelUp.bind(this));
  }

  onLevelUp(level) {
    console.log(`System received level up event. Current level: ${level}`);
  }
}

