// Vanilla JavaScript Turn-Based Tactics Duel Game

// Constants
const PLAYER_MAX_HEALTH = 100;
const RESPAWN_DELAY = 3000; // milliseconds

// Variables
let canvas, ctx;
let playerHealth = PLAYER_MAX_HEALTH;
let isDead = false;
let respawnTimeout = null;

// Initialize canvas and context
function initCanvas() {
    canvas = document.createElement('canvas');
    document.body.appendChild(canvas);
    ctx = canvas.getContext('2d');
    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);
}

// Resize canvas to fit the window with devicePixelRatio handling
function resizeCanvas() {
    const dpr = window.devicePixelRatio || 1;
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
    ctx.scale(dpr, dpr);
}

// Draw health bar
function drawHealthBar() {
    const barWidth = canvas.width * 0.8;
    const barHeight = 20;
    const x = (canvas.width - barWidth) / 2;
    const y = canvas.height * 0.9;

    ctx.fillStyle = '#ddd';
    ctx.fillRect(x, y, barWidth, barHeight);

    ctx.fillStyle = '#0f0';
    ctx.fillRect(x, y, (playerHealth / PLAYER_MAX_HEALTH) * barWidth, barHeight);

    ctx.strokeStyle = '#000';
    ctx.strokeRect(x, y, barWidth, barHeight);
}

// Handle player death and respawn
function handlePlayerDeath() {
    if (playerHealth <= 0 && !isDead) {
        isDead = true;
        console.log('Player died! Respawning in ' + (RESPAWN_DELAY / 1000) + ' seconds...');
        respawnTimeout = setTimeout(respawnPlayer, RESPAWN_DELAY);
    }
}

// Respawn player
function respawnPlayer() {
    playerHealth = PLAYER_MAX_HEALTH;
    isDead = false;
    console.log('Player respawned!');
    respawnTimeout = null;
}

// Main game loop
function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawHealthBar();
    handlePlayerDeath();
    requestAnimationFrame(gameLoop);
}

// Simulate player taking damage (for demonstration)
function takeDamage(amount) {
    if (!isDead) {
        playerHealth -= amount;
        if (playerHealth < 0) playerHealth = 0;
        console.log('Player took ' + amount + ' damage. Health: ' + playerHealth);
    }
}

// Start the game
initCanvas();
gameLoop();

// Simulate damage every 10 seconds for demonstration
setInterval(() => takeDamage(20), 10000);
