    this.crops.push(crop);
  }

  harvestCrops() {
    const harvest = {};
    this.crops.forEach(crop => {
      const amount = crop.getHarvest();
      harvest[crop.name] = (harvest[crop.name] || 0) + amount;
    });
    this.crops = []; // Clear the crops after harvesting
    return harvest;
  }
}

class Market {
  constructor(prices) {
    this.prices = prices;
  }

  sellHarvest(harvest) {
    let totalEarnings = 0;
    for (const [cropName, amount] of Object.entries(harvest)) {
      if (this.prices[cropName]) {
        totalEarnings += this.prices[cropName] * amount;
      }
    }
    return totalEarnings;
  }
}

