        this.y = y;
        this.type = type;
        this.growthTime = type.growTime;
        this.growStartTime = Date.now();
    }

    update() {
        const currentTime = Date.now();
        if (currentTime - this.growStartTime >= this.growthTime) {
            this.harvest();
        }
    }

    render() {
        ctx.fillStyle = this.type.color;
        ctx.fillRect(this.x, this.y, 20, 20);
    }

    harvest() {
        score += 10;
        const index = plants.indexOf(this);
        if (index !== -1) {
            plants.splice(index, 1);
        }
    }
}

class Enemy {
    constructor(x, y) {
