        this.y += this.speed;
    }

    render() {
        ctx.fillStyle = 'red';
        ctx.fillRect(this.x, this.y, 10, 10);
    }

    checkCollision(plant) {
        return (
            this.x < plant.x + 20 &&
            this.x + 10 > plant.x &&
            this.y < plant.y + 20 &&
            this.y + 10 > plant.y
        );
    }
}

