        spawnEnemies();
        lastWaveTime = now;
        waveInterval = Math.max(waveInterval * 0.9, 2000);
    }

    plants.forEach(plant => plant.update());
    enemies.forEach(enemy => {
        enemy.update();
        plants.forEach(plant => {
            if (enemy.checkCollision(plant)) {
                plant.harvest();
            }
        });
    });
}

