class Pricing {
  constructor(basePrice, markup) {
    this.basePrice = basePrice;
    this.markup = markup;
  }

  calculatePrice(quantity) {
    return (this.basePrice + this.markup) * quantity;
  }
}

class Demand {
  constructor(initialDemand, sensitivity) {
    this.demand = initialDemand;
    this.sensitivity = sensitivity;
  }

  adjustDemand(price) {
    // Simple model: demand decreases as price increases
    this.demand -= price * this.sensitivity;
    return this.demand;
  }
}

class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
  }

  sell(quantity) {
    const adjustedDemand = this.demand.adjustDemand(this.pricing.calculatePrice(quantity));
    if (adjustedDemand >= quantity) {
      console.log(`Sold ${quantity} items at a price of ${this.pricing.calculatePrice(quantity)}`);
      return true;
    } else {
      console.log(`Could not sell ${quantity} items. Only ${adjustedDemand} items were demanded.`);
      return false;
    }
  }
}

