canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const tileSize = 32;
const roomWidth = 10;
const roomHeight = 8;
const timerDuration = 60; // seconds

let timer = timerDuration;
let gameLoopId;

const tiles = [];
for (let y = 0; y < roomHeight; y++) {
  for (let x = 0; x < roomWidth; x++) {
    tiles.push({ x, y, type: Math.random() > 0.8 ? 'wall' : 'floor' });
  }
}

function drawTile(x, y, type) {
  ctx.fillStyle = type === 'wall' ? '#333' : '#fff';
  ctx.fillRect(x * tileSize, y * tileSize, tileSize, tileSize);
}

function drawRoom() {
  tiles.forEach(tile => drawTile(tile.x, tile.y, tile.type));
}

function drawTimer() {
  ctx.fillStyle = '#000';
  ctx.font = '24px Arial';
  ctx.fillText(`Time: ${Math.floor(timer)}s`, 10, 30);
}

function update() {
  if (timer > 0) {
    timer -= 0.016; // approx 60fps
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawRoom();
  drawTimer();
}

function gameLoop() {
  update();
  render();
  gameLoopId = requestAnimationFrame(gameLoop);
}

gameLoop();

canvas.addEventListener('click', () => {
  cancelAnimationFrame(gameLoopId);
  setTimeout(() => {
    timer = timerDuration;
    gameLoop();
  }, 1000);
});
