class Experience {
  constructor() {
    this.levelThresholds = [100, 200, 300, 400, 500];
  }

  calculateLevel(experiencePoints) {
    for (let i = 0; i < this.levelThresholds.length; i++) {
      if (experiencePoints < this.levelThresholds[i]) {
        return i + 1;
      }
    }
    return this.levelThresholds.length + 1;
  }
}

