class Building {
    constructor() {
        this.buildings = {};
    }

    addBuilding(type, count = 1) {
        if (this.buildings[type]) {
            this.buildings[type] += count;
        } else {
            this.buildings[type] = count;
        }
    }

    getBuildingCount(type) {
        return this.buildings[type] || 0;
    }
}

class Resource {
    constructor() {
        this.resources = {};
    }

    addResource(type, amount = 1) {
        if (this.resources[type]) {
            this.resources[type] += amount;
        } else {
            this.resources[type] = amount;
        }
    }

    getResourceAmount(type) {
        return this.resources[type] || 0;
    }

    consumeResource(type, amount) {
        if (this.resources[type] >= amount) {
            this.resources[type] -= amount;
            return true;
        }
        return false;
    }
}

class Economy {
    constructor() {
        this.revenue = {};
    }

    addRevenue(type, amount = 1) {
        if (this.revenue[type]) {
            this.revenue[type] += amount;
        } else {
            this.revenue[type] = amount;
        }
    }

    getRevenue(type) {
        return this.revenue[type] || 0;
    }
}

class Coordinator {
    constructor() {
        this.buildingSystem = new Building();
        this.resourceSystem = new Resource();
        this.economySystem = new Economy();
    }

    build(type, count) {
        this.buildingSystem.addBuilding(type, count);
        console.log(`Built ${count} ${type} building(s).`);
    }

    collectResources() {
        const lumberMills = this.buildingSystem.getBuildingCount('lumberMill');
        const woodPerMill = 10;
        const totalWood = lumberMills * woodPerMill;
        this.resourceSystem.addResource('wood', totalWood);
        console.log(`Collected ${totalWood} wood.`);
    }

    generateRevenue() {
        const woodAmount = this.resourceSystem.getResourceAmount('wood');
        const woodPrice = 1;
        const totalRevenue = woodAmount * woodPrice;
        this.economySystem.addRevenue('gold', totalRevenue);
        this.resourceSystem.consumeResource('wood', woodAmount);
        console.log(`Generated ${totalRevenue} gold.`);
    }

    displayStatus() {
        console.log('Current Status:');
        console.log(`Buildings:`, this.buildingSystem.buildings);
        console.log(`Resources:`, this.resourceSystem.resources);
        console.log(`Economy:`, this.economySystem.revenue);
    }
}

