        if (this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }

    getBalance() {
        return this.balance;
    }
}

class Crop {
    constructor(name, growTime) {
        this.name = name;
        this.growTime = growTime;
        this.isReady = false;
    }

    grow() {
        if (this.growTime > 0) {
            this.growTime--;
            if (this.growTime === 0) {
                this.isReady = true;
            }
        }
    }

    isHarvestReady() {
        return this.isReady;
    }

    harvest() {
        if (this.isReady) {
            this.isReady = false;
            return this.name;
        }
        return null;
    }
}

class Farm {
    constructor() {
        this.crops = [];
    }

    plantCrop(name, growTime) {
        this.crops.push(new Crop(name, growTime));
    }

    growCrops() {
        this.crops.forEach(crop => crop.grow());
    }

    harvestCrops() {
        const harvested = [];
        this.crops = this.crops.filter(crop => {
            const harvestedCrop = crop.harvest();
            if (harvestedCrop) {
                harvested.push(harvestedCrop);
            }
            return !crop.isReady;
        });
        return harvested;
    }
}

class Market {
    constructor(economy) {
        this.economy = economy;
        this.inventory = {};
    }

    purchase(item, quantity) {
        const price = this.economy.getPrice(item) * quantity;
        if (this.economy.debit(price)) {
            if (this.inventory[item]) {
                this.inventory[item] += quantity;
            } else {
                this.inventory[item] = quantity;
            }
            return true;
        }
        return false;
    }

    getInventory() {
        return this.inventory;
    }
}

