const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const state = {
  currentState: 'menu',
  lastTimestamp: 0,
  fixedTimestep: 1000 / 60, // 60 FPS
  accumulatedTime: 0,
  deltaTime: 0,
  playerHealth: 100,
  enemyHealth: 100,
};

function renderMenu() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'white';
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('Press Enter to Start', canvas.width / 2, canvas.height / 2);
}

function renderPlaying() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'green';
  ctx.fillRect(50, 50, state.playerHealth * 8, 30);
  ctx.fillStyle = 'red';
  ctx.fillRect(canvas.width - 50 - (state.enemyHealth * 8), 50, state.enemyHealth * 8, 30);
}

function renderPaused() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'white';
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('Game Paused', canvas.width / 2, canvas.height / 2);
}

function renderGameOver() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'white';
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
}

function updateMenu() {
  if (keys.Enter) {
    state.currentState = 'playing';
  }
}

function updatePlaying(deltaTime) {
  if (keys.Space) {
    state.enemyHealth -= 10;
    keys.Space = false;
  }
  if (keys.P) {
    state.currentState = 'paused';
  }
  if (state.enemyHealth <= 0) {
    state.currentState = 'gameover';
  }
}

function updatePaused() {
  if (keys.P) {
    state.currentState = 'playing';
  }
}

function updateGameOver() {
  if (keys.R) {
    state.currentState = 'menu';
    state.playerHealth = 100;
    state.enemyHealth = 100;
  }
}

const keys = {};
document.addEventListener('keydown', (e) => {
  keys[e.key] = true;
});
document.addEventListener('keyup', (e) => {
  keys[e.key] = false;
});

function gameLoop(timestamp) {
  state.deltaTime = timestamp - state.lastTimestamp;
  state.lastTimestamp = timestamp;
  state.accumulatedTime += state.deltaTime;

  while (state.accumulatedTime >= state.fixedTimestep) {
    switch (state.currentState) {
      case 'menu':
        updateMenu();
        break;
      case 'playing':
        updatePlaying(state.fixedTimestep);
        break;
      case 'paused':
        updatePaused();
        break;
      case 'gameover':
        updateGameOver();
        break;
    }
    state.accumulatedTime -= state.fixedTimestep;
  }

  ctx.clearRect(0, 0, canvas.width, canvas.height);
  switch (state.currentState) {
    case 'menu':
      renderMenu();
      break;
    case 'playing':
      renderPlaying();
      break;
    case 'paused':
      renderPaused();
      break;
    case 'gameover':
      renderGameOver();
      break;
  }

  requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
