class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
    } else {
      throw new Error(`Not enough ${item} in inventory`);
    }
  }

  hasItem(item, quantity = 1) {
    return this.items[item] && this.items[item] >= quantity;
  }

  getItemQuantity(item) {
    return this.items[item] || 0;
  }
}

class Economy {
  constructor(prices) {
    this.prices = prices; // { item: price }
  }

  getCost(item) {
    return this.prices[item] || 0;
  }

  debit(amount) {
    if (amount > 0) {
      // For simplicity, assume we always have enough money
      console.log(`Debited ${amount} from the Economy`);
    } else {
      throw new Error('Invalid debit amount');
    }
  }
}

class Store {
