const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const FPS = 60;
const FIXED_TIMESTEP = 1000 / FPS;
let lastTime = performance.now();
let accumulator = 0;

const fish = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    size: 20,
    speed: 1,
    direction: Math.PI / 4
};

const particles = [];

function update(dt) {
    fish.x += fish.speed * Math.cos(fish.direction) * dt;
    fish.y += fish.speed * Math.sin(fish.direction) * dt;

    // Wrap around screen edges
    if (fish.x < 0) fish.x = canvas.width;
    if (fish.x > canvas.width) fish.x = 0;
    if (fish.y < 0) fish.y = canvas.height;
    if (fish.y > canvas.height) fish.y = 0;

    // Update particles
    particles.forEach(particle => {
        particle.x += particle.vx * dt;
        particle.y += particle.vy * dt;
        particle.alpha -= 0.02 * dt;
    });
    particles.filter(particle => particle.alpha > 0);
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw fish
    ctx.save();
    ctx.translate(fish.x, fish.y);
    ctx.rotate(fish.direction);
    ctx.beginPath();
    ctx.arc(0, 0, fish.size, 0, Math.PI * 2);
    ctx.fillStyle = 'blue';
    ctx.fill();
    ctx.restore();

    // Draw particles
    ctx.globalCompositeOperation = 'lighter';
    particles.forEach(particle => {
        ctx.beginPath();
        ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(255, 255, 255, ${particle.alpha})`;
        ctx.fill();
    });
    ctx.globalCompositeOperation = 'source-over';
}

function createParticleBurst(x, y) {
    for (let i = 0; i < 10; i++) {
        particles.push({
            x: x,
            y: y,
            size: Math.random() * 2 + 1,
            vx: (Math.random() - 0.5) * 5,
            vy: (Math.random() - 0.5) * 5,
            alpha: 1
        });
    }
}

canvas.addEventListener('click', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    createParticleBurst(x, y);
});

function gameLoop(timestamp) {
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    accumulator += dt;

    while (accumulator >= FIXED_TIMESTEP) {
        update(FIXED_TIMESTEP);
        accumulator -= FIXED_TIMESTEP;
    }

    render();
    requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
