// Ball Drop Game with Scoring System and Game Over State

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
const ctx = canvas.getContext('2d');
const dpr = window.devicePixelRatio;
canvas.width *= dpr;
canvas.height *= dpr;
ctx.scale(dpr, dpr);

const ball = {
  x: canvas.width / 2,
  y: 50,
  radius: 10,
  dx: 0,
  dy: 2,
  color: 'blue'
};

const platform = {
  x: 0,
  y: canvas.height - 30,
  width: canvas.width,
  height: 10,
  color: 'green'
};

let score = 0;
let gameOver = false;

function drawBall() {
  ctx.beginPath();
  ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
  ctx.fillStyle = ball.color;
  ctx.fill();
  ctx.closePath();
}

function drawPlatform() {
  ctx.beginPath();
  ctx.rect(platform.x, platform.y, platform.width, platform.height);
  ctx.fillStyle = platform.color;
  ctx.fill();
  ctx.closePath();
}

function drawScore() {
  ctx.font = '20px Arial';
  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 10, 30);
}

function update() {
  if (gameOver) return;

  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Ball movement
  ball.x += ball.dx;
  ball.y += ball.dy;

  // Ball collision with walls
  if (ball.x + ball.radius > canvas.width || ball.x - ball.radius < 0) {
    ball.dx = -ball.dx;
  }
  if (ball.y - ball.radius < 0) {
    ball.dy = -ball.dy;
  }

  // Ball collision with platform
  if (ball.y + ball.radius >= platform.y &&
      ball.x + ball.radius >= platform.x &&
      ball.x - ball.radius <= platform.x + platform.width) {
    ball.dy = -ball.dy;
    score++;
  }

  // Ball drop below platform
  if (ball.y + ball.radius > platform.y + platform.height) {
    gameOver = true;
  }

  drawBall();
  drawPlatform();
  drawScore();

  requestAnimationFrame(update);
}

update();

// Event listeners for platform movement
document.addEventListener('mousemove', (e) => {
  if (!gameOver) {
    platform.x = e.clientX;
  }
});

document.addEventListener('touchmove', (e) => {
  if (!gameOver) {
    platform.x = e.touches[0].clientX;
  }
});
