// Memory Card Game with Health Bar and Respawn

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let cards = [];
let flippedCards = [];
let matchedPairs = 0;
let health = 100;
let isRespawning = false;

const cardWidth = 80;
const cardHeight = 120;
const margin = 10;
const rows = 4;
const cols = 4;
const cardImages = [
  'https://via.placeholder.com/80x120?text=1',
  'https://via.placeholder.com/80x120?text=2',
  'https://via.placeholder.com/80x120?text=3',
  'https://via.placeholder.com/80x120?text=4',
  'https://via.placeholder.com/80x120?text=5',
  'https://via.placeholder.com/80x120?text=6',
  'https://via.placeholder.com/80x120?text=7',
  'https://via.placeholder.com/80x120?text=8'
];

function setCanvasSize() {
  const dpr = window.devicePixelRatio || 1;
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  ctx.scale(dpr, dpr);
}

function initializeGame() {
  cards = [];
  matchedPairs = 0;
  health = 100;
  isRespawning = false;

  cardImages.forEach(img => {
    cards.push({ img, matched: false, flipped: false });
    cards.push({ img, matched: false, flipped: false });
  });

  cards.sort(() => Math.random() - 0.5);

  requestAnimationFrame(gameLoop);
}

function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  renderCards();
  renderHealthBar();
  if (isRespawning) {
    health -= 1;
    if (health <= 0) {
      initializeGame();
    }
  }
  requestAnimationFrame(gameLoop);
}

function renderCards() {
  for (let i = 0; i < cards.length; i++) {
    const col = i % cols;
    const row = Math.floor(i / cols);
    const x = col * (cardWidth + margin) + margin;
    const y = row * (cardHeight + margin) + margin;

    ctx.strokeStyle = 'black';
    ctx.lineWidth = 2;

    if (cards[i].flipped || cards[i].matched) {
      const img = new Image();
      img.src = cards[i].img;
      img.onload = () => ctx.drawImage(img, x, y, cardWidth, cardHeight);
    } else {
      ctx.strokeRect(x, y, cardWidth, cardHeight);
    }
  }
}

