function flipCard(cardIndex) {
  if (flippedCards.length >= 2 || cards[cardIndex].flipped || cards[cardIndex].matched) return;

  cards[cardIndex].flipped = true;
  flippedCards.push(cards[cardIndex]);

  if (flippedCards.length === 2) {
