  const purchasedItem = store.purchaseItem(50);
  console.log("Purchased item:", purchasedItem);
  console.log("Current balance:", economy.getBalance());
  console.log("Inventory:", inventory.getItems());
} catch (error) {
  console.error(error.message);
}
