class Bank {
  constructor() {
    this.balance = 0;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      console.log(`Deposited ${amount}, new balance is ${this.balance}`);
    } else {
      console.log('Deposit amount must be positive');
    }
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}, new balance is ${this.balance}`);
    } else {
      console.log('Invalid withdrawal amount');
    }
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor() {
    this.prices = {
      apple: 1,
      banana: 2,
      orange: 3
    };
  }

  getPrice(item) {
    return this.prices[item] || null;
  }

  sellItem(item, quantity, bank) {
    const price = this.getPrice(item);
    if (price !== null) {
      const totalCost = price * quantity;
      bank.withdraw(totalCost);
      console.log(`Sold ${quantity} ${item}(s) for ${totalCost}`);
