        ctx.font = '36px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(`Elapsed: ${elapsedTime.toFixed(1)}s`, canvas.width / 2, 50);
        ctx.fillText(`Taps: ${tapCount}`, canvas.width / 2, 100);

        if (tapCount > 0) {
            const tapSpeed = Date.now() - lastTapTime;
            ctx.fillText(`Last Tap Speed: ${tapSpeed.toFixed(1)}ms`, canvas.width / 2, 150);
        }
    }
}

