ctx.scale(devicePixelRatio, devicePixelRatio);

const tileSize = 32;
const boardWidth = 10;
const boardHeight = 10;
const board = Array.from({ length: boardHeight }, () =>
  Array(boardWidth).fill(null)
);

const player = { x: 0, y: 0, turn: true };
const enemy = { x: boardWidth - 1, y: boardHeight - 1, turn: false };

function drawBoard() {
  ctx.fillStyle = 'white';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  for (let y = 0; y < boardHeight; y++) {
    for (let x = 0; x < boardWidth; x++) {
      ctx.fillStyle = (x + y) % 2 === 0 ? '#ddd' : '#aaa';
      ctx.fillRect(x * tileSize, y * tileSize, tileSize, tileSize);
    }
  }
}

function drawEntities() {
  ctx.fillStyle = player.turn ? 'green' : 'blue';
  ctx.fillRect(player.x * tileSize, player.y * tileSize, tileSize, tileSize);

  ctx.fillStyle = enemy.turn ? 'green' : 'blue';
  ctx.fillRect(enemy.x * tileSize, enemy.y * tileSize, tileSize, tileSize);
}

function handleInput() {
  if (player.turn) {
    const move = { x: 0, y: 0 };

    if (keys['ArrowUp']) move.y = -1;
    if (keys['ArrowDown']) move.y = 1;
    if (keys['ArrowLeft']) move.x = -1;
    if (keys['ArrowRight']) move.x = 1;

    const newX = player.x + move.x;
    const newY = player.y + move.y;

    if (newX >= 0 && newX < boardWidth && newY >= 0 && newY < boardHeight) {
      player.x = newX;
      player.y = newY;
    }
  }
}

const keys = {};
document.addEventListener('keydown', (e) => {
  keys[e.key] = true;
});
document.addEventListener('keyup', (e) => {
  keys[e.key] = false;
});

canvas.addEventListener('click', (e) => {
  const rect = canvas.getBoundingClientRect();
  const x = Math.floor(((e.clientX - rect.left) / devicePixelRatio) / tileSize);
  const y = Math.floor(((e.clientY - rect.top) / devicePixelRatio) / tileSize);

  if (player.turn) {
    if (x >= 0 && x < boardWidth && y >= 0 && y < boardHeight) {
      player.x = x;
      player.y = y;
    }
  }
});

function gameLoop() {
