const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const fixedTimestep = 16.67; // approximately 60 FPS
let accumulator = 0;

const entities = [
  { x: 100, y: 300, dx: 2, dy: 0, color: 'red' },
  { x: 700, y: 300, dx: -2, dy: 0, color: 'blue' }
];

function update(delta) {
  entities.forEach(entity => {
    entity.x += entity.dx * delta;
    entity.y += entity.dy * delta;

    // Simple boundary collision
    if (entity.x <= 0 || entity.x >= canvas.width) {
      entity.dx *= -1;
      particleBurst(entity.x, entity.y, entity.color);
    }
  });
}

function particleBurst(x, y, color) {
  const numParticles = 20;
  for (let i = 0; i < numParticles; i++) {
    const angle = Math.random() * Math.PI * 2;
    const speed = Math.random() * 2;
    const particle = {
      x: x,
      y: y,
      dx: Math.cos(angle) * speed,
      dy: Math.sin(angle) * speed,
      color: color,
      ttl: 50 // Time to live
    };
    particles.push(particle);
  }
}

const particles = [];

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Render entities
  entities.forEach(entity => {
    ctx.fillStyle = entity.color;
    ctx.fillRect(entity.x, entity.y, 20, 20);
  });

  // Render particles
  particles.forEach(particle => {
    ctx.fillStyle = particle.color;
    ctx.beginPath();
    ctx.arc(particle.x, particle.y, 2, 0, Math.PI * 2);
    ctx.fill();
  });
}

function gameLoop(timestamp) {
  const delta = timestamp - lastTimestamp;
  lastTimestamp = timestamp;

  accumulator += delta;

  while (accumulator >= fixedTimestep) {
    update(fixedTimestep / 1000);
    accumulator -= fixedTimestep;
  }

  render();

  requestAnimationFrame(gameLoop);
}

let lastTimestamp = performance.now();
requestAnimationFrame(gameLoop);
