class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Wallet {
  constructor(eventBus, initialBalance = 0) {
    this.eventBus = eventBus;
    this.balance = initialBalance;
    this.eventBus.subscribe('purchase', this.handlePurchase.bind(this));
  }

  getBalance() {
    return this.balance;
  }

  addFunds(amount) {
    this.balance += amount;
    console.log(`Added ${amount} to wallet. New balance: ${this.balance}`);
  }

  handlePurchase(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      console.log(`Purchased item for ${amount}. Remaining balance: ${this.balance}`);
      this.eventBus.emit('purchaseSuccess', { amount });
    } else {
      console.log(`Insufficient funds to purchase item for ${amount}. Current balance: ${this.balance}`);
      this.eventBus.emit('purchaseFailure', { amount, message: 'Insufficient funds' });
    }
  }
}

class Shop {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {
      sword: { price: 50 },
      shield: { price: 30 },
      potion: { price: 10 }
    };
    this.eventBus.subscribe('purchaseSuccess', this.handlePurchaseSuccess.bind(this));
    this.eventBus.subscribe('purchaseFailure', this.handlePurchaseFailure.bind(this));
  }

  getItems() {
    return this.items;
  }

  purchaseItem(itemName) {
    const item = this.items[itemName];
    if (item) {
      console.log(`Attempting to purchase ${itemName} for ${item.price}`);
      this.eventBus.emit('purchase', item.price);
    } else {
      console.log(`Item ${itemName} not found in shop.`);
    }
  }

  handlePurchaseSuccess({ amount }) {
    console.log(`Purchase successful for ${amount}.`);
  }

  handlePurchaseFailure({ amount, message }) {
    console.log(`Purchase failed for ${amount}: ${message}`);
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {};
    this.eventBus.subscribe('purchaseSuccess', this.addItem.bind(this));
  }

  getInventory() {
    return this.items;
  }

  addItem({ amount }) {
    const itemName = Object.keys(this.eventBus.eventBus.events.purchase).find(key => this.eventBus.eventBus.events.purchase[key] === amount);
    if (itemName) {
      this.items[itemName] = (this.items[itemName] || 0) + 1;
      console.log(`Added ${itemName} to inventory. Current inventory:`, this.items);
    }
  }
}

// Demo
