const inventory = new Inventory(eventBus);

console.log('Initial wallet balance:', wallet.getBalance());
shop.purchaseItem('sword');
shop.purchaseItem('potion');
shop.purchaseItem('shield');
shop.purchaseItem('elixir'); // Non-existent item
console.log('Final wallet balance:', wallet.getBalance());
console.log('Final inventory:', inventory.getInventory());
