const canvas = document.createElement('canvas');
canvas.width = 400;
canvas.height = 400;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const TILE_SIZE = 100;
const GRID_SIZE = 4;
const BOARD_WIDTH = TILE_SIZE * GRID_SIZE;
const BOARD_HEIGHT = TILE_SIZE * GRID_SIZE;

let board = Array.from({ length: GRID_SIZE }, () => Array(GRID_SIZE).fill(0));
let score = 0;
let highScore = localStorage.getItem('highScore') ? parseInt(localStorage.getItem('highScore')) : 0;

function getRandomEmptyCell() {
  const emptyCells = [];
  for (let i = 0; i < GRID_SIZE; i++) {
    for (let j = 0; j < GRID_SIZE; j++) {
      if (board[i][j] === 0) {
        emptyCells.push({ x: i, y: j });
      }
    }
  }
  return emptyCells[Math.floor(Math.random() * emptyCells.length)];
}

function spawnTile() {
  const cell = getRandomEmptyCell();
  if (cell) {
    board[cell.x][cell.y] = Math.random() > 0.9 ? 4 : 2;
  }
}

function drawTile(x, y, value) {
  ctx.fillStyle = '#cdc1b4';
  ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
  ctx.fillStyle = value >= 2048 ? '#f9f6f2' : '#776e65';
  ctx.font = '50px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(value, (x + 0.5) * TILE_SIZE, (y + 0.5) * TILE_SIZE);
}

function drawBoard() {
  ctx.fillStyle = '#bbada0';
  ctx.fillRect(0, 0, BOARD_WIDTH, BOARD_HEIGHT);
  for (let i = 0; i < GRID_SIZE; i++) {
    for (let j = 0; j < GRID_SIZE; j++) {
      if (board[i][j] !== 0) {
        drawTile(i, j, board[i][j]);
      }
    }
  }
}

function move(dir) {
  let moved = false;
  let newBoard = Array.from({ length: GRID_SIZE }, () => Array(GRID_SIZE).fill(0));

  if (dir === 'up') {
    for (let j = 0; j < GRID_SIZE; j++) {
      let col = [];
      for (let i = 0; i < GRID_SIZE; i++) {
        if (board[i][j] !== 0) {
          col.push(board[i][j]);
        }
      }
      let newRow = merge(col);
      for (let i = 0; i < GRID_SIZE; i++) {
        newBoard[i][j] = newRow[i];
        if (newBoard[i][j] !== board[i][j]) {
          moved = true;
        }
      }
    }
  } else if (dir === 'down') {
    for (let j = 0; j < GRID_SIZE; j++) {
      let col = [];
      for (let i = GRID_SIZE - 1; i >= 0; i--) {
        if (board[i][j] !== 0) {
          col.push(board[i][j]);
        }
      }
      let newRow = merge(col).reverse();
      for (let i = GRID_SIZE - 1; i >= 0; i--) {
        newBoard[i][j] = newRow[GRID_SIZE - 1 - i];
        if (newBoard[i][j] !== board[i][j]) {
          moved = true;
        }
      }
    }
  } else if (dir === 'left') {
    for (let i = 0; i < GRID_SIZE; i++) {
      let row = [];
      for (let j = 0; j < GRID_SIZE; j++) {
        if (board[i][j] !== 0) {
          row.push(board[i][j]);
        }
      }
      let newRow = merge(row);
      for (let j = 0; j < GRID_SIZE; j++) {
        newBoard[i][j] = newRow[j];
        if (newBoard[i][j] !== board[i][j]) {
          moved = true;
        }
      }
    }
  } else if (dir === 'right') {
    for (let i = 0; i < GRID_SIZE; i++) {
      let row = [];
      for (let j = GRID_SIZE - 1; j >= 0; j--) {
        if (board[i][j] !== 0) {
          row.push(board[i][j]);
        }
      }
      let newRow = merge(row).reverse();
      for (let j = GRID_SIZE - 1; j >= 0; j--) {
        newBoard[i][j] = newRow[GRID_SIZE - 1 - j];
        if (newBoard[i][j] !== board[i][j]) {
          moved = true;
        }
      }
    }
  }

  if (moved) {
    board = newBoard;
    spawnTile();
    updateScore();
  }
}

function merge(row) {
  let newRow = [];
  let skip = false;
  for (let i = 0; i < row.length; i++) {
    if (skip) {
      skip = false;
      continue;
    }
    if (i < row.length - 1 && row[i] === row[i + 1]) {
      newRow.push(row[i] * 2);
      score += row[i] * 2;
      skip = true;
    } else {
      newRow.push(row[i]);
    }
  }
  while (newRow.length < GRID_SIZE) {
    newRow.push(0);
  }
  return newRow;
}

function updateScore() {
  highScore = Math.max(score, highScore);
  localStorage.setItem('highScore', highScore);
}

function checkGameOver() {
  for (let i = 0; i < GRID_SIZE; i++) {
    for (let j = 0; j < GRID_SIZE; j++) {
      if (board[i][j] === 0) {
        return false;
      }
      if (i > 0 && board[i][j] === board[i - 1][j]) {
        return false;
      }
      if (i < GRID_SIZE - 1 && board[i][j] === board[i + 1][j]) {
        return false;
      }
      if (j > 0 && board[i][j] === board[i][j - 1]) {
        return false;
      }
      if (j < GRID_SIZE - 1 && board[i][j] === board[i][j + 1]) {
        return false;
      }
    }
  }
  return true;
}

function mainLoop() {
  drawBoard();
  if (checkGameOver()) {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.fillRect(0, 0, BOARD_WIDTH, BOARD_HEIGHT);
    ctx.fillStyle = '#ffffff';
    ctx.font = '40px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('Game Over', BOARD_WIDTH / 2, BOARD_HEIGHT / 2);
  }
  requestAnimationFrame(mainLoop);
}

document.addEventListener('keydown', (e) => {
  switch (e.key) {
    case 'ArrowUp':
      move('up');
      break;
    case 'ArrowDown':
      move('down');
      break;
    case 'ArrowLeft':
      move('left');
      break;
    case 'ArrowRight':
      move('right');
      break;
  }
});

spawnTile();
spawnTile();
mainLoop();
