    if (player.health <= 0) {
        player.respawnCountdown += dt;
        if (player.respawnCountdown >= player.respawnTime) {
            player.health = 100;
            player.respawnCountdown = 0;
        }
        return;
    }

    if (keys[target.text[0]]) {
        target.text = target.text.slice(1);
    }

    if (target.text.length === 0) {
        target.x = Math.random() * canvas.width;
        target.y = Math.random() * canvas.height;
