      this.resourceSystem.consumeResources(cost);
      this.buildingSystem.build(name, type, cost);
      return true;
    }
    return false;
  }

  getEconomyStatus() {
    return {
      resources: this.resourceSystem.getResources(),
      buildings: this.buildingSystem.buildings
    };
  }
