  cardImages.push(`image${i}.png`);
}

// Shuffle card images
for (let i = cardImages.length - 1; i > 0; i--) {
  const j = Math.floor(Math.random() * (i + 1));
  [cardImages[i], cardImages[j]] = [cardImages[j], cardImages[i]];
}

// Create cards
for (let i = 0; i < rows; i++) {
  for (let j = 0; j < cols; j++) {
    const x = j * (cardWidth + cardSpacing) + (canvas.width - (cols * (cardWidth + cardSpacing))) / 2;
    const y = i * (cardHeight + cardSpacing) + (canvas.height - (rows * (cardHeight + cardSpacing))) / 2;
    cards.push({
      x,
      y,
      image: cardImages.shift(),
      flipped: false,
      matched: false
    });
  }
}

function drawCard(card) {
  if (card.flipped || card.matched) {
    const img = new Image();
    img.src = card.image;
    ctx.drawImage(img, card.x, card.y, cardWidth, cardHeight);
  } else {
    ctx.fillStyle = '#ccc';
    ctx.fillRect(card.x, card.y, cardWidth, cardHeight);
  }
}

