  if (performance.now() - lastSpawnTime >= spawnInterval) {
    lastSpawnTime = performance.now();
    enemyCount++;
    spawnInterval = Math.max(1000, spawnInterval - 100); // Decrease spawn interval to increase difficulty
  }
}

function flipCard(card) {
  if (flippedCards.length < 2 && !card.flipped && !card.matched) {
    card.flipped = true;
