const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
let ctx = canvas.getContext('2d');

let boardSize = 4;
let tileSize = 100;
let padding = 10;
let comboMultiplier = 1;

function resizeCanvas() {
  let dpr = window.devicePixelRatio || 1;
  let width = window.innerWidth;
  let height = window.innerHeight;
  canvas.width = width * dpr;
  canvas.height = height * dpr;
  canvas.style.width = `${width}px`;
  canvas.style.height = `${height}px`;
  ctx.scale(dpr, dpr);
}

function createBoard() {
  let board = Array.from({ length: boardSize }, () => Array(boardSize).fill(0));
  addRandomTile(board);
  addRandomTile(board);
  return board;
}

function addRandomTile(board) {
  let emptyTiles = [];
  for (let i = 0; i < boardSize; i++) {
    for (let j = 0; j < boardSize; j++) {
      if (board[i][j] === 0) emptyTiles.push([i, j]);
    }
  }
  if (emptyTiles.length > 0) {
    let [x, y] = emptyTiles[Math.floor(Math.random() * emptyTiles.length)];
    board[x][y] = Math.random() < 0.9 ? 2 : 4;
  }
}

function drawBoard(board) {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let i = 0; i < boardSize; i++) {
    for (let j = 0; j < boardSize; j++) {
      let value = board[i][j];
      ctx.fillStyle = value ? `rgb(${255 - value * 10}, ${value * 10}, 255)` : '#ccc';
      ctx.fillRect(j * tileSize + padding, i * tileSize + padding, tileSize - padding * 2, tileSize - padding * 2);
      ctx.fillStyle = '#000';
      ctx.font = 'bold 30px Arial';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(value || '', j * tileSize + tileSize / 2, i * tileSize + tileSize / 2);
    }
  }
}

function moveBoard(board, direction) {
  let moved = false;
  let newBoard = board.map(row => row.slice());
  switch (direction) {
    case 'up':
      newBoard = transpose(newBoard);
      [moved, newBoard] = slideLeft(newBoard);
      newBoard = transpose(newBoard);
      break;
    case 'down':
      newBoard = transpose(newBoard).map(row => row.reverse());
      [moved, newBoard] = slideLeft(newBoard);
      newBoard = transpose(newBoard).map(row => row.reverse());
      break;
    case 'left':
      [moved, newBoard] = slideLeft(newBoard);
      break;
    case 'right':
      newBoard = newBoard.map(row => row.reverse());
      [moved, newBoard] = slideLeft(newBoard);
      newBoard = newBoard.map(row => row.reverse());
      break;
  }
  if (moved) {
    addRandomTile(newBoard);
  }
  return newBoard;
}

function transpose(board) {
  return board[0].map((_, i) => board.map(row => row[i]));
}

function slideLeft(board) {
  let moved = false;
  for (let i = 0; i < boardSize; i++) {
    let row = board[i].filter(num => num !== 0);
    let newRow = [];
    for (let j = 0; j < row.length; j++) {
      if (j < row.length - 1 && row[j] === row[j + 1]) {
        newRow.push(row[j] * comboMultiplier);
        comboMultiplier++;
        row[j + 1] = 0;
      } else {
        newRow.push(row[j]);
      }
    }
    newRow = newRow.filter(num => num !== 0);
    while (newRow.length < boardSize) newRow.push(0);
    if (JSON.stringify(board[i]) !== JSON.stringify(newRow)) moved = true;
    board[i] = newRow;
  }
  comboMultiplier = 1;
  return [moved, board];
}

function handleKeyPress(e) {
  let board = moveBoard(currentBoard, e.key.replace('Arrow', ''));
  if (JSON.stringify(board) !== JSON.stringify(currentBoard)) {
    currentBoard = board;
    drawBoard(currentBoard);
  }
}

resizeCanvas();
window.addEventListener('resize', resizeCanvas);
window.addEventListener('keydown', handleKeyPress);

let currentBoard = createBoard();
drawBoard(currentBoard);
