// Maze Chase Game with Wave/Level Progression

const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);

const ctx = canvas.getContext('2d');

let level = 1;
let wave = 1;
const maxWaves = 5;
const player = { x: canvas.width / 2, y: canvas.height / 2, size: 10, speed: 5 };
let enemies = [];
let lastEnemySpawn = 0;
const spawnInterval = 1000;

function random(min, max) {
    return Math.random() * (max - min) + min;
}

function generateMaze() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const wallSize = 30;
    for (let i = 0; i < canvas.width; i += wallSize) {
        ctx.fillStyle = 'black';
        ctx.fillRect(i, 0, wallSize, wallSize);
        ctx.fillRect(i, canvas.height - wallSize, wallSize, wallSize);
    }
    for (let j = 0; j < canvas.height; j += wallSize) {
        ctx.fillStyle = 'black';
        ctx.fillRect(0, j, wallSize, wallSize);
        ctx.fillRect(canvas.width - wallSize, j, wallSize, wallSize);
    }
}

function spawnEnemy() {
    if (Date.now() - lastEnemySpawn > spawnInterval) {
        enemies.push({
            x: random(wallSize, canvas.width - wallSize),
            y: random(wallSize, canvas.height - wallSize),
            size: 10,
            speed: 1 + wave * 0.2
        });
        lastEnemySpawn = Date.now();
    }
}

function drawPlayer() {
    ctx.fillStyle = 'blue';
    ctx.beginPath();
    ctx.arc(player.x, player.y, player.size, 0, Math.PI * 2);
    ctx.fill();
}

function drawEnemies() {
    ctx.fillStyle = 'red';
    enemies.forEach(enemy => {
        ctx.beginPath();
        ctx.arc(enemy.x, enemy.y, enemy.size, 0, Math.PI * 2);
        ctx.fill();
    });
}

function moveEnemies() {
    enemies.forEach(enemy => {
        const dx = player.x - enemy.x;
        const dy = player.y - enemy.y;
        const distance = Math.sqrt(dx * dx + dy * dy);
        if (distance > 0) {
            enemy.x += (dx / distance) * enemy.speed;
            enemy.y += (dy / distance) * enemy.speed;
        }
    });
}

function checkCollision() {
    enemies = enemies.filter(enemy => {
        const dx = player.x - enemy.x;
        const dy = player.y - enemy.y;
        const distance = Math.sqrt(dx * dx + dy * dy);
        return distance > player.size + enemy.size;
    });
}

function handleInput() {
    if (keys['ArrowUp'] && player.y > player.size) player.y -= player.speed;
    if (keys['ArrowDown'] && player.y < canvas.height - player.size) player.y += player.speed;
    if (keys['ArrowLeft'] && player.x > player.size) player.x -= player.speed;
    if (keys['ArrowRight'] && player.x < canvas.width - player.size) player.x += player.speed;
}

const keys = {};
window.addEventListener('keydown', e => keys[e.key] = true);
window.addEventListener('keyup', e => keys[e.key] = false);

function update() {
    handleInput();
    spawnEnemy();
    moveEnemies();
    checkCollision();
    if (enemies.length === 0) {
        wave++;
        if (wave > maxWaves) {
            level++;
            wave = 1;
        }
        generateMaze();
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    generateMaze();
    drawPlayer();
    drawEnemies();
}

function gameLoop() {
    update();
    draw();
    requestAnimationFrame(gameLoop);
}

generateMaze();
gameLoop();
