class Trade {
  constructor() {
    this.resources = { gold: 0, wood: 0, stone: 0 };
  }

  // Public API
  trade(resource, amount, faction) {
    if (this.resources[resource] >= amount) {
      this.resources[resource] -= amount;
      faction.receiveResource(resource, amount);
      console.log(`Traded ${amount} ${resource} to ${faction.name}.`);
      return true;
    } else {
      console.log(`Not enough ${resource} to trade.`);
      return false;
    }
  }

  getResources() {
    return { ...this.resources };
  }
}

class Reputation {
  constructor() {
    this.standing = { trader: 0, gatherer: 0, warrior: 0 };
  }

  // Public API
  updateReputation(faction, amount) {
    this.standing[faction] += amount;
    console.log(`Reputation with ${faction} updated by ${amount}.`);
  }

  getReputation() {
    return { ...this.standing };
  }
}

class Faction {
  constructor(name, tradeSystem, reputationSystem) {
    this.name = name;
    this.tradeSystem = tradeSystem;
    this.reputationSystem = reputationSystem;
    this.resources = { gold: 0, wood: 0, stone: 0 };
  }

  // Public API
  receiveResource(resource, amount) {
    this.resources[resource] += amount;
    console.log(`${this.name} received ${amount} ${resource}.`);
  }

  tradeResource(resource, amount, targetFaction) {
    if (this.tradeSystem.trade(resource, amount, targetFaction)) {
      this.reputationSystem.updateReputation(targetFaction.name, 1);
    } else {
      this.reputationSystem.updateReputation(targetFaction.name, -1);
    }
  }

  getResources() {
    return { ...this.resources };
  }
}

