class Crafting {
  constructor() {
    this.recipes = {};
  }

  addRecipe(recipe) {
    this.recipes[recipe.id] = recipe;
  }

  canCraft(itemId, inventory) {
    const recipe = this.recipes[itemId];
    if (!recipe) return false;
    for (const [ingredient, amount] of Object.entries(recipe.ingredients)) {
      if (inventory.getCount(ingredient) < amount) return false;
    }
    return true;
  }

  craft(itemId, inventory) {
    if (!this.canCraft(itemId, inventory)) return false;
    const recipe = this.recipes[itemId];
    for (const [ingredient, amount] of Object.entries(recipe.ingredients)) {
      inventory.remove(ingredient, amount);
    }
    inventory.add(recipe.result, 1);
    return true;
  }
}

