const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let state = 'menu';
let lastTime = 0;
let score = 0;
let player = { x: 50, y: 100, width: 20, height: 20 };
let obstacles = [];
let obstacleSpeed = 2;
let obstacleWidth = 20;
let obstacleHeight = 50;

function resizeCanvas() {
    const dpr = window.devicePixelRatio || 1;
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
    ctx.scale(dpr, dpr);
}

window.addEventListener('resize', resizeCanvas);
resizeCanvas();

function createObstacle() {
    obstacles.push({
        x: canvas.width,
        y: canvas.height - obstacleHeight,
        width: obstacleWidth,
        height: obstacleHeight
    });
}

function update() {
    const now = performance.now();
    const dt = (now - lastTime) / 1000;
    lastTime = now;

    if (state === 'playing') {
        player.x += 5; // Simple movement

        // Move obstacles
        obstacles.forEach(obstacle => {
            obstacle.x -= obstacleSpeed;
        });

        // Remove off-screen obstacles
        obstacles = obstacles.filter(obstacle => obstacle.x + obstacle.width > 0);

        // Check for collisions
        if (obstacles.some(obstacle => {
            return player.x < obstacle.x + obstacle.width &&
                   player.x + player.width > obstacle.x &&
                   player.y < obstacle.y + obstacle.height &&
                   player.y + player.height > obstacle.y;
        })) {
            state = 'gameover';
        }

        // Create new obstacle
        if (Math.random() < 0.05) {
            createObstacle();
        }

        // Increase score
        score++;
    }

    requestAnimationFrame(update);
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (state === 'menu') {
        ctx.fillText('Press Space to Start', canvas.width / 2 - 50, canvas.height / 2);
    } else if (state === 'playing') {
        ctx.fillRect(player.x, player.y, player.width, player.height);
        obstacles.forEach(obstacle => {
            ctx.fillRect(obstacle.x, obstacle.y, obstacle.width, obstacle.height);
        });
        ctx.fillText(`Score: ${score}`, 10, 20);
    } else if (state === 'paused') {
        ctx.fillText('Paused', canvas.width / 2 - 20, canvas.height / 2);
    } else if (state === 'gameover') {
        ctx.fillText('Game Over', canvas.width / 2 - 25, canvas.height / 2);
        ctx.fillText(`Score: ${score}`, canvas.width / 2 - 20, canvas.height / 2 + 30);
        ctx.fillText('Press Space to Restart', canvas.width / 2 - 50, canvas.height / 2 + 60);
    }

    requestAnimationFrame(render);
}

