const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let width = window.innerWidth;
let height = window.innerHeight;
let dpr = window.devicePixelRatio;

canvas.width = width * dpr;
canvas.height = height * dpr;
ctx.scale(dpr, dpr);

const snake = [{ x: width / 2, y: height / 2 }];
const food = { x: Math.random() * width, y: Math.random() * height };
let direction = { x: 0, y: 0 };
let health = 100;
let gameOver = false;

function drawRect(x, y, w, h, color) {
  ctx.fillStyle = color;
  ctx.fillRect(x, y, w, h);
}

function drawText(text, x, y, color, font = '20px Arial') {
  ctx.fillStyle = color;
  ctx.font = font;
  ctx.fillText(text, x, y);
}

function resetGame() {
  snake.length = 1;
  snake[0] = { x: width / 2, y: height / 2 };
  food.x = Math.random() * width;
  food.y = Math.random() * height;
  direction = { x: 0, y: 0 };
  health = 100;
  gameOver = false;
}

function update() {
  if (gameOver) return;

  const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

  if (head.x < 0 || head.x > width || head.y < 0 || head.y > height) {
    health -= 10;
    if (health <= 0) {
      gameOver = true;
    } else {
      resetGame();
    }
    return;
  }

  snake.unshift(head);

  if (Math.abs(head.x - food.x) < 10 && Math.abs(head.y - food.y) < 10) {
    food.x = Math.random() * width;
    food.y = Math.random() * height;
  } else {
    snake.pop();
  }
}

function draw() {
  ctx.clearRect(0, 0, width, height);

  drawRect(food.x, food.y, 10, 10, 'red');

  snake.forEach(segment => {
    drawRect(segment.x, segment.y, 10, 10, 'green');
  });

  drawText(`Health: ${health}`, 10, 20, 'black');

  if (gameOver) {
    drawText('Game Over! Press R to restart', width / 2 - 100, height / 2, 'red', '30px Arial');
  }
}

function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

window.addEventListener('keydown', e => {
  switch (e.key) {
    case 'ArrowUp':
      if (direction.y === 0) direction = { x: 0, y: -10 };
      break;
    case 'ArrowDown':
      if (direction.y === 0) direction = { x: 0, y: 10 };
      break;
    case 'ArrowLeft':
      if (direction.x === 0) direction = { x: -10, y: 0 };
      break;
    case 'ArrowRight':
      if (direction.x === 0) direction = { x: 10, y: 0 };
      break;
    case 'r':
      if (gameOver) resetGame();
      break;
  }
});

window.addEventListener('resize', () => {
  width = window.innerWidth;
  height = window.innerHeight;
  dpr = window.devicePixelRatio;

  canvas.width = width * dpr;
  canvas.height = height * dpr;
  ctx.scale(dpr, dpr);
});

gameLoop();
