    for (let i = 0; i < numPowerUps; i++) {
        powerUps.push({
            x: Math.random() * (canvas.width - powerUpSize),
            y: Math.random() * (canvas.height - powerUpSize),
            collected: false
        });
    }
}

function drawPowerUps() {
    powerUps.forEach(powerUp => {
        if (!powerUp.collected) {
            ctx.fillStyle = 'green';
            ctx.fillRect(powerUp.x, powerUp.y, powerUpSize, powerUpSize);
        }
    });
}

function drawPlayer() {
    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x, player.y, player.size, player.size);
}

function checkCollision() {
    powerUps.forEach(powerUp => {
        if (!powerUp.collected &&
            player.x < powerUp.x + powerUpSize &&
            player.x + player.size > powerUp.x &&
            player.y < powerUp.y + powerUpSize &&
            player.y + player.size > powerUp.y) {
            powerUp.collected = true;
            score++;
        }
    });
}

function update() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = 'lightgreen';
    ctx.fillRect(0, 0, plotSize, plotSize);
    checkCollision();
    drawPowerUps();
    drawPlayer();
    ctx.fillStyle = 'black';
    ctx.fillText(`Score: ${score}`, 10, 20);
}

function gameLoop() {
    update();
    requestAnimationFrame(gameLoop);
