const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 400;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const BLOCK_SIZE = 20;
const COLS = canvas.width / BLOCK_SIZE;
const ROWS = canvas.height / BLOCK_SIZE;

let currentBlock = null;
let nextBlock = null;
let score = 0;
let level = 1;
let fallSpeed = 500; // milliseconds

const shapes = [
    [[1, 1, 1, 1]], // I
    [[1, 1], [1, 1]], // O
    [[1, 1, 0], [0, 1, 1]], // S
    [[0, 1, 1], [1, 1, 0]], // Z
    [[1, 0, 0], [1, 1, 1]], // L
    [[0, 0, 1], [1, 1, 1]], // J
    [[1, 1, 1], [0, 1, 0]]  // T
];

function getRandomShape() {
    const randomIndex = Math.floor(Math.random() * shapes.length);
    return shapes[randomIndex].map(row => [...row]);
}

function createBlock() {
    return {
        shape: getRandomShape(),
        x: Math.floor((COLS - currentBlock.shape[0].length) / 2),
        y: 0
    };
}

function drawBlock(block, color = 'blue') {
    block.shape.forEach((row, y) => {
        row.forEach((cell, x) => {
            if (cell) {
                ctx.fillStyle = color;
                ctx.fillRect((block.x + x) * BLOCK_SIZE, (block.y + y) * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
                ctx.strokeStyle = 'black';
                ctx.strokeRect((block.x + x) * BLOCK_SIZE, (block.y + y) * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
            }
        });
    });
}

function canMove(block, dx, dy) {
    return block.shape.every((row, y) => {
        return row.every((cell, x) => {
            const newX = block.x + dx + x;
            const newY = block.y + dy + y;
            return !cell || (newX >= 0 && newX < COLS && newY < ROWS);
        });
    });
}

function mergeBlock(block) {
    block.shape.forEach((row, y) => {
        row.forEach((cell, x) => {
            if (cell) {
                grid[block.y + y][block.x + x] = cell;
            }
        });
    });
}

function clearLines() {
    let linesCleared = 0;
    for (let y = ROWS - 1; y >= 0; y--) {
        if (grid[y].every(cell => cell)) {
            grid.splice(y, 1);
            grid.unshift(Array(COLS).fill(0));
            linesCleared++;
        }
    }
    if (linesCleared) {
        score += linesCleared * linesCleared;
        if (score >= level * 100) {
            level++;
            fallSpeed = Math.max(100, fallSpeed - 100);
        }
    }
}

let lastTime = 0;

function gameLoop(timestamp) {
    const deltaTime = timestamp - lastTime;
    lastTime = timestamp;

    if (!currentBlock) {
        currentBlock = nextBlock || createBlock();
        nextBlock = createBlock();
        if (!canMove(currentBlock, 0, 0)) {
            alert(`Game Over! Your score: ${score}`);
            document.location.reload();
            return;
        }
    }

    if (deltaTime > fallSpeed) {
        if (canMove(currentBlock, 0, 1)) {
            currentBlock.y++;
        } else {
            mergeBlock(currentBlock);
            clearLines();
            currentBlock = null;
        }
        lastTime = timestamp;
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    grid.forEach((row, y) => {
        row.forEach((cell, x) => {
            if (cell) {
                ctx.fillStyle = 'gray';
                ctx.fillRect(x * BLOCK_SIZE, y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
                ctx.strokeStyle = 'black';
                ctx.strokeRect(x * BLOCK_SIZE, y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
            }
        });
    });

    drawBlock(currentBlock);
    drawBlock(nextBlock, 'orange', 0, BLOCK_SIZE * ROWS);

    requestAnimationFrame(gameLoop);
}

const grid = Array.from({ length: ROWS }, () => Array(COLS).fill(0));

document.addEventListener('keydown', (event) => {
    if (event.key === 'ArrowLeft' && canMove(currentBlock, -1, 0)) {
        currentBlock.x--;
    } else if (event.key === 'ArrowRight' && canMove(currentBlock, 1, 0)) {
        currentBlock.x++;
    } else if (event.key === 'ArrowDown' && canMove(currentBlock, 0, 1)) {
        currentBlock.y++;
    } else if (event.key === 'ArrowUp') {
        const rotatedShape = currentBlock.shape[0].map((_, index) => 
            currentBlock.shape.map(row => row[index]).reverse()
        );
        const newBlock = { ...currentBlock, shape: rotatedShape };
        if (canMove(newBlock, 0, 0)) {
            currentBlock = newBlock;
        }
    }
});

requestAnimationFrame(gameLoop);
