const BOARD_SIZE = 8;
const TILE_SIZE = canvas.width / BOARD_SIZE;
const ENEMY_SPAWN_RATE = 500; // milliseconds
const DIFFICULTY_INCREMENT = 50; // milliseconds

let board = [];
let enemies = [];
let spawnInterval = ENEMY_SPAWN_RATE;

function initBoard() {
  for (let y = 0; y < BOARD_SIZE; y++) {
    const row = [];
    for (let x = 0; x < BOARD_SIZE; x++) {
      row.push(Math.floor(Math.random() * 3) + 1);
    }
    board.push(row);
  }
}

function drawBoard() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let y = 0; y < BOARD_SIZE; y++) {
    for (let x = 0; x < BOARD_SIZE; x++) {
      const value = board[y][x];
      ctx.fillStyle = `hsl(${value * 60}, 100%, 50%)`;
      ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
      ctx.strokeStyle = '#000';
      ctx.strokeRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
    }
  }
  drawEnemies();
}

function drawEnemies() {
  ctx.fillStyle = 'red';
  enemies.forEach(enemy => {
    ctx.fillRect(enemy.x * TILE_SIZE, enemy.y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
  });
}

function spawnEnemy() {
  const x = Math.floor(Math.random() * BOARD_SIZE);
  const y = Math.floor(Math.random() * BOARD_SIZE);
  enemies.push({ x, y });
  setTimeout(spawnEnemy, spawnInterval);
}

function update() {
  drawBoard();
  requestAnimationFrame(update);
}

