function spawnEnemy() {
  const x = Math.random() * (windowWidth - 50);
  const y = -50;
  const size = 30;
  enemies.push(new Enemy(x, y, size));
}

function update() {
  if (!isRunning) return;
  const now = Date.now();
  if (now - lastSpawnTime > spawnInterval) {
    spawnEnemy();
    lastSpawnTime = now;
    spawnInterval = Math.max(spawnInterval - 100, 500); // Ramp up difficulty
  }

  runner.update();
  enemies.forEach(enemy => {
    enemy.update();
    if (checkCollision(runner, enemy)) {
      gameOver();
    }
  });

  // Remove enemies that have moved off screen
  enemies = enemies.filter(enemy => enemy.y < windowHeight);
}

function draw() {
  ctx.clearRect(0, 0, windowWidth, windowHeight);

  runner.draw();
  enemies.forEach(enemy => enemy.draw());

  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
}

function checkCollision(runner, enemy) {
  return (
    runner.x < enemy.x + enemy.size &&
    runner.x + runner.size > enemy.x &&
    runner.y < enemy.y + enemy.size &&
    runner.y + runner.size > enemy.y
  );
}

