  enemies = [];
  runner.y = windowHeight - 100;
  spawnInterval = 2000;
}

function startGame() {
  isRunning = true;
  lastSpawnTime = Date.now();
  requestAnimationFrame(gameLoop);
}

function gameLoop() {
  update();
  draw();
  if (isRunning) requestAnimationFrame(gameLoop);
