const fixedTimestep = 16.666666666666668; // approximately 60 frames per second
let accumulator = 0;

const gravity = 0.5;
const jumpStrength = -10;
const moveSpeed = 5;

const player = {
    x: 50,
    y: 50,
    width: 30,
    height: 30,
    velocityY: 0,
    isGrounded: false
};

const platforms = [
    { x: 0, y: 550, width: canvas.width, height: 50 },
    { x: 200, y: 400, width: 200, height: 20 },
    { x: 500, y: 300, width: 100, height: 20 }
];

let comboMultiplier = 1;
let comboTimer = 0;
const comboTimeout = 1000;

function update(deltaTime) {
    const moveDirection = (keys['ArrowRight'] ? 1 : 0) - (keys['ArrowLeft'] ? 1 : 0);
    player.velocityY += gravity;
    player.x += moveSpeed * moveDirection;
    player.y += player.velocityY;

    for (const platform of platforms) {
        if (player.y + player.height > platform.y && player.y + player.height < platform.y + 5 &&
            player.x + player.width > platform.x && player.x < platform.x + platform.width) {
            player.y = platform.y - player.height;
            player.velocityY = 0;
            player.isGrounded = true;
            break;
        } else {
            player.isGrounded = false;
        }
    }

    if (keys['ArrowUp'] && player.isGrounded) {
        player.velocityY = jumpStrength;
        comboMultiplier = 1; // Reset combo multiplier on jump
    }

    // Update combo timer
    comboTimer += deltaTime;
    if (comboTimer > comboTimeout) {
        comboMultiplier = 1; // Reset combo multiplier after timeout
    }

    // Handle input for combo
    if (keys['ArrowRight'] || keys['ArrowLeft']) {
        comboTimer = 0; // Reset combo timer on movement
        comboMultiplier += 0.1; // Increment combo multiplier
    }
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x, player.y, player.width, player.height);

    ctx.fillStyle = 'green';
    for (const platform of platforms) {
        ctx.fillRect(platform.x, platform.y, platform.width, platform.height);
    }

    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Combo: ${comboMultiplier.toFixed(1)}x`, 10, 30);
}

const keys = {};
window.addEventListener('keydown', (e) => { keys[e.key] = true; });
window.addEventListener('keyup', (e) => { keys[e.key] = false; });

function gameLoop(timestamp) {
    accumulator += timestamp - lastTimestamp;
    lastTimestamp = timestamp;

    while (accumulator >= fixedTimestep) {
        update(fixedTimestep);
        accumulator -= fixedTimestep;
    }

    render();
    requestAnimationFrame(gameLoop);
}

let lastTimestamp = performance.now();
requestAnimationFrame(gameLoop);
