// Game state
const player = {
    x: canvas.width / 2,
    y: canvas.height - 50,
    width: 20,
    height: 20,
    speed: 5,
    jumping: false
};
let gravity = 0.5;
let jumpStrength = -10;
let obstacles = [];
let wave = 1;
let score = 0;
let lastTime = performance.now();
const fixedTimeStep = 1000 / 60; // 60 FPS

// Obstacle class
class Obstacle {
    constructor(x, y, width, height, speed) {
        this.x = x;
        this.y = y;
        this.width = width;
        this.height = height;
        this.speed = speed;
    }

    update() {
        this.x -= this.speed;
    }

    draw() {
        ctx.fillStyle = 'red';
        ctx.fillRect(this.x, this.y, this.width, this.height);
    }
}

// Button to jump
const button = document.createElement('button');
button.textContent = 'Jump';
button.style.position = 'absolute';
button.style.top = '10px';
button.style.left = '10px';
document.body.appendChild(button);
button.addEventListener('click', () => {
    if (!player.jumping) {
        player.jumping = true;
        player.y += jumpStrength;
    }
});

// Generate obstacles
function generateObstacles() {
    if (Math.random() < 0.1) {
        const width = 30;
        const height = 20;
        const speed = 2 + wave / 2;
        const x = canvas.width;
        const y = canvas.height - height - player.height;
        obstacles.push(new Obstacle(x, y, width, height, speed));
    }
}

// Check for collisions
function checkCollisions() {
    for (let obstacle of obstacles) {
        if (player.x < obstacle.x + obstacle.width &&
            player.x + player.width > obstacle.x &&
            player.y < obstacle.y + obstacle.height &&
            player.y + player.height > obstacle.y) {
            alert('Game Over! Score: ' + score);
            resetGame();
        }
    }
}

// Reset the game
function resetGame() {
    player.x = canvas.width / 2;
    player.y = canvas.height - 50;
    player.jumping = false;
    obstacles = [];
    wave = 1;
    score = 0;
}

// Update game state
function update(deltaTime) {
    if (player.jumping) {
        player.y += gravity * deltaTime;
        if (player.y + player.height >= canvas.height) {
            player.y = canvas.height - player.height;
            player.jumping = false;
        }
    }

    for (let obstacle of obstacles) {
        obstacle.update();
        if (obstacle.x + obstacle.width < 0) {
            obstacles.shift();
        }
    }

    generateObstacles();
    checkCollisions();
    score += deltaTime / 1000;
    if (score > wave * 10) {
        wave++;
    }
}

// Render the game
function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = 'green';
    ctx.fillRect(0, canvas.height - 50, canvas.width, 50); // Ground

    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x, player.y, player.width, player.height); // Player

    for (let obstacle of obstacles) {
        obstacle.draw();
    }

    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText('Wave: ' + wave, 10, 30);
    ctx.fillText('Score: ' + Math.floor(score), 10, 60);
}

// Main game loop
function gameLoop(timestamp) {
    const deltaTime = timestamp - lastTime;
    lastTime = timestamp;

    update(deltaTime);
    render();

    requestAnimationFrame(gameLoop);
}

// Start the game loop
requestAnimationFrame(gameLoop);
