game.displayStatus(); // Status after buying a sword
console.log("Buying a potion:", game.buyItem("potion"));
game.displayStatus(); // Status after buying a potion
console.log("Buying a non-existent item:", game.buyItem("non-existent"));
game.displayStatus(); // Status after trying to buy a non-existent item
