class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Farm {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('market:cropSold', this.onCropSold.bind(this));
  }

  plantCrop(cropType) {
    console.log(`Planting ${cropType} on the farm.`);
    this.eventBus.emit('farm:cropPlanted', { cropType });
  }

  onCropSold(data) {
    console.log(`Crop ${data.cropType} sold at price ${data.price}.`);
    this.eventBus.emit('farm:cropGrown', { cropType: data.cropType, amount: 10 });
  }
}

class Crop {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('farm:cropPlanted', this.onCropPlanted.bind(this));
    this.eventBus.subscribe('farm:cropGrown', this.onCropGrown.bind(this));
  }

  onCropPlanted(data) {
    console.log(`Crop ${data.cropType} has been planted.`);
  }

  onCropGrown(data) {
    console.log(`Crop ${data.cropType} has grown, now available for selling.`);
    this.eventBus.emit('market:cropAvailable', { cropType: data.cropType, amount: data.amount });
  }
}

class Market {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('market:cropAvailable', this.onCropAvailable.bind(this));
  }

  onCropAvailable(data) {
    console.log(`Crop ${data.cropType} is now available for sale.`);
    const price = Math.floor(Math.random() * 5) + 1; // Random price between 1 and 5
    console.log(`Selling ${data.cropType} at price ${price}.`);
    this.eventBus.emit('market:cropSold', { cropType: data.cropType, price });
  }
}

