const canvas = document.createElement('canvas');
canvas.width = 400;
canvas.height = 400;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const tileSize = 100;
const tileSpacing = 10;
const gridCols = 4;
const gridRows = 4;
const targetScore = 2048;

let grid = Array.from({ length: gridRows }, () => Array(gridCols).fill(0));
let score = 0;
let gameOver = false;

function randomTile() {
  return Math.random() < 0.9 ? 2 : 4;
}

function spawnTile() {
  const emptyCells = [];
  for (let row = 0; row < gridRows; row++) {
    for (let col = 0; col < gridCols; col++) {
      if (grid[row][col] === 0) {
        emptyCells.push({ row, col });
      }
    }
  }
  if (emptyCells.length > 0) {
    const { row, col } = emptyCells[Math.floor(Math.random() * emptyCells.length)];
    grid[row][col] = randomTile();
  }
}

function drawTile(value, x, y) {
  ctx.fillStyle = value > 2048 ? '#000' : '#fff';
  ctx.fillRect(x, y, tileSize, tileSize);
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = value > 2048 ? '#fff' : '#000';
  ctx.fillText(value, x + tileSize / 2, y + tileSize / 2);
}

function drawGrid() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let row = 0; row < gridRows; row++) {
    for (let col = 0; col < gridCols; col++) {
      const value = grid[row][col];
      if (value > 0) {
        drawTile(value, col * (tileSize + tileSpacing), row * (tileSize + tileSpacing));
      }
    }
  }
}

function move(direction) {
  let moved = false;
  const backupGrid = JSON.parse(JSON.stringify(grid));

  switch (direction) {
    case 'up':
      for (let col = 0; col < gridCols; col++) {
        let newRow = 0;
        let lastMergedRow = -1;
        for (let row = 0; row < gridRows; row++) {
          if (grid[row][col] > 0) {
            if (newRow > 0 && grid[newRow - 1][col] === grid[row][col] && newRow - 1 !== lastMergedRow) {
              grid[newRow - 1][col] *= 2;
              score += grid[newRow - 1][col];
              grid[row][col] = 0;
              lastMergedRow = newRow - 1;
              moved = true;
            } else if (grid[newRow][col] === 0) {
              grid[newRow][col] = grid[row][col];
              grid[row][col] = 0;
              moved = true;
            }
            newRow++;
          }
        }
      }
      break;
    case 'down':
      for (let col = 0; col < gridCols; col++) {
        let newRow = gridRows - 1;
        let lastMergedRow = -1;
        for (let row = gridRows - 1; row >= 0; row--) {
          if (grid[row][col] > 0) {
            if (newRow < gridRows - 1 && grid[newRow + 1][col] === grid[row][col] && newRow + 1 !== lastMergedRow) {
              grid[newRow + 1][col] *= 2;
              score += grid[newRow + 1][col];
              grid[row][col] = 0;
              lastMergedRow = newRow + 1;
              moved = true;
            } else if (grid[newRow][col] === 0) {
              grid[newRow][col] = grid[row][col];
              grid[row][col] = 0;
              moved = true;
            }
            newRow--;
          }
        }
      }
      break;
    case 'left':
      for (let row = 0; row < gridRows; row++) {
        let newCol = 0;
        let lastMergedCol = -1;
        for (let col = 0; col < gridCols; col++) {
          if (grid[row][col] > 0) {
            if (newCol > 0 && grid[row][newCol - 1] === grid[row][col] && newCol - 1 !== lastMergedCol) {
              grid[row][newCol - 1] *= 2;
              score += grid[row][newCol - 1];
              grid[row][col] = 0;
              lastMergedCol = newCol - 1;
              moved = true;
            } else if (grid[row][newCol] === 0) {
              grid[row][newCol] = grid[row][col];
              grid[row][col] = 0;
              moved = true;
            }
            newCol++;
          }
        }
      }
      break;
    case 'right':
      for (let row = 0; row < gridRows; row++) {
        let newCol = gridCols - 1;
        let lastMergedCol = -1;
        for (let col = gridCols - 1; col >= 0; col--) {
          if (grid[row][col] > 0) {
            if (newCol < gridCols - 1 && grid[row][newCol + 1] === grid[row][col] && newCol + 1 !== lastMergedCol) {
              grid[row][newCol + 1] *= 2;
              score += grid[row][newCol + 1];
              grid[row][col] = 0;
              lastMergedCol = newCol + 1;
              moved = true;
            } else if (grid[row][newCol] === 0) {
              grid[row][newCol] = grid[row][col];
              grid[row][col] = 0;
              moved = true;
            }
            newCol--;
          }
        }
      }
      break;
  }

  if (moved) {
    spawnTile();
  }

  return moved;
}

function isGameOver() {
  for (let row = 0; row < gridRows; row++) {
    for (let col = 0; col < gridCols; col++) {
      if (grid[row][col] === 0) {
        return false;
      }
      if (row > 0 && grid[row][col] === grid[row - 1][col]) {
        return false;
      }
      if (row < gridRows - 1 && grid[row][col] === grid[row + 1][col]) {
        return false;
      }
      if (col > 0 && grid[row][col] === grid[row][col - 1]) {
        return false;
      }
      if (col < gridCols - 1 && grid[row][col] === grid[row][col + 1]) {
        return false;
      }
    }
  }
  return true;
}

function aiMove() {
  const directions = ['up', 'down', 'left', 'right'];
  const moves = directions.map(dir => ({ direction: dir, moved: move(dir) }));
  moves.forEach(move => {
    move.moved = false;
    move.direction = null;
  });
  const bestMove = moves.find(move => move.moved);
  if (bestMove) {
    move(bestMove.direction);
  }
}

function gameLoop() {
  if (isGameOver()) {
    gameOver = true;
    console.log('Game Over!');
    return;
  }

  if (gameOver) return;

  aiMove();
  drawGrid();

  requestAnimationFrame(gameLoop);
}

function setup() {
  spawnTile();
  spawnTile();
  gameLoop();
}

document.addEventListener('DOMContentLoaded', setup);
