class Crafting {
  constructor(recipeSystem, inventorySystem) {
    this.recipeSystem = recipeSystem;
    this.inventorySystem = inventorySystem;
  }

  craft(item) {
    const recipe = this.recipeSystem.getRecipe(item);
    if (!recipe) {
      console.log(`No recipe found for ${item}`);
      return false;
    }

    if (this.inventorySystem.hasIngredients(recipe.ingredients)) {
      this.inventorySystem.consumeIngredients(recipe.ingredients);
      this.inventorySystem.addItem(item);
      console.log(`Crafted ${item}`);
      return true;
    } else {
      console.log(`Missing ingredients to craft ${item}`);
      return false;
    }
  }
}

// Recipe System
class Recipe {
  constructor() {
    this.recipes = {
      sword: { ingredients: { wood: 1, metal: 1 } },
      shield: { ingredients: { wood: 2, metal: 1 } }
    };
  }

  getRecipe(item) {
    return this.recipes[item];
  }
}

// Inventory System
class Inventory {
  constructor() {
    this.items = {};
  }

  hasIngredients(ingredients) {
    for (const [ingredient, amount] of Object.entries(ingredients)) {
      if (this.items[ingredient] === undefined || this.items[ingredient] < amount) {
        return false;
      }
    }
    return true;
  }

  consumeIngredients(ingredients) {
    for (const [ingredient, amount] of Object.entries(ingredients)) {
      this.items[ingredient] -= amount;
    }
  }

  addItem(item) {
    if (this.items[item]) {
      this.items[item]++;
    } else {
      this.items[item] = 1;
    }
  }

  logInventory() {
    console.log("Inventory:", this.items);
  }
}

