class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  hasItem(item, quantity) {
    return this.items[item] && this.items[item] >= quantity;
  }

  getItems() {
    return { ...this.items };
  }
}

class Recipe {
  constructor(name, ingredients, result) {
    this.name = name;
    this.ingredients = ingredients; // { item: quantity }
    this.result = result; // { item: quantity }
  }

  canCraft(inventory) {
    for (const [item, quantity] of Object.entries(this.ingredients)) {
      if (!inventory.hasItem(item, quantity)) {
        return false;
      }
    }
    return true;
  }
}

class Crafting {
  constructor(inventory, recipes) {
    this.inventory = inventory;
    this.recipes = recipes;
  }

  craft(recipeName) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (recipe && recipe.canCraft(this.inventory)) {
      for (const [item, quantity] of Object.entries(recipe.ingredients)) {
        this.inventory.removeItem(item, quantity);
      }
      for (const [item, quantity] of Object.entries(recipe.result)) {
        this.inventory.addItem(item, quantity);
      }
      return true;
    }
    return false;
  }

  getAvailableRecipes() {
    return this.recipes.filter(recipe => recipe.canCraft(this.inventory)).map(recipe => recipe.name);
  }
}

