```js
// Match-3 Board with Particle Burst Effect
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let pixelRatio = window.devicePixelRatio;
window.addEventListener('resize', () => {
    pixelRatio = window.devicePixelRatio;
    resizeCanvas();
});

function resizeCanvas() {
    canvas.width = window.innerWidth * pixelRatio;
    canvas.height = window.innerHeight * pixelRatio;
    ctx.scale(pixelRatio, pixelRatio);
    drawBoard();
}

resizeCanvas();

const boardSize = 8;
const cellSize = 50;
const colors = ['#FF5733', '#33FF57', '#3357FF', '#F3FF33', '#FF33F6', '#33FFF6'];
let board = generateBoard();

function generateBoard() {
    return Array.from({ length: boardSize }, () => 
        Array.from({ length: boardSize }, () => Math.floor(Math.random() * colors.length))
    );
}

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let y = 0; y < boardSize; y++) {
        for (let x = 0; x < boardSize; x++) {
            ctx.fillStyle = colors[board[y][x]];
            ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
            ctx.strokeStyle = '#000';
            ctx.strokeRect(x * cellSize, y * cellSize, cellSize, cellSize);
        }
    }
}

function findMatches() {
    let matches = [];
    // Check horizontal matches
    for (let y = 0; y < boardSize; y++) {
        for (let x = 0; x < boardSize - 2; x++) {
            if (board[y][x] === board[y][x + 1] && board[y][x] === board[y][x + 2]) {
                matches.push([[x, y], [x + 1, y], [x + 2, y]]);
            }
        }
    }
    // Check vertical matches
    for (let x = 0; x < boardSize; x++) {
        for (let y = 0; y < boardSize - 2; y++) {
            if (board[y][x] === board[y + 1][x] && board[y][x] === board[y + 2][x]) {
                matches.push([[x, y], [x, y + 1], [x, y + 2]]);
            }
        }
    }
    return matches;
}

function removeMatches(matches) {
    matches.forEach(match => {
        match.forEach(([x, y]) => board[y][x] = null);
    });
}

function dropTiles() {
    for (let x = 0; x < boardSize; x++) {
        let emptySlots = [];
        for (let y = boardSize - 1; y >= 0; y--) {
            if (board[y][x] === null) {
                emptySlots.push(y);
            } else if (emptySlots.length > 0) {
                let emptyY = emptySlots.pop();
                board[emptyY][x] = board[y][x];
                board[y][x] = null;
            }
        }
    }
}

function refillBoard() {
    for (let y = 0; y < boardSize; y++) {
        for (let x = 0; x < boardSize; x++) {
            if (board[y][x] === null) {
                board[y][x] = Math.floor(Math.random() * colors.length);
            }
        }
    }
}

function updateBoard() {
    let matches = findMatches();
    if (matches.length > 0) {
        removeMatches(matches);
        dropTiles();
        refillBoard();
        drawBoard();
        setTimeout(updateBoard, 100); // Continue checking for new matches
    }
}

function particleBurst(x, y) {
    const particleCount = 10;
    const particles = [];
    for (let i = 0; i < particleCount; i++) {
        particles.push({
            x: x * cellSize + cellSize / 2,
            y: y * cellSize + cellSize / 2,
            vx: (Math.random() - 0.5) * 2,
            vy: (Math.random() - 0.5) * 2,
            size: Math.random() * 2 + 1,
            color: colors[board[y][x]]
        });
    }
    animateParticles(particles);
}

function animateParticles(particles) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawBoard();
    for (let particle of particles) {
        particle.x += particle.vx;
        particle.y += particle.vy;
        particle.size -= 0.05;
        ctx.fillStyle = particle.color;
        ctx.beginPath();
        ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2);
        ctx.fill();
    }
    if (particles.some(particle => particle.size > 0)) {
        requestAnimationFrame(() => animateParticles(particles));
    }
}

canvas.addEventListener('click', (event) => {
    const rect = canvas.getBoundingClientRect();
    const x = Math.floor((event.clientX - rect.left) / (cellSize * pixelRatio));
    const y = Math.floor((event.clientY - rect.top) / (cellSize * pixelRatio));
    if (x >= 0 && x < boardSize && y >= 0 && y < boardSize) {
        particleBurst(x, y);
    }
});

updateBoard();
```

