const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const player = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    radius: 10,
    speed: 5,
    health: 100,
    maxHealth: 100,
    alive: true
};

const enemies = [];

function spawnEnemy() {
    const enemy = {
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        radius: 5,
        speed: 3,
        alive: true
    };
    enemies.push(enemy);
}

function update() {
    if (!player.alive) {
        setTimeout(() => {
            player.alive = true;
            player.health = player.maxHealth;
            player.x = canvas.width / 2;
            player.y = canvas.height / 2;
        }, 2000); // Respawn after 2 seconds
        return;
    }

    if (Math.random() < 0.01) spawnEnemy();

    enemies.forEach((enemy, index) => {
        if (enemy.alive) {
            const dx = player.x - enemy.x;
            const dy = player.y - enemy.y;
            const dist = Math.sqrt(dx * dx + dy * dy);
            if (dist < player.radius + enemy.radius) {
                player.health -= 10;
                if (player.health <= 0) player.alive = false;
                enemies.splice(index, 1);
            } else {
                const angle = Math.atan2(dy, dx);
                enemy.x += Math.cos(angle) * enemy.speed;
                enemy.y += Math.sin(angle) * enemy.speed;
            }
        }
    });

    const keys = {};
    document.addEventListener('keydown', e => keys[e.code] = true);
    document.addEventListener('keyup', e => keys[e.code] = false);

    if (keys['ArrowUp'] && player.y > player.radius) player.y -= player.speed;
    if (keys['ArrowDown'] && player.y < canvas.height - player.radius) player.y += player.speed;
    if (keys['ArrowLeft'] && player.x > player.radius) player.x -= player.speed;
    if (keys['ArrowRight'] && player.x < canvas.width - player.radius) player.x += player.speed;
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw player
    ctx.beginPath();
    ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
    ctx.fillStyle = player.alive ? 'green' : 'red';
    ctx.fill();

    // Draw enemies
    enemies.forEach(enemy => {
        if (enemy.alive) {
            ctx.beginPath();
            ctx.arc(enemy.x, enemy.y, enemy.radius, 0, Math.PI * 2);
            ctx.fillStyle = 'black';
            ctx.fill();
        }
    });

    // Draw health bar
    ctx.fillStyle = 'black';
    ctx.fillRect(10, 10, 100, 10);
    ctx.fillStyle = player.alive ? 'green' : 'red';
    ctx.fillRect(10, 10, (player.health / player.maxHealth) * 100, 10);
}

function gameLoop() {
    update();
    render();
    requestAnimationFrame(gameLoop);
}

gameLoop();
