class Spaceship {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.width = 20;
    this.height = 20;
    this.angle = 0;
    this.speed = 5;
  }

  update() {
    const radians = (this.angle * Math.PI) / 180;
    this.x += this.speed * Math.cos(radians);
    this.y -= this.speed * Math.sin(radians);
  }

  draw() {
    ctx.save();
    ctx.translate(this.x, this.y);
    ctx.rotate((this.angle * Math.PI) / 180);
    ctx.beginPath();
    ctx.moveTo(10, 0);
    ctx.lineTo(-10, -10);
    ctx.lineTo(-10, 10);
    ctx.closePath();
    ctx.fillStyle = 'white';
    ctx.fill();
    ctx.restore();
  }
}

class Asteroid {
  constructor(x, y, size) {
    this.x = x;
    this.y = y;
    this.size = size;
    this.speed = 2 + Math.random() * 2;
    this.angle = Math.random() * 360;
  }

  update() {
    const radians = (this.angle * Math.PI) / 180;
    this.x += this.speed * Math.cos(radians);
    this.y += this.speed * Math.sin(radians);

    if (this.x > width + this.size || this.x < -this.size || this.y > height + this.size || this.y < -this.size) {
      this.x = Math.random() * width;
      this.y = Math.random() * height;
    }
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
    ctx.fillStyle = 'gray';
    ctx.fill();
  }
}

let spaceship = new Spaceship(width / 2, height / 2);
let asteroids = [];
for (let i = 0; i < 10; i++) {
  asteroids.push(new Asteroid(Math.random() * width, Math.random() * height, 10 + Math.random() * 20));
}

let countdown = 10;
let gameOver = false;
let gameInterval;

function update() {
  if (gameOver) return;

  ctx.clearRect(0, 0, width, height);

  spaceship.update();
  spaceship.draw();

  asteroids.forEach(asteroid => {
    asteroid.update();
    asteroid.draw();
  });

  countdown -= 0.01;
  ctx.font = '30px Arial';
  ctx.fillStyle = 'white';
