class Economy {
  constructor() {
    this.balances = new Map();
  }

  getBalance(player) {
    return this.balances.get(player) || 0;
  }

  setBalance(player, amount) {
    this.balances.set(player, amount);
  }

  debit(player, amount) {
    const currentBalance = this.getBalance(player);
    if (currentBalance >= amount) {
      this.setBalance(player, currentBalance - amount);
      return true;
    }
    return false;
  }

  credit(player, amount) {
    const currentBalance = this.getBalance(player);
    this.setBalance(player, currentBalance + amount);
  }
}

class Inventory {
  constructor() {
    this.items = new Map();
  }

  getInventory(player) {
    return this.items.get(player) || [];
  }

  addItem(player, item) {
    const inventory = this.getInventory(player);
    inventory.push(item);
    this.items.set(player, inventory);
  }

  removeItem(player, item) {
    const inventory = this.getInventory(player);
    const index = inventory.indexOf(item);
    if (index !== -1) {
      inventory.splice(index, 1);
      this.items.set(player, inventory);
    }
  }
}

class Store {
  constructor(economy, prices) {
    this.economy = economy;
    this.prices = prices;
  }

  purchase(player, item) {
    const price = this.prices[item];
    if (price !== undefined && this.economy.debit(player, price)) {
      this.inventory.addItem(player, item);
      console.log(`${player} purchased ${item} for ${price}.`);
      return true;
    }
    console.log(`${player} could not purchase ${item}.`);
    return false;
  }
}

class Combat {
  constructor() {
    this.health = new Health();
  }

  attack(attacker, defender, damage) {
    this.health.takeDamage(defender, damage);
    console.log(`${attacker} attacks ${defender} for ${damage} damage.`);
  }
}

class Health {
  constructor() {
    this.healthPoints = new Map();
  }

  takeDamage(player, amount) {
    const currentHealth = this.healthPoints.get(player) || 100;
    const newHealth = Math.max(currentHealth - amount, 0);
    this.healthPoints.set(player, newHealth);
    if (newHealth === 0) {
      console.log(`${player} has been defeated.`);
    }
  }

  getHealth(player) {
    return this.healthPoints.get(player) || 100;
  }
}

class Loot {
  constructor(store, inventory) {
    this.store = store;
    this.inventory = inventory;
  }

  dropLoot(player, item, price) {
    this.store.prices[item] = price;
    console.log(`${player} dropped ${item} worth ${price}.`);
  }

  collectLoot(player, item) {
    if (this.inventory.getInventory(player).includes(item)) {
      console.log(`${player} collected ${item}.`);
      return true;
    }
    console.log(`${player} could not collect ${item}.`);
    return false;
  }
}

