// Constants for the game
const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 600;
const FPS = 60;
const FIXED_TIMESTEP = 1000 / FPS;
const BULLET_SPEED = 10;
const PLAYER_SPEED = 5;
const ENEMY_SPEED = 3;
const PLAYER_SIZE = 20;
const ENEMY_SIZE = 15;
const BULLET_SIZE = 5;

// Game state
let lastTime = 0;
let accumulatedTime = 0;
let player = { x: CANVAS_WIDTH / 2, y: CANVAS_HEIGHT - 30, angle: 0 };
let bullets = [];
let enemies = [];
let keys = {};

// Canvas setup
const canvas = document.createElement('canvas');
canvas.width = CANVAS_WIDTH;
canvas.height = CANVAS_HEIGHT;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Event listeners for keyboard input
document.addEventListener('keydown', (e) => keys[e.key] = true);
document.addEventListener('keyup', (e) => keys[e.key] = false);

// Event listeners for pointer input
canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;
    player.angle = Math.atan2(mouseY - player.y, mouseX - player.x);
});

canvas.addEventListener('click', () => {
    bullets.push({
        x: player.x,
        y: player.y,
        angle: player.angle,
        speed: BULLET_SPEED
    });
});

// Main game loop
function gameLoop(timestamp) {
    const deltaTime = timestamp - lastTime;
    lastTime = timestamp;
    accumulatedTime += deltaTime;

    while (accumulatedTime >= FIXED_TIMESTEP) {
        update(FIXED_TIMESTEP);
        accumulatedTime -= FIXED_TIMESTEP;
    }

    render();
    requestAnimationFrame(gameLoop);
}

// Update game state
function update(deltaTime) {
    // Player movement
    if (keys['w']) player.y -= PLAYER_SPEED;
    if (keys['s']) player.y += PLAYER_SPEED;
    if (keys['a']) player.x -= PLAYER_SPEED;
    if (keys['d']) player.x += PLAYER_SPEED;

    // Keep player within bounds
    player.x = Math.max(0, Math.min(CANVAS_WIDTH - PLAYER_SIZE, player.x));
    player.y = Math.max(0, Math.min(CANVAS_HEIGHT - PLAYER_SIZE, player.y));

    // Bullet movement
    bullets.forEach((bullet, index) => {
        bullet.x += Math.cos(bullet.angle) * bullet.speed;
        bullet.y += Math.sin(bullet.angle) * bullet.speed;

        // Remove bullets that go off-screen
        if (bullet.x < 0 || bullet.x > CANVAS_WIDTH || bullet.y < 0 || bullet.y > CANVAS_HEIGHT) {
            bullets.splice(index, 1);
        }
    });

    // Enemy spawning
    if (Math.random() < 0.01) {
        enemies.push({
            x: Math.random() * CANVAS_WIDTH,
            y: 0,
            angle: Math.atan2(player.y - 0, player.x - (Math.random() * CANVAS_WIDTH))
        });
    }

    // Enemy movement
    enemies.forEach((enemy, index) => {
        enemy.x += Math.cos(enemy.angle) * ENEMY_SPEED;
        enemy.y += Math.sin(enemy.angle) * ENEMY_SPEED;

        // Remove enemies that go off-screen
        if (enemy.y > CANVAS_HEIGHT) {
            enemies.splice(index, 1);
        }
    });

    // Collision detection
    bullets.forEach((bullet, bulletIndex) => {
        enemies.forEach((enemy, enemyIndex) => {
            const distance = Math.sqrt(Math.pow(bullet.x - enemy.x, 2) + Math.pow(bullet.y - enemy.y, 2));
            if (distance < BULLET_SIZE + ENEMY_SIZE) {
                bullets.splice(bulletIndex, 1);
                enemies.splice(enemyIndex, 1);
            }
        });
    });
}

// Render the game
function render() {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Draw player
    ctx.save();
    ctx.translate(player.x, player.y);
    ctx.rotate(player.angle);
    ctx.fillStyle = 'blue';
    ctx.fillRect(-PLAYER_SIZE / 2, -PLAYER_SIZE / 2, PLAYER_SIZE, PLAYER_SIZE);
    ctx.restore();

    // Draw bullets
    ctx.fillStyle = 'black';
    bullets.forEach((bullet) => {
        ctx.fillRect(bullet.x - BULLET_SIZE / 2, bullet.y - BULLET_SIZE / 2, BULLET_SIZE, BULLET_SIZE);
    });

    // Draw enemies
    ctx.fillStyle = 'red';
    enemies.forEach((enemy) => {
        ctx.fillRect(enemy.x - ENEMY_SIZE / 2, enemy.y - ENEMY_SIZE / 2, ENEMY_SIZE, ENEMY_SIZE);
    });
}

// Start the game loop
requestAnimationFrame(gameLoop);
