class Hunger {
  constructor() {
    this.level = 100; // Full
  }

  eat(amount) {
    this.level = Math.min(100, this.level + amount);
    console.log(`Ate ${amount}. Hunger level is now ${this.level}.`);
  }

  consume(amount) {
    this.level = Math.max(0, this.level - amount);
    console.log(`Consumed ${amount}. Hunger level is now ${this.level}.`);
  }

  getLevel() {
    return this.level;
  }
}

class Energy {
  constructor() {
    this.level = 100; // Full
  }

  rest(amount) {
    this.level = Math.min(100, this.level + amount);
    console.log(`Rested ${amount}. Energy level is now ${this.level}.`);
  }

  expend(amount) {
    this.level = Math.max(0, this.level - amount);
    console.log(`Expend ${amount}. Energy level is now ${this.level}.`);
  }

  getLevel() {
    return this.level;
  }
}

class Clock {
  constructor() {
    this.time = 0; // Start at 0 hours
  }

  tick() {
    this.time++;
    console.log(`Time is now ${this.time} hours.`);
    return this.time;
  }

  getTime() {
    return this.time;
  }
}

class Coordinator {
  constructor() {
    this.hunger = new Hunger();
    this.energy = new Energy();
    this.clock = new Clock();
  }

  update() {
    const currentTime = this.clock.tick();

    if (currentTime % 4 === 0) { // Every 4 hours, consume energy and increase hunger
      this.energy.expend(10);
      this.hunger.consume(5);
    }

    if (currentTime % 8 === 0) { // Every 8 hours, rest and eat
      this.energy.rest(15);
      this.hunger.eat(10);
    }
  }

  run(duration) {
    for (let i = 0; i < duration; i++) {
      this.update();
    }
  }
}

// Demo
const coordinator = new Coordinator();
coordinator.run(24); // Run for 24 hours
