const balance = 100;
const inventoryItems = { 'burger': 10, 'fries': 20 };
const kitchenItems = { 'burger': 10, 'fries': 20 };

const economy = new Economy(prices, balance);
const inventory = new Inventory(inventoryItems);
const kitchen = new Kitchen(kitchenItems);
const store = new Store(economy, inventory, kitchen);
const customer = new Customer('Alice');

store.purchaseItem(customer, new Order('burger', 2)); // Should succeed
store.purchaseItem(customer, new Order('fries', 5));  // Should succeed
store.purchaseItem(customer, new Order('soda', 1));   // Should fail (item not found)
store.purchaseItem(customer, new Order('burger', 15)); // Should fail (insufficient kitchen stock)
