const canvas = document.createElement('canvas');
canvas.width = 480;
canvas.height = 640;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const TILE_SIZE = 64;
const ROWS = 8;
const COLS = 6;
const HEALTH_MAX = 10;
const SPAWN_RATE = 0.05;
const MATCH_THRESHOLD = 3;
const FIXED_TIMESTEP = 1 / 60;
const MAX_FRAMESKIP = 5;

let health = HEALTH_MAX;
let score = 0;
let lastTime = performance.now();
let accumulator = 0;

const board = Array.from({ length: ROWS }, () =>
  Array.from({ length: COLS }, () => Math.floor(Math.random() * 6))
);

function drawBoard() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let row = 0; row < ROWS; row++) {
    for (let col = 0; col < COLS; col++) {
      const x = col * TILE_SIZE;
      const y = row * TILE_SIZE;
      ctx.fillStyle = `hsl(${board[row][col] * 60}, 100%, 50%)`;
      ctx.fillRect(x, y, TILE_SIZE, TILE_SIZE);
    }
  }
}

function drawHealthBar() {
  ctx.fillStyle = 'red';
  ctx.fillRect(10, 10, health * 40, 20);
  ctx.strokeStyle = 'black';
  ctx.strokeRect(10, 10, HEALTH_MAX * 40, 20);
}

function checkMatches() {
  let matches = [];

  // Check horizontal matches
  for (let row = 0; row < ROWS; row++) {
    for (let col = 0; col < COLS - MATCH_THRESHOLD + 1; col++) {
      const color = board[row][col];
      if (color !== -1) {
        let match = true;
        for (let i = 1; i < MATCH_THRESHOLD; i++) {
          if (board[row][col + i] !== color) {
            match = false;
            break;
          }
        }
        if (match) {
          matches = matches.concat(
            Array.from({ length: MATCH_THRESHOLD }, (_, i) => ({
              row,
              col: col + i,
            }))
          );
        }
      }
    }
  }

  // Check vertical matches
  for (let col = 0; col < COLS; col++) {
    for (let row = 0; row < ROWS - MATCH_THRESHOLD + 1; row++) {
      const color = board[row][col];
      if (color !== -1) {
        let match = true;
        for (let i = 1; i < MATCH_THRESHOLD; i++) {
          if (board[row + i][col] !== color) {
            match = false;
            break;
          }
        }
        if (match) {
          matches = matches.concat(
            Array.from({ length: MATCH_THRESHOLD }, (_, i) => ({
              row: row + i,
              col,
            }))
          );
        }
      }
    }
  }

  return matches;
}

function removeMatches(matches) {
  matches.forEach(({ row, col }) => {
    board[row][col] = -1;
  });
}

function dropTiles() {
  for (let col = 0; col < COLS; col++) {
    let emptyRow = ROWS - 1;
    for (let row = ROWS - 1; row >= 0; row--) {
      if (board[row][col] === -1) {
        emptyRow = row;
      } else if (emptyRow < row) {
        board[emptyRow][col] = board[row][col];
        board[row][col] = -1;
        emptyRow--;
      }
    }
  }
}

function spawnTiles() {
  for (let col = 0; col < COLS; col++) {
    if (Math.random() < SPAWN_RATE) {
      board[0][col] = Math.floor(Math.random() * 6);
    }
  }
}

function update() {
  const matches = checkMatches();
  if (matches.length > 0) {
    removeMatches(matches);
    dropTiles();
    spawnTiles();
    score += matches.length;
    health = Math.min(health + matches.length, HEALTH_MAX);
  } else {
    health--;
    if (health <= 0) {
      alert(`Game Over! Score: ${score}`);
      resetGame();
    }
  }
}

function resetGame() {
  health = HEALTH_MAX;
  score = 0;
  board.forEach(row => row.fill(-1));
  for (let row = ROWS - 1; row >= 0; row--) {
    for (let col = 0; col < COLS; col++) {
      if (row === ROWS - 1 || board[row + 1][col] === -1) {
        board[row][col] = Math.floor(Math.random() * 6);
      }
    }
  }
}

function gameLoop(currentTime) {
  const frameTime = currentTime - lastTime;
  lastTime = currentTime;
  accumulator += frameTime;

  let framesSkipped = 0;
  while (accumulator >= FIXED_TIMESTEP && framesSkipped < MAX_FRAMESKIP) {
    update();
    accumulator -= FIXED_TIMESTEP;
    framesSkipped++;
  }

  drawBoard();
  drawHealthBar();

  requestAnimationFrame(gameLoop);
}

resetGame();
requestAnimationFrame(gameLoop);
