class Hunger {
  constructor(initialLevel = 100) {
    this.level = initialLevel;
  }

  consume(amount) {
    this.level = Math.max(0, this.level - amount);
    return this.level;
  }

  eat(amount) {
    this.level = Math.min(100, this.level + amount);
    return this.level;
  }

  getLevel() {
    return this.level;
  }
}

class Energy {
  constructor(initialLevel = 100, clock) {
    this.level = initialLevel;
    this.clock = clock;
  }

  spend(amount) {
    this.level = Math.max(0, this.level - amount);
    return this.level;
  }

  regenerate() {
    if (this.clock.isNight()) {
      this.level = Math.min(100, this.level + 5);
    }
    return this.level;
  }

  getLevel() {
    return this.level;
  }
}

class Clock {
  constructor() {
    this.time = 6; // Start at 6 AM
  }

  tick() {
    this.time = (this.time + 1) % 24;
    return this.time;
  }

  isNight() {
    return this.time >= 18 || this.time < 6;
  }

  getTime() {
    return this.time;
  }
}

