// Maze Chase Game with Combo Multiplier

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let pixelRatio = window.devicePixelRatio || 1;

function resizeCanvas() {
  const width = window.innerWidth;
  const height = window.innerHeight;
  canvas.width = width * pixelRatio;
  canvas.height = height * pixelRatio;
  canvas.style.width = width + 'px';
  canvas.style.height = height + 'px';
  ctx.scale(pixelRatio, pixelRatio);
}

window.addEventListener('resize', resizeCanvas);
resizeCanvas();

const mazeWidth = 20;
const mazeHeight = 15;
const cellSize = 30;
const playerSize = 10;
const enemySize = 10;
const maze = Array.from({ length: mazeHeight }, () =>
  Array.from({ length: mazeWidth }, () => Math.random() > 0.5 ? 1 : 0)
);

let playerX = Math.floor(mazeWidth / 2);
let playerY = Math.floor(mazeHeight / 2);
let enemyX = Math.floor(Math.random() * mazeWidth);
let enemyY = Math.floor(Math.random() * mazeHeight);
let combo = 0;
let score = 0;

function drawMaze() {
  ctx.fillStyle = 'black';
  for (let y = 0; y < mazeHeight; y++) {
    for (let x = 0; x < mazeWidth; x++) {
      if (maze[y][x]) {
        ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
      }
    }
  }
}

function drawPlayer() {
  ctx.fillStyle = 'blue';
  ctx.fillRect(playerX * cellSize + (cellSize - playerSize) / 2, playerY * cellSize + (cellSize - playerSize) / 2, playerSize, playerSize);
}

function drawEnemy() {
  ctx.fillStyle = 'red';
  ctx.fillRect(enemyX * cellSize + (cellSize - enemySize) / 2, enemyY * cellSize + (cellSize - enemySize) / 2, enemySize, enemySize);
}

function drawScore() {
  ctx.fillStyle = 'white';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}, Combo: x${combo}`, 10, 25);
}

function update() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawMaze();
  drawPlayer();
  drawEnemy();
  drawScore();

  if (playerX === enemyX && playerY === enemyY) {
    score += 10 * combo;
    combo++;
    enemyX = Math.floor(Math.random() * mazeWidth);
    enemyY = Math.floor(Math.random() * mazeHeight);
  }

  requestAnimationFrame(update);
}

document.addEventListener('keydown', (e) => {
  let newX = playerX;
  let newY = playerY;

  switch (e.key) {
    case 'ArrowUp':
      newY = Math.max(0, playerY - 1);
      break;
    case 'ArrowDown':
      newY = Math.min(mazeHeight - 1, playerY + 1);
      break;
    case 'ArrowLeft':
      newX = Math.max(0, playerX - 1);
      break;
    case 'ArrowRight':
      newX = Math.min(mazeWidth - 1, playerX + 1);
      break;
  }

  if (!maze[newY][newX]) {
    playerX = newX;
    playerY = newY;
  }
});

update();
