class Recipe {
  constructor(id, ingredients, result) {
    this.id = id;
    this.ingredients = ingredients; // { itemId: quantity }
    this.result = result; // { itemId: quantity }
  }
}

class Crafting {
  constructor(recipes) {
    this.recipes = new Map(recipes.map(recipe => [recipe.id, recipe]));
  }

  canCraft(recipeId, inventory) {
    const recipe = this.recipes.get(recipeId);
    if (!recipe) return false;
    for (const [itemId, quantity] of Object.entries(recipe.ingredients)) {
      if (inventory[itemId] < quantity) return false;
    }
    return true;
  }

  craft(recipeId, inventory) {
    const recipe = this.recipes.get(recipeId);
    if (!recipe) return false;
    for (const [itemId, quantity] of Object.entries(recipe.ingredients)) {
      inventory[itemId] -= quantity;
    }
    for (const [itemId, quantity] of Object.entries(recipe.result)) {
      inventory[itemId] = (inventory[itemId] || 0) + quantity;
    }
    return true;
  }
}

class Inventory {
  constructor(items = {}) {
    this.items = items;
  }

  addItem(itemId, quantity) {
    this.items[itemId] = (this.items[itemId] || 0) + quantity;
  }

  getItems() {
    return this.items;
  }
}

class Economy {
  constructor(prices) {
    this.prices = prices; // { itemId: price }
  }

  debit(price, balance) {
    if (balance < price) return false;
    return balance - price;
  }

  getPrice(itemId) {
    return this.prices[itemId] || 0;
  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
  }

  purchase(itemId, quantity, balance) {
    const price = this.economy.getPrice(itemId) * quantity;
    const newBalance = this.economy.debit(price, balance);
    if (newBalance === false) return false;
    this.inventory.addItem(itemId, quantity);
    return newBalance;
  }
}

