class Economy {
  constructor() {
    this.prices = {
      potion: 5,
      sword: 10,
      shield: 15
    };
    this.balance = 100;
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }

  debit(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  getItems() {
    return this.items;
  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
  }

  purchase(item) {
    const price = this.economy.getPrice(item);
    if (price > 0 && this.economy.debit(price)) {
      this.inventory.addItem(item);
      console.log(`Purchased ${item} for ${price}. Remaining balance: ${this.economy.getBalance()}`);
      return true;
    } else {
      console.log(`Failed to purchase ${item}. Insufficient funds or item not available.`);
      return false;
    }
  }
}

class Combat {
  constructor() {
    this.health = 100;
  }

  takeDamage(amount) {
    this.health -= amount;
    if (this.health < 0) {
      this.health = 0;
    }
    console.log(`Took ${amount} damage. Current health: ${this.health}`);
  }

  heal(amount) {
    this.health += amount;
    if (this.health > 100) {
      this.health = 100;
    }
    console.log(`Healed for ${amount}. Current health: ${this.health}`);
  }
}

class Loot {
  constructor() {
    this.lootTable = {
      potion: 0.3,
      sword: 0.2,
      shield: 0.1
    };
  }

  rollLoot() {
    const roll = Math.random();
    let cumulativeProbability = 0;
    for (const item in this.lootTable) {
      cumulativeProbability += this.lootTable[item];
      if (roll <= cumulativeProbability) {
        console.log(`Rolled ${item} as loot.`);
        return item;
      }
    }
    return null;
  }
}

