const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = window.innerWidth * devicePixelRatio;
canvas.height = window.innerHeight * devicePixelRatio;
const ctx = canvas.getContext('2d');

let gameRunning = false;
let countdown = 3;
let player = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  radius: 10,
  speed: 5,
  angle: 0
};
let enemies = [];
let enemyCount = 5;
let score = 0;

function getRandom(min, max) {
  return Math.random() * (max - min) + min;
}

function createEnemy() {
  return {
    x: getRandom(0, canvas.width),
    y: getRandom(0, canvas.height),
    radius: 5,
    speed: getRandom(1, 3)
  };
}

function startGame() {
  gameRunning = true;
  countdown = 3;
  score = 0;
  enemies = [];
  for (let i = 0; i < enemyCount; i++) {
    enemies.push(createEnemy());
  }
}

function update() {
  if (!gameRunning) {
    countdown--;
    if (countdown < 0) {
      startGame();
    }
    return;
  }

  player.x += player.speed * Math.cos(player.angle);
  player.y += player.speed * Math.sin(player.angle);

  if (player.x < 0 || player.x > canvas.width || player.y < 0 || player.y > canvas.height) {
    gameRunning = false;
  }

  for (let enemy of enemies) {
    enemy.x += enemy.speed * Math.cos(getRandom(0, 2 * Math.PI));
    enemy.y += enemy.speed * Math.sin(getRandom(0, 2 * Math.PI));

    if (Math.hypot(player.x - enemy.x, player.y - enemy.y) < player.radius + enemy.radius) {
      gameRunning = false;
    }

    if (enemy.x < 0 || enemy.x > canvas.width || enemy.y < 0 || enemy.y > canvas.height) {
      enemy.x = getRandom(0, canvas.width);
      enemy.y = getRandom(0, canvas.height);
    }
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  if (!gameRunning) {
    ctx.font = '48px Arial';
    ctx.fillStyle = 'white';
    ctx.textAlign = 'center';
    ctx.fillText(countdown < 0 ? 'Game Over' : `Starting in ${countdown}`, canvas.width / 2, canvas.height / 2);
    return;
  }

  ctx.fillStyle = 'blue';
  ctx.beginPath();
  ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = 'red';
  for (let enemy of enemies) {
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, enemy.radius, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.font = '24px Arial';
  ctx.fillStyle = 'white';
  ctx.fillText(`Score: ${score}`, 10, 30);
}

function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

canvas.addEventListener('mousemove', (e) => {
  player.angle = Math.atan2(e.clientY - canvas.height / 2, e.clientX - canvas.width / 2);
});

canvas.addEventListener('click', () => {
  if (!gameRunning) {
    startGame();
  }
});

gameLoop();
