// Combat System
class Combat {
  constructor() {
    this.attacks = {
      slash: { damage: 10 },
      fireball: { damage: 15 },
      heal: { heal: 5 }
    };
  }

  attack(attacker, defender, attackType) {
    const attack = this.attacks[attackType];
    if (attackType === 'heal') {
      attacker.heal(attack.heal);
    } else {
      defender.takeDamage(attack.damage);
    }
  }
}

// Health System
class Health {
  constructor(maxHealth) {
    this.currentHealth = maxHealth;
    this.maxHealth = maxHealth;
  }

  takeDamage(amount) {
    this.currentHealth -= amount;
    if (this.currentHealth < 0) {
      this.currentHealth = 0;
    }
  }

  heal(amount) {
    this.currentHealth += amount;
    if (this.currentHealth > this.maxHealth) {
      this.currentHealth = this.maxHealth;
    }
  }

  getHealth() {
    return this.currentHealth;
  }
}

// Loot System
class Loot {
  constructor() {
    this.items = {
      potion: { heal: 10 },
      gold: 50
    };
  }

  collect(itemType) {
    return this.items[itemType];
  }
}

// Coordinator
class GameCoordinator {
  constructor() {
    this.combat = new Combat();
    this.playerHealth = new Health(100);
    this.enemyHealth = new Health(80);
    this.loot = new Loot();
  }

  playerAttack(attackType) {
    this.combat.attack(this.playerHealth, this.enemyHealth, attackType);
    console.log(`Player attacks with ${attackType}. Enemy health: ${this.enemyHealth.getHealth()}`);
  }

  enemyAttack() {
    const randomAttack = Object.keys(this.combat.attacks)[Math.floor(Math.random() * 3)];
    this.combat.attack(this.enemyHealth, this.playerHealth, randomAttack);
    console.log(`Enemy attacks with ${randomAttack}. Player health: ${this.playerHealth.getHealth()}`);
  }

  collectItem(itemType) {
    const item = this.loot.collect(itemType);
    if (item.heal) {
      this.playerHealth.heal(item.heal);
      console.log(`Player heals ${item.heal} points. Player health: ${this.playerHealth.getHealth()}`);
    } else {
      console.log(`Player collects ${item} gold.`);
    }
  }
}

