  }
}

class PowerUp {
  constructor(x, y, type) {
    this.x = x;
    this.y = y;
    this.type = type;
    this.radius = 10;
  }

  draw() {
    ctx.fillStyle = 'green';
    ctx.beginPath();
    ctx.arc(this.x + TILE_SIZE / 2, this.y + TILE_SIZE / 2, this.radius, 0, Math.PI * 2);
    ctx.fill();
  }

  collect(player) {
    switch (this.type) {
      case 'heal':
        player.health = Math.min(player.health + 20, 100);
        break;
      case 'speed':
        player.speed += 1;
        break;
      case 'damage':
        player.damage += 1;
        break;
    }
  }
}

