window.addEventListener('keyup', handleKeyup);
window.addEventListener('mousedown', handleMousedown);
window.addEventListener('mouseup', handleMouseup);
window.addEventListener('mousemove', (event) => {
    mouse.x = event.clientX;
    mouse.y = event.clientY;
});

const ship = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    angle: 0,
    speed: 0,
    thrust: 0.1,
    drag: 0.99,
    maxSpeed: 5,
    radius: 10,
    color: 'white'
};

const bullets = [];
const asteroids = [];
const asteroidCount = 5;

function createAsteroid(x, y, radius) {
    return {
        x: x || Math.random() * canvas.width,
        y: y || Math.random() * canvas.height,
        radius: radius || Math.random() * 30 + 20,
        angle: Math.random() * Math.PI * 2,
        speed: Math.random() * 0.5 + 0.5,
        color: 'gray'
    };
}

function init() {
    for (let i = 0; i < asteroidCount; i++) {
        asteroids.push(createAsteroid());
    }
}

function wrapPosition(obj) {
    if (obj.x < 0) obj.x = canvas.width;
    if (obj.x > canvas.width) obj.x = 0;
    if (obj.y < 0) obj.y = canvas.height;
    if (obj.y > canvas.height) obj.y = 0;
}

function updateShip() {
    if (keyStates['ArrowUp']) {
        ship.speed += ship.thrust;
        ship.speed = Math.min(ship.speed, ship.maxSpeed);
    } else {
        ship.speed *= ship.drag;
    }

    if (keyStates['ArrowLeft']) {
        ship.angle -= 0.1;
    }

    if (keyStates['ArrowRight']) {
        ship.angle += 0.1;
    }

    if (keyStates[' ']) {
        bullets.push({
            x: ship.x + Math.cos(ship.angle) * ship.radius,
            y: ship.y + Math.sin(ship.angle) * ship.radius,
            angle: ship.angle,
            speed: 5,
            radius: 2,
            color: 'white',
            life: 100
        });
    }

    ship.x += Math.cos(ship.angle) * ship.speed;
    ship.y += Math.sin(ship.angle) * ship.speed;

    wrapPosition(ship);
}

function updateBullets() {
    for (let i = bullets.length - 1; i >= 0; i--) {
        bullets[i].x += Math.cos(bullets[i].angle) * bullets[i].speed;
        bullets[i].y += Math.sin(bullets[i].angle) * bullets[i].speed;
        bullets[i].life--;

        wrapPosition(bullets[i]);

        if (bullets[i].life <= 0) {
            bullets.splice(i, 1);
        }
    }
}

function updateAsteroids() {
    for (let i = 0; i < asteroids.length; i++) {
        asteroids[i].x += Math.cos(asteroids[i].angle) * asteroids[i].speed;
        asteroids[i].y += Math.sin(asteroids[i].angle) * asteroids[i].speed;

        wrapPosition(asteroids[i]);

        for (let j = bullets.length - 1; j >= 0; j--) {
            const dx = asteroids[i].x - bullets[j].x;
            const dy = asteroids[i].y - bullets[j].y;
            const distance = Math.sqrt(dx * dx + dy * dy);

            if (distance < asteroids[i].radius + bullets[j].radius) {
                bullets.splice(j, 1);
                splitAsteroid(asteroids[i]);
                asteroids.splice(i, 1);
                break;
            }
        }
    }
}

function splitAsteroid(asteroid) {
    if (asteroid.radius > 20) {
        for (let i = 0; i < 2; i++) {
            asteroids.push(createAsteroid(asteroid.x, asteroid.y, asteroid.radius / 2));
        }
    }
}

function drawShip() {
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    ctx.beginPath();
    ctx.moveTo(0, -ship.radius);
    ctx.lineTo(ship.radius, ship.radius);
    ctx.lineTo(-ship.radius, ship.radius);
    ctx.closePath();
    ctx.fillStyle = ship.color;
    ctx.fill();
    ctx.restore();
}

function drawBullets() {
    ctx.fillStyle = 'white';
    for (const bullet of bullets) {
        ctx.beginPath();
        ctx.arc(bullet.x, bullet.y, bullet.radius, 0, Math.PI * 2);
        ctx.fill();
    }
}

function drawAsteroids() {
    for (const asteroid of asteroids) {
        ctx.beginPath();
        ctx.arc(asteroid.x, asteroid.y, asteroid.radius, 0, Math.PI * 2);
        ctx.fillStyle = asteroid.color;
        ctx.fill();
    }
}

function clearCanvas() {
    ctx.fillStyle = 'black';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
}

function gameLoop(timestamp) {
    const fixedTimestep = 16.67; // roughly 60 FPS
    staticTime += timestamp - lastTime;
    lastTime = timestamp;

    while (staticTime >= fixedTimestep) {
        updateShip();
        updateBullets();
        updateAsteroids();
        staticTime -= fixedTimestep;
    }

    clearCanvas();
    drawAsteroids();
    drawBullets();
    drawShip();

    requestAnimationFrame(gameLoop);
}

let staticTime = 0;
let lastTime = performance.now();
init();
gameLoop(performance.now());
