function startGame() {
    running = true;
    combo = 0;
    score = 0;
    player.y = groundLevel;
    obstacles = [];
    requestAnimationFrame(gameLoop);
}

function gameLoop() {
    if (!running) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Player physics
    player.velocity += gravity;
    player.y += player.velocity;

    if (player.y > groundLevel) {
        player.y = groundLevel;
        player.velocity = 0;
        combo = 0;
    }

