class Combat {
  constructor() {
    this.attacker = null;
    this.defender = null;
  }

  engage(attacker, defender) {
    this.attacker = attacker;
    this.defender = defender;
    console.log(`${this.attacker.name} attacks ${this.defender.name}!`);
  }

  dealDamage(amount) {
    if (this.defender) {
      console.log(`${this.attacker.name} deals ${amount} damage to ${this.defender.name}!`);
      this.defender.takeDamage(amount);
    }
  }
}

class Health {
  constructor(maxHealth) {
    this.currentHealth = maxHealth;
    this.maxHealth = maxHealth;
  }

  takeDamage(amount) {
    this.currentHealth -= amount;
    if (this.currentHealth <= 0) {
      this.currentHealth = 0;
      console.log(`${this.owner.name} has been defeated!`);
    } else {
      console.log(`${this.owner.name} now has ${this.currentHealth} health remaining.`);
    }
  }

  heal(amount) {
    this.currentHealth += amount;
    if (this.currentHealth > this.maxHealth) {
      this.currentHealth = this.maxHealth;
    }
    console.log(`${this.owner.name} has been healed to ${this.currentHealth} health.`);
  }

  setOwner(owner) {
    this.owner = owner;
  }
}

class Loot {
  constructor() {
    this.items = [];
  }

  addItem(item) {
    this.items.push(item);
    console.log(`${item} has been added to the loot.`);
  }

  dropLoot(defender) {
    if (defender.isDefeated()) {
      console.log(`${defender.name} drops: ${this.items.join(', ')}`);
      this.items = [];
    }
  }
}

class GameCoordinator {
