class Trade {
    constructor(exchangeRate) {
        this.exchangeRate = exchangeRate;
    }

    trade(amount, currency) {
        if (currency === 'gold') {
            return amount * this.exchangeRate;
        } else if (currency === 'silver') {
            return amount / this.exchangeRate;
        } else {
            throw new Error('Unsupported currency');
        }
    }
