        const tradedAmount = tradeSystem.trade(amount, currency);
        console.log(`${this.name} traded ${amount} ${currency} for ${tradedAmount} gold.`);
        return tradedAmount;
    }

    gainReputation(points) {
        const newReputation = this.reputationSystem.improveReputation(points);
        console.log(`${this.name} reputation increased to ${newReputation}.`);
        return newReputation;
    }

    getReputation() {
        return this.reputationSystem.getReputation();
    }
}

