class EventBus {
    constructor() {
        this.events = {};
    }

    subscribe(event, callback) {
        if (!this.events[event]) {
            this.events[event] = [];
        }
        this.events[event].push(callback);
    }

    emit(event, data) {
        if (this.events[event]) {
            this.events[event].forEach(callback => callback(data));
        }
    }
}

class Order {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('customerOrder', this.placeOrder.bind(this));
    }

    placeOrder(order) {
        console.log(`Order received: ${order}`);
        this.eventBus.emit('orderPrepared', order);
    }
}

class Kitchen {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('orderPrepared', this.prepareOrder.bind(this));
    }

    prepareOrder(order) {
        console.log(`Preparing order: ${order}`);
        setTimeout(() => {
            this.eventBus.emit('orderReady', order);
        }, 2000); // Simulate kitchen preparation time
    }
}

class Customer {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('orderReady', this.receiveOrder.bind(this));
    }

    placeOrder(order) {
        console.log(`Customer orders: ${order}`);
        this.eventBus.emit('customerOrder', order);
    }

    receiveOrder(order) {
        console.log(`Customer receives: ${order}`);
    }
}

// Demo
