let lastObstacleTime = 0;
let lastPowerUpTime = 0;

function generateObstacle() {
  const obstacle = {
    x: canvas.width,
    y: canvas.height - 30,
    width: 30,
    height: 30,
    speed: 5
  };
  obstacles.push(obstacle);
}

function generatePowerUp() {
  const powerUp = {
    x: canvas.width,
    y: Math.random() * (canvas.height - 30),
    width: 20,
    height: 20,
    speed: 5,
    collected: false
  };
  powerUps.push(powerUp);
}

