canvas.height = height * dpr;
canvas.style.width = `${width}px`;
canvas.style.height = `${height}px`;

ctx.scale(dpr, dpr);

class Player {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.size = 10;
    this.speed = 5;
    this.dx = 0;
    this.dy = 0;
  }

  update() {
    this.x += this.dx;
    this.y += this.dy;
  }

  draw() {
    ctx.fillStyle = 'blue';
    ctx.fillRect(this.x - this.size, this.y - this.size, this.size * 2, this.size * 2);
  }

  handleInput() {
    if (keys.right) this.dx = this.speed;
    else if (keys.left) this.dx = -this.speed;
    else this.dx = 0;

    if (keys.down) this.dy = this.speed;
    else if (keys.up) this.dy = -this.speed;
    else this.dy = 0;
  }
}

class Enemy {
  constructor(x, y, target) {
    this.x = x;
    this.y = y;
    this.size = 8;
    this.speed = 2;
    this.target = target;
  }

  update() {
    const dx = this.target.x - this.x;
    const dy = this.target.y - this.y;
    const dist = Math.sqrt(dx * dx + dy * dy);

    if (dist > 0) {
      this.x += (dx / dist) * this.speed;
      this.y += (dy / dist) * this.speed;
    }
  }

  draw() {
    ctx.fillStyle = 'red';
    ctx.fillRect(this.x - this.size, this.y - this.size, this.size * 2, this.size * 2);
  }
}

class Maze {
  constructor(width, height, cellSize) {
    this.width = width;
    this.height = height;
    this.cellSize = cellSize;
    this.grid = this.generateGrid();
  }

  generateGrid() {
    const grid = [];
    for (let y = 0; y < this.height; y++) {
      const row = [];
      for (let x = 0; x < this.width; x++) {
        row.push(Math.random() > 0.7 ? 1 : 0);
      }
      grid.push(row);
    }
    return grid;
  }

  draw() {
    ctx.fillStyle = 'gray';
    for (let y = 0; y < this.height; y++) {
      for (let x = 0; x < this.width; x++) {
        if (this.grid[y][x]) {
          ctx.fillRect(x * this.cellSize, y * this.cellSize, this.cellSize, this.cellSize);
        }
      }
    }
  }
}

const keys = { right: false, left: false, up: false, down: false };
const player = new Player(width / 2, height / 2);
const enemies = [];
const maze = new Maze(50, 30, 16);

function handleKeyDown(e) {
  if (e.key === 'ArrowRight') keys.right = true;
  if (e.key === 'ArrowLeft') keys.left = true;
  if (e.key === 'ArrowDown') keys.down = true;
  if (e.key === 'ArrowUp') keys.up = true;
}

function handleKeyUp(e) {
  if (e.key === 'ArrowRight') keys.right = false;
