class Trade {
    constructor(prices) {
        this.prices = prices;
    }

    getTradePrice(item) {
        return this.prices[item] || null;
    }

    executeTrade(item, quantity, buyer, seller) {
        if (buyer.funds >= this.prices[item] * quantity && seller.inventory[item] >= quantity) {
            buyer.funds -= this.prices[item] * quantity;
            seller.inventory[item] -= quantity;
            buyer.inventory[item] = (buyer.inventory[item] || 0) + quantity;
            return true;
        }
        return false;
    }
}

class Reputation {
