// Initialize canvas and context
const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Game state
let score = 0;
let gameRunning = true;
let fish = [];
let hook = { x: 400, y: 580, size: 10 };

// Fish properties
const fishCount = 10;
const fishSpeed = 1;
const fishSize = 20;

// Initialize fish
function initFish() {
    for (let i = 0; i < fishCount; i++) {
        fish.push({
            x: Math.random() * canvas.width,
            y: Math.random() * canvas.height / 2,
            dx: (Math.random() - 0.5) * fishSpeed,
            dy: (Math.random() - 0.5) * fishSpeed
        });
    }
}

// Draw fish
function drawFish() {
    ctx.fillStyle = 'blue';
    fish.forEach(f => {
        ctx.fillRect(f.x, f.y, fishSize, fishSize);
    });
}

// Move fish
function moveFish() {
    fish.forEach(f => {
        f.x += f.dx;
        f.y += f.dy;
        // Boundary collision
        if (f.x < 0 || f.x > canvas.width - fishSize) f.dx *= -1;
        if (f.y < 0 || f.y > canvas.height / 2) f.dy *= -1;
    });
}

// Draw hook
function drawHook() {
    ctx.fillStyle = 'red';
    ctx.fillRect(hook.x, hook.y, hook.size, hook.size);
}

// Check for collision
function checkCollision() {
    fish.forEach(f => {
        if (hook.x < f.x + fishSize && hook.x + hook.size > f.x &&
            hook.y < f.y + fishSize && hook.y + hook.size > f.y) {
            score++;
            f.x = -100; // Remove fish off screen
        }
    });
}

// Draw score
function drawScore() {
    ctx.fillStyle = 'black';
    ctx.font = '24px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
}

// Game over
function gameOver() {
    ctx.fillStyle = 'red';
    ctx.font = '48px Arial';
    ctx.fillText('Game Over', canvas.width / 2 - 100, canvas.height / 2);
    gameRunning = false;
}

// Game loop
function gameLoop() {
    if (!gameRunning) return;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawFish();
    moveFish();
    drawHook();
    checkCollision();
    drawScore();
    requestAnimationFrame(gameLoop);
}

// Handle mouse movement
canvas.addEventListener('mousemove', (e) => {
    hook.x = e.clientX - canvas.offsetLeft - hook.size / 2;
    hook.y = e.clientY - canvas.offsetTop - hook.size / 2;
});

// Start game
initFish();
gameLoop();
