const ctx = canvas.getContext('2d');

const fish = [];
const maxFish = 10;
const fishSpeed = 2;
const reelSpeed = 5;
const maxReelLength = 200;
const hook = { x: canvas.width / 2, y: canvas.height - 50, length: 0, angle: 0 };

let wave = 0;
let score = 0;
let level = 1;
let gameRunning = true;

function spawnFish() {
    if (fish.length < maxFish) {
        fish.push({
            x: Math.random() * canvas.width,
            y: 0,
            speed: Math.random() * fishSpeed + 1,
            size: Math.random() * 20 + 10,
            caught: false
        });
    }
}

function update() {
    if (!gameRunning) return;

    spawnFish();

    fish.forEach(f => {
        f.y += f.speed;
        if (f.y > canvas.height) {
            f.y = 0;
            f.x = Math.random() * canvas.width;
        }
    });

    fish.forEach(f => {
        const dx = f.x - hook.x;
        const dy = f.y - hook.y;
        const distance = Math.sqrt(dx * dx + dy * dy);
        if (distance < f.size && hook.length > 0) {
            f.caught = true;
            score += 10 * level;
            hook.length = 0;
        }
    });

    if (hook.length > 0) {
        hook.length -= reelSpeed;
        if (hook.length < 0) hook.length = 0;
    }

    if (score >= 100 * level) {
        level++;
        wave++;
        score = 0;
    }
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = 'blue';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = 'green';
    fish.forEach(f => {
        if (!f.caught) {
            ctx.beginPath();
            ctx.arc(f.x, f.y, f.size, 0, Math.PI * 2);
            ctx.fill();
        }
    });

    ctx.strokeStyle = 'black';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(hook.x, hook.y);
    ctx.lineTo(hook.x + Math.cos(hook.angle) * hook.length, hook.y + Math.sin(hook.angle) * hook.length);
    ctx.stroke();

    ctx.fillStyle = 'black';
    ctx.fillText(`Score: ${score}`, 10, 20);
    ctx.fillText(`Level: ${level}`, 10, 40);
    ctx.fillText(`Wave: ${wave}`, 10, 60);
}

let lastTime = 0;
const fixedTimestep = 1000 / 60; // 60 FPS

function gameLoop(timestamp) {
    const deltaTime = timestamp - lastTime;
    if (deltaTime >= fixedTimestep) {
        lastTime = timestamp;
        update();
        render();
    }
    requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);

canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    hook.angle = Math.atan2(y - hook.y, x - hook.x);
});

canvas.addEventListener('click', () => {
    if (hook.length < maxReelLength) {
        hook.length += reelSpeed;
    }
