    this.eventBus.emit('skillLearned', { skillName });
  }

  onLevelUp(data) {
    console.log(`Gained a new level! Learning a new skill...`);
    this.learnSkill(`Skill Level ${data.level}`);
  }
}

class Experience {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.experiencePoints = 0;
    this.eventBus.subscribe('skillLearned', this.onSkillLearned.bind(this));
  }

  earnExperience(points) {
    this.experiencePoints += points;
    console.log(`Earned ${points} experience points. Total: ${this.experiencePoints}`);
    this.checkLevelUp();
  }

