  grow() {
    this.growthDays++;
    if (this.growthDays >= this.growthTime) {
      return true;
    }
    return false;
  }

  isReadyToHarvest() {
    return this.growthDays >= this.growthTime;
  }

  getName() {
    return this.name;
  }
